// - Font Picker Component -
// Cria um font picker interativo com busca, preview e suporte a fontes do sistema.
/**
 * Os caracteres DISTINTOS que a numeração aberta no editor manda ao papel.
 *
 * É por eles que se decide se uma fonte serve: não interessa se ela tem 3.000
 * glifos, interessa se tem estes. Sai do banco carregado (só as colunas que os
 * elementos leem) e dos textos digitados à mão — prefixo, sufixo e valor fixo.
 *
 * Devolve uma string sem repetição, pronta para `faltamNaFonte`.
 */
function caracteresDoBancoDaNumeracao() {
    const vistos = new Set();
    const juntar = (t) => {
        for (const ch of String(t == null ? '' : t)) vistos.add(ch);
    };
    const linhas = Array.isArray(state.numCsvData) ? state.numCsvData : [];
    (state.numElements || []).forEach(el => {
        if (!el || el.type === 'METADATA') return;
        if (el.fixed) juntar(el.fixed_value);
        ['prefix', 'suffix', 'prefix_fila', 'prefix_lugar'].forEach(k => juntar(el[k]));
        if (el.source === 'database' && el.csv_column) {
            for (const linha of linhas) {
                if (!linha || linha.__ativo === false) continue;   // desmarcada não imprime
                juntar(linha[el.csv_column]);
            }
        }
    });
    // Separadores não são desenhados; cobrar glifo deles acusaria toda fonte.
    ['\n', '\r', '\t'].forEach(c => vistos.delete(c));
    return [...vistos].join('');
}
window.caracteresDoBancoDaNumeracao = caracteresDoBancoDaNumeracao;

/**
 * O veredito de UMA fonte sobre o banco aberto: serve, não serve, ou não sei.
 *
 * `null` quando não dá para saber — cobertura ainda não lida, fonte do sistema,
 * arquivo que não abriu. É a regra de ouro do fonte-glifos.js aplicada à tela:
 * o seletor cala a boca em vez de chutar.
 */
function vereditoDaFonteSobreOBanco(nomeDaFonte, caracteres) {
    const mapa = typeof window.mapaDeCoberturas === 'function' ? window.mapaDeCoberturas() : null;
    if (!mapa || typeof window.faltamNaFonte !== 'function') return null;
    const cob = mapa[String(nomeDaFonte || '').trim().toLowerCase()];
    if (!cob) return null;
    const faltam = window.faltamNaFonte(cob, caracteres || '');
    return { serve: faltam.length === 0, faltam: faltam };
}
window.vereditoDaFonteSobreOBanco = vereditoDaFonteSobreOBanco;

function createFontPicker(elId, currentValue, onChange) {
    const wrap = document.createElement('div');
    wrap.className = 'font-picker-wrap';
    wrap.dataset.elId = elId;

    const BUILTIN_IDS = ['helv','helv-bold','times','times-bold','cour','cour-bold'];

    const getLabelForValue = (v) => {
        if (!v) return 'Selecione uma fonte...';
        // Traduzir IDs internos para nomes legíveis
        const builtinNames = {
            'helv': 'Helvetica', 'hebo': 'Helvetica Bold',
            'helv-bold': 'Helvetica Bold',
            'times': 'Times New Roman', 'times-bold': 'Times New Roman Bold',
            'cour': 'Courier', 'cour-bold': 'Courier Bold'
        };
        if (builtinNames[v]) return builtinNames[v];
        if (v.startsWith('system:')) {
            const parts = v.slice(7).split('|');
            return parts[0] || v;
        }
        // Tentar encontrar no catálogo pelo font_family
        if (state_fonts.catalogo && state_fonts.catalogo.length) {
            const cat = state_fonts.catalogo.find(f => f.font_family === v || f.nome === v);
            if (cat) return cat.nome;
        }
        return v;
    };

    const buildTriggerHTML = (v) => {
        const label = getLabelForValue(v);
        const css   = getFontCSS(v);
        const fam   = css.replace(/^(bold |italic )*/, '');
        return `<span class="fp-preview" style="font-family:${fam}">${label}</span><span class="fp-arrow">▾</span>`;
    };

    wrap.innerHTML = `
        <button type="button" class="font-picker-trigger" id="fpt-${elId}">
            ${buildTriggerHTML(currentValue)}
        </button>
        <div class="font-picker-dropdown" id="fpd-${elId}">
            <div class="font-picker-search">
                <input type="text" placeholder="🔍 Buscar fonte..." id="fps-${elId}" autocomplete="off">
            </div>
            <div class="font-picker-list" id="fpl-${elId}">
                <div class="font-picker-loading">Carregando fontes...</div>
            </div>
            <div class="font-picker-glifos" id="fpg-${elId}" style="padding:8px 10px; border-top:1px solid rgba(148,163,184,0.25); font-size:0.74rem; line-height:1.35;"></div>
        </div>
    `;

    const trigger     = wrap.querySelector(`#fpt-${elId}`);
    const dropdown    = wrap.querySelector(`#fpd-${elId}`);
    const searchInput = wrap.querySelector(`#fps-${elId}`);
    const list        = wrap.querySelector(`#fpl-${elId}`);
    const rodape      = wrap.querySelector(`#fpg-${elId}`);

    let currentFont = currentValue || '';

    // ── Quais fontes servem para o banco desta numeração ──
    //
    // É a saída da trava do card: ela diz "troque a fonte", e é aqui que o
    // operador descobre por qual. Sem isto ele testaria 273 fontes no escuro.
    //
    // Ler a cobertura custa um download por fonte, então nada é baixado só por
    // abrir a lista: entra em cena o que já estiver no cache, mais a fonte
    // ATUAL (uma só, imediata) — e o resto fica atrás do botão, que é caro e
    // por isso é escolha do operador.
    let caracteresDoBanco = '';
    let conferindoTudo = false;

    const desenharRodape = () => {
        if (!rodape) return;
        if (!caracteresDoBanco) {
            rodape.innerHTML = '<span style="color:#64748b;">Esta numeração ainda não tem texto de banco para conferir.</span>';
            return;
        }
        const v = vereditoDaFonteSobreOBanco(currentFont, caracteresDoBanco);
        let linha;
        if (!v) {
            linha = '<span style="color:#64748b;">Não dá para conferir os caracteres desta fonte '
                + '(fonte do sistema ou arquivo que não abriu).</span>';
        } else if (v.serve) {
            linha = '<span style="color:#4ade80; font-weight:700;">✅ Esta fonte desenha todo o banco.</span>';
        } else {
            const chars = v.faltam.map(ch => (window.rotuloDoCaractere ? window.rotuloDoCaractere(ch) : ch)).join(', ');
            linha = '<span style="color:#f87171; font-weight:700;">⚠️ Esta fonte não desenha ' + escapeHtml(chars)
                + '</span><br><span style="color:#94a3b8;">Na tela o texto aparece inteiro; no papel esses caracteres saem como buraco.</span>';
        }
        const botao = conferindoTudo
            ? '<span style="color:#94a3b8;">Conferindo as fontes do catálogo…</span>'
            : `<button type="button" id="fpc-${elId}" class="btn" style="margin-top:6px; padding:3px 8px; font-size:0.72rem; height:auto;">🔤 Conferir quais fontes servem</button>`;
        rodape.innerHTML = linha + '<div>' + botao + '</div>';
        const btn = rodape.querySelector(`#fpc-${elId}`);
        if (btn) btn.addEventListener('mousedown', async (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (conferindoTudo) return;
            conferindoTudo = true;
            desenharRodape();
            try {
                const catalogo = (state_fonts.catalogo || []);
                // Em lotes: 273 downloads de uma vez disputam a rede com o
                // resto da tela e o navegador enfileira do jeito dele.
                for (let i = 0; i < catalogo.length; i += 12) {
                    const lote = catalogo.slice(i, i + 12).map(f => f.nome);
                    await window.garantirCoberturas(lote, { catalogo: catalogo });
                }
            } catch (err) {
                console.warn('[Fonts] conferência de glifos:', err && err.message);
            }
            conferindoTudo = false;
            renderList(searchInput.value);
            desenharRodape();
        });
    };

    const renderList = (filter = '') => {

        const q = filter.toLowerCase().trim();
        let html = '';

        // - Fontes do Catálogo Web (Gráfica) -
        if (state_fonts.catalogo && state_fonts.catalogo.length) {
            const catFiltered = state_fonts.catalogo.filter(f => !q || (f.nome || '').toLowerCase().includes(q) || (f.font_family || '').toLowerCase().includes(q));
            if (catFiltered.length) {
                html += `<div class="font-picker-group-label" style="color:#38bdf8; font-weight:700;">🌐 Fontes Oficiais da Gráfica (${catFiltered.length})</div>`;
                for (const f of catFiltered) {
                    const fullName = f.nome;
                    const sel = fullName === currentFont ? 'selected' : '';
                    // O selo só aparece quando a cobertura JÁ é conhecida.
                    // Fonte não conferida sai sem marca nenhuma — marcar de
                    // verde o que ninguém leu seria a mesma mentira que este
                    // trabalho inteiro existe para desfazer.
                    const v = caracteresDoBanco ? vereditoDaFonteSobreOBanco(fullName, caracteresDoBanco) : null;
                    const selo = !v ? ''
                        : (v.serve
                            ? '<span title="Desenha todo o banco desta numeração" style="color:#4ade80; flex-shrink:0;">✅</span>'
                            : `<span title="${escapeHtml('Não desenha ' + v.faltam.join(' '))}" style="color:#f87171; flex-shrink:0;">⚠️</span>`);
                    const apagada = v && !v.serve ? 'opacity:0.55;' : '';
                    html += `<div class="font-picker-opt ${sel}" data-value="${fullName}" style="${apagada}">
                        <span class="fp-name" style="flex:1; font-size:0.85rem; color:#e2e8f0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${f.nome}</span>
                        ${selo}
                        <span class="fp-sample" style="font-family:'${f.font_family}',sans-serif; font-size:0.75rem; color:#64748b; flex-shrink:0;">Aa</span>
                    </div>`;
                }
            } else {
                html = `<div class="font-picker-loading">Nenhuma fonte encontrada para "${filter}"</div>`;
            }
        } else {
            html = `<div class="font-picker-loading">Catálogo de fontes vazio. Cadastre em Configurações > Fontes.</div>`;
        }

        list.innerHTML = html;


        list.querySelectorAll('.font-picker-opt').forEach(opt => {
            opt.addEventListener('mousedown', e => {
                e.preventDefault();
                const val = opt.dataset.value;
                currentFont = val;
                trigger.innerHTML = buildTriggerHTML(val);
                closeDropdown();
                if (onChange) onChange(val);
                // A fonte recém-escolhida pode nunca ter sido lida. Vale um
                // download para o operador saber JÁ se resolveu — e para o
                // canvas redesenhar mostrando o buraco, se ainda houver.
                if (typeof window.garantirCoberturas === 'function') {
                    window.garantirCoberturas([val], { catalogo: state_fonts.catalogo || [] })
                        .then(novas => {
                            if (novas && novas.length && typeof drawPreview === 'function') drawPreview();
                        })
                        .catch(() => {});
                }
            });
        });

        const sel = list.querySelector('.font-picker-opt.selected');
        if (sel) sel.scrollIntoView({ block: 'nearest' });
    };

    const openDropdown = async () => {
        trigger.classList.add('open');
        dropdown.classList.add('open');
        searchInput.value = '';
        searchInput.focus();

        caracteresDoBanco = caracteresDoBancoDaNumeracao();
        renderList('');
        desenharRodape();

        // Só a fonte ATUAL vai à rede na abertura: é um arquivo, e é a resposta
        // que o operador veio buscar ("a que está aí serve?"). O catálogo
        // inteiro fica atrás do botão do rodapé.
        if (caracteresDoBanco && typeof window.garantirCoberturas === 'function') {
            try {
                const novas = await window.garantirCoberturas([currentFont], {
                    catalogo: state_fonts.catalogo || [],
                });
                if (novas && novas.length) { renderList(searchInput.value); desenharRodape(); }
            } catch (e) { /* seletor nunca quebra por causa da conferência */ }
        }
    };

    const closeDropdown = () => {
        trigger.classList.remove('open');
        dropdown.classList.remove('open');
    };

    trigger.addEventListener('click', e => {
        e.stopPropagation();
        if (dropdown.classList.contains('open')) {
            closeDropdown();
        } else {
            document.querySelectorAll('.font-picker-dropdown.open').forEach(d => d.classList.remove('open'));
            document.querySelectorAll('.font-picker-trigger.open').forEach(t => t.classList.remove('open'));
            openDropdown();
        }
    });

    searchInput.addEventListener('input', () => renderList(searchInput.value));

    // Fechar ao clicar fora
    document.addEventListener('click', (e) => {
        if (!wrap.contains(e.target)) closeDropdown();
    }, { capture: true, passive: true });

    return wrap;
}

// Gera o HTML do grupo de Fonte para uso em template strings de elementos
// (será montado depois via JS, não inline HTML, pois precisa do DOM)
function fontPickerHTML(elId, currentValue) {
    // Retorna um placeholder que será substituído após inserção no DOM
    return `<div class="font-picker-mount" data-el-id="${elId}" data-current="${currentValue || 'helv'}"></div>`;
}

// Monta todos os font pickers pendentes no DOM
function mountFontPickers() {
    document.querySelectorAll('.font-picker-mount').forEach(mount => {
        if (mount.dataset.mounted) return;
        mount.dataset.mounted = '1';
        const elId = mount.dataset.elId;
        const currentValue = mount.dataset.current || 'helv';
        const picker = createFontPicker(elId, currentValue, (val) => {
            updateEl(elId, 'font_name', val);
        });
        mount.replaceWith(picker);
    });
}



// - Utility -- Toast -

function toast(msg, type = 'info') {

    // 'warning' faltava aqui e o app já o usava em dezenas de chamadas: icons[type]
    // vinha undefined e o usuário lia "undefined Mensagem...". O fallback cobre
    // qualquer tipo novo que apareça sem passar por aqui.
    const icons = { success: '✅', error: '❌', info: 'ℹ️', warning: '⚠️' };

    const tc = document.getElementById('toast-container');

    const el = document.createElement('div');

    el.className = `toast toast-${type}`;

    el.innerHTML = `<span>${icons[type] || icons.info}</span> ${msg}`;

    tc.appendChild(el);

    setTimeout(() => el.remove(), 3100);

}



// - Navigation -

document.querySelectorAll('.nav-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        const viewId = btn.dataset.view;

        // MENU ABRE A PAGINA INICIAL DA TELA, nunca o detalhe da visita
        // anterior. A pagina inicial do Pedido passou a ser a fila com NENHUM
        // modelo selecionado, entao vir pelo menu fecha a janela de
        // visualizacao que tenha ficado aberta.
        //
        // Quem abre um modelo por codigo NAO passa por aqui: o
        // `enviarParaPedido` chama `showView` direto, de proposito.
        if (viewId === 'view-pedido' && typeof window.fecharJanelaDoModelo === 'function') {
            window.fecharJanelaDoModelo();
        }

        if (typeof window.showView === 'function') {
            window.showView(viewId);
        } else {
            document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.view-section').forEach(v => v.classList.remove('active'));
            btn.classList.add('active');
            const view = document.getElementById(viewId);
            if (view) view.classList.add('active');
        }
    });
});


// ── MENU EM GRUPOS (29/08/2026) ───────────────────────────────────────────────
//
// O menu tinha vinte botoes num rolo so, ~1.280 px de altura: mais alto do que
// qualquer monitor da grafica, entao ele rolava. Agora os tres grupos abrem e
// fecham, e quem manda em qual fica aberto e a TELA EM QUE O OPERADOR ESTA — nao
// o ultimo grupo que ele clicou. Sair de Pedido para Formatos fecha Producao e
// abre Configuracao sozinho; e o mesmo espirito de
// `menu-abre-na-pagina-inicial-da-tela`: o menu mostra onde a pessoa esta.
//
// Na estacao, com o menu encolhido em 56 px, so aparecem os icones — do grupo
// aberto e dos tres cabecalhos. Quem quer outro grupo passa o mouse (a barra
// abre sozinha, como sempre) e clica no cabecalho.

/**
 * Telas que nao tem botao proprio no menu, e de quem elas acendem o botao.
 *
 * As tres duplas editor+lista viraram uma entrada so, que abre a LISTA. O editor
 * continua existindo e continua sendo alcancado pelo "+ Novo" de dentro da lista
 * — mas, aberto, ele precisa deixar aceso o botao por onde se chega ate ele,
 * senao o menu fica sem nenhum item marcado e o operador perde a referencia.
 */
const NAV_DA_VIEW = {
    'view-formatos':  'nav-lista-formatos',
    'view-numeracao': 'nav-catalogo',
    'view-cores':     'nav-lista-cores',
};

function botaoDoMenuDaView(viewId) {
    return document.querySelector(`.nav-btn[data-view="${viewId}"]`)
        || (NAV_DA_VIEW[viewId] ? document.getElementById(NAV_DA_VIEW[viewId]) : null);
}
window.botaoDoMenuDaView = botaoDoMenuDaView;

/** Abre UM grupo e fecha os outros. `null` fecha todos. */
function abrirGrupoDoMenu(chave) {
    document.querySelectorAll('.nav-group').forEach(g => {
        const aberto = g.dataset.grupo === chave;
        g.classList.toggle('open', aberto);
        g.setAttribute('aria-expanded', aberto ? 'true' : 'false');
    });
    document.querySelectorAll('.nav-group-corpo').forEach(c => {
        c.classList.toggle('open', c.dataset.grupoCorpo === chave);
    });
}
window.abrirGrupoDoMenu = abrirGrupoDoMenu;

/**
 * Acende o botao do menu correspondente a tela, e abre o grupo em que ele mora.
 *
 * Usada pelo `showView` e pelos poucos pontos que trocam de tela na mao (salvar
 * um formato, editar uma numeracao). Antes cada um deles fazia
 * `getElementById('nav-...').classList.add('active')` sem guarda — o que
 * quebrava assim que um botao saia do menu.
 */
function ativarBotaoDoMenu(viewId) {
    document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
    const btn = botaoDoMenuDaView(viewId);
    if (!btn) return;
    btn.classList.add('active');
    const corpo = btn.closest('.nav-group-corpo');
    if (corpo) abrirGrupoDoMenu(corpo.dataset.grupoCorpo);
}
window.ativarBotaoDoMenu = ativarBotaoDoMenu;

/**
 * O numero ao lado do nome do grupo conta telas VISIVEIS, nao telas existentes.
 *
 * Quem nao tem permissao para Mapas nao pode ler "6" num grupo que so abre
 * cinco coisas para ele. E grupo que ficou sem nenhuma tela some inteiro, em vez
 * de virar um cabecalho que abre no vazio.
 */
function atualizarContagemDosGrupos() {
    document.querySelectorAll('.nav-group').forEach(g => {
        const corpo = document.querySelector(
            `.nav-group-corpo[data-grupo-corpo="${g.dataset.grupo}"]`);
        if (!corpo) return;
        const visiveis = Array.from(corpo.querySelectorAll('.nav-btn'))
            .filter(b => b.style.display !== 'none').length;
        const conta = g.querySelector('.nav-group-conta');
        if (conta) conta.textContent = visiveis ? String(visiveis) : '';
        g.style.display = visiveis ? '' : 'none';
        if (!visiveis) {
            g.classList.remove('open');
            corpo.classList.remove('open');
        }
    });
}
window.atualizarContagemDosGrupos = atualizarContagemDosGrupos;

document.querySelectorAll('.nav-group').forEach(g => {
    g.addEventListener('click', () => {
        // Clicar no grupo aberto fecha ele: e o unico jeito de ver so os
        // cabecalhos, que e o menu no seu tamanho minimo.
        const jaAberto = g.classList.contains('open');
        abrirGrupoDoMenu(jaAberto ? null : g.dataset.grupo);
    });
});

// Uma primeira contagem ao abrir a pagina. As permissoes chamam de novo quando
// chegam, mas na estacao — que entra pelo acesso local, sem sessao do Supabase —
// elas podem nao chegar nunca, e sem isto o numero ao lado do nome do grupo
// ficava em branco para o operador.
atualizarContagemDosGrupos();



// - API Helpers -

// ── O CATÁLOGO DE CORES NÃO CARREGA O PDF DE REFERÊNCIA ───────────────
//
// `producao_cores` guarda o PDF inteiro da cor dentro da própria linha, em
// base64. São 24 linhas e 17,8 MiB de JSON: 16,8 MiB de `pdf_base64` +
// `pdf_verso_base64`, 1 MiB de `preview_base64` (coluna que este frontend não
// lê em lugar nenhum) e 11,7 KiB de tudo o que a tela realmente mostra.
//
// Enquanto a lista vinha com `select('*')`, abrir o painel baixava esses 18 MB
// (13,5 MiB comprimidos) antes de qualquer tela aparecer — era isso que fazia o
// parceiro esperar ao clicar no link direto do pedido, e o cliente esperar na
// página de aprovação. O mesmo remédio já tinha sido aplicado ao `csv_data` das
// numerações em `cliente.js`.
//
// Quem precisa dos bytes chama `garantirPdfDaCor(cor)` e recebe a MESMA linha
// com as duas colunas preenchidas — uma cor por vez, só a que vai ser desenhada.
// Para saber se existe PDF sem baixá-lo, use `pdf_filename` (frente) e
// `name_verso` (verso): as duas colunas são gravadas junto com o arquivo.
const COLUNAS_DA_COR_NA_LISTA = 'id,empresa_id,name,hex,pdf_url,pdf_filename,created_at,updated_at,formato_id,width_mm,height_mm,id_modelo_cor_num,name_verso,frente_verso,cor_referencia';

// O CATÁLOGO DE NUMERAÇÕES SEM O BANCO DE DADOS DE CADA UMA (26/08/2026).
//
// Mesma doença da lista de cores logo acima, com um número pior. Medido contra
// o banco real, `producao_numeracoes` tem 105 registros e 27 colunas:
//
//     select('*')                     29,17 MB   1.772 ms
//     esta lista                       0,19 MB     273 ms
//
// A diferença inteira é UMA coluna. `csv_data` sozinho pesa 30,1 MB dos 30,3 MB
// da tabela; as outras 26 somadas dão 209 KB. Não é uma lista de "colunas
// leves" — é a tabela inteira menos o elefante.
//
// O que isso custava, e que não aparecia como erro em lugar nenhum: abrir o
// painel baixava 29 MB antes de qualquer tela, e deixava 187.021 linhas de CSV
// vivas na memória da aba — de bancos que a lista não mostra e ninguém pediu.
// O sintoma que o usuário via era outro: um clique qualquer travando por 200 ms
// (o INP do Chrome apontou o filtro do editor de CSV, que medido sozinho custa
// 14 ms com 56.000 linhas). Quem paga a conta da memória é sempre o próximo
// clique, não quem a encheu.
//
// Quem precisa das linhas chama `garantirCsvDaNumeracao(num)` e recebe a MESMA
// numeração com o `csv_data` preenchido — uma por vez, só a que vai ser aberta,
// desenhada ou impressa. As numerações do pedido aberto continuam vindo
// inteiras pelo `recarregarNumeracoesDoPedido`, que lê por id.
//
// Para saber se existe banco SEM baixá-lo, use `csv_filename` e `csv_headers`:
// as duas são gravadas junto com o CSV e estão nesta lista de propósito.
//
// COLUNA NOVA NA TABELA PRECISA ENTRAR AQUI. Não há "select tudo menos uma" no
// PostgREST, então a lista é explícita e envelhece em silêncio: a coluna que
// faltar chega como `undefined`, sem erro nenhum. O teste
// `test_catalogo_de_numeracoes_sem_csv` trava isso contra o que a duplicação
// copia, que é a enumeração mais completa que o código tem.
const COLUNAS_DA_NUMERACAO_NA_LISTA = 'id,empresa_id,name,formato_id,formato_ids,tipo,'
    + 'print_mode,ticket_qtd,ticket_logica,csv_filename,csv_headers,csv_url,'
    + 'svg_content,svg_filename,pdf_content,pdf_filename,bg_url,bg_filename,'
    + 'elements,preview_jpg,is_custom,os_item_id,id_gabarito,Cli_Num,'
    + 'created_at,updated_at';

const _pdfDeCorEmVoo = new Map();

async function garantirPdfDaCor(cor) {
    if (!cor || !cor.id) return cor;
    // `undefined` = a linha veio da lista enxuta. `null` = já foi buscado e a
    // cor não tem arquivo. Só o primeiro caso vai ao banco.
    if (cor.pdf_base64 !== undefined) return cor;
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return cor;

    const chave = String(cor.id);
    if (!_pdfDeCorEmVoo.has(chave)) {
        _pdfDeCorEmVoo.set(chave, supabaseClient
            .from('producao_cores')
            .select('pdf_base64,pdf_verso_base64')
            .eq('id', cor.id)
            .maybeSingle()
            .then(({ data, error }) => {
                if (error) throw error;
                return data || { pdf_base64: null, pdf_verso_base64: null };
            }));
    }

    try {
        const linha = await _pdfDeCorEmVoo.get(chave);
        cor.pdf_base64 = linha.pdf_base64 || null;
        cor.pdf_verso_base64 = linha.pdf_verso_base64 || null;
        // A mesma cor pode estar em duas referências (a do state e uma cópia).
        const noEstado = (state.cores || []).find(c => String(c.id) === chave);
        if (noEstado && noEstado !== cor) {
            noEstado.pdf_base64 = cor.pdf_base64;
            noEstado.pdf_verso_base64 = cor.pdf_verso_base64;
        }
    } catch (e) {
        _pdfDeCorEmVoo.delete(chave);
        console.warn('[cores] Nao foi possivel baixar o PDF da cor ' + cor.id, e);
    }
    return cor;
}
window.garantirPdfDaCor = garantirPdfDaCor;

// As buscas de `csv_data` em voo, por id. Mesma mecânica do `_pdfDeCorEmVoo`:
// duas telas pedindo o banco da mesma numeração ao mesmo tempo fazem UMA
// consulta. O mapa é limpo a cada releitura do catálogo — ver o `api()`.
const _csvDaNumeracaoEmVoo = new Map();

/**
 * Preenche o `csv_data` de uma numeração que veio da lista enxuta.
 *
 * ## Os três estados de `csv_data`, e por que eles não podem se confundir
 *
 *   `undefined` — veio da lista, o banco não foi buscado ainda. SÓ ESTE vai à rede.
 *   `null`      — já foi buscado, e esta numeração não tem banco.
 *   array       — está aqui.
 *
 * A diferença entre os dois primeiros é a coisa mais importante deste arquivo.
 * Quase todo leitor de `csv_data` no painel pergunta `if (!num.csv_data)` e
 * conclui "esta numeração não tem banco" — e uma numeração COM banco que
 * simplesmente não foi baixado responde igual a uma SEM banco. O motor, sem
 * linhas, ignora o banco e cai na numeração sequencial: sai número impresso no
 * lugar do nome da pessoa, sem erro em tela nenhuma.
 *
 * É por isso que a lista enxuta NÃO traz a coluna (deixando `undefined`) em vez
 * de trazê-la vazia, e por isso `numeracaoTemBanco()` existe: para quem precisa
 * decidir "tem banco?" sem ter as linhas em mãos.
 *
 * Nunca lança: sem rede, a numeração volta como estava e quem chamou segue com
 * o que tem — igual ao `garantirPdfDaCor`.
 */
async function garantirCsvDaNumeracao(num) {
    if (!num || !num.id) return num;
    if (num.csv_data !== undefined) return num;
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return num;

    const chave = String(num.id);
    if (!_csvDaNumeracaoEmVoo.has(chave)) {
        _csvDaNumeracaoEmVoo.set(chave, supabaseClient
            .from('producao_numeracoes')
            .select('csv_data')
            .eq('id', num.id)
            .maybeSingle()
            .then(({ data, error }) => {
                if (error) throw error;
                return data || { csv_data: null };
            }));
    }

    try {
        const linha = await _csvDaNumeracaoEmVoo.get(chave);
        num.csv_data = linha.csv_data || null;
        // A mesma numeração pode estar em duas referências (a do catálogo e uma
        // cópia que a tela guardou). Mesma precaução do `garantirPdfDaCor`.
        const noEstado = (state.numeracoes || []).find(n => String(n.id) === chave);
        if (noEstado && noEstado !== num) noEstado.csv_data = num.csv_data;
    } catch (e) {
        _csvDaNumeracaoEmVoo.delete(chave);
        console.warn('[numeracoes] nao consegui baixar o banco de dados da numeracao ' + num.id, e);
    }
    return num;
}
window.garantirCsvDaNumeracao = garantirCsvDaNumeracao;

/** Esquece o `csv_data` baixado de uma numeração — quem grava tem de chamar. */
function esquecerCsvDaNumeracao(numId) {
    _csvDaNumeracaoEmVoo.delete(String(numId));
}
window.esquecerCsvDaNumeracao = esquecerCsvDaNumeracao;

/**
 * Esta numeração tem banco de dados? Responde SEM baixar as linhas.
 *
 * `csv_filename` e `csv_headers` são gravados junto com o CSV e vêm na lista
 * enxuta de propósito. Perguntar por `csv_data.length` responderia "não" para
 * toda numeração cujo banco ainda não desceu — ver o comentário do
 * `garantirCsvDaNumeracao`.
 */
function numeracaoTemBanco(num) {
    if (!num) return false;
    if (Array.isArray(num.csv_data)) return num.csv_data.length > 0;
    return !!(num.csv_filename || (num.csv_headers && num.csv_headers.length));
}
window.numeracaoTemBanco = numeracaoTemBanco;

/** As numeracoes de um pedido cujo banco ainda nao desceu. */
function numeracoesSemBancoBaixado(osId) {
    const itens = (state.osItens && state.osItens[osId]) || [];
    const ids = new Set();
    itens.forEach(it => {
        const id = numeracaoIdDoItem(it);
        if (!id) return;
        const num = (state.numeracoes || []).find(n => String(n.id) === String(id));
        // `undefined` e o unico estado que falta baixar. `null` ja respondeu
        // "nao tem banco", e array esta aqui. Ver `garantirCsvDaNumeracao`.
        if (num && num.csv_data === undefined) ids.add(num);
    });
    return Array.from(ids);
}
window.numeracoesSemBancoBaixado = numeracoesSemBancoBaixado;

/**
 * Baixa, uma a uma, os bancos das numeracoes de um pedido.
 *
 * Uma por vez de proposito: no 21202 sao 22 MB somados, e dispara-las
 * juntas entope a rede da estacao no momento em que o operador esta
 * justamente esperando a tela. Em serie, cada card acende assim que o dele
 * chega. Nunca lanca -- sem rede a tela fica como estava.
 */
/** O numero da OS (`pedidos_modelos.id_int`), tirado dos modelos ja carregados. */
function idIntDoPedido(osId) {
    const itens = (state.osItens && state.osItens[osId]) || [];
    const com = itens.find(it => it && it.id_int);
    return com ? com.id_int : null;
}
window.idIntDoPedido = idIntDoPedido;

/**
 * Os bancos de dados do PEDIDO e o vinculo de cada modelo com eles.
 *
 * Duas consultas pequenas, uma por tabela. O `csv_data` vem junto porque e ele
 * que o desenho precisa, e e a mesma ordem de grandeza do que o
 * `garantirCsvDaNumeracao` ja baixa hoje.
 *
 * Pedido sem nenhum banco proprio devolve as duas estruturas vazias, e todo
 * modelo dele segue pelo caminho de sempre — que e o caso de 100% dos pedidos
 * ate a Etapa 2 existir. Ver `docs/superpowers/plans/2026-08-27-peca-e-banco-etapa-1.md`.
 */
async function carregarBancosDoPedidoNovo(osId, idInt) {
    if (!Array.isArray(state.bancosDoPedido)) state.bancosDoPedido = [];
    if (!state.vinculosDeBanco) state.vinculosDeBanco = {};
    if (typeof supabaseClient === 'undefined' || !supabaseClient || !idInt) return 0;

    const { data: bancos, error: e1 } = await supabaseClient
        .from('pedidos_bancos').select('*').eq('id_int', idInt);
    if (e1) throw e1;
    state.bancosDoPedido = bancos || [];
    if (!state.bancosDoPedido.length) { state.vinculosDeBanco = {}; return 0; }

    const ids = state.bancosDoPedido.map(b => b.id);
    const { data: vinculos, error: e2 } = await supabaseClient
        .from('pedidos_modelos_banco').select('*').in('banco_id', ids);
    if (e2) throw e2;
    const mapa = {};
    (vinculos || []).forEach(v => { if (v && v.modelo_id) mapa[String(v.modelo_id)] = v; });
    state.vinculosDeBanco = mapa;
    return state.bancosDoPedido.length;
}
window.carregarBancosDoPedidoNovo = carregarBancosDoPedidoNovo;

/**
 * Modelo com vinculo de banco cujo banco NAO chegou. Lista vazia = pode imprimir.
 *
 * Mesma armadilha que o `garantirCsvDoTrabalho` tapa do outro lado: o motor
 * decide entre banco e numeracao SEQUENCIAL pelo tamanho de `rows`, entao um
 * banco que nao desceu sai como numero impresso no lugar do nome da pessoa, sem
 * erro em tela nenhuma. Aqui a falta e visivel e vira recusa, nao silencio.
 */
/**
 * Os modelos do trabalho da tela cujo banco do pedido nao chegou.
 *
 * Olha os mesmos pedidos que o `idsDeNumeracaoDoTrabalho` olha: a selecao
 * multipla e o modelo aberto.
 */
function modelosSemBancoDoTrabalho() {
    let fora = [];
    osIdsDoTrabalho().forEach(osId => { fora = fora.concat(modelosComBancoNaoBaixado(osId)); });
    return fora;
}
window.modelosSemBancoDoTrabalho = modelosSemBancoDoTrabalho;

/**
 * Os modelos DESTA imposição parados em "Corrigir Arte".
 *
 * Só os que vão para o papel agora — `itensDaImposicao` — e não o pedido
 * inteiro: a decisão do usuário em 02/09/2026 foi que a marca trava aquele
 * modelo e deixa os outros do mesmo pedido imprimindo. Um pedido de credenciais
 * com dez modelos não pode parar inteiro porque um deles tem a arte errada.
 */
function modelosEmCorrecaoDeArte() {
    return itensDaImposicao((state.selectedOSItems || []).length > 1)
        .filter(it => modeloEmCorrecaoDeArte(it));
}
window.modelosEmCorrecaoDeArte = modelosEmCorrecaoDeArte;

/**
 * De quais PEDIDOS sai o trabalho da tela atual: a selecao multipla e o modelo
 * aberto. Os mesmos que o `idsDeNumeracaoDoTrabalho` olha.
 *
 * Estava escrito tres vezes, quase igual. Vale uma definicao so pelo motivo de
 * sempre neste projeto: duas definicoes de "quais pedidos" divergem no dia em
 * que uma delas mudar, e o sintoma seria a trava conferindo um pedido enquanto
 * a carga busca outro -- uma ponta esperando o que a outra nunca manda.
 */
function osIdsDoTrabalho() {
    const osIds = new Set();
    (state.selectedOSItems || []).forEach(sel => { if (sel && sel.osId) osIds.add(sel.osId); });
    if (state.activeOSItem && state.activeOSItem.osId) osIds.add(state.activeOSItem.osId);
    return Array.from(osIds);
}
window.osIdsDoTrabalho = osIdsDoTrabalho;

function modelosComBancoNaoBaixado(osId) {
    const itens = (state.osItens && state.osItens[osId]) || [];
    if (!window.BancoDoModelo) return [];
    return itens.filter(it => {
        const v = vinculoDeBancoDoModelo(it);
        if (!v) return false;
        return !window.BancoDoModelo.bancoDoModelo(v, state.bancosDoPedido || []);
    });
}
window.modelosComBancoNaoBaixado = modelosComBancoNaoBaixado;

/**
 * Os modelos do trabalho com elemento de banco SEM coluna apontada — ou
 * apontada para coluna que o banco do modelo nao tem.
 *
 * Existe por causa da peca nova (28/08/2026), que nao escolhe coluna: cada
 * elemento e apontado no modelo, no 🔤 Colunas. Elemento sem apontamento
 * imprime VAZIO, sem erro em tela nenhuma — entao a impressao recusa e diz
 * onde apontar. So conta modelo com vinculo de banco: o caminho legado (CSV
 * dentro da peca) continua com os avisos de sempre.
 */
function modelosComElementoSemColuna() {
    if (!window.BancoDoModelo) return [];
    const fora = [];
    osIdsDoTrabalho().forEach(osId => {
        ((state.osItens && state.osItens[osId]) || []).forEach(it => {
            const v = vinculoDeBancoDoModelo(it);
            if (!v) return;
            const banco = window.BancoDoModelo.bancoDoModelo(v, state.bancosDoPedido || []);
            if (!banco) return;   // esse caso e da trava do banco nao baixado
            const soltos = window.BancoDoModelo.elementosSemColunaNoBanco(
                pecaDoModelo(it), banco, v.csv_mapa);
            if (soltos.length) fora.push(it);
        });
    });
    return fora;
}
window.modelosComElementoSemColuna = modelosComElementoSemColuna;

/**
 * A peca CRUA do catalogo, sem o banco do pedido nem o mapa de colunas.
 *
 * O `numeracaoDoModelo` devolve a resolvida, que e o que serve para desenhar e
 * imprimir. Quem precisa desta e quem fala das colunas que a peca PEDE -- o
 * modal de Colunas -- porque na resolvida elas ja estao trocadas.
 */
function pecaDoModelo(item) {
    const nid = numeracaoIdDoItem(item);
    if (!nid) return null;
    return (state.numeracoes || []).find(n => String(n.id) === String(nid)) || null;
}
window.pecaDoModelo = pecaDoModelo;

/**
 * De qual POCO de linhas este modelo bebe: o banco do pedido, quando ha
 * vinculo, ou o CSV de dentro da numeracao, como sempre.
 *
 * Existe porque a distribuicao de linhas (o "🧩 Linhas") sempre agrupou os
 * modelos pelo id da NUMERACAO. Com o banco do pedido isso passou a estar
 * errado de duas maneiras, e a segunda estraga trabalho: o modal abriria as
 * linhas da numeracao e gravaria em `csv_selecao` os `__id` de um banco que
 * este modelo nao imprime. O modelo passaria a levar as linhas erradas -- ou
 * nenhuma -- sem nada na tela dizendo por que.
 *
 * A `chave` e o que agrupa: dois modelos so aparecem no mesmo modal de
 * distribuicao quando bebem do MESMO poco.
 */
function fonteDoModelo(item) {
    const vinc = vinculoDeBancoDoModelo(item);
    const banco = window.BancoDoModelo
        ? window.BancoDoModelo.bancoDoModelo(vinc, state.bancosDoPedido || [])
        : null;

    if (vinc && banco) {
        return {
            chave: 'banco:' + banco.id, tipo: 'banco', id: banco.id,
            headers: banco.csv_headers || [], rows: banco.csv_data || [],
            filename: banco.csv_filename || (banco.nome || 'banco') + '.csv',
            nome: banco.nome || banco.csv_filename || 'banco do pedido'
        };
    }
    // Vinculo sem banco na mao NAO vira "a numeracao": seria o modal abrindo o
    // poco errado. Quem barra e a trava do `modelosComBancoNaoBaixado`.
    if (vinc) return null;

    const num = pecaDoModelo(item);
    if (!num || !Array.isArray(num.csv_data) || !num.csv_data.length) return null;
    return {
        chave: 'num:' + num.id, tipo: 'numeracao', id: num.id, num,
        headers: num.csv_headers || [], rows: num.csv_data,
        filename: num.csv_filename || 'banco.csv',
        nome: num.csv_filename || num.name || 'numeração'
    };
}
window.fonteDoModelo = fonteDoModelo;

/** A fonte de uma chave (`banco:<id>` ou `num:<id>`), sem precisar de um modelo. */
function fontePelaChave(chave) {
    const texto = String(chave || '');
    if (texto.indexOf('banco:') === 0) {
        const b = (state.bancosDoPedido || []).find(x => String(x.id) === texto.slice(6));
        if (!b) return null;
        return {
            chave: texto, tipo: 'banco', id: b.id,
            headers: b.csv_headers || [], rows: b.csv_data || [],
            filename: b.csv_filename || (b.nome || 'banco') + '.csv',
            nome: b.nome || b.csv_filename || 'banco do pedido'
        };
    }
    // Sem prefixo é o id de uma numeração — o formato antigo, que continua
    // valendo para quem chama de fora com o id na mão.
    const id = texto.indexOf('num:') === 0 ? texto.slice(4) : texto;
    const num = (state.numeracoes || []).find(n => String(n.id) === String(id));
    if (!num || !Array.isArray(num.csv_data) || !num.csv_data.length) return null;
    return {
        chave: 'num:' + num.id, tipo: 'numeracao', id: num.id, num,
        headers: num.csv_headers || [], rows: num.csv_data,
        filename: num.csv_filename || 'banco.csv',
        nome: num.csv_filename || num.name || 'numeração'
    };
}
window.fontePelaChave = fontePelaChave;

/** Grava as linhas de volta no lugar de onde elas vieram. */
async function salvarLinhasDaFonte(fonte, rows) {
    if (!fonte) return;
    if (fonte.tipo === 'banco') {
        const { error } = await supabaseClient.from('pedidos_bancos')
            .update({ csv_data: rows, updated_at: new Date().toISOString() })
            .eq('id', fonte.id);
        if (error) throw error;
        const b = (state.bancosDoPedido || []).find(x => String(x.id) === String(fonte.id));
        if (b) b.csv_data = rows;
        return;
    }
    if (fonte.num) fonte.num.csv_data = rows;
    await salvarCsvDaNumeracao(fonte.id, rows);
}
window.salvarLinhasDaFonte = salvarLinhasDaFonte;

/**
 * Escapa texto que vai para dentro de HTML montado a mao.
 *
 * Existe porque o `esc` deste arquivo e uma const LOCAL de outra funcao, e nome
 * de banco e nome de coluna vem de arquivo do cliente: um `<` no cabecalho de
 * um CSV quebraria o modal, e um `<script>` faria pior.
 */
function escDoBanco(s) {
    return String(s === null || s === undefined ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
window.escDoBanco = escDoBanco;

/**
 * Cria um banco do pedido a partir de um CSV ja lido. Devolve o registro
 * gravado, ja dentro de `state.bancosDoPedido`.
 *
 * `garantirIds` antes de gravar, e nao depois: o `__id` e a identidade que a
 * distribuicao de linhas guarda. Linha sem id gravada no banco faria a fatia de
 * um modelo apontar para o vazio na proxima abertura do pedido.
 */
async function criarBancoDoPedido(idInt, nome, headers, rows, filename, csvUrl) {
    if (!supabaseClient) throw new Error('Sem conexão com o banco.');
    if (!idInt) throw new Error('Não sei de qual pedido é este banco.');
    if (!Array.isArray(rows) || !rows.length) throw new Error('O arquivo não tem nenhuma linha.');
    if (window.CsvEditor) window.CsvEditor.garantirIds(rows);

    const { data, error } = await supabaseClient.from('pedidos_bancos').insert({
        id_int: idInt,
        nome: String(nome || filename || 'banco').slice(0, 120),
        csv_filename: String(filename || ''),
        csv_headers: headers || [],
        csv_data: rows,
        // O link da planilha fica no banco: e ele que o "🔄 Planilha" usa para
        // trazer o conteudo de novo, meses depois.
        csv_url: String(csvUrl || '')
    }).select().single();
    if (error) throw error;

    if (!Array.isArray(state.bancosDoPedido)) state.bancosDoPedido = [];
    state.bancosDoPedido.push(data);
    return data;
}
window.criarBancoDoPedido = criarBancoDoPedido;

/**
 * Liga um modelo a um banco do pedido, ou o desliga (bancoId nulo).
 *
 * Desligar apaga a linha inteira, e nao so o `banco_id`: sem banco nao ha mapa
 * de colunas que faca sentido, e uma linha com os dois campos vazios diria
 * "este modelo tem vinculo" para a trava do `modelosComBancoNaoBaixado`.
 */
async function ligarModeloAoBanco(itemId, bancoId, mapa) {
    if (!supabaseClient) throw new Error('Sem conexão com o banco.');
    if (!state.vinculosDeBanco) state.vinculosDeBanco = {};
    const chave = String(itemId);

    if (!bancoId) {
        const { error } = await supabaseClient.from('pedidos_modelos_banco')
            .delete().eq('modelo_id', itemId);
        if (error) throw error;
        delete state.vinculosDeBanco[chave];
        return null;
    }

    const linha = { modelo_id: itemId, banco_id: bancoId, csv_mapa: mapa || null };
    const { data, error } = await supabaseClient.from('pedidos_modelos_banco')
        .upsert(linha, { onConflict: 'modelo_id' }).select().single();
    if (error) throw error;
    state.vinculosDeBanco[chave] = data;
    return data;
}
window.ligarModeloAoBanco = ligarModeloAoBanco;

async function carregarBancosDoPedido(osId, aoChegar) {
    // Os bancos proprios do pedido primeiro. Se a consulta falhar — tabela
    // ainda nao criada, rede fora — o pedido segue pelo caminho de sempre, que
    // e o comportamento correto: ausencia de vinculo significa banco de dentro
    // da numeracao.
    try { await carregarBancosDoPedidoNovo(osId, idIntDoPedido(osId)); } catch (e) { /* segue */ }

    const faltando = numeracoesSemBancoBaixado(osId);
    let baixadas = 0;
    for (const num of faltando) {
        try { await garantirCsvDaNumeracao(num); } catch (e) { /* segue */ }
        baixadas++;
        if (typeof aoChegar === 'function') { try { aoChegar(num, baixadas, faltando.length); } catch (e) {} }
    }
    return baixadas;
}
window.carregarBancosDoPedido = carregarBancosDoPedido;

/**
 * O banco de dados de todas as numeracoes que um trabalho pode usar, na mao
 * antes de o payload ser montado.
 *
 * ## Por que isto e uma trava, e nao uma otimizacao
 *
 * O motor decide entre banco e numeracao SEQUENCIAL pelo tamanho de `rows`.
 * Uma numeracao cujo `csv_data` ainda nao desceu chega com zero linhas e e
 * indistinguivel de uma sem banco nenhum: o trabalho sai com numero impresso
 * no lugar do nome da pessoa, sem erro em tela nenhuma e sem ninguem
 * descobrir antes do papel. Enquanto o catalogo vinha com `select('*')` isso
 * era impossivel por acidente; desde 26/08/2026 e possivel, e por isso passa
 * a haver uma linha explicita que impede.
 *
 * Uma por vez e em serie, de proposito: sao poucas (as do pedido aberto), e
 * as que ja estao em memoria voltam na hora, sem tocar a rede.
 */
async function garantirCsvDoTrabalho(ids) {
    const unicos = Array.from(new Set((ids || []).filter(Boolean).map(String)));
    for (const id of unicos) {
        const num = (state.numeracoes || []).find(n => String(n.id) === id);
        if (num) await garantirCsvDaNumeracao(num);
    }
}
window.garantirCsvDoTrabalho = garantirCsvDoTrabalho;

/**
 * Os bancos do PEDIDO na mao antes de o payload ser montado.
 *
 * ## O defeito que isto conserta (01/09/2026)
 *
 * O `garantirCsvDoTrabalho` acima cobre o banco que mora DENTRO da numeracao.
 * O banco que e do pedido (`pedidos_bancos` + `pedidos_modelos_banco`, desde
 * 27/08/2026) nao tinha o equivalente: ele so era carregado pela tela de
 * Amostras, dentro do `renderAmostrasOSItens`, sob a condicao
 * `containerId === 'amostras-itens-container'`.
 *
 * Quem abrisse a tela do Pedido e mandasse imprimir sem passar por Amostras
 * tinha `bancosDoPedido` e `vinculosDeBanco` vazios. Sem vinculo, o
 * `resolverNumeracaoParaModelo` devolve a peca CRUA -- `csv_data` nulo e o
 * `csv_column` do elemento vazio --, o motor recebe zero linhas e o ramo final
 * do `_render_element` imprime o NUMERO SEQUENCIAL dentro do QR. Foi o que o
 * usuario viu no pedido 21460, nos tres botoes: imposicao, impressao e PDF.
 *
 * A trava que devia impedir isso estava cega pelo mesmo motivo: ela parte do
 * `vinculoDeBancoDoModelo`, que le o mesmo `state.vinculosDeBanco` que nunca
 * foi carregado. "Nunca olhei" e "nao tem banco" davam a mesma resposta.
 *
 * Nunca lanca: quem recusa o trabalho e o `pedidosComBancoDesconhecido` logo
 * abaixo, que sabe dizer ao operador o que fazer.
 *
 * ## A recaida, e o que faltava (02/09/2026)
 *
 * O 21460 voltou a sair com numero sequencial no QR, com o conserto acima ja no
 * ar. A marca `_bancosConsultados` dizia "ja perguntei por este pedido", e isso
 * bastava para pular a carga -- mas ela sobrevivia ao que certificava:
 *
 *   1. o operador imprime o 21460: a carga roda, os bancos entram no state;
 *   2. ele abre OUTRO pedido na tela de Amostras. O `renderAmostrasOSItens`
 *      esvazia `bancosDoPedido` e `vinculosDeBanco` de proposito -- manter os
 *      do anterior ofereceria, no card do novo, um banco que nao e do trabalho;
 *   3. ele volta ao 21460 e manda imprimir. A marca continua la, a carga e
 *      pulada, e o payload sai sem uma linha sequer.
 *
 * Medido no navegador, contra o banco de verdade: passo 1 devolve 3.000 linhas
 * e a coluna EXPOSITOR; passo 3, ZERO linhas e coluna vazia -- e as travas
 * deixavam passar, porque para elas o pedido estava "consultado".
 *
 * A licao e sobre a marca, nao sobre a carga: memoria de "ja perguntei" so vale
 * enquanto a RESPOSTA continua na mao. Quem sabe disso e o `_bancosPedidoDe`,
 * que a propria tela de Amostras mantem apontando para o pedido cujos bancos
 * estao carregados. Ele passou a ser a unica autorizacao para pular, e a marca
 * antiga e apagada antes de cada nova tentativa -- senao uma carga que falhasse
 * herdaria o "pode imprimir" da carga bem-sucedida de meia hora atras.
 */
async function garantirBancosDoTrabalho(osIds) {
    state._bancosConsultados = state._bancosConsultados || {};
    for (const osId of Array.from(new Set((osIds || []).filter(Boolean).map(String)))) {
        // A UNICA autorizacao para pular a carga: os bancos deste pedido estao
        // carregados agora. Vale tanto para o que a tela de Amostras baixou
        // quanto para o que esta funcao baixou da ultima vez -- e para de valer
        // no instante em que outro pedido toma o lugar.
        if (String(state._bancosPedidoDe) === osId) { state._bancosConsultados[osId] = true; continue; }
        // Daqui para baixo o pedido volta a ser "nao sei" ate a carga terminar.
        // Sem isto, a marca de uma carga antiga faria a trava responder "pode
        // imprimir" sobre um state que ja foi esvaziado.
        delete state._bancosConsultados[osId];
        const idInt = idIntDoPedido(osId);
        // Sem o numero da OS nao ha o que consultar -- e nao ha o que travar:
        // os itens chegam depois do primeiro desenho, e isso acontece de verdade.
        if (!idInt) continue;
        // Sem cliente nao ha A QUEM perguntar (modo offline, `?local=true`, a
        // marca em localStorage). Marcar como consultado aqui recriaria o
        // defeito calado: o `carregarBancosDoPedidoNovo` devolve 0 nesse caso,
        // que e indistinguivel de "este pedido nao tem banco".
        if (typeof supabaseClient === 'undefined' || !supabaseClient) continue;
        try {
            await carregarBancosDoPedidoNovo(osId, idInt);
            state._bancosConsultados[osId] = true;
            state._bancosPedidoDe = osId;
        } catch (e) {
            // Fica sem a marca de proposito: e ela que separa "consultei e nao
            // ha bancos" de "nao consegui consultar".
        }
    }
}
window.garantirBancosDoTrabalho = garantirBancosDoTrabalho;

/**
 * A ultima conferencia, sobre o payload PRONTO: o que vai sair com campo de
 * banco vazio (02/09/2026).
 *
 * As travas de cima olham o `state` -- quais pedidos foram consultados, quais
 * vinculos existem. Esta olha o que esta REALMENTE indo ao motor, e por isso
 * pega o que elas nao alcancam: a aba Imposicao, onde o operador escolhe uma
 * numeracao na lista e monta a folha sem modelo nenhum.
 *
 * E o caso do 21460. A peca "Expointer 2026" nao guarda dado nenhum
 * (`csv_data` nulo, `csv_column` vazio de proposito): o banco e do PEDIDO, e
 * quem diz qual coluna cada campo le e o MODELO, pelo `csv_mapa`. Cinco modelos
 * compartilham essa mesma peca, cada um com a sua coluna. Fora do pedido nao ha
 * o que resolver -- e adivinhar seria pior que parar: imprimiria a credencial de
 * um setor com o codigo de outro.
 *
 * Antes disto o trabalho seguia ate o motor e voltava com a recusa dele, que
 * fala de `el_1` e de `csv_row`. Aqui a recusa e na tela, com o nome da
 * numeracao e a saida.
 */
function bancoVazioNoPayload(numeracaoUnica, artes) {
    const fora = [];
    const olhar = (num, rotulo) => {
        if (!num) return;
        const pedeBanco = (num.elements || []).some(el => el && el.source === 'database');
        if (!pedeBanco) return;
        if ((num.csv_data || []).length) return;
        const nome = String(rotulo || num.name || 'numeração').trim();
        if (fora.indexOf(nome) === -1) fora.push(nome);
    };
    olhar(numeracaoUnica, null);
    (artes || []).forEach(a => olhar(a && a.numeracao, a && a.nome));
    return fora;
}
window.bancoVazioNoPayload = bancoVazioNoPayload;

/**
 * O recado de quem foi barrado pelo `bancoVazioNoPayload`.
 *
 * Diz a saída, que é sempre a mesma: imprimir a partir do MODELO. Não há como
 * esta tela adivinhar a coluna — no 21460 são cinco modelos na mesma peça, cada
 * um lendo a sua —, e chutar imprimiria a credencial de um setor com o código de
 * outro.
 */
function recadoDeBancoVazio(nomes) {
    return 'A numeração ' + nomes.map(n => '"' + n + '"').join(', ')
        + ' lê os dados de um banco do pedido, e este trabalho chegou sem nenhuma linha. '
        + 'Ela só imprime a partir do modelo: abra o pedido, escolha o modelo e mande '
        + 'imprimir por lá — é o modelo que diz qual coluna do banco cada campo lê. '
        + 'Imprimir daqui sairia com número sequencial no lugar do código.';
}
window.recadoDeBancoVazio = recadoDeBancoVazio;

/**
 * Os pedidos do trabalho cujos vinculos de banco NAO se sabe se existem.
 *
 * Lista vazia depois do `garantirBancosDoTrabalho` significa "consultei todos":
 * dai em diante, pedido sem vinculo e pedido que realmente nao tem banco, e as
 * travas seguintes voltam a enxergar. Com a consulta falhada a lista vem cheia,
 * e a impressao para -- porque imprimir ali sairia com numero sequencial no
 * lugar do codigo, calado, que e o pior desfecho possivel.
 */
function pedidosComBancoDesconhecido(osIds) {
    const consultados = state._bancosConsultados || {};
    return Array.from(new Set((osIds || []).filter(Boolean).map(String)))
        .filter(osId => idIntDoPedido(osId) && !consultados[osId]);
}
window.pedidosComBancoDesconhecido = pedidosComBancoDesconhecido;

/**
 * Os modelos que DEPENDEM de um banco que nao se conseguiu consultar.
 *
 * A recusa nao pode ser "este pedido tem banco desconhecido", porque numa
 * estacao em modo offline isso seria TODO pedido -- e a gráfica pararia de
 * imprimir o que sempre imprimiu. Fica sendo, entao, so' o modelo que nao tem
 * como sair certo:
 *
 *   · a peca dele pede banco (`source: 'database'` em algum elemento), E
 *   · a propria peca nao traz linha nenhuma.
 *
 * Nesse cruzamento o dado so' pode vir do banco do pedido. Sem ter conseguido
 * perguntar, imprimir ali sai com numero sequencial dentro do QR, calado --
 * exatamente o 21460. Fora dele, nada muda: numeracao sem campo de banco e
 * numeracao com o CSV dentro dela seguem imprimindo offline como sempre.
 */
function modelosComBancoNaoConferido() {
    const desconhecidos = new Set(pedidosComBancoDesconhecido(osIdsDoTrabalho()).map(String));
    if (!desconhecidos.size) return [];
    const fora = [];
    osIdsDoTrabalho().forEach(osId => {
        if (!desconhecidos.has(String(osId))) return;
        ((state.osItens && state.osItens[osId]) || []).forEach(it => {
            const num = typeof pecaDoModelo === 'function' ? pecaDoModelo(it) : null;
            if (!num) return;
            const pedeBanco = (num.elements || []).some(el => el && el.source === 'database');
            const temLinhaPropria = !!(num.csv_data && num.csv_data.length);
            if (pedeBanco && !temLinhaPropria) fora.push(it);
        });
    });
    return fora;
}
window.modelosComBancoNaoConferido = modelosComBancoNaoConferido;

/** Os ids de numeracao que o trabalho da tela atual pode usar. */
function idsDeNumeracaoDoTrabalho(idDoSelect) {
    const doItem = it => it && (it.amostra_num_id || it.numeracao_id);
    const ids = (state.selectedOSItems || []).map(sel => doItem(
        ((state.osItens && state.osItens[sel.osId]) || [])
            .find(i => String(i.id) === String(sel.itemId))));
    const ativo = state.activeOSItem;
    if (ativo) {
        ids.push(doItem(((state.osItens && state.osItens[ativo.osId]) || [])
            .find(i => String(i.id) === String(ativo.itemId))));
    }
    const sel = idDoSelect && document.getElementById(idDoSelect);
    if (sel && sel.value) ids.push(sel.value);
    return ids;
}
window.idsDeNumeracaoDoTrabalho = idsDeNumeracaoDoTrabalho;

/** Baixa o PDF de referência da cor no clique — o catálogo não o traz. */
window.baixarPdfDaCor = async function (id, face) {
    const cor = (state.cores || []).find(c => String(c.id) === String(id));
    if (!cor) return;
    await garantirPdfDaCor(cor);
    const dados = (face === 'verso') ? cor.pdf_verso_base64 : cor.pdf_base64;
    if (!dados) {
        toast('Esta cor nao tem PDF de referencia gravado.', 'error');
        return;
    }
    const a = document.createElement('a');
    a.href = dados;
    a.download = (face === 'verso')
        ? (cor.name_verso || 'referencia_verso.pdf')
        : (cor.pdf_filename || 'referencia_frente.pdf');
    document.body.appendChild(a);
    a.click();
    a.remove();
};

/**
 * Deixa uma linha de `producao_numeracoes` lida do banco com a forma que o
 * resto do painel espera: SEM o elemento METADATA dentro de `elements`, e com
 * `print_mode` preenchido (da coluna ou, na falta dela, do proprio METADATA).
 *
 * Existe como funcao porque a mesma leitura acontece em tres lugares — a lista
 * do catalogo, uma numeracao por id, e a releitura das numeracoes de um pedido
 * (`recarregarNumeracoesDoPedido`) — e em 22/08/2026 a terceira entrou sem
 * isto: a linha crua, com o METADATA ainda dentro, ia para `state.numeracoes`,
 * e o editor de numeracao a recebia no lapis do card com um elemento a mais.
 * Altera e devolve a mesma linha.
 */
function normalizarNumeracaoLida(n) {
    if (!n) return n;
    if (n.elements && Array.isArray(n.elements)) {
        const metadataEl = n.elements.find(el => el && el.type === 'METADATA');
        if (metadataEl) {
            // Se a coluna nao tem print_mode, extrair do METADATA
            if (!n.print_mode || n.print_mode === 'front') {
                if (metadataEl.print_mode) n.print_mode = metadataEl.print_mode;
            }
            n.elements = n.elements.filter(el => !el || el.type !== 'METADATA');
        }
    }
    if (!n.print_mode) n.print_mode = 'front';
    return n;
}
window.normalizarNumeracaoLida = normalizarNumeracaoLida;

async function api(method, path, body = null) {

    if (typeof supabaseClient !== 'undefined' && supabaseClient && (path.startsWith('/formatos') || path.startsWith('/numeracoes') || path.startsWith('/saidas') || path.startsWith('/cores') || path.startsWith('/modelos_imposicao'))) {

        const parts = path.substring(1).split('/');

        let col = parts[0];
        // Adicionar o prefixo producao_ exigido pelo parceiro Vibecode
        if (col === 'modelos_imposicao') {
            col = 'producao_modelos_imposicao';
        } else {
            col = 'producao_' + col;
        }

        const docId = parts[1] || null;



        try {

            if (method === 'GET') {

                if (docId) {

                    const { data, error } = await supabaseClient.from(col).select('*').eq('id', docId).single();

                    if (error) throw error;

                    if (col === 'modelos_imposicao' && data) {

                        return { id: data.id, name: data.name, ...data.config };

                    }

                    if (col === 'producao_numeracoes' && data) {
                        normalizarNumeracaoLida(data);   // sem METADATA, com print_mode
                    }

                    return data;

                } else {

                    // Cores sem os PDFs, numerações sem o banco de dados — ver as duas
                    // constantes no topo. Nos dois casos a coluna pesada desce depois,
                    // uma por vez, por `garantirPdfDaCor` / `garantirCsvDaNumeracao`.
                    const colunas = (col === 'producao_cores') ? COLUNAS_DA_COR_NA_LISTA
                        : (col === 'producao_numeracoes') ? COLUNAS_DA_NUMERACAO_NA_LISTA
                        : '*';
                    // Catálogo relido é catálogo novo: o que já se baixou de `csv_data`
                    // não vale mais para estas linhas, que voltam com ele em `undefined`.
                    if (col === 'producao_numeracoes') _csvDaNumeracaoEmVoo.clear();

                    // ORDEM FIXA para o catálogo de numerações.
                    //
                    // Sem `order`, o Postgres devolve na ordem FÍSICA do heap, e
                    // um UPDATE grava uma versão nova da linha e a MOVE de lugar.
                    // Com dois registros de mesmo nome — e `producao_numeracoes`
                    // não tem UNIQUE em `name` —, qualquer `.find()` por nome
                    // passava a devolver ora um, ora outro, conforme quem tinha
                    // sido salvo por último. Foi assim que um modelo ficou
                    // trocando de numeração sozinho (25/08/2026).
                    //
                    // Quem lê por id não depende disto, e o `saveNumeracao` já
                    // não lê por nome. A ordem fica como segunda linha de
                    // defesa: o próximo leitor encontra sempre a mesma lista.
                    //
                    // `id`, e não `name`: é a chave primária, nunca é nula e
                    // nunca empata. Ordenar por nome deixaria justamente as
                    // homônimas em ordem indefinida entre si.
                    const consulta = supabaseClient.from(col).select(colunas);
                    if (col === 'producao_numeracoes') consulta.order('id');

                    const { data, error } = await consulta;

                    if (error) throw error;

                    if (col === 'modelos_imposicao' && data) {

                        return data.map(item => ({ id: item.id, name: item.name, ...item.config }));

                    }

                    if (col === 'producao_numeracoes' && data) {
                        data.forEach(normalizarNumeracaoLida);   // sem METADATA, com print_mode
                    }

                    return data;

                }

            } else if (method === 'POST') {

                let id = body.id;
                if (!id) {
                    if (typeof supabaseClient !== 'undefined' && supabaseClient) {
                        id = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
                            var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                            return v.toString(16);
                        });
                    } else {
                        id = col.substring(0,3) + '_' + Date.now().toString(36) + Math.random().toString(36).substring(2,6);
                    }
                }

                let insertPayload;

                if (col === 'modelos_imposicao') {

                    const { name, ...configData } = body;

                    insertPayload = { id, name, config: configData };

                } else {

                    insertPayload = { id, ...body };

                }

                let { data, error } = await supabaseClient.from(col).insert([insertPayload]).select().single();

                if (error && (error.message || '').includes("Could not find the '")) {
                    const match = (error.message || '').match(/Could not find the '(.*?)' column/);
                    if (match && match[1]) {
                        const missingCol = match[1];
                        console.warn(`[api] Coluna '${missingCol}' ausente na tabela '${col}'. Tratando graciosamente...`);
                        delete insertPayload[missingCol];
                        const retryRes = await supabaseClient.from(col).insert([insertPayload]).select().single();
                        data = retryRes.data;
                        error = retryRes.error;
                    }
                }

                if (error) throw error;

                return { id: data ? data.id : id };

            } else if (method === 'PUT') {

                if (!docId) throw new Error('ID ausente para atualização');

                let updateData;

                if (col === 'modelos_imposicao') {

                    const { name, ...configData } = body;

                    updateData = { name, config: configData };

                } else {

                    updateData = { ...body };

                    delete updateData.id;

                }

                let { error } = await supabaseClient.from(col).update(updateData).eq('id', docId);

                if (error && (error.message || '').includes("Could not find the '")) {
                    const match = (error.message || '').match(/Could not find the '(.*?)' column/);
                    if (match && match[1]) {
                        const missingCol = match[1];
                        console.warn(`[api] Coluna '${missingCol}' ausente na tabela '${col}'. Tratando graciosamente...`);
                        delete updateData[missingCol];
                        const retryRes = await supabaseClient.from(col).update(updateData).eq('id', docId);
                        error = retryRes.error;
                    }
                }

                if (error) throw error;

                return { status: 'success' };

            } else if (method === 'DELETE') {

                if (!docId) throw new Error('ID ausente para exclusão');

                const { error } = await supabaseClient.from(col).delete().eq('id', docId);

                if (error) throw error;

                return { status: 'success' };

            }

        } catch (e) {

            console.error(`Erro no Supabase (${method} ${path}):`, e);

            throw new Error(`Erro no Banco de Dados: ${e.message}`);

        }

    }



    const baseUrl = typeof API_BASE_URL !== 'undefined' ? API_BASE_URL : '';

    const opts = { method, headers: {} };

    if (body) { opts.headers['Content-Type'] = 'application/json'; opts.body = JSON.stringify(body); }

    

    const res = await fetch(`${baseUrl}/api${path}`, opts);

    if (!res.ok) {

        const err = await res.json().catch(() => ({ detail: 'Erro desconhecido' }));

        throw new Error(err.detail || `HTTP ${res.status}`);

    }

    return res.json().catch(() => ({}));

}





// - Load All Data -

async function loadAll() {

    try {

        const [fmts, nums, sais, cores, modelos, vibeProdutos] = await Promise.all([
            api('GET', '/formatos'),
            api('GET', '/numeracoes'),
            api('GET', '/saidas'),
            api('GET', '/cores').catch(() => []),
            api('GET', '/modelos_imposicao').catch(() => []),
            (typeof vibeClient !== 'undefined' && vibeClient ? vibeClient.from('produtos').select('*') : Promise.resolve({data:[]}))
                .then(r => {
                    if (r && r.error) {
                        console.error('[loadAll] Erro ao buscar produtos:', r.error);
                    }
                    console.log('[loadAll] vibeProdutos carregados:', r ? (r.data ? r.data.length : 0) : 0);
                    return r ? r.data : [];
                })
                .catch(err => {
                    console.error('[loadAll] Exception ao buscar produtos:', err);
                    return [];
                })
        ]);

        state.formatos = fmts;

        state.numeracoes = nums;

        state.saidas = sais;

        state.cores = cores || [];
        try {
            const localRefMap = JSON.parse(localStorage.getItem('ideal_cores_referencia_map') || '{}');
            state.cores.forEach(c => {
                if (localRefMap[c.id]) {
                    c.cor_referencia = localRefMap[c.id];
                }
            });
        } catch(e) {}

        state.modelosImposicao = modelos || [];
        state.produtosGlobais = vibeProdutos || [];

        // Os itens podem ter sido mapeados antes desta linha — é o caso comum,
        // porque as OS carregam por conta própria. Sem este reparo eles ficam
        // sem setor para sempre e os filtros de setor não devolvem nada.
        const _reparados = repararSetoresDosItens();
        if (_reparados) {
            console.log(`[loadAll] Setor preenchido em ${_reparados} item(ns) mapeado(s) antes dos produtos chegarem.`);
        }

        // O limiar da sobra e a lista de produtos que podem dividir folha entre
        // pedidos. Vai depois do catálogo e sem `await` no caminho crítico: se
        // falhar, o selo cai no limiar padrão e a busca entre pedidos não acha
        // ninguém — nenhuma das duas coisas impede imprimir.
        if (typeof carregarConfigDeAproveitamento === 'function') {
            carregarConfigDeAproveitamento().catch(e =>
                console.warn('[loadAll] aproveitamento nao carregou:', e));
        }

        renderAll();
        if (typeof renderPedOSQueue === 'function') {
            console.log('[loadAll] Re-renderizando fila de pedidos após carregar produtos...');
            renderPedOSQueue();
        }

    } catch (e) {

        toast('Erro ao carregar dados: ' + e.message, 'error');

    }

}



function renderAll() {

    renderFormatos();

    renderNumeracoes();

    renderSaidas();

    renderCores();

    renderModelosImposicao();

    updateBadges();

    populateSelects();

}



function updateBadges() {

    document.getElementById('badge-formatos').textContent = state.formatos.length;

    document.getElementById('badge-numeracao').textContent = state.numeracoes.length;

    document.getElementById('badge-saidas').textContent = state.saidas.length;

    const badgeCores = document.getElementById('badge-cores');

    if (badgeCores) badgeCores.textContent = state.cores.length;

}



// - FORMATOS -

function renderFormatos() {

    const tbody = document.getElementById('tbody-formatos');

    const empty = document.getElementById('empty-formatos');

    if (!state.formatos.length) {

        tbody.innerHTML = '';

        empty.style.display = 'block';

        return;

    }

    empty.style.display = 'none';

    tbody.innerHTML = state.formatos.map(f => `

        <tr>

            <td>${f.name}</td>

            <td>${f.width_mm} × ${f.height_mm} mm</td>

            <td><span class="badge badge-blue">${f.cols} × ${f.rows}</span></td>

            <td>${f.gap_h_mm} × ${f.gap_v_mm} mm</td>

            <td class="actions-cell">

                <button class="btn btn-secondary btn-sm" onclick="duplicateFmt('${f.id}')" title="Duplicar Formato">⧉</button>

                <button class="btn btn-sm btn-ghost" onclick="editFmt('${f.id}')">✏️ Editar</button>

                <button class="btn btn-danger btn-sm" onclick="deleteFmt('${f.id}')">🗑️</button>

            </td>

        </tr>

    `).join('');

}



async function saveFmt() {

    const id = document.getElementById('fmt-id').value;



    // Validar campos de offset (aceita vírgula como separador decimal)

    const offhEl = document.getElementById('fmt-offh');

    const offvEl = document.getElementById('fmt-offv');

    const offH = validateOffsetField(offhEl);

    const offV = validateOffsetField(offvEl);

    if (offH === null || offV === null) return toast('Valor de offset inválido. Use números decimais (ex: 10,2).', 'error');



    const data = {

        name: document.getElementById('fmt-name').value.trim(),

        width_mm: parseFloat(document.getElementById('fmt-w').value),

        height_mm: parseFloat(document.getElementById('fmt-h').value),

        cols: parseInt(document.getElementById('fmt-cols').value),

        rows: parseInt(document.getElementById('fmt-rows').value),

        gap_h_mm: parseFloat(document.getElementById('fmt-gaph').value),

        gap_v_mm: parseFloat(document.getElementById('fmt-gapv').value),

        offset_h_mm: offH,

        offset_v_mm: offV,

        rotations: (() => {
            const r = { ...(state.fmtRotations || {}) };
            r.page_rotate = parseInt(document.getElementById('fmt-def-rotate').value) || 0;
            return r;
        })(),

        default_schema: document.getElementById('fmt-def-schema').value,

        default_saida_id: document.getElementById('fmt-def-saida').value || null,

        default_cut_stack_mode: document.getElementById('fmt-def-cut-stack-mode').value,

        default_sheets_per_block: parseInt(document.getElementById('fmt-def-sheets').value) || 50,

        default_block_depth: parseInt(document.getElementById('fmt-def-depth').value) || 1,

        default_rotate_page: (parseInt(document.getElementById('fmt-def-rotate').value) || 0) > 0,

        has_cover: document.getElementById('fmt-has-cover').checked,

        cover_scale: parseFloat(document.getElementById('fmt-cover-scale').value) || 80.0,

        cover_offset_x: parseFloat(document.getElementById('fmt-cover-offx').value) || 0,

        cover_offset_y: parseFloat(document.getElementById('fmt-cover-offy').value) || 0,

        cover_font_size: parseInt(document.getElementById('fmt-cover-font-size').value) || 12,

        cover_font_color: document.getElementById('fmt-cover-font-color').value || '#000000',

        cover_font_x: parseFloat(document.getElementById('fmt-cover-font-x').value) || 10.0,

        cover_font_y: parseFloat(document.getElementById('fmt-cover-font-y').value) || 10.0,

    };

    if (!data.name) return toast('Informe um nome para o formato.', 'error');

    try {

        if (id) {

            await api('PUT', `/formatos/${id}`, data);

            toast('Formato atualizado!', 'success');

        } else {

            await api('POST', '/formatos', data);

            toast('Formato salvo!', 'success');

        }

        cancelFmtEdit();

        await loadAll();

        // Redirecionar para Lista Formatos

        document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));

        document.querySelectorAll('.view-section').forEach(v => v.classList.remove('active'));

        ativarBotaoDoMenu('view-lista-formatos');

        document.getElementById('view-lista-formatos').classList.add('active');

    } catch (e) { toast(e.message, 'error'); }

}



function editFmt(id) {

    const f = state.formatos.find(x => x.id === id);

    if (!f) return;



    // Ativar view de formatos para edição

    document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));

    document.querySelectorAll('.view-section').forEach(v => v.classList.remove('active'));

    ativarBotaoDoMenu('view-formatos');

    document.getElementById('view-formatos').classList.add('active');



    document.getElementById('fmt-id').value = f.id;

    document.getElementById('fmt-name').value = f.name;

    document.getElementById('fmt-w').value = f.width_mm;

    document.getElementById('fmt-h').value = f.height_mm;

    document.getElementById('fmt-cols').value = f.cols;

    document.getElementById('fmt-rows').value = f.rows;

    document.getElementById('fmt-gaph').value = f.gap_h_mm;

    document.getElementById('fmt-gapv').value = f.gap_v_mm;

    document.getElementById('fmt-offh').value = (f.offset_h_mm || 0).toString().replace('.', ',');

    document.getElementById('fmt-offv').value = (f.offset_v_mm || 0).toString().replace('.', ',');

    document.getElementById('fmt-def-schema').value = f.default_schema || 'sequential';
    
    document.getElementById('fmt-def-saida').value = f.default_saida_id || '';
    
    document.getElementById('fmt-def-cut-stack-mode').value = f.default_cut_stack_mode || 'independent';
    
    document.getElementById('fmt-def-sheets').value = f.default_sheets_per_block || 50;
    
    document.getElementById('fmt-def-depth').value = f.default_block_depth || 1;
    
    (() => {
        const fRot = f.rotations || {};
        let rotVal = 0;
        if (fRot.page_rotate !== undefined) {
            rotVal = parseInt(fRot.page_rotate) || 0;
        } else {
            rotVal = f.default_rotate_page ? 90 : 0;
        }
        document.getElementById('fmt-def-rotate').value = String(rotVal);
    })();

    document.getElementById('fmt-has-cover').checked = !!f.has_cover;
    document.getElementById('fmt-cover-scale').value = f.cover_scale !== undefined ? f.cover_scale : 80;
    document.getElementById('fmt-cover-offx').value = f.cover_offset_x || 0;
    document.getElementById('fmt-cover-offy').value = f.cover_offset_y || 0;
    document.getElementById('fmt-cover-font-size').value = f.cover_font_size || 12;
    document.getElementById('fmt-cover-font-color').value = f.cover_font_color || '#000000';
    document.getElementById('fmt-cover-font-x').value = f.cover_font_x !== undefined ? f.cover_font_x : 10;
    document.getElementById('fmt-cover-font-y').value = f.cover_font_y !== undefined ? f.cover_font_y : 10;

    const cutStackOpts = document.getElementById('fmt-def-cut-stack-options');
    if (cutStackOpts) cutStackOpts.style.display = (f.default_schema === 'cut_stack') ? 'block' : 'none';
    
    const coverOpts = document.getElementById('fmt-cover-options');
    if (coverOpts) coverOpts.style.display = f.has_cover ? 'block' : 'none';

    state.fmtRotations = f.rotations || {};

    state.fmtSelectedCellIndex = null;

    updateRotationButtons();

    document.getElementById('fmt-form-title').textContent = 'Editar Formato';

    document.getElementById('btn-fmt-cancel').style.display = 'inline-flex';

    window.scrollTo({ top: 0, behavior: 'smooth' });

    drawFormatPreview();

}



