/**
 * O convite que substitui a criacao automatica de campos.
 *
 * Ate a v699 o banco que chegava ja desenhava um campo por coluna no ticket
 * (`adicionarColunasComoElementos`). O usuario mandou tirar isso em 23/08/2026:
 * carregar o banco nao poe nada na janela; a coluna so vai para o ticket quando
 * ele a escolhe, clicando nela.
 *
 * A razao que fez a criacao automatica nascer continua valendo, e por isso ela
 * nao some sem substituto: sem campo nenhum, o canvas fica igual ao de antes do
 * upload, e quem nao conhece a tela conclui que a busca falhou. O que responde
 * isso agora e a tela dizendo o passo seguinte — este convite no aviso, e o
 * mesmo recado dentro da barra "Colunas do Banco de Dados (CSV)".
 */
const CONVITE_DAS_COLUNAS = ' Clique numa coluna abaixo para pô-la no ticket.';


/**
 * Deixa a linha "Da web" contando a verdade sobre o banco que esta carregado:
 * com planilha ligada aparecem o botao de atualizar e a explicacao; sem ela,
 * so o campo vazio esperando um endereco novo.
 *
 * `limparCampo` so e verdadeiro quando quem chama sabe que o banco mudou de
 * dono (remover, ou abrir outra numeracao). Numa renderizacao qualquer o campo
 * nao pode ser apagado: o operador pode estar no meio de colar um link.
 */
function sincronizarLigacaoCsv(limparCampo) {

    const campo = document.getElementById('num-csv-url');

    const btnAtualizar = document.getElementById('btn-atualizar-num-csv');

    const ligado = document.getElementById('num-csv-ligado');

    const url = state.numCsvUrl || '';

    if (campo && (url || limparCampo)) campo.value = url;

    if (btnAtualizar) btnAtualizar.style.display = url ? 'inline-flex' : 'none';

    if (ligado) ligado.style.display = url ? 'block' : 'none';

}



function renderNumCsvInterface() {

    const nameEl = document.getElementById('num-csv-file-name');

    const btnRemove = document.getElementById('btn-remove-num-csv');

    const container = document.getElementById('num-csv-columns-container');

    const bar = document.getElementById('num-csv-columns-bar');

    

    const totalLinhas = state.numCsvData ? state.numCsvData.length : 0;

    const ativas = linhasAtivasCsv(state.numCsvData).length;

    if (nameEl) {

        nameEl.textContent = ativas === totalLinhas
            ? `📎 ${state.numCsvFilename} (${totalLinhas} linhas)`
            : `📎 ${state.numCsvFilename} (${ativas} de ${totalLinhas} linhas serão impressas)`;

    }

    if (btnRemove) btnRemove.style.display = 'inline-flex';

    const btnVer = document.getElementById('btn-ver-num-csv');

    if (btnVer) btnVer.style.display = 'inline-flex';

    const btnCriar = document.getElementById('btn-criar-num-csv');

    if (btnCriar) btnCriar.style.display = 'none';

    

    if (container && bar && state.numCsvHeaders && state.numCsvHeaders.length) {

        container.style.display = 'block';

        // Esta barra tem UM trabalho: pôr coluna no ticket. O botão
        // "📋 Ver / Editar CSV" morava aqui e chamava exatamente a mesma
        // função do "📋 Ver / Editar" da box "Banco de Dados (CSV)", logo
        // acima, no mesmo painel — duas portas para a mesma sala, e uma delas
        // disputando espaço com o recado que esta barra precisa dar. Tirado a
        // pedido do usuário em 25/08/2026.
        //
        // Desde 26/08/2026 a box É a única porta: o "📊 Ver / editar" do card do
        // modelo saiu, porque editar dali parecia mexer só naquele modelo e
        // mexia na numeração inteira.
        bar.innerHTML = state.numCsvHeaders.map(col => `

            <button class="btn btn-sm btn-secondary" onclick="addCsvColumnElement('${col}')" title="Pôr esta coluna no ticket, como texto variável">📊 ${col}</button>

        `).join('');

        // O passo seguinte dito na própria tela. Desde 23/08/2026 o banco que
        // chega não desenha campo nenhum (regra do usuário), e sem esta linha o
        // canvas vazio depois do upload parece uma busca que falhou.
        const recado = document.getElementById('num-csv-columns-recado');

        if (recado) {

            recado.textContent = state.numElements && state.numElements.some(el => el && el.source === 'database')
                ? 'Clique numa coluna para pôr mais um campo no ticket.'
                : 'Nenhuma coluna está no ticket ainda — clique na que você quer imprimir.';

        }

    } else if (container) {

        container.style.display = 'none';

    }

    sincronizarLigacaoCsv(false);

    

    renderElementsList();

    drawCanvas();

}



/**
 * O link que se copia da barra do navegador termina em `/edit?usp=sharing` e
 * devolve HTML. Quem devolve CSV e o endereco de exportacao. O `gid` identifica
 * a ABA — sem ele vem sempre a primeira, que raramente e a que o operador esta
 * olhando.
 *
 * Devolve o endereco a buscar. Se nao for uma Planilha Google, devolve o
 * proprio link: serve para qualquer .csv publico.
 */
function urlCsvDaPlanilha(url) {

    const limpo = String(url || '').trim();

    if (!limpo) return null;

    const m = limpo.match(/docs\.google\.com\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);

    if (!m) return limpo;

    // Ja e um endereco que devolve CSV: nao mexer.
    if (/[?&]format=csv|tqx=out:csv/.test(limpo)) return limpo;

    const gid = (limpo.match(/[#?&]gid=(\d+)/) || [])[1];

    return `https://docs.google.com/spreadsheets/d/${m[1]}/export?format=csv`

        + (gid ? `&gid=${gid}` : '');

}



/** O nome do arquivo que o servidor mandou, quando manda. */
function nomeDoContentDisposition(cd) {

    if (!cd) return null;

    // O `filename*` vem em UTF-8 e sem os problemas de acento do `filename`.
    const estrela = cd.match(/filename\*=UTF-8''([^;]+)/i);

    if (estrela) { try { return decodeURIComponent(estrela[1]); } catch (_) { } }

    const simples = cd.match(/filename="?([^";]+)"?/i);

    return simples ? simples[1] : null;

}



/**
 * Baixa e interpreta o CSV de um endereco. Devolve { headers, rows, filename }.
 *
 * Os dois caminhos que trazem banco da web — buscar pela primeira vez e
 * atualizar um banco ja ligado a uma planilha — passam por aqui, para que as
 * mensagens de erro sejam as mesmas nos dois.
 */
/** O identificador da planilha dentro do link, ou null se nao for uma. */
function idDaPlanilhaGoogle(url) {

    const m = String(url || '').match(/docs\.google\.com\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);

    return m ? m[1] : null;

}



/** Nome de coluna que ainda nao existe: "Página", "Página 2", "Página 3"… */
function nomeLivreDaColuna(base, headers) {

    if (!headers.includes(base)) return base;

    let i = 2;

    while (headers.includes(`${base} ${i}`)) i++;

    return `${base} ${i}`;

}



/**
 * Baixa um endereco e devolve { texto, filename }, com as guardas que separam
 * um CSV de verdade de uma pagina de login.
 */
async function baixarTextoDaWeb(url) {

    let resp;

    try {

        resp = await fetch(url, { credentials: 'omit' });

    } catch (_) {

        // Erro de rede no fetch chega como TypeError sem detalhe: quase sempre e
        // o link que nao permite leitura de outro site.
        throw new Error('Não consegui ler esse endereço do navegador. '

            + 'Se for Planilha Google, confira o compartilhamento por link.');

    }

    if (!resp.ok) {

        throw new Error(resp.status === 404

            ? 'Planilha não encontrada, ou não está compartilhada por link.'

            : `O servidor respondeu ${resp.status}.`);

    }

    const texto = await resp.text();

    // Planilha privada devolve a pagina de login, com 200. Sem esta guarda o
    // parser aceitaria o HTML como se fosse uma tabela de uma coluna so.
    if (/^\s*<(!doctype|html)/i.test(texto)) {

        throw new Error('Veio uma página HTML, não um CSV. '

            + 'Compartilhe a planilha como "Qualquer pessoa com o link".');

    }

    return {

        texto,

        filename: nomeDoContentDisposition(resp.headers.get('content-disposition'))

            || 'planilha-web.csv'

    };

}



/**
 * As paginas (abas) de uma Planilha Google, na ordem em que aparecem la.
 *
 * O `/export?format=csv` so entrega UMA pagina, e o `gid` de cada uma e um
 * numero arbitrario que nao da para adivinhar. Quem lista as paginas sem exigir
 * chave de API e a pagina `/htmlview`, que o Google serve com os cabecalhos de
 * CORS e que carrega um trecho de javascript com `items.push({name: …, gid: …})`
 * — um por aba, na ordem certa, com o nome ja legivel.
 *
 * Isso e leitura de HTML dos outros, entao pode deixar de funcionar sem aviso.
 * Por isso qualquer falha aqui devolve lista vazia em vez de erro: a busca cai
 * no caminho de sempre e traz a primeira pagina, que e o comportamento anterior.
 */
async function paginasDaPlanilhaGoogle(id) {

    try {

        const resp = await fetch(

            `https://docs.google.com/spreadsheets/d/${id}/htmlview`, { credentials: 'omit' });

        if (!resp.ok) return [];

        const html = await resp.text();

        const re = /items\.push\(\{\s*name:\s*"((?:[^"\\]|\\.)*)"[\s\S]{0,400}?gid:\s*"(\d+)"/g;

        const paginas = [];

        const vistos = new Set();

        let m;

        while ((m = re.exec(html))) {

            let nome = m[1];

            // O nome vem escapado como string de javascript (\u00e1, \").
            try { nome = JSON.parse('"' + nome + '"'); } catch (_) { }

            if (vistos.has(m[2])) continue;

            vistos.add(m[2]);

            paginas.push({ nome, gid: m[2] });

        }

        return paginas;

    } catch (_) {

        return [];

    }

}



/**
 * Empilha as paginas numa tabela so.
 *
 * O CABECALHO e a uniao das colunas de todas as paginas, na ordem em que
 * aparecem — e o que o editor usa para desenhar a grade. A primeira coluna e
 * criada por nos e diz de qual pagina veio a linha: sem ela, 300 linhas de 8
 * paises viram um bloco indistinguivel, e e justamente por ela que o operador
 * filtra no editor e reparte as linhas entre os modelos.
 *
 * CADA LINHA, porem, guarda so as colunas da PROPRIA pagina.
 *
 * Ate a v700 cada linha era preenchida com a uniao inteira, e as colunas das
 * outras paginas entravam como texto vazio. Numa planilha de 19 abas com duas
 * colunas cada — a do Expointer 2026, medida em 23/08/2026 — isso dava 39
 * campos por linha, 37 deles em branco: 46.921 linhas viravam um pacote de
 * **45,4 MB** para 3,5 MB de dado real. Salvar essa numeracao nao completava:
 * a conexao caia no meio e o erro chegava como "TypeError: Failed to fetch",
 * junto com a falha do preview no Storage.
 *
 * Chave ausente e lida como vazia em todo lugar que consome estas linhas — o
 * `csv_row.get(col, "")` do motor, o `escaparCampo` do editor, a conferencia de
 * dados —, e quem precisa da lista de colunas usa o `csv_headers`, que continua
 * completo. Por isso a economia nao custa nada em lugar nenhum.
 */
function juntarPaginas(partes) {

    const colunas = [];

    for (const p of partes) {

        for (const h of p.headers) if (h && !colunas.includes(h)) colunas.push(h);

    }

    const colunaPagina = nomeLivreDaColuna('Página', colunas);

    const rows = [];

    for (const p of partes) {

        // As colunas DESTA pagina, e so elas. As da propria pagina entram mesmo
        // vazias: ali o branco e um dado — a celula que o cliente deixou em
        // branco —, e nao o preenchimento de uma coluna que nem e dela.
        const daPagina = (p.headers || []).filter(Boolean);

        for (const r of p.rows) {

            const nova = {};

            nova[colunaPagina] = p.nome;

            for (const c of daPagina) nova[c] = (r[c] !== undefined && r[c] !== null) ? r[c] : '';

            rows.push(nova);

        }

    }

    return { headers: [colunaPagina, ...colunas], rows, colunaPagina };

}



/** "267690 Credencial - Bulgaria.csv" + aba "Bulgaria" → "267690 Credencial". */
function nomeDoCadernoSemAPagina(filename, nomeDaPagina) {

    const base = String(filename || '').replace(/\.csv$/i, '');

    const sufixo = ' - ' + nomeDaPagina;

    return base.endsWith(sufixo) ? base.slice(0, -sufixo.length) : base;

}



/**
 * Baixa todas as paginas e devolve uma tabela so. Uma pagina que falhe ou venha
 * vazia nao derruba as outras — ela e relatada e o resto entra.
 */
async function baixarTodasAsPaginas(id, paginas, progresso) {

    let prontas = 0;

    const naoVieram = [];

    const partes = await Promise.all(paginas.map(async (pagina) => {

        try {

            const { texto, filename } = await baixarTextoDaWeb(

                `https://docs.google.com/spreadsheets/d/${id}/export?format=csv&gid=${pagina.gid}`);

            const parsed = window.CsvEditor.parseCsv(texto);

            // O `gid` vem junto: é ele que permite ligar cada numeração criada
            // por página à SUA aba, para o "🔄 atualizar da planilha" continuar
            // funcionando uma a uma depois de separadas.
            return { nome: pagina.nome, gid: pagina.gid, headers: parsed.headers, rows: parsed.rows, filename };

        } catch (_) {

            naoVieram.push(pagina.nome);

            return null;

        } finally {

            prontas++;

            if (progresso) progresso(`⏳ ${prontas}/${paginas.length}`);

        }

    }));

    const comLinhas = partes.filter(p => p && p.rows.length);

    const vazias = partes.filter(p => p && !p.rows.length).map(p => p.nome);

    if (!comLinhas.length) {

        throw new Error(`Nenhuma das ${paginas.length} páginas tinha linhas.`);

    }

    const { headers, rows, colunaPagina } = juntarPaginas(comLinhas);

    const caderno = nomeDoCadernoSemAPagina(comLinhas[0].filename, comLinhas[0].nome);

    return {

        headers,

        rows,

        colunaPagina,

        filename: `${caderno} (${comLinhas.length} páginas).csv`,

        paginas: comLinhas.map(p => ({ nome: p.nome, linhas: p.rows.length })),

        // As páginas CRUAS, cada uma com o próprio cabeçalho e as próprias
        // linhas. É delas que sai a opção "uma numeração por página" — sem isso
        // só restaria a tabela empilhada, da qual não dá para separar de volta
        // sem adivinhar de que aba veio cada coluna.
        partes: comLinhas,

        idDaPlanilha: id,

        vazias,

        naoVieram

    };

}



/**
 * Baixa e interpreta o CSV de um endereco. Devolve
 * { headers, rows, filename, paginas, colunaPagina, vazias, naoVieram }.
 *
 * Os dois caminhos que trazem banco da web — buscar pela primeira vez e
 * atualizar um banco ja ligado a uma planilha — passam por aqui, para que as
 * mensagens de erro sejam as mesmas nos dois.
 *
 * Planilha Google com mais de uma pagina vem INTEIRA. Foi o pedido, e faz
 * sentido no trabalho: um caderno de credenciais tem uma pagina por pais, e o
 * pedido imprime todos. Quem quiser so uma abre a pagina no Google antes de
 * copiar o endereco — o link fica com `#gid=`, e um gid explicito e respeitado
 * como escolha deliberada de uma pagina so.
 */
async function baixarCsvDaWeb(link, progresso) {

    const alvo = urlCsvDaPlanilha(link);

    if (!alvo) throw new Error('Cole o link da planilha antes de buscar.');

    if (!/^https?:\/\//i.test(alvo)) {

        throw new Error('O link precisa começar com http:// ou https://');

    }

    const id = idDaPlanilhaGoogle(link);

    const gidExplicito = /[#?&]gid=\d+/.test(String(link || ''));

    if (id && !gidExplicito) {

        const paginas = await paginasDaPlanilhaGoogle(id);

        if (paginas.length > 1) return await baixarTodasAsPaginas(id, paginas, progresso);

    }

    const { texto, filename } = await baixarTextoDaWeb(alvo);

    const parsed = window.CsvEditor.parseCsv(texto);

    if (!parsed.rows.length) throw new Error('A planilha está vazia.');

    return { headers: parsed.headers, rows: parsed.rows, filename, paginas: [] };

}



/**
 * A frase que conta o que veio de um caderno de varias paginas. Vazia quando a
 * planilha tinha uma pagina so — nesse caso nao ha nada a explicar.
 */
function fraseDasPaginas(res) {

    const paginas = (res && res.paginas) || [];

    if (paginas.length < 2) return '';

    const nomes = paginas.map(p => p.nome);

    const mostra = nomes.slice(0, 3).join(', ') + (nomes.length > 3 ? ` +${nomes.length - 3}` : '');

    let frase = ` ${paginas.length} páginas (${mostra}), com a coluna "${res.colunaPagina}" dizendo de qual veio cada linha.`;

    if (res.vazias && res.vazias.length) frase += ` ${res.vazias.length} vazia(s) ignorada(s).`;

    if (res.naoVieram && res.naoVieram.length) frase += ` Não veio: ${res.naoVieram.join(', ')}.`;

    return frase;

}



/** Trava o botao enquanto a rede responde, e devolve o rotulo dele no fim. */
async function comBotaoOcupado(id, rotuloOcupado, tarefa) {

    const botao = document.getElementById(id);

    const rotulo = botao ? botao.textContent : '';

    const progresso = (txt) => { if (botao) botao.textContent = txt; };

    if (botao) { botao.disabled = true; botao.textContent = rotuloOcupado; }

    try { return await tarefa(progresso); }

    finally { if (botao) { botao.disabled = false; botao.textContent = rotulo; } }

}



/**
 * Busca o banco de dados de um endereco da web e carrega no editor da
 * numeracao, do mesmo jeito que o upload de arquivo faz.
 */
// ─── Planilha de várias páginas: uma numeração só, ou uma por página ────────
//
// Pedido do usuário em 23/08/2026, depois de a planilha do Expointer (19 abas)
// não conseguir salvar. Ele já resolvia isso à mão — no pedido 21085 separou as
// abas em CSVs e criou uma numeração para cada. Esta escolha faz o mesmo em um
// clique, e mantém cada numeração ligada à SUA aba pelo `gid`, para o
// "🔄 atualizar da planilha" continuar valendo uma a uma.

/** Guarda o que a busca trouxe enquanto o operador decide. */
let escolhaDaPlanilha = null;

function fecharEscolhaDaPlanilha() {

    const caixa = document.getElementById('escolha-planilha-overlay');

    if (caixa) caixa.remove();

    escolhaDaPlanilha = null;

}
window.fecharEscolhaDaPlanilha = fecharEscolhaDaPlanilha;

/**
 * A primeira linha PARECE cabeçalho?
 *
 * Só uma sugestão — quem decide é o operador, na janela. Duas evidências, as que
 * a planilha do Expointer expôs em 23/08/2026:
 *
 * - **Cabeçalho não se repete no corpo.** Nome de coluna aparece uma vez; se o
 *   valor da primeira linha reaparece na mesma coluna mais abaixo, ele é dado.
 *   Naquela planilha a segunda coluna trazia "CONVIDADOS OFICIAIS" em todas as
 *   1.300 linhas, a primeira inclusive.
 * - **Cabeçalho todo numérico é raro.** Uma primeira linha em que toda coluna é
 *   número é quase sempre a primeira credencial da lista.
 */
function pareceCabecalho(headers, rows) {

    const cols = (headers || []).filter(h => h !== undefined && h !== null && String(h).trim() !== '');

    if (!cols.length) return true;

    // 200 linhas bastam para a evidência e não custam nada num banco de 20 mil.
    const corpo = (rows || []).slice(0, 200);

    for (const c of cols) {

        const valor = String(c).trim();

        const repete = corpo.some(r => {

            const v = r ? r[c] : undefined;

            return String(v === undefined || v === null ? '' : v).trim() === valor;

        });

        if (repete) return false;

    }

    const soNumero = cols.every(c => /\d/.test(String(c)) && /^[\d\s.,\/-]+$/.test(String(c).trim()));

    return !soNumero;

}

/**
 * A primeira linha era DADO, e não cabeçalho: devolve a tabela corrigida.
 *
 * As colunas passam a se chamar "Coluna 1", "Coluna 2"… — nomes que o operador
 * renomeia no editor se quiser — e a linha que tinha virado cabeçalho volta para
 * o corpo, na primeira posição, que é onde ela estava na planilha.
 *
 * Sem isto, a planilha do Expointer perdia UMA credencial por aba (19 no total,
 * medido em 23/08/2026) e o primeiro código virava o nome da coluna.
 */
function primeiraLinhaComoDado(headers, rows) {

    const antigos = (headers || []).map(h => (h === undefined || h === null) ? '' : h);

    const nomes = antigos.map((_, i) => `Coluna ${i + 1}`);

    const resgatada = {};

    nomes.forEach((n, i) => { resgatada[n] = String(antigos[i]).trim(); });

    const corpo = (rows || []).map(r => {

        const o = {};

        nomes.forEach((n, i) => {

            const v = r ? r[antigos[i]] : undefined;

            o[n] = (v === undefined || v === null) ? '' : String(v);

        });

        return o;

    });

    return { headers: nomes, rows: [resgatada, ...corpo] };
}

/**
 * Aplica a escolha "a primeira linha é dado" a um resultado de busca inteiro —
 * a tabela empilhada E cada página crua, que é de onde saem as numerações
 * separadas. Uma sem a outra deixaria os dois caminhos discordando.
 */
function comAPrimeiraLinhaComoDado(res) {

    const ajustado = primeiraLinhaComoDado(res.headers, res.rows);

    const partes = Array.isArray(res.partes)

        ? res.partes.map(p => {

            const q = primeiraLinhaComoDado(p.headers, p.rows);

            return Object.assign({}, p, { headers: q.headers, rows: q.rows });

        })

        : res.partes;

    return Object.assign({}, res, { headers: ajustado.headers, rows: ajustado.rows, partes });
}

/**
 * A janela "Como trazer esta planilha".
 *
 * Ela junta as duas decisões que a busca pode ter, e só aparece quando existe
 * alguma: a planilha tem mais de uma página, ou a primeira linha não parece
 * cabeçalho. Planilha simples com cabeçalho claro continua entrando direto,
 * sem pergunta nenhuma.
 */
function abrirEscolhaDaPlanilha(res, link) {

    const varias = Array.isArray(res.partes) && res.partes.length > 1;

    const exemplo = (varias ? res.partes[0] : res);

    const sugereCabecalho = pareceCabecalho(exemplo.headers, exemplo.rows);

    escolhaDaPlanilha = { res, link, ehCabecalho: sugereCabecalho };

    const amostra = (exemplo.headers || []).slice(0, 6)

        .map(h => `<code style="background:rgba(148,163,184,0.14); padding:1px 5px; border-radius:4px;">${escapeHtml(String(h))}</code>`)

        .join(' <span style="color:#475569;">·</span> ');

    const blocoPaginas = varias ? `
        <div style="margin-top:18px; padding-top:16px; border-top:1px solid rgba(148,163,184,0.2);">
            <div style="font-weight:800; color:#e2e8f0; margin-bottom:8px;">Esta planilha tem ${res.partes.length} páginas</div>
            <table style="border-collapse:collapse; font-size:0.8rem; margin-bottom:12px;">
                ${res.partes.map((p, i) => `<tr><td style="padding:2px 12px 2px 0;">${escapeHtml(p.nome)}</td>`
                    + `<td id="acab-pag-linhas-${i}" data-linhas="${p.rows.length}"`
                    + ` style="padding:2px 0; text-align:right; font-family:monospace; color:#94a3b8;">${p.rows.length}</td></tr>`).join('')}
            </table>
            <label style="display:flex; gap:8px; align-items:flex-start; cursor:pointer; margin-bottom:6px;">
                <input type="radio" name="acab-paginas" value="juntas" checked style="margin-top:3px;">
                <span><b>Tudo numa numeração só</b> — as linhas empilhadas numa tabela, com a coluna
                <code>Página</code> dizendo de onde veio cada uma.</span>
            </label>
            <label style="display:flex; gap:8px; align-items:flex-start; cursor:pointer;">
                <input type="radio" name="acab-paginas" value="separadas" style="margin-top:3px;">
                <span><b>Uma numeração por página</b> — cria ${res.partes.length} numerações, cada uma com o
                banco da sua página e ligada a ela para atualizar depois. Copia o formato e os elementos
                desta numeração.</span>
            </label>
        </div>` : '';

    const overlay = document.createElement('div');

    overlay.id = 'escolha-planilha-overlay';

    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(2,6,23,0.82); z-index:100002;'

        + ' display:flex; align-items:center; justify-content:center; padding:20px;';

    overlay.innerHTML = `
        <div style="background:#1e293b; border:1px solid rgba(148,163,184,0.25); border-radius:12px;
                    box-shadow:0 24px 60px rgba(0,0,0,0.6); width:min(640px,96vw); max-height:90vh;
                    display:flex; flex-direction:column; overflow:hidden;">
            <div style="padding:16px 22px; border-bottom:1px solid rgba(148,163,184,0.2);">
                <h3 style="margin:0; font-size:1.05rem; font-weight:800; color:#e2e8f0;">📑 Como trazer esta planilha</h3>
            </div>
            <div style="padding:16px 22px; overflow:auto; color:#e2e8f0; font-size:0.88rem; line-height:1.5;">
                <div style="font-weight:800; margin-bottom:8px;">A primeira linha${varias ? ' de cada página' : ''} é:</div>
                <div style="padding:10px 12px; border-radius:8px; background:rgba(76,200,240,0.08);
                            border:1px solid rgba(76,200,240,0.28); margin-bottom:12px; font-size:0.82rem;">
                    ${amostra || '<span style="color:#94a3b8;">(vazia)</span>'}
                </div>
                <label style="display:flex; gap:8px; align-items:flex-start; cursor:pointer; margin-bottom:6px;">
                    <input type="radio" name="acab-cabecalho" value="cabecalho" ${sugereCabecalho ? 'checked' : ''} style="margin-top:3px;">
                    <span><b>O nome das colunas</b> — é o cabeçalho, e não sai impressa.</span>
                </label>
                <label style="display:flex; gap:8px; align-items:flex-start; cursor:pointer;">
                    <input type="radio" name="acab-cabecalho" value="dado" ${sugereCabecalho ? '' : 'checked'} style="margin-top:3px;">
                    <span><b>Já é dado</b> — é a primeira credencial da lista, e precisa ser impressa.
                    As colunas passam a se chamar <code>Coluna 1</code>, <code>Coluna 2</code>…</span>
                </label>
                ${blocoPaginas}
            </div>
            <div style="padding:14px 22px; border-top:1px solid rgba(148,163,184,0.2); display:flex; gap:10px; justify-content:flex-end;">
                <button type="button" data-role="cancelar" style="border:1px solid rgba(148,163,184,0.35); background:transparent; color:#cbd5e1; border-radius:8px; padding:9px 16px; font-weight:700; cursor:pointer;">Cancelar</button>
                <button type="button" data-role="trazer" style="border:none; background:linear-gradient(135deg,#3b82f6,#2563eb); color:#fff; border-radius:8px; padding:9px 20px; font-weight:800; cursor:pointer;">Trazer</button>
            </div>
        </div>`;

    overlay.querySelector('[data-role="cancelar"]').addEventListener('click', fecharEscolhaDaPlanilha);

    overlay.querySelector('[data-role="trazer"]').addEventListener('click', () => confirmarEscolhaDaPlanilha());

    // A contagem de cada página acompanha a escolha: com "já é dado" a linha que
    // tinha virado cabeçalho volta para o corpo, e são 600 e não 599. Mostrar o
    // número de antes seria a janela discordando do que ela mesma vai fazer.
    overlay.querySelectorAll('input[name="acab-cabecalho"]').forEach(radio => {

        radio.addEventListener('change', () => {

            const ehDado = radio.value === 'dado' && radio.checked;

            overlay.querySelectorAll('[data-linhas]').forEach(td => {

                const base = parseInt(td.dataset.linhas, 10) || 0;

                td.textContent = base + (ehDado ? 1 : 0);

            });

        });

    });

    document.body.appendChild(overlay);

}

/** O botão "Trazer": lê as duas escolhas e segue por um dos dois caminhos. */
async function confirmarEscolhaDaPlanilha() {

    const guardado = escolhaDaPlanilha;

    if (!guardado) return;

    const marcado = n => {

        const el = document.querySelector(`#escolha-planilha-overlay input[name="${n}"]:checked`);

        return el ? el.value : '';

    };

    const ehDado = marcado('acab-cabecalho') === 'dado';

    const separar = marcado('acab-paginas') === 'separadas';

    const res = ehDado ? comAPrimeiraLinhaComoDado(guardado.res) : guardado.res;

    if (separar) {

        escolhaDaPlanilha = Object.assign({}, guardado, { res });

        await criarUmaNumeracaoPorPagina();

        return;

    }

    const link = guardado.link;

    fecharEscolhaDaPlanilha();

    aplicarBancoNaNumeracao(res, link);

}
window.confirmarEscolhaDaPlanilha = confirmarEscolhaDaPlanilha;

/**
 * Os elementos desta numeração, reapontados para as colunas de OUTRA página.
 *
 * O elemento guarda o NOME da coluna (`csv_column`), e cada aba tem os seus —
 * "EXPOSITOR ok" numa, "JURADOS ok" noutra. O que se mantém entre elas é a
 * POSIÇÃO: a 1ª coluna de cada aba é o código, a 2ª é o rótulo. Então o
 * reapontamento é por posição, tomando as colunas da numeração aberta como
 * referência.
 *
 * Coluna que não tiver correspondente na página fica como está, e o elemento é
 * relatado: melhor um campo apontando para coluna que não existe — que a
 * Conferência de dados aponta — do que um apontamento adivinhado.
 */
function elementosParaAPagina(elementos, colunasDeReferencia, colunasDaPagina) {

    const semCorrespondente = [];

    const copia = JSON.parse(JSON.stringify(elementos || []));

    copia.forEach(el => {

        if (!el || el.source !== 'database') return;

        const col = String(el.csv_column || '').trim();

        if (!col) return;

        const i = colunasDeReferencia.indexOf(col);

        if (i >= 0 && colunasDaPagina[i]) el.csv_column = colunasDaPagina[i];

        else semCorrespondente.push(col);

    });

    return { elementos: copia, semCorrespondente };

}

/**
 * Cria uma numeração para cada página da planilha buscada.
 *
 * Cada uma nasce com o formato, o tipo e os elementos da numeração aberta — é a
 * mesma peça, mudando só o banco — e com o `csv_url` apontando para a SUA aba
 * (`&gid=`), de modo que "🔄 atualizar da planilha" depois vale por página.
 *
 * O que NÃO vai junto: o preview. Ele é gerado do canvas ao salvar, e gerar 19
 * previews aqui custaria mais do que vale — a numeração ganha o dela na
 * primeira vez que for aberta e salva.
 */
async function criarUmaNumeracaoPorPagina() {

    const guardado = escolhaDaPlanilha;

    if (!guardado) return;

    const { res, link } = guardado;

    const botao = document.querySelector('#escolha-planilha-overlay [data-role="trazer"]');

    if (botao) { botao.disabled = true; botao.textContent = 'Criando…'; }

    const fmtId = document.getElementById('num-formato').value;

    const tipo = document.getElementById('num-tipo').value || 'SEQUENCIAL';

    if (!fmtId) {

        toast('Selecione um formato antes de separar a planilha em numerações.', 'error');

        if (botao) { botao.disabled = false; botao.textContent = 'Trazer'; }

        return;

    }

    const referencia = (state.numCsvHeaders || []).filter(Boolean);

    const criadas = [];

    const falharam = [];

    const semColuna = new Set();

    for (const p of res.partes) {

        const colunas = (p.headers || []).filter(Boolean);

        const { elementos, semCorrespondente } = elementosParaAPagina(state.numElements, referencia, colunas);

        semCorrespondente.forEach(c => semColuna.add(c));

        const payload = {

            name: p.nome,

            formato_id: fmtId,

            tipo,

            formato_ids: [fmtId],

            ticket_qtd: parseInt(document.getElementById('num-ticket-qtd').value) || 1,

            ticket_logica: document.getElementById('num-ticket-logica').value || 'HORIZONTAL',

            csv_filename: p.nome + '.csv',

            csv_headers: colunas,

            csv_data: p.rows,

            // Ligada à SUA aba: o gid explícito faz o `baixarCsvDaWeb` trazer só
            // ela quando alguém mandar atualizar.
            csv_url: res.idDaPlanilha && p.gid

                ? `https://docs.google.com/spreadsheets/d/${res.idDaPlanilha}/edit#gid=${p.gid}`

                : link,

            elements: elementos,

            print_mode: document.getElementById('num-print-mode')?.value || 'front',

        };

        try {

            await api('POST', '/numeracoes', payload);

            criadas.push(p.nome);

        } catch (e) {

            console.error('[planilha] não deu para criar a numeração da página', p.nome, e);

            falharam.push(p.nome);

        }

        if (botao) botao.textContent = `Criando… ${criadas.length + falharam.length}/${res.partes.length}`;

    }

    fecharEscolhaDaPlanilha();

    // A mesma recarga que o `saveNumeracao` faz depois de gravar: sem ela a
    // lista de numerações continuaria mostrando o que havia antes.
    if (typeof loadAll === 'function') { try { await loadAll(); } catch (_) { /* a lista se atualiza no próximo desenho */ } }

    let recado = `${criadas.length} numeração(ões) criada(s), uma por página.`;

    if (falharam.length) recado += ` ${falharam.length} não deu(ram) certo: ${falharam.join(', ')}.`;

    if (semColuna.size) {

        recado += ` Confira a coluna dos elementos: ${[...semColuna].join(', ')} não tinha correspondente em todas as páginas.`;

    }

    toast(recado, falharam.length ? 'warning' : 'success');

}
window.criarUmaNumeracaoPorPagina = criarUmaNumeracaoPorPagina;

/**
 * O banco de UMA página, aplicado à numeração aberta.
 *
 * É o caminho de sempre — a tabela empilhada de todas as páginas, ou o CSV de
 * uma página só — separado numa função porque agora existe um segundo destino
 * possível para a mesma busca: uma numeração por página.
 */
function aplicarBancoNaNumeracao(res, link) {

    state.numCsvHeaders = res.headers;

    state.numCsvData = res.rows;

    state.numCsvFilename = res.filename;

    // Guardar o endereco que o operador colou, e nao o de exportacao que o
    // urlCsvDaPlanilha deriva: e este que ele reconhece quando reabre a
    // numeracao meses depois.
    state.numCsvUrl = link;

    renderNumCsvInterface();

    toast(

        `${res.rows.length} linha(s) e ${res.headers.length} coluna(s) `

        + `de "${res.filename}".` + fraseDasPaginas(res) + CONVITE_DAS_COLUNAS

        + ' Salve a numeração para gravar.',

        'success'

    );

}

window.buscarCsvDaWeb = async function() {

    const campo = document.getElementById('num-csv-url');

    const link = campo ? String(campo.value || '').trim() : '';

    try {

        const res = await comBotaoOcupado(

            'btn-buscar-num-csv', '⏳ Buscando…', (p) => baixarCsvDaWeb(link, p));

        // A janela só aparece quando há o que decidir (23/08/2026): a planilha
        // tem mais de uma página, ou a primeira linha não parece cabeçalho.
        // Planilha simples com cabeçalho claro entra direto, sem pergunta —
        // perguntar o que já está respondido é atrito, não cuidado.
        const varias = Array.isArray(res.partes) && res.partes.length > 1;

        const exemplo = varias ? res.partes[0] : res;

        if (varias || !pareceCabecalho(exemplo.headers, exemplo.rows)) {

            abrirEscolhaDaPlanilha(res, link);

            return;

        }

        aplicarBancoNaNumeracao(res, link);

    } catch (e) {

        toast('Erro ao buscar: ' + e.message, 'error');

    }

};

/**
 * Traz de novo o conteudo da planilha ligada, por cima do banco atual.
 *
 * O cuidado que da razao de ser a esta funcao: cada linha do CSV carrega um
 * `__id`, e e por ele que a fatia de cada modelo do pedido
 * (`pedidos_modelos.csv_selecao`) sabe quais linhas imprimir. Uma planilha
 * baixada de novo chega sem `__id` nenhum, e deixar o editor criar ids novos
 * faria toda selecao ja feita apontar para o vazio. Entao o `__id` — e o
 * `__ativo`, que diz se a linha imprime — sao herdados POSICAO A POSICAO: a 5a
 * linha da planilha vira a 5a linha do banco, com a identidade que ela ja tinha.
 *
 * Isso esta certo enquanto a planilha so mudar de conteudo. Se linhas forem
 * inseridas, apagadas ou reordenadas la, tudo abaixo do ponto anda um lugar e a
 * selecao de um modelo passa a valer para outra pessoa. Por isso a confirmacao
 * diz isso com todas as letras antes de trocar qualquer coisa.
 */
window.atualizarCsvDaPlanilha = async function() {

    const campo = document.getElementById('num-csv-url');

    const link = String(state.numCsvUrl || (campo ? campo.value : '') || '').trim();

    if (!link) {

        toast('Não há planilha ligada a este banco de dados.', 'error');

        return;

    }

    try {

        const res = await comBotaoOcupado(

            'btn-atualizar-num-csv', '⏳ Atualizando…', (p) => baixarCsvDaWeb(link, p));

        const { headers, rows, filename } = res;

        const antigas = Array.isArray(state.numCsvData) ? state.numCsvData : [];

        // Coluna que sumiu e algum elemento ainda usa: nao quebra o salvamento,
        // mas imprime vazio — melhor o operador saber antes de trocar.
        const perdidas = [...new Set((state.numElements || [])

            .filter(el => el && el.source === 'database' && el.csv_column

                && !headers.includes(el.csv_column))

            .map(el => el.csv_column))];

        const aviso = perdidas.length

            ? `\n\nATENÇÃO: ${perdidas.map(c => `"${c}"`).join(', ')} `

              + 'não existe mais na planilha, e há elemento da numeração usando essa coluna.'

            : '';

        const diferenca = rows.length === antigas.length

            ? 'O número de linhas é o mesmo.'

            : (rows.length > antigas.length

                ? `Entram ${rows.length - antigas.length} linha(s) no fim.`

                : `Saem ${antigas.length - rows.length} linha(s) do fim.`);

        const ok = confirm(

            'Atualizar o banco de dados pela planilha?\n\n'

            + `Aqui: ${antigas.length} linha(s).    Na planilha: ${rows.length} linha(s).\n`

            + diferenca + '\n\n'

            + 'As linhas são reconhecidas pela POSIÇÃO: a 1ª da planilha é a 1ª daqui. '

            + 'Se você inseriu, apagou ou reordenou linhas na planilha, a seleção de '

            + 'linhas já feita nos pedidos passa a apontar para outra linha.\n\n'

            + 'O que tiver sido editado à mão aqui no CSV é substituído.'

            + aviso

        );

        if (!ok) { toast('Atualização cancelada. Nada mudou.', 'info'); return; }

        // Ids nao sao reaproveitados: linha nova comeca depois do maior ja usado.
        let proximo = 1;

        for (const r of antigas) {

            const v = Number(r && r.__id);

            if (Number.isFinite(v) && v >= proximo) proximo = v + 1;

        }

        let herdadas = 0;

        rows.forEach((linha, i) => {

            const velha = antigas[i];

            const id = velha ? Number(velha.__id) : NaN;

            if (Number.isFinite(id) && id > 0) {

                linha.__id = id;

                // Ausencia da chave significa ativa: so a desmarcacao viaja.
                if (velha.__ativo === false) linha.__ativo = false;

                herdadas++;

            } else {

                linha.__id = proximo++;

            }

        });

        state.numCsvHeaders = headers;

        state.numCsvData = rows;

        state.numCsvFilename = filename;

        state.numCsvUrl = link;

        renderNumCsvInterface();

        toast(

            `Banco atualizado: ${rows.length} linha(s), ${herdadas} mantendo a `

            + 'identidade que já tinham.' + fraseDasPaginas(res)

            + ' Salve a numeração para gravar.',

            'success'

        );

    } catch (e) {

        toast('Erro ao atualizar: ' + e.message, 'error');

    }

};

window.urlCsvDaPlanilha = urlCsvDaPlanilha;



/**
 * Só as linhas do CSV que serão impressas. Uma linha desmarcada no editor de
 * CSV carrega `__ativo: false`; a ausência da chave significa ativa, então todo
 * CSV salvo antes da v524 continua valendo. O engine.py aplica o mesmo filtro.
 */
function linhasAtivasCsv(rows) {

    if (!Array.isArray(rows)) return [];

    return rows.filter(r => !r || r.__ativo !== false);

}

window.linhasAtivasCsv = linhasAtivasCsv;



/**
 * Abre o editor de CSV (modal de tela cheia, em frontend/csv-editor.js) com o
 * banco de dados da numeração que está aberta no editor.
 */
window.abrirEditorCsvDaNumeracao = function() {

    if (typeof window.abrirEditorCsv !== 'function') {

        toast('O editor de CSV não carregou. Recarregue a página.', 'error');

        return;

    }

    if (!state.numCsvData || !state.numCsvData.length) {

        toast('Nenhum CSV carregado nesta numeração.', 'error');

        return;

    }

    _abrirEditorCsvDaNumeracao(state.numCsvHeaders || [], state.numCsvData, state.numCsvFilename || 'banco.csv');

};



/**
 * Abre o Gerenciador de Fotos para um elemento FOTO da numeração aberta.
 *
 * Esta é a ponte entre o editor e o `gerenciador-fotos.js`, que não enxerga o
 * `state` — mesmo desenho do editor de CSV. Ela entrega as linhas VIVAS (os
 * mesmos objetos de `state.numCsvData`), porque é escrevendo `__fotos` dentro
 * delas que o enquadramento passa a viajar junto com a pessoa.
 */
window.abrirFotosDoElemento = function (elId) {

    const el = (state.numElements || []).find(e => e.id === elId);

    if (!el) return;

    if (typeof window.abrirGerenciadorDeFotos !== 'function') {

        toast('O Gerenciador de Fotos não carregou. Recarregue a página.', 'error');

        return;

    }

    if (!state.numCsvData || !state.numCsvData.length) {

        toast('Esta numeração ainda não tem banco de dados. Crie ou importe o CSV antes de trazer as fotos — '
            + 'ou, se o banco é do PEDIDO, use o 🖼️ Fotos do box Gerenciamento de Bancos de Dados.', 'error');

        return;

    }

    if (!el.csv_column) {

        toast('Escolha primeiro a coluna do banco em que a foto será guardada. '
            + 'Numa peça que lê banco do pedido, aponte a coluna no 🔤 Colunas do modelo e use o 🖼️ Fotos do box.', 'error');

        return;

    }

    // A coluna da foto pode ter sido digitada à mão e ainda não existir na
    // planilha. Ela precisa existir, senão a célula com o nome do arquivo não
    // apareceria na grade e o operador acharia que nada foi gravado.
    if (!(state.numCsvHeaders || []).includes(el.csv_column)) {

        state.numCsvHeaders = [...(state.numCsvHeaders || []), el.csv_column];

    }

    const numId = (document.getElementById('num-id')?.value || 'rascunho').trim() || 'rascunho';

    window.abrirGerenciadorDeFotos({

        janela: { w_mm: el.width_mm || 25, h_mm: el.height_mm || 32, fit: el.fit || 'cover' },

        // Identifica a sessão: é por ela que as fotos que sobraram voltam para a
        // tela quando o gerenciador é reaberto nesta mesma numeração.
        chave: numId + '|' + el.csv_column,

        coluna: el.csv_column,

        headers: state.numCsvHeaders || [],

        rows: state.numCsvData,

        // O bucket 'artes' é o mesmo que já recebe as artes do editor; as fotos
        // ficam sob o prefixo fotos/<numeração>/, com o hash no nome. Foto
        // idêntica reenviada sobrescreve a si mesma em vez de duplicar.
        subirFoto: (blob, hash) => uploadToStorage(blob, hash + '.jpg', 'fotos', {
            objectPath: `fotos/${numId}/${hash}.jpg`
        }),

        onAplicar: ({ gravadas, queimadas, falhas, semFoto, sobrando, coluna }) => {

            if (gravadas) {

                // A redução 350→300 é automática e acontece durante o envio,
                // sem nada para marcar. Se ela não for dita aqui, o operador
                // não tem como saber que aconteceu — e já veio perguntar onde
                // ela estava.
                const reduzidas = queimadas
                    ? ` ${queimadas} passava(m) de 350 dpi e subiu(ram) reamostrada(s) para 300.`
                    : '';

                // "Ligadas" sem o aviso do Salvar é meia verdade: o vínculo é
                // escrito nas linhas do RASCUNHO do editor, e só o Salvar da
                // numeração o leva ao banco. As fotos já subiram ao Storage e a
                // tela já as desenha, então tudo PARECE pronto — mas um F5 antes
                // de salvar joga fora os vínculos, e a impressão volta a acusar
                // as mesmas pessoas. Já aconteceu.
                toast(`${gravadas} foto(s) ligadas à coluna “${coluna}”.${reduzidas} Salve a numeração para ficar gravado.`, 'success');

            }

            if (falhas && falhas.length) {

                toast(`${falhas.length} foto(s) não subiram. Elas continuam no lote.`, 'error');

            }

            if (semFoto && semFoto.length) {

                toast(`${semFoto.length} linha(s) ainda estão sem foto — a impressão vai recusar.`, 'info');

            }

            if (sobrando) {

                toast(`${sobrando} foto(s) continuam sem linha e seguem na tela do gerenciador.`, 'info');

            }

            if (typeof renderNumCsvInterface === 'function') renderNumCsvInterface();

            renderElementsList();

            drawCanvas();

        }

    });

};



/**
 * Abre o editor com um banco vazio, para montar do zero: colar as colunas do
 * Excel, importar um arquivo, ou digitar à mão. Sem isto, uma numeração sem CSV
 * não tinha nenhum caminho a não ser ter o arquivo pronto de antemão.
 */
window.criarCsvVazioDaNumeracao = function() {

    if (typeof window.abrirEditorCsv !== 'function') {

        toast('O editor de CSV não carregou. Recarregue a página.', 'error');

        return;

    }

    // Já existe banco: abrir vazio jogaria fora o que está lá. Abre o de sempre.
    if (state.numCsvData && state.numCsvData.length) {

        return window.abrirEditorCsvDaNumeracao();

    }

    _abrirEditorCsvDaNumeracao([], [], 'banco.csv');

};



function _abrirEditorCsvDaNumeracao(headers, rows, filename, destacar) {

    window.abrirEditorCsv({

        headers: headers,

        rows: rows,

        filename: filename,

        // Quando o conferidor da box 📏 manda a tela abrir apontando linhas.
        destacar: destacar || null,

        // Colunas que são janela de foto. A grade marca em vermelho a célula de
        // quem ainda não tem foto — o banco é a lista de quem vai imprimir, e é
        // percorrendo ele que o operador enxerga os buracos do lote.
        colunasDeFoto: [...new Set(
            (state.numElements || [])
                .filter(el => el && el.type === 'FOTO' && el.csv_column)
                .map(el => el.csv_column)
        )],

        // Quantos elementos apontam para cada coluna, para o modal avisar antes
        // de renomear ou remover uma coluna em uso.
        colunasEmUso: () => {

            const uso = {};

            (state.numElements || []).forEach(el => {

                if (el.source === 'database' && el.csv_column) {

                    uso[el.csv_column] = (uso[el.csv_column] || 0) + 1;

                }

            });

            return uso;

        },

        onAplicar: ({ headers, rows, filename, renomeacoes }) => {

            // Aplicar um banco sem nenhuma linha equivale a nao ter banco: se
            // ficasse um array vazio, a numeracao seguiria marcada como "tem
            // CSV" e a Imposicao tentaria imprimir zero itens.
            if (!rows.length) {

                clearNumCsvFile();

                toast('Banco de dados vazio — a numeração ficou sem CSV.', 'info');

                return;

            }

            state.numCsvHeaders = headers;

            state.numCsvData = rows;

            state.numCsvFilename = filename;

            // Coluna renomeada tem que arrastar junto os elementos que a usam,
            // senão eles ficariam apontando para um nome que não existe mais.
            let ajustados = 0;

            (renomeacoes || []).forEach(({ de, para }) => {

                (state.numElements || []).forEach(el => {

                    if (el.source === 'database' && el.csv_column === de) {

                        el.csv_column = para;

                        ajustados++;

                    }

                });

            });

            renderNumCsvInterface();

            const fora = rows.length - linhasAtivasCsv(rows).length;

            toast(

                `CSV atualizado: ${rows.length} linhas`

                + (fora ? `, ${fora} fora da impressão` : '')

                + (ajustados ? `, ${ajustados} elemento(s) reapontados` : '')

                + '. Salve a numeração para gravar.',

                'success'

            );

        }

    });

};




// ─────────────────────────────────────────────────────────────────────────────
// DISTRIBUIR O BANCO DE DADOS (CSV) ENTRE OS MODELOS DE UM PEDIDO
//
// Um mesmo CSV costuma servir a vários modelos do mesmo pedido — o mapa do
// teatro vira um modelo por setor. O banco fica UMA vez na numeração; o que
// muda por modelo é a fatia, guardada em `pedidos_modelos.csv_selecao`. Ver
// docs/editor_de_csv.md.
// ─────────────────────────────────────────────────────────────────────────────

/** O item do pedido carregado na Imposição agora, ou null. */
function itemAtivoDoPedido() {

    const a = state.activeOSItem;

    if (!a || !a.osId) return null;

    return (state.osItens[a.osId] || []).find(i => String(i.id) === String(a.itemId)) || null;

}



/**
 * A numeração que um item usa.
 *
 * ── Por que há DOIS nomes para uma coluna só ────────────────────────────────
 *
 * No banco existe um campo: `pedidos_modelos.amostra_num_id`. Em memória o item
 * carrega esse valor em `amostra_num_id` E em `numeracao_id` — o segundo é um
 * espelho antigo, que o `dbFieldMap` do `autoSaveOSItemField` traduz de volta
 * para a coluna verdadeira.
 *
 * Dois nomes para o mesmo dado só funcionam enquanto alguém os mantém iguais, e
 * ninguém mantinha. `onItemNumSelect` e `saveAmostraToDB` escreviam só o
 * `amostra_num_id`; este leitor preferia o `numeracao_id`. Resultado, medido no
 * pedido 21202 em 26/08/2026: trocar a numeração de um modelo — ou salvar uma
 * cópia dela — atualizava o card, o rótulo do banco e o select, e o
 * **📊 Ver / editar continuava abrindo o banco da numeração anterior**, até
 * alguém recarregar a página. Pior no **🧩 Linhas**, que grava: a distribuição
 * escreveria `csv_selecao` com os `__id` do banco errado.
 *
 * O conserto tem duas metades, e as duas importam:
 *   1. `sincronizarNumeracaoDoItem()` escreve os dois nomes juntos, sempre.
 *   2. este leitor passou a preferir `amostra_num_id` — a coluna do banco manda,
 *      como em `dados-do-parceiro-mandam-sempre`.
 */
function numeracaoIdDoItem(item) {

    if (!item) return null;

    return item.amostra_num_id || item.numeracao_id || null;

}

/**
 * Grava a numeração do item nos DOIS nomes locais.
 *
 * Use isto em vez de escrever `item.amostra_num_id` na mão: é o que impede os
 * espelhos de discordarem de novo. Não fala com o banco — quem grava é o
 * `autoSaveOSItemField` ou o `saveAmostraToDB`.
 */
function sincronizarNumeracaoDoItem(item, numId) {
    if (!item) return;
    const v = numId || null;
    item.amostra_num_id = v;
    item.numeracao_id = v;
}
window.sincronizarNumeracaoDoItem = sincronizarNumeracaoDoItem;



/**
 * As colunas do CSV que a numeração deste modelo realmente lê — as apontadas
 * pelos elementos `source: 'database'`. São elas que dizem o que daquele banco
 * vai para o papel; o resto do arquivo pode ser de outro modelo.
 */
/**
 * O que um elemento de banco mostra quando NAO ha dado para mostrar.
 *
 * Desde 28/08/2026 a peca nova nao escolhe coluna — o elemento guarda um
 * "Exemplo:" digitado no editor, so para layout e posicionamento; a coluna
 * real e apontada no modelo. Com exemplo, a previa mostra o exemplo; sem, cai
 * no rotulo antigo `[coluna]`, que e como toda peca legada continua se
 * comportando. `semColchetes` e para o codigo de barras, que nunca usou [].
 */
function textoDeExemploDoElemento(el, semColchetes) {
    const exemplo = String((el && el.exemplo) || '').trim();
    if (exemplo) return `${el.prefix || ''}${exemplo}${el.suffix || ''}`;
    const col = (el && el.csv_column) || 'coluna';
    return semColchetes
        ? `${el.prefix || ''}${(el && el.csv_column) || 'COLUNA'}${el.suffix || ''}`
        : `${el.prefix || ''}[${col}]${el.suffix || ''}`;
}
window.textoDeExemploDoElemento = textoDeExemploDoElemento;

function colunasDoBancoDaNumeracao(num) {

    if (!num) return [];

    const vistas = [];

    (num.elements || []).forEach(el => {

        if (!el || el.source !== 'database') return;

        const col = String(el.csv_column || '').trim();

        if (col && vistas.indexOf(col) === -1) vistas.push(col);

    });

    return vistas;

}
window.colunasDoBancoDaNumeracao = colunasDoBancoDaNumeracao;

/**
 * As colunas que ENTRAM na conferencia de repeticoes (26/08/2026).
 *
 * ## Por que nao e a mesma lista de cima
 *
 * `colunasDoBancoDaNumeracao` decide quais linhas IMPRIMEM: uma linha entra na
 * fatia se tiver dado em alguma das colunas que a numeracao le. Mexer nela
 * mudaria o papel. Esta aqui decide outra coisa, e so ela: quais colunas contam
 * quando o painel procura valor repetido.
 *
 * ## O que ela conserta
 *
 * A conferencia tratava toda coluna de banco como identificacao. No pedido
 * 21202 a numeracao do CAMAROTE CORPORATIVO le duas: `Codigo`, que e unico por
 * ingresso, e `Camarote`, que vai de 1 a 140 e REPETE por natureza -- 25
 * ingressos por camarote. O aviso somava as duas e dizia "3.640 celulas
 * repetidas" quando o que repetia eram os 140 numeros de camarote, e nenhum
 * codigo. Numero inflado por construcao ensina o operador a ignorar o aviso, e
 * ai ele nao serve para o dia em que houver codigo repetido de verdade.
 *
 * ## Onde a escolha mora
 *
 * No proprio elemento, em `sem_conferencia`. Nao ha coluna nova na tabela do
 * parceiro para isso, e nao precisa haver: `elements` ja e nosso, ja viaja com
 * a numeracao e ja e gravado inteiro. Ausente = conferida, que e como todas as
 * numeracoes que existiam antes deste dia continuam se comportando.
 *
 * Duas colunas iguais em elementos diferentes: basta UM elemento pedir para
 * conferir para a coluna ser conferida. Desmarcar e uma decisao sobre a COLUNA,
 * e a tela grava a marca em todos os elementos que a leem.
 */
function colunasConferidasDaNumeracao(num) {
    if (!num) return [];
    const conferidas = [], vistas = {};
    (num.elements || []).forEach(el => {
        if (!el || el.source !== 'database') return;
        const col = String(el.csv_column || '').trim();
        if (!col) return;
        if (vistas[col] === undefined) { vistas[col] = false; conferidas.push(col); }
        if (!el.sem_conferencia) vistas[col] = true;
    });
    return conferidas.filter(c => vistas[c]);
}
window.colunasConferidasDaNumeracao = colunasConferidasDaNumeracao;

/** O estado dos checkboxes: toda coluna do banco, e se ela e conferida. */
function conferenciaDasColunasDaNumeracao(num) {
    const conferidas = colunasConferidasDaNumeracao(num);
    return colunasDoBancoDaNumeracao(num)
        .map(c => ({ nome: c, conferida: conferidas.indexOf(c) !== -1 }));
}
window.conferenciaDasColunasDaNumeracao = conferenciaDasColunasDaNumeracao;

/**
 * Os checkboxes de conferencia para um grupo do modal de Linhas.
 *
 * Fonte NUMERACAO: o comportamento de sempre, as colunas da propria peca.
 *
 * Fonte BANCO DO PEDIDO (28/08/2026): as caixas voltam, mas listando as
 * colunas que as PECAS dos modelos leem — e nao as do banco. A marca mora nos
 * elementos da peca, e cada modelo chega a coluna do banco pelo SEU mapa:
 * marcar "CODIGO" confere o 05/09 no modelo do dia 5 e o 06/09 no do dia 6,
 * que e exatamente o que a `celulasRepetidasDoPedido` faz com a peca
 * resolvida. Dois modelos com pecas diferentes no mesmo banco: a lista e a
 * uniao, e coluna com o mesmo nome nas duas pecas vale uma caixa so.
 */
function conferenciaDasColunasDoGrupo(fonte, itens) {
    if (!fonte) return [];
    if (fonte.tipo === 'numeracao') return conferenciaDasColunasDaNumeracao(fonte.num);

    const vistas = {};
    const lista = [];
    (itens || []).forEach(it => {
        const peca = pecaDoModelo(it);
        conferenciaDasColunasDaNumeracao(peca).forEach(c => {
            if (vistas[c.nome] === undefined) {
                vistas[c.nome] = c.conferida;
                lista.push(c);
            } else if (c.conferida && !vistas[c.nome]) {
                // Basta UMA peca conferir para a caixa nascer marcada — a
                // mesma regra dos elementos dentro de uma peca so.
                vistas[c.nome] = true;
                lista.find(x => x.nome === c.nome).conferida = true;
            }
        });
    });
    return lista;
}
window.conferenciaDasColunasDoGrupo = conferenciaDasColunasDoGrupo;

/**
 * Grava a escolha de conferencia em TODAS as pecas do grupo — uma so, no caso
 * comum, mas o mesmo banco pode ser lido por modelos de pecas diferentes.
 * As chaves de `escolha` sao nomes de coluna da peca, nos dois mundos.
 *
 * Devolve se ALGO mudou: a frase do Aplicar precisa disso para nao dizer
 * "nada foi mudado" depois de gravar a escolha — foi um relato do usuario.
 */
async function aplicarConferenciaNoGrupo(fonte, itens, escolha) {
    if (!escolha) return false;
    const pecas = [];
    if (fonte && fonte.tipo === 'numeracao' && fonte.num) {
        pecas.push(fonte.num);
    } else {
        (itens || []).forEach(it => {
            const p = pecaDoModelo(it);
            if (p && pecas.indexOf(p) === -1) pecas.push(p);
        });
    }
    let mudou = false;
    for (const peca of pecas) {
        if (aplicarConferenciaNasColunas(peca, escolha)) {
            await salvarCamposDaNumeracao(peca.id, { elements: peca.elements });
            mudou = true;
        }
    }
    return mudou;
}
window.aplicarConferenciaNoGrupo = aplicarConferenciaNoGrupo;

/**
 * Grava nos elementos quais colunas ficam fora da conferencia. Devolve quantos
 * elementos mudaram -- zero quer dizer que nao ha o que salvar.
 */
function aplicarConferenciaNasColunas(num, escolha) {
    if (!num || !escolha) return 0;
    let mudou = 0;
    (num.elements || []).forEach(el => {
        if (!el || el.source !== 'database') return;
        const col = String(el.csv_column || '').trim();
        if (!col || escolha[col] === undefined) return;
        const fora = !escolha[col];
        const antes = !!el.sem_conferencia;
        if (antes === fora) return;
        if (fora) el.sem_conferencia = true; else delete el.sem_conferencia;
        mudou++;
    });
    return mudou;
}
window.aplicarConferenciaNasColunas = aplicarConferenciaNasColunas;



/**
 * Só as linhas em que ESTA numeração tem alguma coisa a imprimir.
 *
 * Regra do usuário, 24/08/2026: a célula de um modelo se conta pelas colunas que
 * a numeração dele usa, e não pelo tamanho do arquivo. Nasceu do pedido 21118 —
 * um CSV de 450 linhas com três pares de colunas, um por modelo: VIP preenchido
 * em 50 linhas, ACA em 350, CRE em 450. Os três modelos apontavam para o mesmo
 * arquivo, então os três contavam 450 células; o VIP, de Qtd 50, ficava acusado
 * de 400 células a mais e não podia ser marcado PRONTO. A saída era desmarcar
 * 400 linhas na mão, uma a uma, em cada numeração.
 *
 * Basta UMA das colunas ter conteúdo para a linha ser do modelo: linha com o
 * nome preenchido e o QR vazio continua imprimindo, e continua aparecendo na
 * Conferência como célula vazia. Só sai a linha que não tem nada daquele modelo.
 *
 * A regra não se aplica — e a lista volta inteira — quando a numeração não tem
 * elemento de banco (não há coluna para medir) ou quando nenhuma das colunas
 * dela existe no CSV: esse caso já é o "banco incompleto", que avisa e segura o
 * PRONTO com um recado próprio. Filtrar ali zeraria a tiragem por causa de um
 * nome de coluna errado.
 */
function linhasComDadoDaNumeracao(rows, num) {

    if (!Array.isArray(rows) || !rows.length) return Array.isArray(rows) ? rows : [];

    const colunas = colunasDoBancoDaNumeracao(num);

    if (!colunas.length) return rows;

    const cabecalho = (num && num.csv_headers && num.csv_headers.length)

        ? num.csv_headers.map(c => String(c))

        : Object.keys(rows[0] || {}).filter(k => k !== '__ativo' && k !== '__id' && k !== '__fotos');

    const existentes = colunas.filter(c => cabecalho.indexOf(c) !== -1);

    if (!existentes.length) return rows;

    return rows.filter(r => existentes.some(c => {

        const v = r ? r[c] : null;

        return String(v === null || v === undefined ? '' : v).trim() !== '';

    }));

}
window.linhasComDadoDaNumeracao = linhasComDadoDaNumeracao;



/**
 * As linhas do banco que ESTE modelo imprime, na ordem original — que é a ordem
 * de impressão. Item sem `csv_selecao` recebe o banco inteiro, que é o
 * comportamento de todo pedido anterior a esta versão.
 *
 * Sobre o que sobrar, seja a distribuição ou o banco inteiro, ainda passa o
 * corte por coluna (`linhasComDadoDaNumeracao`): linha sem nada nas colunas que
 * esta numeração lê não é célula deste modelo, nem para contar nem para imprimir.
 * Os dois cortes se somam — desmarcar continua sendo a palavra final do
 * operador sobre uma linha que TEM dado.
 */
function fatiaCsvDoItem(item, num) {

    const rows = (num && num.csv_data) || [];

    const sel = item && item.csv_selecao;

    const mesmaNum = item && num && String(numeracaoIdDoItem(item)) === String(num.id);

    const base = (!sel || !mesmaNum || !window.CsvEditor)

        ? linhasAtivasCsv(rows)

        : window.CsvEditor.fatiaDoModelo(rows, sel);

    return linhasComDadoDaNumeracao(base, num);

}



/**
 * Numerações com CSV que dois ou mais modelos do pedido compartilham. Com um
 * modelo só não há o que distribuir — ele leva o banco inteiro.
 */
function gruposDeCsvDoPedido(osId) {

    const itens = state.osItens[osId] || [];

    // Agrupado pela FONTE (27/08/2026), e nao pela numeracao: dois modelos so
    // dividem linhas quando bebem do MESMO poco. Ver `fonteDoModelo`.
    const porFonte = {};

    itens.forEach(it => {

        const fonte = fonteDoModelo(it);

        if (!fonte) return;

        if (!porFonte[fonte.chave]) porFonte[fonte.chave] = { fonte, num: fonte.num || null, itens: [] };

        porFonte[fonte.chave].itens.push(it);

    });

    return Object.values(porFonte).filter(g => g.itens.length >= 2);

}



/**
 * Nome curto do modelo para a tela de distribuição. Cuidado: `item.modelo` NÃO
 * é o nome — o loadOSItens o preenche com o id do registro. O nome de gente
 * está em `nome_modelo`, e `produto` é derivado dele.
 */
function rotuloDoModelo(item, i) {

    return item.nome_modelo || item.produto || item.nome_produto_real || `Modelo ${i + 1}`;

}



/**
 * Abre a tela de distribuição do banco entre os modelos do pedido. `focoItemId`
 * destaca um modelo — é por onde o botão do card entra, para o operador ver de
 * cara qual das faixas coloridas é a dele.
 *
 * Vale também com UM modelo só: escolher que ele imprime parte do banco é
 * legítimo, e era o único jeito de recortar uma fatia sem ter um segundo modelo.
 */
/**
 * A distribuição que o modal devolveu deu linha a ALGUM modelo?
 *
 * O modal manda uma entrada por modelo, sempre — inclusive vazia —, porque numa
 * distribuição de verdade o modelo esquecido PRECISA ficar gravado com zero: ler
 * a ausência como "o banco inteiro" fazia o esquecido imprimir tudo, o oposto do
 * que a tela dizia, e em silêncio (v630).
 *
 * Só que "todos vazios" não é uma distribuição: é o operador que marcou as
 * linhas e clicou em Aplicar sem o segundo passo, que é clicar no NOME do
 * modelo. Gravar ali põe TODOS em zero, e modelo sem linha não imprime nada.
 *
 * Foi o que zerou o pedido 21146 em 25/08/2026: três modelos, cada um com a sua
 * numeração e o seu banco de 13 linhas, todos gravados com `ids: []`. O card
 * mostrava "0 de 13" em vermelho, e repetir a operação zerava de novo — nas
 * palavras do usuário, "mesmo selecionando o banco inteiro no Linhas, nada
 * muda". Não havia como sair pela tela.
 */
function distribuicaoAtribuiuAlgo(distribuicao) {
    const d = distribuicao || {};
    return Object.keys(d).some(k => {
        const sel = d[k];
        return !!(sel && Array.isArray(sel.ids) && sel.ids.length);
    });
}
window.distribuicaoAtribuiuAlgo = distribuicaoAtribuiuAlgo;

window.abrirDistribuicaoCsv = function(osId, chaveDaFonte, focoItemId) {

    if (typeof window.abrirEditorCsv !== 'function') {

        toast('O editor de CSV não carregou. Recarregue a página.', 'error');

        return;

    }

    // A FONTE, e nao a numeracao (27/08/2026): o modelo pode beber do banco do
    // pedido, e ai as linhas -- e os `__id` que a distribuicao guarda -- sao as
    // dele, nao as do CSV de dentro da numeracao. Ver `fonteDoModelo`.
    const fonte = fontePelaChave(chaveDaFonte);

    const itens = (state.osItens[osId] || []).filter(it => {
        const f = fonteDoModelo(it);
        return f && fonte && f.chave === fonte.chave;
    });

    if (!fonte || !fonte.rows.length || !itens.length) {

        toast('Nenhum modelo deste pedido usa esse banco de dados.', 'error');

        return;

    }

    const num = fonte.num || null;

    const grupo = { num, itens };

    window.abrirEditorCsv({

        headers: fonte.headers,

        rows: fonte.rows,

        filename: fonte.filename,

        foco: focoItemId != null ? String(focoItemId) : null,

        // Os checkboxes de "conferir repeticoes em" (26/08/2026). Nascem como
        // a numeracao esta hoje -- e toda numeracao anterior a este dia nasce
        // com todas marcadas, porque a marca de FORA e que e explicita.
        // Com banco do pedido (28/08/2026) as caixas voltam, mas pelas colunas
        // da PECA: a marca mora nos elementos, e e o mapa de cada modelo que a
        // leva ate a coluna do dia dele. Ver `conferenciaDasColunasDoGrupo`.
        conferencia: conferenciaDasColunasDoGrupo(fonte, grupo.itens),

        modelos: grupo.itens.map((it, i) => ({

            id: String(it.id),

            nome: rotuloDoModelo(it, i),

            selecao: it.csv_selecao || null

        })),

        onAplicar: async ({ rows, distribuicao, conferencia }) => {

            // 1. As linhas podem ter mudado (cancelar/reativar) e ganhado __id
            //    novo. Grava o banco de volta na numeração, uma vez só.
            await salvarLinhasDaFonte(fonte, rows);

            // A escolha das colunas conferidas mora nos ELEMENTOS, e por isso
            // ela e gravada aqui e nao junto das fatias: fatia e do modelo,
            // conferencia e da peca. As chaves de `conferencia` sao sempre os
            // nomes de coluna DA PECA (ver conferenciaDasColunasDoGrupo), entao
            // gravar e igual nos dois mundos — com banco do pedido, so muda que
            // o grupo pode ter mais de uma peca.
            const conferenciaMudou = await aplicarConferenciaNoGrupo(fonte, grupo.itens, conferencia);

            // 2. Aplicar sem atribuir NENHUMA linha a NENHUM modelo não é uma
            //    distribuição — é o segundo passo que faltou. Gravar aqui poria
            //    todos em zero, e zero linha não imprime nada. Ver
            //    distribuicaoAtribuiuAlgo(): o modelo esquecido de uma
            //    distribuição de verdade continua sendo gravado vazio.
            if (!distribuicaoAtribuiuAlgo(distribuicao)) {

                renderImpOSQueue();

                redesenharCardsDoPedido(osId);

                // A frase precisa dizer o que ACONTECEU, e desde 26/08/2026 pode
                // ter acontecido uma coisa: a escolha das colunas conferidas. Dizer
                // "nada foi mudado" depois de gravá-la manda o operador achar que o
                // checkbox não pegou -- e foi exatamente o que ele relatou.
                toast(conferenciaMudou
                    ? 'Colunas da conferência salvas. Nenhuma linha foi atribuída a '
                      + 'nenhum modelo, então a distribuição ficou como estava.'
                    : 'Nenhuma linha foi atribuída a nenhum modelo, então nada '
                      + 'foi mudado. Marque as linhas e clique no NOME do modelo '
                      + 'para dá-las a ele.',
                    conferenciaMudou ? 'success' : 'info');

                return;

            }

            // 3. A fatia de cada modelo vai para o registro dele no pedido.
            let semFatia = 0;

            for (const it of grupo.itens) {

                const sel = distribuicao[String(it.id)] || { tipo: 'linhas', ids: [] };

                it.csv_selecao = sel;

                if (!sel.ids.length) semFatia++;

                await autoSaveOSItemField(it.id, osId, 'csv_selecao', sel);

            }

            renderImpOSQueue();

            // O card de cada modelo mostra a fatia dele; sem isto continuaria
            // exibindo a contagem e a página anteriores até o próximo redesenho.
            redesenharCardsDoPedido(osId);

            const ativas = linhasAtivasCsv(rows).length;

            // Linha compartilhada (28/08/2026) conta UMA vez: a sobra é o que
            // ficou sem NENHUM modelo, e não a diferença contra a soma das
            // fatias — que passa do total quando os modelos dividem colunas.
            const distribuidas = new Set(grupo.itens.flatMap(it =>
                window.CsvEditor.expandirIds((it.csv_selecao && it.csv_selecao.ids) || []))).size;

            const sobra = ativas - distribuidas;

            toast(

                `Distribuição salva: ${distribuidas} de ${ativas} linhas`

                + (sobra > 0 ? `, ${sobra} sem modelo` : '')

                + (semFatia ? `, ${semFatia} modelo(s) sem nenhuma linha` : ''),

                sobra > 0 || semFatia ? 'info' : 'success'

            );

        }

    });

};



/** Grava só o csv_data de uma numeração, sem passar pelo editor dela. */
async function salvarCsvDaNumeracao(numId, rows) {

    return salvarCamposDaNumeracao(numId, { csv_data: rows });

}



/**
 * Grava campos avulsos de uma numeração. Existe porque o banco de dados passou
 * a ser editável de fora do editor de numeração — do card do modelo, no pedido —
 * e ali não há formulário para submeter: é uma alteração cirúrgica.
 */
async function salvarCamposDaNumeracao(numId, patch) {

    // Gravou por cima do banco de dados: o que `garantirCsvDaNumeracao` tiver
    // baixado desta numeracao esta velho a partir de agora.
    if (patch && Object.prototype.hasOwnProperty.call(patch, 'csv_data')) {
        esquecerCsvDaNumeracao(numId);
    }

    try {

        if (typeof supabaseClient !== 'undefined' && supabaseClient) {

            const { error } = await supabaseClient

                .from('producao_numeracoes')

                .update(patch)

                .eq('id', numId);

            if (error) throw error;

        } else {

            await fetch(`${API_BASE_URL}/api/numeracoes/${numId}`, {

                method: 'PUT',

                headers: { 'Content-Type': 'application/json' },

                body: JSON.stringify(patch)

            });

        }

    } catch (e) {

        console.error('[CSV] Erro ao gravar na numeração:', e);

        toast('Não foi possível gravar na numeração: ' + e.message, 'error');

    }

}




// ─────────────────────────────────────────────────────────────────────────────
// VISUALIZACAO PAGINADA DA AMOSTRA (uma pagina por linha do CSV)
//
// Numeracao com elemento de CSV nao tem "uma" amostra: tem uma por linha de
// dado. A visualizacao do card vira multipagina, e cada modelo navega apenas
// pelas linhas da SUA fatia — as que lhe foram atribuidas na distribuicao.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * As linhas que a visualizacao deste modelo pode mostrar. E a fatia do modelo
 * quando ele tem uma; senao o banco inteiro da numeracao; senao o que estiver
 * carregado na Imposicao (o comportamento antigo, que atende a amostra avulsa).
 *
 * ## O banco "solto" so vale quando veio de FORA de uma numeracao
 *
 * Corrigido em 22/08/2026. A numeracao "Expointer 2026", sem CSV nenhum no
 * banco, mostrava "1 de 19.500" no card do modelo: eram as linhas da numeracao
 * 1000475, que tinham ficado em `state.csvData` (a fatia montada quando o
 * operador olhou aquele modelo) e em `state.numCsvData` (o editor). Como a
 * Expointer tinha um elemento de banco de dados, a tela pedia linhas, nao
 * achava nenhuma dela e pegava emprestadas as da vizinha.
 *
 * Agora o terceiro degrau so existe para CSV que NAO pertence a numeracao
 * nenhuma — o arquivo subido na caixa da Imposicao ou o mapa de teatro
 * (`state.csvDataDerivado === false`). Fatia de numeracao nao e emprestada, e o
 * estado do editor (`numCsvData`) nunca entra: ele e de quem esta editando, nao
 * do modelo que esta sendo desenhado.
 */
function linhasDaAmostra(item, num) {

    if (num && num.csv_data && num.csv_data.length) {

        return fatiaCsvDoItem(item, num);

    }

    if (item && item.csv_data && item.csv_data.length) return linhasAtivasCsv(item.csv_data);

    if (state.csvDataDerivado) return [];

    const solto = state.csvData || null;

    return solto && solto.length ? linhasAtivasCsv(solto) : [];

}



/**
 * A pagina fica num mapa do state, e nao no objeto do item, porque o pedido
 * recarrega os itens em segundo plano e substitui os objetos — um campo posto
 * no item se perderia no meio da navegacao, e o operador veria a pagina voltar
 * sozinha para a primeira linha.
 */
function chaveDaAmostra(osId, item) {

    return `${osId || ''}:${item ? item.id : ''}`;

}



/** Pagina corrente do modelo, sempre dentro do intervalo. */
function paginaDaAmostra(item, total, osId) {

    if (!total) return 0;

    if (!state.amostraCsvPaginas) state.amostraCsvPaginas = {};

    const p = parseInt(state.amostraCsvPaginas[chaveDaAmostra(osId, item)]) || 0;

    return Math.max(0, Math.min(total - 1, p));

}



/** A linha do CSV que a visualizacao deste modelo esta mostrando agora. */
function linhaDaAmostra(item, num, osId) {

    const linhas = linhasDaAmostra(item, num);

    if (!linhas.length) return null;

    return linhas[paginaDaAmostra(item, linhas.length, osId)] || null;

}



/**
 * Move a visualizacao do modelo. `delta` anda; `absoluto` vai direto (1-based,
 * como o operador le na tela).
 */
window.amostraCsvPagina = function(idx, osId, delta, absoluto) {

    const item = state.osItens[osId] ? state.osItens[osId][idx] : null;

    if (!item) return;

    // Resolvida pelo banco do pedido: o total de paginas e o das linhas que
    // este modelo de fato mostra (28/08/2026).
    const num = numeracaoDoModelo(item);

    const total = linhasDaAmostra(item, num).length;

    if (!total) return;

    let nova = (typeof absoluto === 'number' && !isNaN(absoluto))

        ? absoluto - 1

        : paginaDaAmostra(item, total, osId) + (delta || 0);

    if (!state.amostraCsvPaginas) state.amostraCsvPaginas = {};

    state.amostraCsvPaginas[chaveDaAmostra(osId, item)] = Math.max(0, Math.min(total - 1, nova));

    // Navegar nao e editar: nao marca _needsSnapshot, senao o instantaneo que
    // vai para o link do cliente passaria a ser a linha que o operador estava
    // olhando por acaso.
    //
    // Devolve a promessa: a janela ampliada espelha o canvas do card e precisa
    // esperar o desenho terminar antes de copiar o bitmap.
    return renderItemAmostraCombinada(idx, osId);

};



/**
 * Mostra e preenche a navegacao de linhas do CSV no card de um modelo.
 * Espelha o idioma que o modo PDF ja usa logo acima (amostra-pdf-nav-N).
 */
function atualizarNavCsvDaAmostra(idx, item, num, container, osId) {

    const nav = container.querySelector(`#amostra-csv-nav-${idx}`);

    if (!nav) return;

    const linhas = linhasDaAmostra(item, num);

    const temElementoCsv = !!(num && (num.elements || []).some(el => el.source === 'database'));

    // So aparece quando ha de fato dado variavel vindo de CSV para navegar.
    if (!temElementoCsv || linhas.length <= 1) {

        nav.style.display = 'none';

        return;

    }

    nav.style.display = 'flex';

    const total = linhas.length;

    const pag = paginaDaAmostra(item, total, osId);

    const linha = linhas[pag] || {};

    const info = container.querySelector(`#amostra-csv-info-${idx}`);

    if (info) info.textContent = `Linha ${pag + 1} / ${total}`;

    const resumo = container.querySelector(`#amostra-csv-resumo-${idx}`);

    if (resumo) {

        // Um resumo curto da linha para o operador saber o que esta vendo sem
        // precisar abrir o banco.
        //
        // As colunas do resumo sao as que ESTE modelo imprime (28/08/2026):
        // `num` aqui ja e a peca resolvida pelo banco do pedido, entao elas
        // saem do 🔤 de cada modelo. Ha pedido em que os modelos COMPARTILHAM
        // as linhas e dividem as colunas — mostrar as tres primeiras do banco
        // punha no card a coluna do modelo vizinho. Peca sem coluna apontada
        // nenhuma cai no resumo antigo, as primeiras colunas do banco.
        const doModelo = window.BancoDoModelo
            ? window.BancoDoModelo.colunasQueAPecaPede(num)
            : [];
        const cols = doModelo.length ? doModelo
            : ((num.csv_headers && num.csv_headers.length)

            ? num.csv_headers

            : Object.keys(linha).filter(k => k !== '__ativo' && k !== '__id'));

        resumo.textContent = cols.slice(0, 3)

            .map(c => `${c}: ${linha[c] == null ? '' : linha[c]}`)

            .join('  ·  ');

    }

    const goto = container.querySelector(`#amostra-csv-goto-${idx}`);

    if (goto && document.activeElement !== goto) {

        goto.value = pag + 1;

        goto.max = total;

    }

    const bPrev = container.querySelector(`#amostra-csv-prev-${idx}`);

    const bNext = container.querySelector(`#amostra-csv-next-${idx}`);

    if (bPrev) bPrev.disabled = pag <= 0;

    if (bNext) bNext.disabled = pag >= total - 1;

}



/**
 * Liga os dois botões de CSV do card do modelo. Ficam escondidos enquanto a
 * numeração escolhida não tiver banco de dados — e como a numeração muda pelo
 * seletor sem redesenhar o card inteiro, quem decide isso é esta função, a cada
 * redesenho, e não o template.
 */
function atualizarBotoesCsvDaAmostra(idx, item, num, container, osId) {

    const linha = container.querySelector(`#linha-csv-${idx}`);

    if (!linha) return;

    // TRES estados, e o do meio e novo (26/08/2026).
    //
    // A caixa aparece pelo `csv_filename`, e nao pelas linhas: enquanto o banco
    // desce em segundo plano, `csv_data` e `undefined`, e a versao anterior
    // desta funcao escondia a caixa inteira -- a caixa do banco piscava para
    // fora da tela e voltava. Pior: o `minhas` daria zero e o botao ficaria
    // VERMELHO dizendo "este modelo esta SEM nenhuma linha", que e a frase que
    // manda o operador ir mexer numa distribuicao que esta certa.
    const baixando = !!(num && num.csv_data === undefined && numeracaoTemBanco(num));

    // A caixa aparece tambem quando o PEDIDO tem banco proprio, ou quando este
    // modelo esta ligado a um (27/08/2026). Sem isso, a peca cujo CSV nao mora
    // dentro dela nao teria onde receber o banco -- e um modelo ligado a um
    // banco ficaria sem o controle que o desliga.
    const vinculoDaqui = vinculoDeBancoDoModelo(item);
    const pedidoTemBanco = !!(state.bancosDoPedido && state.bancosDoPedido.length);

    // E aparece tambem quando a peca TEM campo de banco e nao trouxe CSV
    // nenhum: é exatamente a numeracao reaproveitada (ou recem-criada) sem dado
    // dentro, a que precisa da porta para receber o banco do pedido. Campo COM
    // ou SEM coluna escolhida — a peca feita para este fluxo nasce sem CSV, e
    // sem CSV nao ha coluna para escolher ainda: exigir o nome da coluna (o
    // que `colunasQueAPecaPede` faz, de proposito, para o mapa) escondia o
    // "Vem de:" justamente da peca nova do pedido de teste 21346 (28/08/2026).
    const pecaPedeColuna = !!(num && (num.elements || [])
        .some(el => el && el.source === 'database'));

    const temCsv = baixando || !!(num && num.csv_data && num.csv_data.length)
        || !!vinculoDaqui || pedidoTemBanco || pecaPedeColuna;

    linha.style.display = temCsv ? 'flex' : 'none';

    if (!temCsv) return;

    desenharEscolhaDeBanco(idx, item, container, vinculoDaqui);
    desenharColunasDoModeloNoCard(idx, item, container, vinculoDaqui);

    // O "Colunas" so existe com banco do pedido: no CSV de dentro da numeracao
    // os campos ja apontam para as colunas dela, e nao ha de-para a fazer.
    const bColunas = container.querySelector(`#btn-csv-colunas-${idx}`);
    if (bColunas) bColunas.style.display = vinculoDaqui ? '' : 'none';

    // A edicao do conteudo do banco do PEDIDO mora no box "Gerenciamento de
    // Bancos de Dados" (📊 Conferir), nao aqui: o card so tem o que e do
    // MODELO. O banco da numeracao continua com uma porta so, a do editor de
    // numeracao — decisao do usuario em 26/08/2026, redesenho em 28/08/2026.

    // Sem nenhuma linha para contar, o resto da caixa nao tem o que dizer. Sem
    // esta saida o "Linhas" ficaria VERMELHO anunciando que o modelo esta sem
    // linhas -- o que e falso: ele so ainda nao recebeu banco nenhum.
    const semDado = !baixando && !(num && num.csv_data && num.csv_data.length);
    const bLinhas = container.querySelector(`#btn-csv-fatia-${idx}`);
    if (semDado) {
        if (bLinhas) bLinhas.style.display = 'none';
        const semNome = container.querySelector(`#csv-nome-${idx}`);
        if (semNome) semNome.textContent = '—';
        return;
    }
    if (bLinhas) bLinhas.style.display = '';

    const nome = container.querySelector(`#csv-nome-${idx}`);

    if (nome) nome.textContent = num.csv_filename || 'banco.csv';

    if (baixando) {
        const contaEmEspera = container.querySelector(`#csv-conta-${idx}`);
        if (contaEmEspera) contaEmEspera.textContent = 'carregando…';
        const bEspera = container.querySelector(`#btn-csv-fatia-${idx}`);
        if (bEspera) {
            bEspera.disabled = true;
            bEspera.title = 'Baixando o banco de dados desta numeração…';
            bEspera.style.color = '';
            bEspera.style.borderColor = '';
        }
        return;
    }

    const minhas = fatiaCsvDoItem(item, num).length;

    const total = linhasAtivasCsv(num.csv_data).length;

    const conta = container.querySelector(`#csv-conta-${idx}`);

    if (conta) conta.textContent = `${minhas} de ${total}`;

    const bFatia = container.querySelector(`#btn-csv-fatia-${idx}`);

    if (!bFatia) return;

    bFatia.disabled = false;

    bFatia.title = minhas

        ? `Este modelo imprime ${minhas} das ${total} linhas do banco. Clique para mudar.`

        : 'Este modelo está SEM nenhuma linha — não imprimiria nada. Clique para escolher.';

    // Um modelo sem nenhuma linha não imprime nada — avisar aqui é mais barato
    // do que descobrir na frente da impressora.
    // ── O "Separar por dia" ──────────────────────────────────────────────
    //
    // Aparece so quando ha o que fazer: banco com coluna `Data` e mais de um
    // dia, e ao menos um modelo do pedido cuja Qtd fecha com as linhas do dia
    // que o NOME dele anuncia. Controle que nao tem o que fazer nao fica na
    // tela -- e, aqui, um botao que criasse numeracoes por engano custaria
    // caro.
    const bDia = container.querySelector(`#btn-csv-dia-${idx}`);
    if (bDia) {
        let plano = null;
        try { plano = planoDeSeparacaoPorDia(osId, num); } catch (e) { plano = null; }
        bDia.style.display = plano ? '' : 'none';
        if (plano) {
            bDia.title = 'Criar ' + plano.entram.length + ' numeração(ões) — uma por dia ('
                + plano.dias.join(', ') + ') — e apontar cada modelo para a sua. '
                + 'O banco original não é alterado.';
        }
    }

    bFatia.style.color = minhas ? '' : 'var(--red, #ef4444)';

    bFatia.style.borderColor = minhas ? '' : 'var(--red, #ef4444)';

}



/**
 * Enche o seletor "Vem de:" do card com as opcoes daquele modelo.
 *
 * A primeira opcao e sempre a numeracao, e ela e a escolhida quando nao ha
 * vinculo -- e por isso que todo pedido que ja existe abre exatamente como
 * antes, so que agora mostrando de onde o dado vem.
 */
function desenharEscolhaDeBanco(idx, item, container, vinculo) {
    const sel = container.querySelector(`#banco-do-pedido-${idx}`);
    if (!sel) return;
    const esc = escDoBanco;

    const bancos = state.bancosDoPedido || [];
    const atual = vinculo ? String(vinculo.banco_id) : '';

    // SO escolha, nenhuma acao (28/08/2026, redesenho do usuario): criar,
    // renomear, atualizar e excluir bancos moram no box "Gerenciamento de
    // Bancos de Dados" do pedido, na coluna do Briefing. Aqui o modelo apenas
    // ADOTA um banco ja carregado — ou volta para a numeracao.
    const opcoes = ['<option value="">a numeração (padrão)</option>'];
    bancos.forEach(b => {
        const nome = esc(b.nome || b.csv_filename || 'banco');
        const linhas = Array.isArray(b.csv_data) ? b.csv_data.length : 0;
        opcoes.push(`<option value="${esc(String(b.id))}">${nome} — ${linhas} linha(s)</option>`);
    });
    if (!bancos.length) {
        opcoes.push('<option value="" disabled>— crie um banco em "Gerenciamento de Bancos de Dados" —</option>');
    }

    sel.innerHTML = opcoes.join('');
    sel.value = atual;
    // Vinculo apontando para banco que nao veio: nao fingir que esta na
    // numeracao. Quem barra a impressao nesse caso e o
    // `modelosComBancoNaoBaixado`, e a tela tem de contar a mesma historia.
    if (atual && sel.value !== atual) {
        sel.insertAdjacentHTML('afterbegin',
            `<option value="${esc(atual)}">banco não encontrado</option>`);
        sel.value = atual;
    }
}
window.desenharEscolhaDeBanco = desenharEscolhaDeBanco;

/**
 * As colunas escolhidas para ESTE modelo, no proprio card (consideracao do
 * usuario em 28/08/2026): uma ficha por elemento de banco, com o nome da
 * coluna que ele le. SO os nomes — a marca de conferencia de repeticoes fica
 * no modal 🔤, por decisao dele, e nao aparece aqui.
 *
 * Elemento ainda sem coluna (ou apontando para coluna que o banco nao tem)
 * vira ficha vermelha "sem coluna" — a mesma historia que a trava de
 * impressao (`modelosComElementoSemColuna`) conta, contada antes de apertar
 * Imprimir. Clicar na faixa abre o 🔤, que e onde se conserta.
 */
function desenharColunasDoModeloNoCard(idx, item, container, vinculo) {
    const alvo = container.querySelector(`#csv-colunas-modelo-${idx}`);
    if (!alvo) return;
    const esc = escDoBanco;

    const banco = window.BancoDoModelo
        ? window.BancoDoModelo.bancoDoModelo(vinculo, state.bancosDoPedido || [])
        : null;
    const peca = pecaDoModelo(item);
    const elementos = ((peca && peca.elements) || []).filter(el => el && el.source === 'database');

    // Sem banco do pedido nao ha escolha a mostrar: no caminho da numeracao
    // as colunas moram na propria peca, como sempre.
    if (!banco || !elementos.length) {
        alvo.style.display = 'none';
        alvo.innerHTML = '';
        return;
    }

    const cabecalho = (banco.csv_headers || []).map(String);
    const mapa = (vinculo && vinculo.csv_mapa) || {};
    const fichas = elementos.map(el => {
        const col = window.BancoDoModelo.colunaDoElemento(mapa, el);
        const ok = col !== '' && cabecalho.indexOf(col) !== -1;
        const nome = String(el.name || '').trim() || 'Elemento';
        const titulo = ok ? (nome + ' lê a coluna ' + col) : (nome + ' ainda não tem coluna no banco');
        const estilo = ok
            ? 'border:1px solid var(--border); color:var(--text);'
            : 'border:1px solid var(--red,#ef4444); color:var(--red,#ef4444);';
        return `<span title="${esc(titulo)}" style="${estilo} border-radius:999px; padding:1px 8px; font-size:0.75rem; white-space:nowrap;">${ok ? esc(col) : 'sem coluna'}</span>`;
    });
    alvo.innerHTML = '<span style="font-size:0.75rem; color:var(--text-dim);">Colunas:</span>' + fichas.join('');
    alvo.style.display = 'flex';
}
window.desenharColunasDoModeloNoCard = desenharColunasDoModeloNoCard;

/** O input de arquivo do banco do pedido, criado uma vez e reaproveitado. */
let _bancoPedidoPendente = null;
function _inputDoBancoDoPedido() {
    let el = document.getElementById('banco-pedido-file');
    if (el) return el;
    el = document.createElement('input');
    el.type = 'file';
    el.id = 'banco-pedido-file';
    el.accept = '.csv,text/csv,text/plain';
    el.style.display = 'none';
    el.addEventListener('change', () => { subirBancoDoPedido().catch(e => toast(String(e.message || e), 'error')); });
    document.body.appendChild(el);
    return el;
}

/**
 * O operador mexeu no "Vem de:". Dois destinos, e so escolha: a numeracao
 * (desligar) ou um banco ja carregado no pedido (ligar). Criar banco e coisa
 * do box "Gerenciamento de Bancos de Dados".
 */
async function trocarBancoDoModelo(idx, osId, valor) {
    const item = (state.osItens[osId] || [])[idx];
    if (!item) return;

    try {
        await ligarModeloAoBanco(item.id, valor || null, null);
        toast(valor ? 'Este modelo passou a ler o banco do pedido.'
                    : 'Este modelo voltou a ler o banco da numeração.', 'success');
        // Trocar o banco troca a identidade das linhas: a distribuicao que
        // existia apontava para `__id` de OUTRO banco e nao quer dizer mais
        // nada. Some junto, e o modelo volta a levar tudo.
        if (item.csv_selecao) {
            item.csv_selecao = null;
            await supabaseClient.from('pedidos_modelos').update({ csv_selecao: null }).eq('id', item.id);
            toast('A distribuição de linhas deste modelo foi limpa: o banco novo tem outras linhas.', 'info');
        }
        renderAmostrasOSItens(osId);
    } catch (e) {
        toast('Não deu para trocar o banco: ' + (e.message || e), 'error');
        renderAmostrasOSItens(osId);
    }
}
window.trocarBancoDoModelo = trocarBancoDoModelo;

/**
 * O de-para de colunas deste modelo: cada coluna que a PECA pede recebe uma
 * coluna do banco do pedido.
 *
 * A lista da esquerda sai da peca CRUA (`pecaDoModelo`), e nao da resolvida:
 * na resolvida os nomes ja estao trocados, e a tela mostraria o destino no
 * lugar da origem -- reabrir o modal moveria o apontamento de novo.
 */
function abrirColunasDoModelo(idx, osId) {
    const esc = escDoBanco;
    const item = (state.osItens[osId] || [])[idx];
    const peca = pecaDoModelo(item);
    const vinc = vinculoDeBancoDoModelo(item);
    const banco = window.BancoDoModelo.bancoDoModelo(vinc, state.bancosDoPedido || []);

    if (!banco) {
        toast('Este modelo não está ligado a nenhum banco do pedido. Escolha um em "Vem de:".', 'info');
        return;
    }

    // UMA LINHA POR ELEMENTO (28/08/2026, redesenho do usuario): a peca nao
    // escolhe mais coluna — guarda so o desenho e um "Exemplo:" — e e AQUI, no
    // modelo, que cada elemento aponta a sua coluna, direto do banco anexado.
    // O apontamento grava no vinculo com chave por elemento (`el:<id>`); o
    // `csv_column` legado continua valendo como fallback, entao toda peca
    // antiga abre com a coluna dela ja selecionada.
    const elementos = ((peca && peca.elements) || []).filter(el => el && el.source === 'database');
    if (!elementos.length) {
        toast('Esta numeração não tem nenhum elemento de banco de dados — não há o que apontar.', 'info');
        return;
    }

    const cabecalho = (banco.csv_headers || []).map(String);
    const mapa = (vinc && vinc.csv_mapa) || {};

    // O mesmo selo que a lista de elementos do editor usa, mais o nome que o
    // operador deu ao item — e assim que ele reconhece o elemento.
    const selo = { TEXT: '🔤 Numeração', FIXED: '🔠 Texto Fixo', QR: '📱 QR Code', QR_IDEAL: '🎟️ QR Ideal', BARCODE: '▌▌ Barcode', SVG: '🎨 SVG', PDF: '📄 PDF', FOTO: '🖼️ Foto', TEATRO_FILA: '🎭 Fila', TEATRO_LUGAR: '🎭 Lugar', TEATRO_COMBO: '🎭 Fila & Lugar', CAMAROTE_LOCAL: '🏛️ Local', CAMAROTE_PESSOA: '👤 Pessoas', CAMAROTE_PESSOA_TOTAL: '👥 Pessoas 1/Total' };
    const nomeDoElemento = (el) => {
        // O nome e o exemplo sao digitados pelo operador: escapa antes do HTML.
        const tipo = esc(selo[el.type] || el.type || 'Elemento');
        const nome = String(el.name || '').trim();
        const exemplo = String(el.exemplo || '').trim();
        return tipo + (nome ? ' — ' + esc(nome) : '')
            + (exemplo ? '<br><span style="color:var(--text-dim); font-size:0.78rem;">ex.: ' + esc(exemplo) + '</span>' : '');
    };

    const linhas = elementos.map(el => {
        const escolhida = window.BancoDoModelo.colunaDoElemento(mapa, el);
        const temNoBanco = escolhida !== '' && cabecalho.indexOf(escolhida) !== -1;
        const opcoes = ['<option value="">— escolher —</option>'].concat(
            cabecalho.map(h => `<option value="${esc(h)}"${h === escolhida ? ' selected' : ''}>${esc(h)}</option>`)
        ).join('');
        return `<tr>
            <td style="padding:8px 10px; border-bottom:1px solid var(--border); font-size:0.85rem;">${nomeDoElemento(el)}</td>
            <td style="padding:8px 10px; border-bottom:1px solid var(--border);">
                <select class="form-control mapa-el" data-el="${esc(String(el.id))}"
                    style="width:100%; ${temNoBanco ? '' : 'border-color:var(--red,#ef4444);'}">${opcoes}</select>
            </td>
            <td style="padding:8px 10px; border-bottom:1px solid var(--border); text-align:center;">
                <input type="checkbox" class="conferir-el" data-el="${esc(String(el.id))}" ${el.sem_conferencia ? '' : 'checked'}
                    title="Conferir repetições desta coluna na Conferência de dados. A marca vale para a numeração inteira, em todos os pedidos.">
            </td>
        </tr>`;
    }).join('');

    const over = document.createElement('div');
    over.id = 'colunas-do-modelo-overlay';
    over.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.65); z-index:12000;'
        + 'display:flex; align-items:center; justify-content:center; padding:20px;';
    over.innerHTML = `
        <div style="background:var(--bg-card,#161b22); border:1px solid var(--border); border-radius:var(--radius,8px);
                    max-width:680px; width:100%; max-height:85vh; display:flex; flex-direction:column;">
            <div style="padding:14px 18px; border-bottom:1px solid var(--border);">
                <div style="font-weight:800; font-size:1.05rem;">🔤 Colunas deste modelo</div>
                <div style="color:var(--text-dim); font-size:0.85rem; margin-top:3px;">
                    ${esc(rotuloDoModelo(item, idx))} · peça: ${esc(peca.name || peca.tipo || 'numeração')}
                    · banco: ${esc(banco.nome || 'banco')}<br>
                    Aponte de qual coluna do banco cada elemento lê. A escolha vale só para ESTE modelo.
                </div>
            </div>
            <div style="overflow:auto; padding:0 4px;">
                <table style="width:100%; border-collapse:collapse;">
                    <thead><tr>
                        <th style="text-align:left; padding:8px 10px; color:var(--text-dim); font-size:0.78rem; text-transform:uppercase;">Elemento</th>
                        <th style="text-align:left; padding:8px 10px; color:var(--text-dim); font-size:0.78rem; text-transform:uppercase;">Coluna no banco</th>
                        <th style="text-align:center; padding:8px 10px; color:var(--text-dim); font-size:0.78rem; text-transform:uppercase;" title="Conferir repetições na Conferência de dados">Conferir</th>
                    </tr></thead>
                    <tbody>${linhas}</tbody>
                </table>
            </div>
            <div style="padding:12px 18px; border-top:1px solid var(--border); display:flex; gap:8px; justify-content:flex-end;">
                <button class="btn btn-secondary" onclick="fecharColunasDoModelo()">Cancelar</button>
                <button class="btn btn-primary" onclick="aplicarColunasDoModelo(${idx}, '${osId}')">Aplicar</button>
            </div>
        </div>`;
    document.body.appendChild(over);
}
window.abrirColunasDoModelo = abrirColunasDoModelo;

function fecharColunasDoModelo() {
    const o = document.getElementById('colunas-do-modelo-overlay');
    if (o) o.remove();
}
window.fecharColunasDoModelo = fecharColunasDoModelo;

async function aplicarColunasDoModelo(idx, osId) {
    const over = document.getElementById('colunas-do-modelo-overlay');
    if (!over) return;
    const item = (state.osItens[osId] || [])[idx];
    const vinc = vinculoDeBancoDoModelo(item);
    if (!vinc) { fecharColunasDoModelo(); return; }

    const peca = pecaDoModelo(item);
    const elementos = ((peca && peca.elements) || []).filter(el => el && el.source === 'database');

    // O apontamento por ELEMENTO, deste modelo. `mapaLimpo` dispensa o que o
    // fallback ja acha sozinho (apontamento igual ao csv_column legado) e
    // descarta chave de elemento que a peca nao tem mais.
    const mapa = {};
    over.querySelectorAll('select.mapa-el').forEach(s => {
        const elId = s.getAttribute('data-el');
        if (elId && s.value) mapa['el:' + elId] = s.value;
    });
    const limpo = window.BancoDoModelo.mapaLimpo(mapa, [], elementos);

    try {
        await ligarModeloAoBanco(item.id, vinc.banco_id, limpo);

        // A marca de conferencia mora no ELEMENTO da peca — vale para a
        // numeracao inteira, em todos os pedidos, como o titulo da caixinha
        // avisa. Grava so quando mudou.
        const escolhaConferir = {};
        over.querySelectorAll('input.conferir-el').forEach(c => {
            escolhaConferir[c.getAttribute('data-el')] = c.checked;
        });
        let conferenciaMudou = 0;
        elementos.forEach(el => {
            const querida = escolhaConferir[String(el.id)];
            if (querida === undefined) return;
            const fora = !querida;
            if (!!el.sem_conferencia === fora) return;
            if (fora) el.sem_conferencia = true; else delete el.sem_conferencia;
            conferenciaMudou++;
        });
        if (conferenciaMudou) {
            await salvarCamposDaNumeracao(peca.id, { elements: peca.elements });
        }

        fecharColunasDoModelo();
        toast('Colunas deste modelo atualizadas.', 'success');
        renderAmostrasOSItens(osId);
    } catch (e) {
        toast('Não deu para salvar as colunas: ' + (e.message || e), 'error');
    }
}
window.aplicarColunasDoModelo = aplicarColunasDoModelo;

/** Os modelos deste pedido que bebem do mesmo banco. */
function modelosDoBanco(osId, bancoId) {
    return ((state.osItens && state.osItens[osId]) || []).filter(it => {
        const v = vinculoDeBancoDoModelo(it);
        return v && String(v.banco_id) === String(bancoId);
    });
}
window.modelosDoBanco = modelosDoBanco;

/**
 * Abre um banco do PEDIDO para conferir e corrigir, no mesmo editor de sempre.
 *
 * A porta mora no box "Gerenciamento de Bancos de Dados", ao lado do banco
 * (28/08/2026, redesenho do usuario) — o botao 📊 saiu do card do modelo
 * porque editar conteudo e coisa do PEDIDO, e a licao de 26/08 continua
 * valendo: a porta diz o alcance antes de qualquer tecla, avisando quantos
 * modelos leem dali. O banco da NUMERACAO segue com uma porta so, a do editor
 * de numeracao.
 */
window.abrirBancoDoPedidoPorId = function (bancoId, osId) {
    if (typeof window.abrirEditorCsv !== 'function') {
        toast('O editor de CSV não carregou. Recarregue a página.', 'error');
        return;
    }
    const banco = (state.bancosDoPedido || []).find(b => String(b.id) === String(bancoId));
    if (!banco) return;
    const fonte = { id: banco.id, nome: banco.nome || banco.csv_filename || 'banco',
        headers: banco.csv_headers || [], rows: banco.csv_data || [],
        filename: banco.csv_filename || '' };

    const usuarios = modelosDoBanco(osId, fonte.id);
    if (usuarios.length > 1) {
        toast('O banco "' + fonte.nome + '" é lido por ' + usuarios.length
            + ' modelos deste pedido. O que você corrigir aqui vale para todos.', 'info');
    }

    // Cada modelo lê a coluna DEPOIS do mapa dele, então a contagem de uso tem
    // de passar pelo mapa: renomear "05/09" precisa avisar que dois campos do
    // modelo do dia 5 dependem dela, mesmo que a peça chame aquilo de CODIGO.
    // A resolução é por ELEMENTO (`colunaDoElemento`): cobre a peça nova, que
    // não tem csv_column e aponta pelo `el:<id>` do 🔤, e a legada, pelo nome.
    const colunasEmUso = () => {
        const uso = {};
        usuarios.forEach(it => {
            const peca = pecaDoModelo(it);
            const mapa = (vinculoDeBancoDoModelo(it) || {}).csv_mapa;
            (peca && peca.elements || []).forEach(el => {
                if (!el || el.source !== 'database') return;
                const noBanco = window.BancoDoModelo.colunaDoElemento(mapa, el);
                if (!noBanco) return;
                uso[noBanco] = (uso[noBanco] || 0) + 1;
            });
        });
        return uso;
    };

    const colunasDeFoto = [...new Set(usuarios.flatMap(it => {
        const peca = pecaDoModelo(it);
        const mapa = (vinculoDeBancoDoModelo(it) || {}).csv_mapa;
        return (peca && peca.elements || [])
            .filter(el => el && el.type === 'FOTO')
            .map(el => window.BancoDoModelo.colunaDoElemento(mapa, el))
            .filter(Boolean);
    }))];

    window.abrirEditorCsv({
        headers: fonte.headers,
        rows: fonte.rows,
        filename: fonte.filename,
        colunasDeFoto,
        colunasEmUso,
        onAplicar: async ({ headers, rows, filename, renomeacoes }) => {
            if (!rows.length) {
                toast('Um banco sem nenhuma linha não imprime nada. Nada foi salvo — '
                    + 'para se livrar do banco, use o 🗑 dele no Gerenciamento de Bancos de Dados.', 'error');
                return;
            }
            try {
                const banco = (state.bancosDoPedido || []).find(b => String(b.id) === String(fonte.id));
                const { error } = await supabaseClient.from('pedidos_bancos').update({
                    csv_data: rows, csv_headers: headers,
                    csv_filename: filename || fonte.filename,
                    updated_at: new Date().toISOString()
                }).eq('id', fonte.id);
                if (error) throw error;
                if (banco) { banco.csv_data = rows; banco.csv_headers = headers; banco.csv_filename = filename || banco.csv_filename; }

                // Renomear coluna arrasta o MAPA de cada modelo, e não os
                // elementos da peça: é o mapa que aponta para o nome do banco.
                // Sem isto, renomear "05/09" faria os modelos do dia 5 lerem uma
                // coluna que não existe mais — e o card só avisaria depois.
                await aplicarRenomeacoesNoMapa(osId, fonte.id, renomeacoes || []);

                toast('Banco "' + fonte.nome + '" salvo com ' + rows.length + ' linha(s).', 'success');
                renderAmostrasOSItens(osId);
            } catch (e) {
                toast('Não deu para salvar o banco: ' + (e.message || e), 'error');
            }
        }
    });
};

/** Leva as renomeações de coluna para o `csv_mapa` de cada modelo do banco. */
async function aplicarRenomeacoesNoMapa(osId, bancoId, renomeacoes) {
    if (!renomeacoes.length) return;
    const de2para = {};
    renomeacoes.forEach(r => { if (r && r.de && r.para) de2para[r.de] = r.para; });

    for (const it of modelosDoBanco(osId, bancoId)) {
        const vinc = vinculoDeBancoDoModelo(it);
        const mapa = (vinc && vinc.csv_mapa) || null;
        const peca = pecaDoModelo(it);
        const pedidas = window.BancoDoModelo.colunasQueAPecaPede(peca);
        const elementos = ((peca && peca.elements) || []).filter(el => el && el.source === 'database');

        const limpo = window.BancoDoModelo.mapaAposRenomear(mapa, pedidas, de2para, elementos);
        await ligarModeloAoBanco(it.id, bancoId, limpo);
    }
}
window.aplicarRenomeacoesNoMapa = aplicarRenomeacoesNoMapa;

/**
 * As colunas de FOTO deste banco, resolvidas por ELEMENTO: cada janela de foto
 * das peças dos modelos que leem o banco aponta uma coluna (pelo `el:<id>` do
 * 🔤 ou pelo `csv_column` legado). Devolve `{ coluna: [janelas...] }`, cada
 * janela com o tamanho/encaixe do elemento e o rótulo do modelo — é por elas
 * que o Gerenciador de Fotos sabe COMO enquadrar.
 */
function colunasDeFotoDoBanco(osId, bancoId) {
    const porColuna = {};
    modelosDoBanco(osId, bancoId).forEach((it, i) => {
        const peca = pecaDoModelo(it);
        const mapa = (vinculoDeBancoDoModelo(it) || {}).csv_mapa;
        ((peca && peca.elements) || []).forEach(el => {
            if (!el || el.type !== 'FOTO') return;
            const col = window.BancoDoModelo.colunaDoElemento(mapa, el);
            if (!col) return;
            (porColuna[col] = porColuna[col] || []).push({
                w_mm: el.width_mm || 25, h_mm: el.height_mm || 32,
                fit: el.fit || 'cover', modelo: rotuloDoModelo(it, i)
            });
        });
    });
    return porColuna;
}
window.colunasDeFotoDoBanco = colunasDeFotoDoBanco;

/**
 * A porta das fotos do BANCO DO PEDIDO (28/08/2026): abre o Gerenciador de
 * Fotos sobre as linhas do banco, e grava na hora.
 *
 * É o mesmo Gerenciador da peça (`abrirFotosDoElemento`), com três diferenças
 * de dono:
 *   · as linhas são as do banco do pedido — o `__fotos` entra NELAS;
 *   · a gravação é imediata (`salvarLinhasDaFonte`), porque o banco é do
 *     pedido e não tem o passo "Salvar a numeração" do fluxo da peça;
 *   · a janela de enquadramento vem do ELEMENTO que lê a coluna — quando
 *     modelos usam janelas diferentes, vale a primeira e a tela avisa qual.
 */
window.abrirFotosDoBanco = function (bancoId, osId, coluna) {
    if (typeof window.abrirGerenciadorDeFotos !== 'function') {
        toast('O Gerenciador de Fotos não carregou. Recarregue a página.', 'error');
        return;
    }
    const banco = (state.bancosDoPedido || []).find(b => String(b.id) === String(bancoId));
    if (!banco) return;
    if (!banco.csv_data || !banco.csv_data.length) {
        toast('Este banco ainda não tem linhas carregadas. Feche e abra o pedido de novo.', 'error');
        return;
    }

    const janelas = colunasDeFotoDoBanco(osId, bancoId);
    const cabecalho = (banco.csv_headers || []).map(String);
    const colunas = Object.keys(janelas).filter(c => cabecalho.indexOf(c) !== -1);
    if (!colunas.length) {
        toast(Object.keys(janelas).length
            ? 'A coluna de foto apontada não existe neste banco. Corrija no 🔤 Colunas do modelo.'
            : 'Nenhum modelo aponta uma janela de foto para este banco. Aponte a coluna do elemento FOTO no 🔤 Colunas do modelo.', 'info');
        return;
    }

    if (!coluna) {
        if (colunas.length === 1) coluna = colunas[0];
        else {
            const escolha = prompt('Este banco tem ' + colunas.length + ' colunas de foto:\n'
                + colunas.map((c, i) => (i + 1) + '. ' + c).join('\n')
                + '\n\nDigite o número da coluna para trazer as fotos:', '1');
            const n = parseInt(escolha, 10);
            if (!n || !colunas[n - 1]) return;
            coluna = colunas[n - 1];
        }
    }

    const usos = janelas[coluna] || [];
    const janela = usos[0] || { w_mm: 25, h_mm: 32, fit: 'cover' };
    const diferentes = usos.some(u => u.w_mm !== janela.w_mm || u.h_mm !== janela.h_mm || u.fit !== janela.fit);
    if (diferentes) {
        toast('Os modelos usam janelas de foto diferentes. O enquadramento vai usar a de '
            + janela.modelo + ' (' + janela.w_mm + '×' + janela.h_mm + ' mm).', 'info');
    }

    window.abrirGerenciadorDeFotos({
        janela: { w_mm: janela.w_mm, h_mm: janela.h_mm, fit: janela.fit },

        // Identifica a sessão: é por ela que as fotos que sobraram voltam à
        // tela quando o gerenciador é reaberto neste mesmo banco.
        chave: 'banco:' + banco.id + '|' + coluna,

        coluna: coluna,

        headers: banco.csv_headers || [],

        // As linhas VIVAS do banco: é escrevendo `__fotos` dentro delas que o
        // enquadramento viaja com a pessoa — e todos os modelos que leem o
        // banco imprimem a mesma foto.
        rows: banco.csv_data,

        subirFoto: (blob, hash) => uploadToStorage(blob, hash + '.jpg', 'fotos', {
            objectPath: `fotos/banco-${banco.id}/${hash}.jpg`
        }),

        onAplicar: async ({ gravadas, queimadas, falhas, semFoto, sobrando, coluna }) => {
            // Diferente do fluxo da peça, aqui não existe o passo "Salvar a
            // numeração": o banco é do pedido, então grava agora — um F5 não
            // pode jogar fora o enquadramento de um lote inteiro.
            try {
                await salvarLinhasDaFonte({ tipo: 'banco', id: banco.id }, banco.csv_data);
                if (gravadas) {
                    const reduzidas = queimadas
                        ? ` ${queimadas} passava(m) de 350 dpi e subiu(ram) reamostrada(s) para 300.`
                        : '';
                    toast(`${gravadas} foto(s) ligadas à coluna “${coluna}” e gravadas no banco.${reduzidas}`, 'success');
                }
            } catch (e) {
                toast('As fotos subiram, mas o banco não gravou: ' + (e.message || e), 'error');
            }
            if (falhas && falhas.length) {
                toast(`${falhas.length} foto(s) não subiram. Elas continuam no lote.`, 'error');
            }
            if (semFoto && semFoto.length) {
                toast(`${semFoto.length} linha(s) ainda estão sem foto — a impressão vai recusar.`, 'info');
            }
            if (sobrando) {
                toast(`${sobrando} foto(s) continuam sem linha e seguem na tela do gerenciador.`, 'info');
            }
            // Os cards desenham a foto na amostra, e o 📊 passa a mostrar a
            // célula ligada.
            renderAmostrasOSItens(osId);
        }
    });
};

/**
 * Quantos modelos leem deste banco, contando TODOS os vinculos carregados.
 *
 * Diferente do `modelosDoBanco`, que so olha os itens do pedido aberto: a
 * exclusao precisa da conta inteira, porque o `carregarBancosDoPedidoNovo` traz
 * os vinculos pelo banco_id, sem filtrar por pedido. Apagar um banco que outro
 * modelo le derrubaria o vinculo dele em cascata — e o modelo cairia em
 * silencio na numeracao, imprimindo o dado errado.
 */
function quantosLeemDoBanco(bancoId) {
    return Object.values(state.vinculosDeBanco || {})
        .filter(v => v && String(v.banco_id) === String(bancoId)).length;
}
window.quantosLeemDoBanco = quantosLeemDoBanco;

/**
 * Renomear e excluir os bancos do pedido.
 *
 * A porta existe porque sem ela um banco criado por engano fica para sempre na
 * lista do "Vem de:" — foi o que aconteceu em 28/08/2026, quando o vinculo
 * falhava e cada tentativa deixava um banco orfao. Excluir so e permitido com
 * ZERO modelos lendo: o ON DELETE CASCADE apagaria os vinculos junto e cada
 * modelo cairia calado na numeracao. A trava diz a saida, como toda trava
 * deste projeto: desligar os modelos no "Vem de:" primeiro.
 */
/**
 * O corpo do box "Gerenciamento de Bancos de Dados" (28/08/2026, redesenho do
 * usuario). O banco e do PEDIDO, entao criar, renomear, atualizar pela
 * planilha e excluir moram aqui, na coluna do Briefing — o card do modelo so
 * ESCOLHE um banco ja carregado, no "Vem de:".
 *
 * Chamado no fim de todo `renderAmostrasOSItens`: o box vive dentro do HTML da
 * tela e se redesenha junto com ela.
 */
function desenharBoxDeBancos(osId) {
    const alvo = document.getElementById(`bancos-pedido-lista-${osId}`);
    if (!alvo) return;
    const esc = escDoBanco;
    const bancos = state.bancosDoPedido || [];

    if (!bancos.length) {
        alvo.innerHTML = `<div style="font-size:0.85rem; color:var(--text-dim); padding:4px 2px;">
            Este pedido ainda não tem banco de dados. Suba um CSV ou busque de um
            link compartilhado — depois, escolha o banco no "Vem de:" de cada modelo.
        </div>`;
        return;
    }

    const linhas = bancos.map(b => {
        const leitores = modelosDoBanco(osId, b.id);
        const nLinhas = Array.isArray(b.csv_data) ? b.csv_data.length : 0;
        const temLink = !!String(b.csv_url || '').trim();
        const quemLe = leitores.map((it, i) => rotuloDoModelo(it, i)).join(', ');
        // O 🖼️ só aparece quando algum modelo aponta uma janela de foto para
        // este banco — controle que não tem o que fazer não fica na tela.
        const temFotos = Object.keys(colunasDeFotoDoBanco(osId, b.id) || {}).length > 0;
        return `
        <div style="border:1px solid var(--border); border-radius:6px; padding:8px 10px; display:flex; flex-direction:column; gap:6px;">
            <div style="display:flex; align-items:center; gap:6px;">
                <input class="form-control" id="nome-banco-${esc(String(b.id))}" type="text" value="${esc(b.nome || '')}"
                    maxlength="120" style="flex:1; min-width:0; height:28px; font-size:0.85rem;"
                    title="O nome que aparece no Vem de: dos modelos"
                    onchange="renomearBancoDoPedido('${esc(String(b.id))}', '${escapeJsAttr(osId)}')">
                <span style="font-size:0.78rem; color:var(--text-dim); white-space:nowrap;"
                    title="${temLink ? 'Ligado à planilha: ' + esc(b.csv_url) : 'Criado de um arquivo CSV'}">${temLink ? '🌐' : '📄'} ${nLinhas} linha(s)</span>
            </div>
            <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                <span style="font-size:0.78rem; ${leitores.length ? '' : 'color:var(--text-dim);'}" title="${esc(quemLe)}">
                    ${leitores.length ? '🔗 lido por ' + leitores.length + ' modelo(s)' : 'nenhum modelo lê este banco'}
                </span>
                <span style="flex:1;"></span>
                ${temLink ? `<button class="btn btn-sm btn-secondary" id="btn-banco-planilha-${esc(String(b.id))}"
                    onclick="atualizarBancoDaPlanilha('${esc(String(b.id))}', '${escapeJsAttr(osId)}')"
                    style="font-size:0.75rem; padding:3px 8px;"
                    title="Trazer de novo o conteúdo da planilha ligada a este banco">🔄 Planilha</button>` : ''}
                ${temFotos ? `<button class="btn btn-sm btn-secondary" onclick="abrirFotosDoBanco('${esc(String(b.id))}', '${escapeJsAttr(osId)}')"
                    style="font-size:0.75rem; padding:3px 8px;"
                    title="Trazer e enquadrar as fotos das pessoas deste banco">🖼️ Fotos</button>` : ''}
                <button class="btn btn-sm btn-secondary" onclick="abrirBancoDoPedidoPorId('${esc(String(b.id))}', '${escapeJsAttr(osId)}')"
                    style="font-size:0.75rem; padding:3px 8px;" title="Conferir e corrigir o conteúdo deste banco">📊 Conferir</button>
                <button class="btn btn-sm btn-ghost btn-danger" onclick="excluirBancoDoPedido('${esc(String(b.id))}', '${escapeJsAttr(osId)}')"
                    style="font-size:0.75rem; padding:3px 8px;"
                    title="${leitores.length ? 'Para excluir, primeiro escolha a numeração no Vem de: dos modelos que leem este banco' : 'Excluir este banco do pedido'}">🗑</button>
            </div>
        </div>`;
    }).join('');

    const semUso = bancos.filter(b => !quantosLeemDoBanco(b.id)).length;
    alvo.innerHTML = linhas + (semUso >= 2
        ? `<button class="btn btn-sm btn-ghost btn-danger" onclick="excluirBancosNaoUsados('${escapeJsAttr(osId)}')"
              style="font-size:0.75rem; align-self:flex-start;"
              title="Excluir de uma vez os bancos que nenhum modelo lê">🗑 Excluir os ${semUso} não usados</button>`
        : '');
}
window.desenharBoxDeBancos = desenharBoxDeBancos;

/** Exclui de uma vez todos os bancos do pedido que nenhum modelo le. */
async function excluirBancosNaoUsados(osId) {
    const soltos = (state.bancosDoPedido || []).filter(b => !quantosLeemDoBanco(b.id));
    if (!soltos.length) return;
    if (!confirm('Excluir ' + soltos.length + ' banco(s) que nenhum modelo lê?\n\n'
        + soltos.map(b => '· ' + (b.nome || 'banco')).join('\n')
        + '\n\nIsso não altera nenhuma numeração nem os bancos em uso.')) return;
    try {
        for (const b of soltos) {
            const { error } = await supabaseClient.from('pedidos_bancos').delete().eq('id', b.id);
            if (error) throw error;
            state.bancosDoPedido = (state.bancosDoPedido || []).filter(x => String(x.id) !== String(b.id));
        }
        toast(soltos.length + ' banco(s) excluído(s).', 'success');
    } catch (e) {
        toast('Não deu para excluir tudo: ' + (e.message || e), 'error');
    }
    renderAmostrasOSItens(osId);
}
window.excluirBancosNaoUsados = excluirBancosNaoUsados;

async function renomearBancoDoPedido(bancoId, osId) {
    const campo = document.getElementById('nome-banco-' + bancoId);
    const nome = campo ? String(campo.value || '').trim() : '';
    if (!nome) { toast('O nome não pode ficar vazio.', 'error'); return; }
    try {
        const { error } = await supabaseClient.from('pedidos_bancos')
            .update({ nome, updated_at: new Date().toISOString() }).eq('id', bancoId);
        if (error) throw error;
        const b = (state.bancosDoPedido || []).find(x => String(x.id) === String(bancoId));
        if (b) b.nome = nome;
        toast('Banco renomeado para "' + nome + '".', 'success');
        renderAmostrasOSItens(osId);   // o "Vem de:" de cada card mostra o nome novo
    } catch (e) {
        toast('Não deu para renomear: ' + (e.message || e), 'error');
    }
}
window.renomearBancoDoPedido = renomearBancoDoPedido;

async function excluirBancoDoPedido(bancoId, osId) {
    const b = (state.bancosDoPedido || []).find(x => String(x.id) === String(bancoId));
    if (!b) return;

    const leitores = quantosLeemDoBanco(bancoId);
    if (leitores) {
        toast('O banco "' + (b.nome || 'banco') + '" é lido por ' + leitores + ' modelo(s). '
            + 'Para excluir, primeiro escolha "a numeração" no "Vem de:" desses modelos.', 'error');
        return;
    }

    const nLinhas = Array.isArray(b.csv_data) ? b.csv_data.length : 0;
    if (!confirm('Excluir o banco "' + (b.nome || 'banco') + '" (' + nLinhas
        + ' linha(s)) deste pedido?\n\nIsso não altera nenhuma numeração — apaga só este banco.')) return;

    try {
        const { error } = await supabaseClient.from('pedidos_bancos').delete().eq('id', bancoId);
        if (error) throw error;
        state.bancosDoPedido = (state.bancosDoPedido || []).filter(x => String(x.id) !== String(bancoId));
        toast('Banco "' + (b.nome || 'banco') + '" excluído.', 'success');
        renderAmostrasOSItens(osId);   // redesenha o box e os cards
    } catch (e) {
        toast('Não deu para excluir: ' + (e.message || e), 'error');
    }
}
window.excluirBancoDoPedido = excluirBancoDoPedido;

/**
 * O banco do pedido nascido de um link compartilhado (28/08/2026).
 *
 * Mesmo caminho de rede da numeracao — `baixarCsvDaWeb` — para que planilha do
 * Google, link com `#gid=`, caderno de varias paginas e CSV solto na web se
 * comportem igual nas duas portas. O link fica gravado em `csv_url`, e o
 * "🔄 Planilha" do gerenciador traz o conteudo de novo quando a lista mudar la.
 */
function abrirBancoDoPedidoPorLink(osId) {
    fecharBancoDoPedidoPorLink();
    const over = document.createElement('div');
    over.id = 'banco-url-overlay';
    over.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.65); z-index:12000;'
        + 'display:flex; align-items:center; justify-content:center; padding:20px;';
    over.innerHTML = `
        <div style="background:var(--bg-card,#161b22); border:1px solid var(--border); border-radius:var(--radius,8px);
                    max-width:560px; width:100%; display:flex; flex-direction:column;">
            <div style="padding:14px 18px; border-bottom:1px solid var(--border);">
                <div style="font-weight:800; font-size:1.05rem;">🌐 Banco de um link compartilhado</div>
                <div style="color:var(--text-dim); font-size:0.85rem; margin-top:3px;">
                    Cole o link de uma planilha do Google compartilhada como
                    "qualquer pessoa com o link", ou de um arquivo CSV na web.
                    Planilha com várias páginas cria um banco por página. O link
                    fica guardado: quando a lista mudar lá, o "🔄 Planilha" do
                    banco traz o conteúdo de novo.
                </div>
            </div>
            <div style="padding:14px 18px; display:flex; flex-direction:column; gap:8px;">
                <label style="font-size:0.78rem; color:var(--text-dim);">Link da planilha</label>
                <input class="form-control" id="banco-url-link" type="text"
                    placeholder="https://docs.google.com/spreadsheets/d/…" style="width:100%;">
            </div>
            <div style="padding:12px 18px; border-top:1px solid var(--border); display:flex; gap:8px; justify-content:flex-end;">
                <button class="btn btn-secondary" onclick="fecharBancoDoPedidoPorLink()">Cancelar</button>
                <button class="btn btn-primary" id="btn-buscar-banco-url"
                    onclick="buscarBancoDoPedidoDaWeb('${escapeJsAttr(osId)}')">Buscar</button>
            </div>
        </div>`;
    document.body.appendChild(over);
    const campo = document.getElementById('banco-url-link');
    if (campo) campo.focus();
}
window.abrirBancoDoPedidoPorLink = abrirBancoDoPedidoPorLink;

function fecharBancoDoPedidoPorLink() {
    const o = document.getElementById('banco-url-overlay');
    if (o) o.remove();
}
window.fecharBancoDoPedidoPorLink = fecharBancoDoPedidoPorLink;

async function buscarBancoDoPedidoDaWeb(osId) {
    const campo = document.getElementById('banco-url-link');
    const link = campo ? String(campo.value || '').trim() : '';
    try {
        const res = await comBotaoOcupado(
            'btn-buscar-banco-url', '⏳ Buscando…', (p) => baixarCsvDaWeb(link, p));
        const idInt = idIntDoPedido(osId);

        // Planilha com varias paginas vira UM BANCO POR PAGINA (28/08/2026,
        // redesenho do usuario): cada banco e uma pagina, selecionavel direto
        // no "Vem de:" do modelo — sem a coluna "Página" e sem de-para para
        // separar depois. Cada um guarda o link da SUA aba (#gid), entao o
        // "🔄 Planilha" atualiza pagina a pagina, como as numeracoes ja fazem.
        const partes = (Array.isArray(res.partes) && res.partes.length > 1) ? res.partes : null;
        const criados = [];
        if (partes) {
            const caderno = String(res.filename || 'planilha')
                .replace(/ \(\d+ p..?ginas\)\.csv$/i, '').replace(/\.csv$/i, '');
            for (const p of partes) {
                const linkDaPagina = res.idDaPlanilha && p.gid !== undefined && p.gid !== null
                    ? `https://docs.google.com/spreadsheets/d/${res.idDaPlanilha}/edit#gid=${p.gid}`
                    : link;
                const b = await criarBancoDoPedido(idInt, caderno + ' — ' + p.nome,
                    p.headers, p.rows, p.nome + '.csv', linkDaPagina);
                criados.push(b);
            }
        } else {
            const nome = String(res.filename || 'planilha').replace(/\.csv$/i, '');
            criados.push(await criarBancoDoPedido(idInt, nome, res.headers, res.rows, res.filename, link));
        }

        // Criar NAO vincula: a adocao e sempre uma escolha no card do modelo.
        fecharBancoDoPedidoPorLink();
        toast(criados.length === 1
            ? `Banco "${criados[0].nome}" criado com ${criados[0].csv_data.length} linha(s). `
              + 'Escolha-o no "Vem de:" dos modelos.'
            : `${criados.length} bancos criados, um por página: `
              + criados.map(b => '"' + b.nome + '"').join(', ')
              + '. Escolha cada um no "Vem de:" do seu modelo.', 'success');
        renderAmostrasOSItens(osId);
    } catch (e) {
        toast('Erro ao buscar: ' + (e.message || e), 'error');
    }
}
window.buscarBancoDoPedidoDaWeb = buscarBancoDoPedidoDaWeb;

/**
 * Traz de novo o conteudo do link ligado a um banco do pedido.
 *
 * O mesmo cuidado do `atualizarCsvDaPlanilha` da numeracao, pelo mesmo motivo:
 * a fatia de cada modelo (`pedidos_modelos.csv_selecao`) aponta para o `__id`
 * das linhas DESTE banco. A planilha baixada chega sem `__id`, e deixar nascer
 * ids novos faria toda distribuicao ja feita apontar para o vazio. O `__id` e o
 * `__ativo` sao herdados POSICAO A POSICAO, e a confirmacao diz isso antes.
 */
async function atualizarBancoDaPlanilha(bancoId, osId) {
    const banco = (state.bancosDoPedido || []).find(b => String(b.id) === String(bancoId));
    if (!banco) return;
    const link = String(banco.csv_url || '').trim();
    if (!link) { toast('Este banco não está ligado a nenhuma planilha.', 'error'); return; }

    try {
        const res = await comBotaoOcupado(
            'btn-banco-planilha-' + bancoId, '⏳…', (p) => baixarCsvDaWeb(link, p));
        const { headers, rows, filename } = res;
        const antigas = Array.isArray(banco.csv_data) ? banco.csv_data : [];

        // Coluna que sumiu e algum modelo do banco ainda le (ja atraves do
        // mapa dele): imprime vazio — melhor saber antes de trocar.
        const perdidas = new Set();
        modelosDoBanco(osId, bancoId).forEach(it => {
            const mapa = (vinculoDeBancoDoModelo(it) || {}).csv_mapa;
            window.BancoDoModelo.colunasQueAPecaPede(pecaDoModelo(it)).forEach(col => {
                const noBanco = window.BancoDoModelo.colunaDoModelo(mapa, col);
                if (!headers.includes(noBanco)) perdidas.add(noBanco);
            });
        });
        const aviso = perdidas.size
            ? `\n\nATENÇÃO: ${[...perdidas].map(c => `"${c}"`).join(', ')} `
              + 'não existe mais na planilha, e há modelo deste pedido lendo essa coluna.'
            : '';

        const diferenca = rows.length === antigas.length
            ? 'O número de linhas é o mesmo.'
            : (rows.length > antigas.length
                ? `Entram ${rows.length - antigas.length} linha(s) no fim.`
                : `Saem ${antigas.length - rows.length} linha(s) do fim.`);

        const ok = confirm(
            `Atualizar o banco "${banco.nome || 'banco'}" pela planilha?\n\n`
            + `Aqui: ${antigas.length} linha(s).    Na planilha: ${rows.length} linha(s).\n`
            + diferenca + '\n\n'
            + 'As linhas são reconhecidas pela POSIÇÃO: a 1ª da planilha é a 1ª daqui. '
            + 'Se você inseriu, apagou ou reordenou linhas na planilha, a distribuição de '
            + 'linhas já feita nos modelos passa a apontar para outra linha.\n\n'
            + 'O que tiver sido corrigido à mão no banco é substituído.'
            + aviso
        );
        if (!ok) { toast('Atualização cancelada. Nada mudou.', 'info'); return; }

        // Ids nao sao reaproveitados: linha nova comeca depois do maior ja usado.
        let proximo = 1;
        for (const r of antigas) {
            const v = Number(r && r.__id);
            if (Number.isFinite(v) && v >= proximo) proximo = v + 1;
        }
        let herdadas = 0;
        rows.forEach((linha, i) => {
            const velha = antigas[i];
            const id = velha ? Number(velha.__id) : NaN;
            if (Number.isFinite(id) && id > 0) {
                linha.__id = id;
                // Ausencia da chave significa ativa: so a desmarcacao viaja.
                if (velha.__ativo === false) linha.__ativo = false;
                herdadas++;
            } else {
                linha.__id = proximo++;
            }
        });

        const { error } = await supabaseClient.from('pedidos_bancos').update({
            csv_data: rows, csv_headers: headers,
            csv_filename: filename || banco.csv_filename,
            updated_at: new Date().toISOString()
        }).eq('id', bancoId);
        if (error) throw error;

        banco.csv_data = rows;
        banco.csv_headers = headers;
        banco.csv_filename = filename || banco.csv_filename;

        toast(`Banco "${banco.nome || 'banco'}" atualizado: ${rows.length} linha(s), `
            + `${herdadas} mantendo a identidade que já tinham.` + fraseDasPaginas(res), 'success');
        renderAmostrasOSItens(osId);   // redesenha o box e os cards
    } catch (e) {
        toast('Erro ao atualizar: ' + (e.message || e), 'error');
    }
}
window.atualizarBancoDaPlanilha = atualizarBancoDaPlanilha;

/** Lê o CSV escolhido, cria o banco do pedido e liga este modelo nele. */
async function subirBancoDoPedido() {
    const alvo = _bancoPedidoPendente;
    const inp = document.getElementById('banco-pedido-file');
    if (!alvo || !inp || !inp.files || !inp.files.length) return;
    const file = inp.files[0];

    const texto = await new Promise((ok, err) => {
        const r = new FileReader();
        r.onload = e => ok(e.target.result);
        r.onerror = e => err(e.target.error);
        r.readAsText(file);
    });

    const parsed = window.CsvEditor.parseCsv(texto);
    if (!parsed.rows.length) throw new Error('O arquivo não tem nenhuma linha.');

    const idInt = idIntDoPedido(alvo.osId);
    const banco = await criarBancoDoPedido(idInt, file.name.replace(/\.csv$/i, ''),
        parsed.headers, parsed.rows, file.name);

    // Criar NAO vincula (28/08/2026, redesenho do usuario): o banco e do
    // pedido, e a adocao e sempre uma escolha feita no card, no "Vem de:".
    // Sem vinculo automatico tambem nao ha vinculo acidental — e nao ha o que
    // desfazer se algo falhar depois do insert.
    _bancoPedidoPendente = null;
    toast(`Banco "${banco.nome}" criado com ${parsed.rows.length} linha(s). `
        + 'Escolha-o no "Vem de:" dos modelos que vão ler dele.', 'success');
    renderAmostrasOSItens(alvo.osId);
}
window.subirBancoDoPedido = subirBancoDoPedido;

/** O botao 📤 do box: abre o seletor de arquivo para criar um banco do pedido. */
function subirBancoPeloBox(osId) {
    _bancoPedidoPendente = { osId };
    const inp = _inputDoBancoDoPedido();
    inp.value = '';
    inp.click();
}
window.subirBancoPeloBox = subirBancoPeloBox;

/**
 * O modelo ficou sem nenhuma linha do banco? Devolve o que dizer, ou null.
 *
 * Só responde quando houve distribuição de verdade (`csv_selecao` presente) e a
 * numeração tem banco: sem `csv_selecao` o modelo leva o banco inteiro, que é o
 * comportamento de todo pedido anterior à v525.
 *
 * Existe porque uma fatia vazia não sai como folha em branco — sai pior. O motor
 * recebe `csv_data` vazio, não entra no ramo do banco e cai na numeração
 * SEQUENCIAL: a credencial sairia com um número no lugar do nome da pessoa, e o
 * operador só descobriria com o material na mão.
 */
function modeloSemLinhasDoBanco(item) {

    if (!item) return null;

    // Resolvida pelo banco do pedido, quando o modelo tem um: a fatia vazia
    // que esta trava caca existe la tambem (28/08/2026).
    const num = numeracaoDoModelo(item);

    if (!num || !num.csv_data || !num.csv_data.length) return null;

    // Dois jeitos de a fatia zerar: a distribuicao nao deu linha nenhuma a este
    // modelo, ou as colunas que a numeracao dele le estao vazias no CSV inteiro.
    // Sem nenhum dos dois nao ha o que conferir, e chamar a fatia a toa custaria
    // uma varredura do banco em cada redesenho do card.
    if (!item.csv_selecao && !colunasDoBancoDaNumeracao(num).length) return null;

    if (fatiaCsvDoItem(item, num).length) return null;

    return rotuloDoModelo(item, 0);

}



/**
 * O recado que trava a imposição, ou null quando todos os modelos têm linhas.
 * O recado diz a saída, e não só o problema: sem isso o operador fica com uma
 * tela que recusa e não ensina.
 */
function recadoDeFatiaVazia(itens) {

    const nomes = (itens || []).map(modeloSemLinhasDoBanco).filter(Boolean);

    if (!nomes.length) return null;

    return `Sem nenhuma linha do banco de dados: ${nomes.join(', ')}. `

        + 'Modelo sem linha não imprime nada. Confira se as colunas que a '

        + 'numeração dele usa têm conteúdo no CSV, ou abra 🧩 Linhas no card do modelo, '

        + 'escolha as linhas que ele imprime e imponha de novo.';

}
window.recadoDeFatiaVazia = recadoDeFatiaVazia;

/** A quantidade do pedido, como veio do ERP. Le-se; nunca se altera aqui. */
function quantidadeContratada(item) {
    if (!item) return 0;
    return parseInt(item.qtd !== undefined && item.qtd !== null ? item.qtd : (item.quantidade || 0)) || 0;
}
window.quantidadeContratada = quantidadeContratada;

/**
 * As linhas que ESTE modelo leva ao motor quando le um banco do PEDIDO
 * (02/09/2026): a fatia dele, limitada a quantidade do pedido.
 *
 * ## O defeito que isto conserta
 *
 * Um modelo impresso SOZINHO recebia o banco inteiro. O motor imprime uma
 * peca por linha e ignora o "1 a N" da tela quando ha linhas (engine.py,
 * `total_items = len(csv_data)`). Entao o EXPOSITOR SIMERS do 21460, de 500
 * pecas, saiu com 3.000: as 500 primeiras com o codigo e 2.500 com o QR EM
 * BRANCO, porque no formato largo a coluna dele so tem 500 celulas.
 * Decodificado nos PDFs gerados em 02/09/2026: 50 QRs com codigo e 150
 * vazios em cada folha, misturados pelo Cut & Stack -- nem separar dava.
 * Marcar os cinco modelos saia certo, porque la a quantidade de cada arte
 * limita as linhas no motor.
 *
 * A fatia e a mesma que o card e o 🧩 Linhas ja usam (`fatiaCsvDoItem`): a
 * distribuicao, quando ha, e o corte por coluna -- linha sem nada nas colunas
 * que este modelo le nao e peca dele. O limite pela quantidade e a regra que
 * o multi_artes sempre aplicou no motor, trazida para o modelo sozinho.
 * Linhas de MENOS nao chegam aqui: `recadoDeLinhasDeMenos` recusa antes.
 *
 * So vale para modelo com vinculo de banco do pedido. O CSV de dentro da
 * numeracao segue o caminho de sempre, intocado.
 */
function linhasDoModeloNoPayload(item, num) {
    const fatia = fatiaCsvDoItem(item, num);
    const qtd = quantidadeContratada(item);
    return (qtd > 0 && fatia.length > qtd) ? fatia.slice(0, qtd) : fatia;
}
window.linhasDoModeloNoPayload = linhasDoModeloNoPayload;

/**
 * O modelo tem MENOS linhas com dado do que a quantidade do pedido? Devolve
 * o que ha para dizer, ou null.
 *
 * So para modelo que le banco do PEDIDO. Sem esta trava, o modelo sozinho
 * sairia com menos pecas, calado; na folha combinada, o motor pararia no meio
 * da geracao com a recusa dele, que fala de `el_1` e de `csv_row`.
 *
 * Linhas de MAIS nao travam: a quantidade limita, como sempre limitou no
 * multi_artes -- e e assim que modelos que leem o banco inteiro continuam
 * imprimindo a sua quantidade.
 */
function modeloComLinhasDeMenos(item) {
    if (!item || !vinculoDeBancoDoModelo(item)) return null;
    const num = numeracaoDoModelo(item);
    if (!num || !num.csv_data || !num.csv_data.length) return null;   // banco nao baixado: trava propria
    const qtd = quantidadeContratada(item);
    if (!qtd) return null;
    const linhas = fatiaCsvDoItem(item, num).length;
    if (!linhas || linhas >= qtd) return null;                        // fatia vazia: recado proprio
    return { nome: rotuloDoModelo(item, 0), qtd, linhas, colunas: colunasDoBancoDaNumeracao(num) };
}
window.modeloComLinhasDeMenos = modeloComLinhasDeMenos;

/** O recado que trava a imposicao por linhas de menos, ou null. Diz a saida. */
function recadoDeLinhasDeMenos(itens) {
    const faltas = (itens || []).map(modeloComLinhasDeMenos).filter(Boolean);
    if (!faltas.length) return null;
    const cada = faltas.map(f => {
        const onde = f.colunas.length ? 'a coluna ' + f.colunas.join(' / ') : 'o banco';
        return `${f.nome} pede ${f.qtd} peças e ${onde} tem ${f.linhas} linhas com dado`;
    });
    return 'O banco de dados tem menos linhas do que a quantidade do pedido: ' + cada.join('; ')
        + '. Imprimir agora sairia com menos peças ou com QR em branco. Complete o banco no '
        + '🗂️ Gerenciamento de Bancos de Dados, ou reparta as linhas no 🧩 Linhas, e mande imprimir de novo.';
}
window.recadoDeLinhasDeMenos = recadoDeLinhasDeMenos;



/** Os modelos que esta imposição vai gerar — um só, ou os da multi-seleção. */
function itensDaImposicao(isMultiSelected) {

    if (!isMultiSelected) return [itemAtivoDoPedido()].filter(Boolean);

    return (state.selectedOSItems || [])

        .map(s => (state.osItens[s.osId] || []).find(i => String(i.id) === String(s.itemId)))

        .filter(Boolean);

}
window.itensDaImposicao = itensDaImposicao;



// ─────────────────────────────────────────────────────────────────────────────
// SOMAR MODELOS NUMA IMPOSIÇÃO SÓ
//
// Um pedido de credenciais tem um modelo por país, e impressos um a um cada um
// deixa até (poses − 1) células vazias na última folha. Somados, a conta é uma
// só: total de itens ÷ células do formato, empilhado, preenchendo na ordem.
//
// Desenho em docs/superpowers/specs/2026-08-17-somar-modelos-aproveitando-a-folha-design.md
// ─────────────────────────────────────────────────────────────────────────────

/** 'separado' (cada modelo em folha própria, o padrão) ou 'aproveitar'. */
function modoSomaFolha() {

    return state.modoSomaFolha === 'aproveitar' ? 'aproveitar' : 'separado';

}
window.modoSomaFolha = modoSomaFolha;



window.setModoSomaFolha = function(valor) {

    state.modoSomaFolha = (valor === 'aproveitar') ? 'aproveitar' : 'separado';

    ['imp-modo-soma', 'ped-modo-soma'].forEach(id => {

        const el = document.getElementById(id);

        if (el && el.value !== state.modoSomaFolha) el.value = state.modoSomaFolha;

    });

    atualizarBarraDeSoma();

    // Só o resumo da aba aberta: `updateImpSummary` lê os controles `imp-*` e
    // grava `state.printMode` e `state.csvData`. Chamá-lo com a aba Pedido na
    // frente sobrescreveria o que o operador escolheu ali.
    const noPedido = document.getElementById('view-pedido')?.classList.contains('active');

    if (noPedido) { if (typeof updatePedSummary === 'function') updatePedSummary(); }

    else { if (typeof updateImpSummary === 'function') updateImpSummary(); }

    if (typeof drawPreview === 'function' && !noPedido) drawPreview();

    if (typeof drawPedPreview === 'function' && noPedido) drawPedPreview();

};



/**
 * Quantos itens este modelo imprime. Com banco de dados é o tamanho da fatia
 * dele — a mesma conta que o payload faz —, e não a quantidade digitada.
 */
function quantidadeDoModelo(item) {

    // Resolvida: com banco do pedido, a conta e sobre as linhas DELE.
    const num = numeracaoDoModelo(item);

    if (num && num.csv_data && num.csv_data.length) return fatiaCsvDoItem(item, num).length;

    return parseInt(item.qtd !== undefined && item.qtd !== null ? item.qtd : (item.quantidade || 0)) || 0;

}
window.quantidadeDoModelo = quantidadeDoModelo;

/** A numeração escolhida para este modelo, ou null. */
function numeracaoDoModelo(item) {
    const nid = numeracaoIdDoItem(item);
    if (!nid) return null;
    const num = (state.numeracoes || []).find(n => String(n.id) === String(nid)) || null;

    // ── O desvio do banco do pedido (27/08/2026) ────────────────────────────
    //
    // Modelo sem vinculo sai por aqui com a MESMA numeracao de sempre, pela
    // mesma referencia. Tudo o que existia antes desta data cai neste return e
    // nao enxerga o caminho novo -- e e por isso que a mudanca nao altera
    // nenhum dos pedidos em andamento.
    //
    // Devolver uma copia, ainda que identica, ja seria uma mudanca de
    // comportamento: o `garantirCsvDaNumeracao` guarda a referencia da
    // numeracao para escrever o `csv_data` nela quando o banco desce, e essa
    // escrita cairia num objeto que mais ninguem le. Ver
    // `tests/banco_do_pedido_regressao_harness.js`, que compara por identidade.
    return resolverNumeracaoParaModelo(num, item);
}
window.numeracaoDoModelo = numeracaoDoModelo;

/**
 * Aplica a um `num` JA escolhido o banco e o mapa de colunas deste modelo.
 *
 * Separado do `numeracaoDoModelo` porque ha um segundo lugar que precisa dele:
 * o payload `multi_artes` da imposicao, que escolhe a numeracao pelo `num1_id`
 * da arte e nao pelo modelo. La a escolha nao pode mudar -- so a resolucao.
 *
 * Sem vinculo devolve o proprio `num`, pela mesma referencia.
 */
function resolverNumeracaoParaModelo(num, item) {
    const vinculo = vinculoDeBancoDoModelo(item);
    if (!num || !vinculo || !window.BancoDoModelo) return num;

    return window.BancoDoModelo.numeracaoResolvida(
        num,
        window.BancoDoModelo.bancoDoModelo(vinculo, state.bancosDoPedido || []),
        vinculo.csv_mapa
    );
}
window.resolverNumeracaoParaModelo = resolverNumeracaoParaModelo;

/**
 * O vinculo deste modelo com um banco do pedido, ou null.
 *
 * Mora em `pedidos_modelos_banco`, tabela NOSSA -- e nao em `pedidos_modelos`,
 * que e do parceiro Vibe. `state.vinculosDeBanco` e preenchido pelo
 * `carregarBancosDoPedidoNovo`; enquanto ele nao rodou, todo modelo e do
 * caminho antigo, que e o padrao seguro.
 */
function vinculoDeBancoDoModelo(item) {
    if (!item || !item.id) return null;
    const mapa = state.vinculosDeBanco || {};
    return mapa[String(item.id)] || null;
}
window.vinculoDeBancoDoModelo = vinculoDeBancoDoModelo;

/**
 * O `csv_data` que esta aba ja baixou continua descrevendo a linha relida?
 *
 * `updated_at` e escrito pelo gatilho `trg_producao_numeracoes_updated`, que
 * dispara em TODO update de `producao_numeracoes` — inclusive o que troca o
 * `csv_data`. Duas leituras com o mesmo carimbo sao a mesma linha, entao o
 * banco que ja esta em memoria vale. Carimbo diferente, ou ausente de um dos
 * lados, responde "nao": na duvida, baixar de novo custa uma consulta; usar o
 * CSV velho custa papel impresso com os dados errados.
 */
function bancoBaixadoContinuaValendo(velha, nova) {
    if (!velha || !nova) return false;
    if (velha.csv_data === undefined) return false;   // nunca desceu — nada a preservar
    if (!velha.updated_at || !nova.updated_at) return false;
    return String(velha.updated_at) === String(nova.updated_at);
}
window.bancoBaixadoContinuaValendo = bancoBaixadoContinuaValendo;

/**
 * Mescla numeracoes recem-lidas do banco no catalogo em memoria: a linha nova
 * substitui a antiga pelo id, e a que nao existia entra. Devolve quantas
 * entraram. Pura, sem rede — e a parte que o harness testa.
 *
 * ## A leitura ENXUTA nao pode desfazer o que ja desceu (27/08/2026)
 *
 * Quem le sem o `csv_data` (`recarregarNumeracoesDoPedido` com
 * `comBanco: false`) recebe linhas SEM a coluna. Trocar a linha antiga por ela
 * sem mais nada devolvia `csv_data` ao estado `undefined` — e, no pedido
 * 21202, isso jogava fora os 17 MB que a tela de Amostras tinha acabado de
 * baixar, banco a banco. Cada troca de modelo os pedia de novo.
 *
 * Entao: linha nova sem a coluna herda o `csv_data` da antiga, mas SO quando o
 * `updated_at` das duas e o mesmo — ver `bancoBaixadoContinuaValendo`. Se a
 * linha mudou no banco, `csv_data` fica `undefined` de proposito e o
 * `garantirCsvDaNumeracao` desce a versao nova quando alguem precisar dela.
 */
function mesclarNumeracoesNoCatalogo(catalogo, frescas) {
    if (!Array.isArray(catalogo) || !Array.isArray(frescas)) return 0;
    let mescladas = 0;
    frescas.forEach(nova => {
        if (!nova || !nova.id) return;
        const i = catalogo.findIndex(n => String(n.id) === String(nova.id));
        if (i >= 0) {
            const semColuna = !Object.prototype.hasOwnProperty.call(nova, 'csv_data');
            if (semColuna && bancoBaixadoContinuaValendo(catalogo[i], nova)) {
                nova.csv_data = catalogo[i].csv_data;
            }
            catalogo[i] = nova;
        } else {
            catalogo.push(nova);
        }
        mescladas++;
    });
    return mescladas;
}
window.mesclarNumeracoesNoCatalogo = mesclarNumeracoesNoCatalogo;

/**
 * Rele do banco as numeracoes que os modelos de um pedido usam e atualiza o
 * catalogo em memoria (`state.numeracoes`).
 *
 * ## Por que existe (22/08/2026)
 *
 * O catalogo de numeracoes so era recarregado inteiro (`loadAll`) quando ESTA
 * aba salvava algo. Os modelos do pedido, por outro lado, ja eram relidos do
 * banco a cada abertura na Lista de Arte. O resultado era uma tela meio
 * fresca, meio velha: o pedido 21085 mostrava no modelo 1000496 o aviso
 * "gerado 19.500" para a numeracao "Expointer 2026" — um CSV que ela teve das
 * 09:54 as 10:19 e que outra aba ja tinha tirado; e a 1000496, criada em
 * outra aba, nem constava no catalogo daqui, entao o seletor caia na primeira
 * opcao. O usuario leu isso como "excluir o CSV nao apaga os registros".
 *
 * Le so as numeracoes que o pedido usa, pelo id: e uma consulta pequena, e e
 * o que o catalogo inteiro custaria para o pedido aberto. Nunca lanca — sem
 * rede, a tela segue com o que tem, exatamente como antes.
 */
async function recarregarNumeracoesDoPedido(osId, opcoes) {
    try {
        if (typeof supabaseClient === 'undefined' || !supabaseClient) return 0;
        const itens = (state.osItens && state.osItens[osId]) || [];
        const ids = Array.from(new Set(itens.map(it => numeracaoIdDoItem(it)).filter(Boolean).map(String)));
        if (!ids.length) return 0;
        // COM ou SEM o banco de dados de cada numeracao (26/08/2026).
        //
        // Medido no pedido 21202 -- 52 modelos, 17 numeracoes, 115.846 linhas
        // de CSV:
        //
        //     select('*')          22,01 MB   2.015 ms
        //     sem o csv_data        0,03 MB      72 ms
        //
        // Quem PRECISA das linhas na hora (a Conferencia de dados, as duas
        // telas de imposicao) continua pedindo tudo, e paga os 2 segundos com
        // conhecimento de causa. A tela de Amostras pede enxuto e deixa os
        // bancos chegarem depois, card a card -- ver `renderAmostrasOSItens`.
        const comBanco = !(opcoes && opcoes.comBanco === false);
        const { data, error } = await supabaseClient
            .from('producao_numeracoes')
            .select(comBanco ? '*' : COLUNAS_DA_NUMERACAO_NA_LISTA)
            .in('id', ids);
        if (error) throw error;
        if (!Array.isArray(state.numeracoes)) state.numeracoes = [];
        // A mesma forma que o api() entrega: sem METADATA, com print_mode. Sem
        // isto o lapis do card abria o editor com um elemento fantasma (v683).
        const frescas = (data || []).map(normalizarNumeracaoLida);
        // Linha que mudou no banco invalida tambem a PROMESSA guardada no
        // `_csvDaNumeracaoEmVoo`: sem isto, o `garantirCsvDaNumeracao` devolveria
        // para sempre as linhas que baixou antes da mudanca, e a mescla logo
        // abaixo teria deixado `csv_data` como `undefined` justamente para que
        // ele fosse a rede. Ver `bancoBaixadoContinuaValendo`.
        frescas.forEach(nova => {
            if (!nova || !nova.id) return;
            const velha = state.numeracoes.find(n => String(n.id) === String(nova.id));
            if (velha && velha.csv_data !== undefined && !bancoBaixadoContinuaValendo(velha, nova)) {
                esquecerCsvDaNumeracao(nova.id);
            }
        });
        return mesclarNumeracoesNoCatalogo(state.numeracoes, frescas);
    } catch (e) {
        console.warn('[numeracoes] nao consegui reler as numeracoes do pedido:', (e && e.message) || e);
        return 0;
    }
}
window.recarregarNumeracoesDoPedido = recarregarNumeracoesDoPedido;

/**
 * Quantas linhas o banco deste modelo PRECISA ter para atender ao pedido.
 *
 * Regra do usuário: com Qtd X, a numeração tem de gerar X linhas — **sempre**,
 * seja Frente ou FxVerso.
 *
 * > *"modelos frente e verso utilizam as mesmas linhas em colunas diferentes,
 * > se Qtd=15 devem ser utilizadas 15 linhas, sendo somente frente ou sendo
 * > frente e verso"* (26/08/2026)
 *
 * Isto CORRIGE a versão de 19/08/2026, que esperava 2X no FxVerso por supor que
 * cada face consumisse uma linha. Não é assim que a peça se monta: **uma linha é
 * uma peça**, e o verso dela lê OUTRAS COLUNAS da mesma linha. O `engine.py`
 * sempre trabalhou assim — `_render_item_back` recebe o mesmo `item_data` que o
 * `_render_item_front`, e o que separa as faces é o campo `face` dos elementos,
 * não o índice da linha. Quem estava errado era a conta desta trava, e ela
 * bloqueava credencial FxVerso com o banco certo.
 *
 * O `print_mode` da numeração continua sendo lido, mas só para o RÓTULO da
 * mensagem ("Frente" ou "FxVerso"): saber qual dos dois é ajuda o operador a
 * entender o que está olhando, e não muda mais a conta.
 *
 * A Qtd é lida e NUNCA escrita: ela chega do ERP e é a quantidade contratada,
 * ou seja, o valor do pedido. Divergência se conserta na numeração.
 *
 * `null` quando não há o que comparar: sem Qtd do ERP ou sem numeração.
 */
function celulasEsperadasDoModelo(item) {
    if (!item) return null;
    const bruto = (item.quantidade !== undefined && item.quantidade !== null)
        ? item.quantidade : item.qtd;
    const qtd = parseInt(bruto);
    if (!qtd || qtd <= 0) return null;
    const num = numeracaoDoModelo(item);
    if (!num) return null;
    return qtd;
}
window.celulasEsperadasDoModelo = celulasEsperadasDoModelo;

/**
 * A numeração imprime frente e verso? É o "Modo de impressão" dela.
 *
 * Serve ao rótulo da divergência, e não à conta: desde 26/08/2026 o FxVerso
 * espera as MESMAS linhas da Frente. Se algum dia isto voltar a multiplicar
 * alguma coisa, leia antes o comentário do `celulasEsperadasDoModelo`.
 */
function numeracaoEhDuplex(num) {
    return temVerso(num && num.print_mode);
}
window.numeracaoEhDuplex = numeracaoEhDuplex;

/**
 * O nome do Modo de Impressão de uma numeração, do jeito que o operador o vê no
 * seletor. Serve só a mensagem de tela.
 */
function rotuloDoModoDeImpressao(num) {
    const m = String((num && num.print_mode) || 'front').trim().toLowerCase();
    if (m === 'duplex_unico') return 'FxVersoUnico';
    return m === 'duplex' ? 'FxVerso' : 'Frente';
}
window.rotuloDoModoDeImpressao = rotuloDoModoDeImpressao;

/**
 * Quantas linhas do banco este modelo imprime hoje — o mesmo número que o botão
 * "🧩 Linhas" mostra no card.
 *
 * `null` quando a numeração não tem banco (faixa de/até, PDF): aí não existe
 * linha para contar, e por decisão do usuário a regra simplesmente não se
 * aplica. Travar o que não dá para medir só pararia trabalho bom.
 */
function celulasGeradasDoModelo(item) {
    const num = numeracaoDoModelo(item);
    if (!num || !num.csv_data || !num.csv_data.length) return null;
    return fatiaCsvDoItem(item, num).length;
}
window.celulasGeradasDoModelo = celulasGeradasDoModelo;

/**
 * A divergência entre o que o pedido comprou e o que a numeração gerou, ou
 * `null` quando bate (ou quando não há como comparar).
 *
 * Devolve os números e não uma frase pronta: quem chama decide se vira aviso na
 * tela ou motivo de bloqueio, e o teste consegue conferir a conta.
 */
function divergenciaDeCelulasDoModelo(item) {
    const esperado = celulasEsperadasDoModelo(item);
    const gerado = celulasGeradasDoModelo(item);
    if (esperado === null || gerado === null || esperado === gerado) return null;
    const bruto = (item.quantidade !== undefined && item.quantidade !== null)
        ? item.quantidade : item.qtd;
    const num = numeracaoDoModelo(item);
    const diferenca = gerado - esperado;
    // Quantas linhas o corte por coluna tirou. So interessa quando a tiragem
    // ficou CURTA: ai a explicacao provavel e uma celula em branco na coluna que
    // esta numeracao le, e o operador precisa saber disso para achar o buraco.
    // Num modelo que fechou a Qtd, as linhas descartadas sao dos outros modelos
    // do mesmo arquivo -- dizer o numero ali seria barulho. Por isso a conta so
    // roda quando falta: esta funcao e chamada a cada redesenho de card, e uma
    // varredura extra do banco de 19 mil linhas se sente na tela.
    let descartadas = 0;
    if (diferenca < 0) {
        const base = linhasAtivasCsv((num && num.csv_data) || []);
        descartadas = Math.max(0, base.length - linhasComDadoDaNumeracao(base, num).length);
    }
    return {
        qtd: parseInt(bruto),
        modo: rotuloDoModoDeImpressao(num),
        esperado: esperado,
        gerado: gerado,
        diferenca: diferenca,
        descartadas: descartadas
    };
}
window.divergenciaDeCelulasDoModelo = divergenciaDeCelulasDoModelo;

/**
 * A DISTRIBUICAO ORFA: uma fatia salva que nao e deste banco (26/08/2026).
 *
 * ## O dia que deu origem a isto
 *
 * O pedido 21202 tinha quatro modelos dividindo a numeracao "CAMAROTE
 * CORPORATIVO". Alguem repartiu as linhas pelo botao "Linhas": o 05/set ficou
 * com `1-3500` e os outros tres ficaram com lista VAZIA. Depois cada modelo
 * ganhou uma numeracao propria, com o banco inteiro dele -- e as fatias
 * salvas passaram a apontar para `__id` de um banco que aquele modelo nao usa
 * mais.
 *
 * Na tela isso apareceu como *"O banco nao fecha com a quantidade do pedido...
 * esperado 3500, gerado 0"*, com a instrucao de corrigir as linhas do banco. E
 * o banco estava certo, com as 3500 linhas. O que estava errado era a fatia --
 * e a mensagem mandava o operador para o lugar oposto.
 *
 * ## Quando uma fatia e orfa
 *
 *   1. ela pede ids e NENHUM deles existe neste banco -- e fatia de outro; ou
 *   2. ela esta vazia e a numeracao e so deste modelo -- com um banco por
 *      modelo nao ha o que repartir, entao uma fatia vazia so pode ser sobra.
 *
 * Fatia vazia num banco que DOIS modelos dividem NAO entra aqui: e o estado
 * legitimo de "este modelo ficou sem nenhuma linha" que o `abrirDistribuicaoCsv`
 * grava de proposito, e quem avisa e a regra de Qtd.
 *
 * So le; nao apaga nada. Quem apaga e o operador, pelo botao do card.
 */
function distribuicaoOrfaDoModelo(item, osId) {
    if (!item || !item.csv_selecao) return null;
    const num = numeracaoDoModelo(item);
    if (!num || !Array.isArray(num.csv_data) || !num.csv_data.length) return null;
    if (String(numeracaoIdDoItem(item)) !== String(num.id)) return null;

    const sel = item.csv_selecao;
    const ids = (sel && Array.isArray(sel.ids)) ? sel.ids : null;
    if (!ids) return null;

    const donos = ((state.osItens && state.osItens[osId]) || [])
        .filter(it => String(numeracaoIdDoItem(it)) === String(num.id)).length;

    if (!ids.length) {
        if (donos > 1) return null;              // repartir de verdade deixou este de fora
        return { motivo: 'vazia_sem_irmaos',
                 texto: 'Este modelo tem uma distribuição salva SEM nenhuma linha, e o banco '
                      + 'de dados é só dele — não há o que repartir.' };
    }

    const existentes = new Set(num.csv_data.map(r => Number(r && r[CsvEditorColId()])));
    const pedidos = (window.CsvEditor && window.CsvEditor.expandirIds)
        ? window.CsvEditor.expandirIds(ids) : [];
    if (!pedidos.length) return null;
    const achados = pedidos.filter(i => existentes.has(Number(i))).length;
    if (achados) return null;                    // a fatia e deste banco

    return { motivo: 'outro_banco',
             texto: 'A distribuição salva neste modelo aponta para ' + pedidos.length
                  + ' linha(s) que não existem neste banco de dados — ela é de um banco anterior.' };
}
window.distribuicaoOrfaDoModelo = distribuicaoOrfaDoModelo;

/** O nome da coluna de identidade da linha, que mora no csv-editor.js. */
function CsvEditorColId() {
    return (window.CsvEditor && window.CsvEditor.COL_ID) || '__id';
}

/** Tira a distribuicao do modelo e redesenha. Chamado pelo botao do card. */
window.removerDistribuicaoDoModelo = async function (idx, osId) {
    const item = ((state.osItens && state.osItens[osId]) || [])[idx];
    if (!item) return;
    item.csv_selecao = null;
    try {
        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            const { error } = await supabaseClient.from('pedidos_modelos')
                .update({ csv_selecao: null }).eq('id', item.id);
            if (error) throw error;
        }
        toast('Distribuição removida — este modelo volta a levar o banco inteiro.', 'success');
    } catch (e) {
        toast('Não consegui remover a distribuição: ' + (e.message || e), 'error');
    }
    redesenharCardsDoPedido(osId);
};

/**
 * Elemento de banco de dados sem banco, ou sem coluna.
 *
 * Regra do usuário, 22/08/2026: sempre que a numeração do modelo tiver um
 * elemento do tipo Banco de Dados (`source: 'database'`), ela PRECISA ter um
 * CSV carregado e cada um desses elementos precisa apontar para uma coluna que
 * exista nesse CSV. Faltando qualquer um dos dois, o card avisa e o modelo não
 * pode ser marcado PRONTO — é a mesma engrenagem da regra de células: o pedido
 * só vira "Enviar Arte" com todos os modelos PRONTO, então isso segura o pedido
 * até alguém consertar a numeração.
 *
 * Nasceu do pedido 21085: onze modelos apontavam para a "Expointer 2026", que
 * tinha o QR de banco de dados e nenhum CSV — e nada na tela dizia isso; o
 * operador descobria quando o seletor de linhas não aparecia, ou quando o
 * Ver/editar avisava que a numeração não usa banco. Num pedido impresso, esse
 * QR sairia vazio.
 *
 * Devolve `null` quando não há o que apontar (numeração sem elemento de banco,
 * ou tudo certo) e `{ motivo, texto }` quando há. Só lê; não escreve nada.
 */
function bancoDeDadosIncompletoDoModelo(item) {
    const num = numeracaoDoModelo(item);
    if (!num) return null;
    const deBanco = (num.elements || []).filter(el => el && el.source === 'database');
    if (!deBanco.length) return null;
    const rows = Array.isArray(num.csv_data) ? num.csv_data : [];
    if (!rows.length) {
        return {
            motivo: 'sem_banco',
            texto: 'A numeração tem ' + (deBanco.length === 1 ? 'um elemento' : deBanco.length + ' elementos')
                + ' de banco de dados, mas nenhum CSV carregado.'
        };
    }
    const colunas = (num.csv_headers && num.csv_headers.length)
        ? num.csv_headers.map(String)
        : Object.keys(rows[0] || {}).filter(k => k !== '__ativo' && k !== '__id' && k !== '__fotos');
    const partes = [];
    deBanco.forEach(el => {
        const col = String(el.csv_column || '').trim();
        const tipo = el.type || 'elemento';
        if (!col) partes.push(tipo + ' sem coluna do banco');
        else if (!colunas.some(c => String(c) === col)) partes.push(tipo + ': a coluna "' + col + '" não existe no CSV');
    });
    if (!partes.length) return null;
    return { motivo: 'coluna', texto: partes.join('; ') + '.' };
}
window.bancoDeDadosIncompletoDoModelo = bancoDeDadosIncompletoDoModelo;

/**
 * Caractere que a fonte escolhida NÃO desenha — o buraco no nome impresso.
 *
 * O navegador, quando falta um caractere na fonte, troca de fonte só naquele
 * caractere, em silêncio: a tela mostra o nome inteiro. O PyMuPDF não faz isso
 * — desenha o que a fonte tem e deixa o vão. Mesmo dado, mesma fonte, dois
 * resultados, e o único que alguém vê antes de imprimir é o que mente.
 *
 * Nasceu do pedido 21146: a Gotham Book não tem `ř`, `ě` nem `č`, e oito dos
 * dez nomes tchecos daquele modelo sairiam furados — "Ondřej Pek" vira
 * "Ond ej Pek". A amostra que o cliente APROVOU mostra o nome inteiro. E já
 * tinha acontecido: o pedido 20495, mesma cliente e mesmo evento, imprimiu 185
 * credenciais em 11/08 com as mesmas fontes, e dois modelos voltaram
 * REPROVADA_CLIENTE. O 21146 é o retrabalho deles.
 *
 * Trava, e não aviso: é a mesma engrenagem de `divergenciaDeCelulasDoModelo` e
 * `bancoDeDadosIncompletoDoModelo` — o modelo não vira PRONTO, e como o pedido
 * só vira "Enviar Arte" com todos PRONTO, o pedido inteiro espera. Nome errado
 * em credencial é reimpressão, e reimpressão é papel, tinta e prazo.
 *
 * `coberturas` é o mapa `{ chave da fonte: cobertura|null }` de
 * `window.mapaDeCoberturas()`. Fonte sem cobertura conhecida (a do sistema, a
 * que não baixou, o WOFF2) NÃO acusa: uma trava falsa pararia a gráfica por
 * causa de um arquivo que o leitor não entendeu. Puro; só lê.
 */
function fonteSemGlifoDoModelo(item, coberturas) {
    const mapa = coberturas || (typeof window !== 'undefined' && window.mapaDeCoberturas
        ? window.mapaDeCoberturas() : null);
    const faltamNaFonte = typeof window !== 'undefined' ? window.faltamNaFonte : null;
    const comoSaiNoPapel = typeof window !== 'undefined' ? window.textoComoSaiNoPapel : null;
    const rotuloCh = typeof window !== 'undefined' ? window.rotuloDoCaractere : null;
    if (!mapa || !faltamNaFonte) return null;
    const chave = (n) => String(n || '').trim().toLowerCase();

    const num = numeracaoDoModelo(item);
    if (!num) return null;
    const linhas = fatiaCsvDoItem(item, num);

    const achados = [];
    (num.elements || []).forEach(el => {
        if (!el || el.type === 'METADATA') return;
        const cob = mapa[chave(el.font_name)];
        if (!cob) return;                       // desconhecida não acusa

        // Todo texto que este elemento manda ao papel. Segue o engine.py: o
        // elemento fixo imprime `fixed_value`; o de banco imprime o valor da
        // coluna, SEM prefixo nem sufixo; e os demais colam prefixo e sufixo
        // em volta do número — e prefixo e sufixo são digitados à mão, então
        // também levam acento.
        // Um CARACTERE por vez, e não um texto por vez. Um banco de 4.000
        // linhas tem umas oitenta letras distintas: juntar primeiro e perguntar
        // depois troca 4.000 varreduras por uma, e esta função roda a cada
        // desenho de card.
        const chars = new Map();     // caractere -> primeiro texto onde apareceu
        const juntar = (t) => {
            const s = String(t == null ? '' : t);
            for (const ch of s) if (!chars.has(ch)) chars.set(ch, s);
        };
        if (el.fixed) {
            juntar(el.fixed_value);
        } else if (el.source === 'database' && el.csv_column) {
            for (const linha of linhas) {
                if (linha) juntar(linha[el.csv_column]);
            }
        }
        ['prefix', 'suffix', 'prefix_fila', 'prefix_lugar'].forEach(k => juntar(el[k]));
        if (!chars.size) return;

        const faltam = faltamNaFonte(cob, [...chars.keys()].join(''));
        if (!faltam.length) return;
        // O exemplo é o texto inteiro onde o caractere apareceu — "Ondřej Pek"
        // diz muito mais ao operador do que "ř".
        const exemplo = chars.get(faltam[0]);

        achados.push({
            elemento: el.name || el.type || 'elemento',
            fonte: el.font_name || '',
            faltam: faltam,
            exemplo: exemplo,
            comoSai: comoSaiNoPapel ? comoSaiNoPapel(exemplo, cob) : null,
        });
    });

    if (!achados.length) return null;

    const partes = achados.map(a => {
        const chars = a.faltam.map(ch => (rotuloCh ? rotuloCh(ch) : '"' + ch + '"')).join(', ');
        let p = 'a fonte "' + a.fonte + '" do elemento «' + a.elemento + '» não desenha ' + chars;
        if (a.exemplo && a.comoSai) p += ' — "' + a.exemplo + '" sai "' + a.comoSai + '"';
        return p;
    });
    const todos = [];
    achados.forEach(a => a.faltam.forEach(ch => { if (todos.indexOf(ch) < 0) todos.push(ch); }));

    return {
        motivo: 'glifo',
        texto: partes.join('; ') + '.',
        faltam: todos,
        elementos: achados,
    };
}
window.fonteSemGlifoDoModelo = fonteSemGlifoDoModelo;

/** Os nomes de fonte que os modelos de um pedido usam — para pedir a cobertura. */
function fontesDosModelosDoPedido(osId) {
    const itens = (state.osItens && state.osItens[osId]) || [];
    const nomes = new Set();
    itens.forEach(it => {
        const num = numeracaoDoModelo(it);
        (num && num.elements || []).forEach(el => {
            if (el && el.font_name) nomes.add(el.font_name);
        });
    });
    return [...nomes];
}
window.fontesDosModelosDoPedido = fontesDosModelosDoPedido;

/**
 * Células do banco que um modelo partilha com OUTRO modelo do mesmo pedido.
 *
 * Regra do usuário, 22/08/2026: "informar nos modelos quando alguma célula de
 * banco de dados utilizada na numeração de um modelo corresponder a uma célula
 * de outro modelo". A célula que importa é a que vai para o papel: o valor da
 * coluna apontada por cada elemento de banco de dados, nas linhas que ESTE
 * modelo imprime (a fatia dele, ou o banco inteiro quando não há fatia).
 *
 * O caso que a motivou é o pedido 21085: três modelos "Veículo" herdaram a
 * numeração do Expositor SIMERS pelo "aplicar a todos", e imprimiriam os
 * mesmos 4.000 códigos dele — credencial repetida, porta que abre duas vezes.
 * O mesmo vale para dois CSVs diferentes com um código em comum.
 *
 * É AVISO, não trava: nada impede o PRONTO. Devolve um mapa por id do modelo:
 *   { total, exemplos: [...até 3 valores], outros: [{ id, nome, n }] }
 * só para os modelos que têm alguma célula repetida. Valores vazios não contam;
 * a comparação é pelo texto exato, sem espaços nas pontas. Só lê.
 */
function celulasRepetidasDoPedido(osId) {
    // Com um banco ainda descendo, a conta sairia MENOR que a verdade, e um
    // aviso que muda de numero sozinho na frente do operador nao vale nada.
    // Cala a boca ate os bancos estarem todos aqui -- o `renderAmostras`
    // redesenha quando o ultimo chega. Ver `carregarBancosDoPedido`.
    if (typeof numeracoesSemBancoBaixado === 'function'
        && numeracoesSemBancoBaixado(osId).length) return {};
    const itens = (state.osItens && state.osItens[osId]) || [];
    const porValor = new Map();     // valor -> Set(id do modelo)
    const usoPorItem = {};          // id do modelo -> { nome, valores: Set }
    itens.forEach((it, i) => {
        if (!it) return;
        const num = numeracaoDoModelo(it);
        if (!num || !Array.isArray(num.csv_data) || !num.csv_data.length) return;
        // So as colunas CONFERIDAS: `Camarote` vai de 1 a 140 e repete por
        // natureza. Ver `colunasConferidasDaNumeracao`.
        const colunas = colunasConferidasDaNumeracao(num);
        if (!colunas.length) return;
        const valores = new Set();
        fatiaCsvDoItem(it, num).forEach(linha => {
            if (!linha) return;
            colunas.forEach(c => {
                const v = linha[c];
                const texto = (v === null || v === undefined) ? '' : String(v).trim();
                if (texto) valores.add(texto);
            });
        });
        const id = String(it.id);
        // Ate 28/08/2026 havia aqui uma isencao: modelos do MESMO banco lendo
        // colunas diferentes nao disputavam valor (`separadosPelaColuna`, do
        // formato largo de 27/08, em que o NOME repete entre os dias de
        // proposito). Ela silenciava tambem o choque REAL -- o mesmo codigo em
        // colunas diferentes de dois modelos -- e foi o que o usuario relatou:
        // 'a Conferencia de dados nao esta verificando entre modelos'. Quem
        // cala a repeticao legitima e a MARCA de conferencia (a caixinha
        // Conferir do editor de colunas): coluna que repete por natureza se
        // DESMARCA, como o proprio SETOR do pedido de teste 21346. A
        // comparacao por valor vale entre TODOS os modelos, como sempre foi
        // antes do formato largo.
        usoPorItem[id] = {
            nome: rotuloDoModelo(it, i),
            valores
        };
        valores.forEach(v => {
            if (!porValor.has(v)) porValor.set(v, new Set());
            porValor.get(v).add(id);
        });
    });

    const saida = {};
    Object.keys(usoPorItem).forEach(id => {
        const porModelo = {};
        const exemplos = [];
        let total = 0;
        usoPorItem[id].valores.forEach(v => {
            const donos = porValor.get(v);
            if (!donos || donos.size < 2) return;
            total++;
            if (exemplos.length < 3) exemplos.push(v);
            donos.forEach(outro => {
                if (outro !== id) porModelo[outro] = (porModelo[outro] || 0) + 1;
            });
        });
        if (!total) return;
        saida[id] = {
            total,
            exemplos,
            outros: Object.keys(porModelo).map(o => ({ id: o, nome: usoPorItem[o].nome, n: porModelo[o] }))
        };
    });
    return saida;
}
window.celulasRepetidasDoPedido = celulasRepetidasDoPedido;

/** A frase do aviso: quantas, com quem, e um gosto de quais. */
function textoDasCelulasRepetidas(d) {
    if (!d || !d.total) return '';
    const com = d.outros.map(o => o.nome + ' (' + o.n + ')').join(', ');
    const ex = d.exemplos.length ? ' Ex.: ' + d.exemplos.join(', ') + (d.total > d.exemplos.length ? '…' : '') : '';
    return d.total + (d.total === 1 ? ' célula do banco deste modelo também está' : ' células do banco deste modelo também estão')
        + ' no banco de: ' + com + '.' + ex;
}
window.textoDasCelulasRepetidas = textoDasCelulasRepetidas;

/**
 * A PRIMEIRA LINHA da fatia de um modelo — SÓ as colunas que a numeração lê.
 *
 * É por onde o banco daquele modelo COMEÇA. Numa numeração dividida entre vários
 * modelos, ler a primeira linha de cada um é o jeito mais rápido de ver que a
 * distribuição saiu certa — um começa no 1001, o outro no 1501 — sem abrir o CSV
 * modelo a modelo (pedido do usuário, 23/08/2026).
 *
 * **Coluna que nenhum elemento da numeração lê não entra** (regra do usuário, no
 * mesmo dia, olhando o pedido 21085). Este relatório responde uma pergunta só —
 * o que vai sair no papel está certo? —, e uma coluna que o cliente deixou no
 * arquivo mas que a numeração ignora não é impressa em lugar nenhum. Na primeira
 * versão desta coluna eu mostrava o CSV inteiro; no 21085 isso significava
 * repetir o nome do setor ao lado de cada código, dobrando o texto da célula
 * para não dizer nada sobre a produção.
 *
 * As colunas do banco aparecem MESMO VAZIAS: coluna apontada em branco na
 * primeira linha é exatamente o que este relatório existe para mostrar. Sem
 * elemento de banco não há primeira linha a mostrar — a célula fica vazia.
 */
function primeiraLinhaDoModelo(fatia, colunasDoBanco) {
    const linha = (Array.isArray(fatia) && fatia.length) ? fatia[0] : null;
    if (!linha || typeof linha !== 'object') return { pares: [], texto: '' };

    const nomes = [];
    (colunasDoBanco || [])
        .map(c => String(c === null || c === undefined ? '' : c).trim())
        .filter(Boolean)
        .forEach(c => { if (nomes.indexOf(c) === -1) nomes.push(c); });

    const pares = nomes.map(c => {
        const v = linha[c];
        return { coluna: c, valor: (v === null || v === undefined) ? '' : String(v).trim() };
    });

    return { pares, texto: pares.map(p => p.coluna + ': ' + (p.valor || '(vazio)')).join(' · ') };
}
window.primeiraLinhaDoModelo = primeiraLinhaDoModelo;

/**
 * A CONFERÊNCIA DE DADOS do pedido — o relatório que o botão 🔎 do pedido
 * aberto mostra (regra do usuário, 22/08/2026).
 *
 * É a mesma revisão que foi feita à mão no pedido 21085 naquele dia, agora
 * dentro da tela, para qualquer pedido, num clique. Para cada modelo:
 *
 *   • a numeração e o arquivo CSV que ele usa;
 *   • quantas linhas ele imprime (a fatia) contra a Qtd do pedido;
 *   • quantos códigos distintos, quantos repetidos DENTRO do próprio CSV e
 *     quantas células vazias na coluna do banco;
 *   • as três regras do card: banco incompleto (elemento de banco sem CSV ou
 *     sem coluna), Qtd × células, e células repetidas com OUTRO modelo.
 *
 * "Códigos" são os valores das colunas apontadas pelos elementos de banco de
 * dados — o que vai para o papel. Modelo cuja numeração não usa banco entra no
 * relatório como "não usa banco", sem ser cobrado por CSV.
 *
 * Só lê, e lê o que está em memória: quem chama (abrirConferenciaDeDados)
 * relê as numerações do pedido no banco antes. Devolve um objeto simples, que
 * o harness exercita sem DOM: { osId, modelos: [...], problemas: [...], ok }.
 */
function conferenciaDeDadosDoPedido(osId) {
    const itens = (state.osItens && state.osItens[osId]) || [];
    const repetidas = celulasRepetidasDoPedido(osId);
    const modelos = [];
    const problemas = [];
    itens.forEach((it, i) => {
        if (!it) return;
        const nome = rotuloDoModelo(it, i);
        const bruto = (it.quantidade !== undefined && it.quantidade !== null) ? it.quantidade : it.qtd;
        const qtd = parseInt(bruto) || 0;
        const num = numeracaoDoModelo(it);
        const linha = {
            id: String(it.id), nome, qtd,
            numeracao: num ? (num.name || num.tipo || '') : '',
            arquivo: num ? (num.csv_filename || '') : '',
            usaBanco: false, linhas: 0, codigos: 0, repetidosDentro: 0, vazios: 0,
            primeira: '', primeiraPares: [],
            avisos: []
        };
        const anotar = (texto) => { linha.avisos.push(texto); problemas.push(nome + ': ' + texto); };
        if (!num) {
            anotar('sem numeração');
            modelos.push(linha);
            return;
        }
        const deBanco = (num.elements || []).filter(el => el && el.source === 'database');
        linha.usaBanco = deBanco.length > 0;

        const incompleto = bancoDeDadosIncompletoDoModelo(it);
        if (incompleto) anotar(incompleto.texto);

        const divergencia = divergenciaDeCelulasDoModelo(it);
        if (divergencia) anotar(textoDaDivergenciaDeCelulas(divergencia));

        if (Array.isArray(num.csv_data) && num.csv_data.length) {
            // A conferencia de repetidos DENTRO do CSV segue a mesma escolha
            // do aviso entre modelos -- ver `colunasConferidasDaNumeracao`.
            const colunas = colunasConferidasDaNumeracao(num);
            const fatia = fatiaCsvDoItem(it, num);

            // A 1ª linha traz SÓ as colunas que a numeração lê. Sem elemento de
            // banco, `colunas` é vazia e a célula fica vazia — é o certo: não há
            // nada daquele CSV indo para o papel.
            const primeira = primeiraLinhaDoModelo(fatia, colunas);
            linha.primeira = primeira.texto;
            linha.primeiraPares = primeira.pares;

            if (linha.usaBanco) {
                linha.linhas = fatia.length;
                const contagem = new Map();
                let vazios = 0;
                fatia.forEach(l => {
                    colunas.forEach(c => {
                        const v = l ? l[c] : null;
                        const texto = (v === null || v === undefined) ? '' : String(v).trim();
                        if (!texto) vazios++;
                        else contagem.set(texto, (contagem.get(texto) || 0) + 1);
                    });
                });
                linha.codigos = contagem.size;
                let rep = 0;
                contagem.forEach(n => { if (n > 1) rep += n - 1; });
                linha.repetidosDentro = rep;
                linha.vazios = vazios;
                if (rep) anotar(rep + ' código(s) repetido(s) dentro do próprio CSV');
                if (vazios) anotar(vazios + ' célula(s) vazia(s) na coluna do banco');
            }
        }

        const rep = repetidas[String(it.id)];
        if (rep) {
            linha.repetidosComOutros = rep;
            anotar(textoDasCelulasRepetidas(rep));
        }
        modelos.push(linha);
    });
    return { osId, modelos, problemas, ok: problemas.length === 0 };
}
window.conferenciaDeDadosDoPedido = conferenciaDeDadosDoPedido;

/** O relatório em texto puro — para copiar e mandar para quem precisa ver. */
function textoDaConferencia(rel, numeroPedido) {
    if (!rel) return '';
    const linhas = [];
    linhas.push('CONFERÊNCIA DE DADOS — Pedido ' + (numeroPedido || rel.osId));
    linhas.push(rel.ok ? 'Nenhum problema encontrado.' : rel.problemas.length + ' ponto(s) de atenção:');
    if (!rel.ok) rel.problemas.forEach(pb => linhas.push('  - ' + pb));
    linhas.push('');
    rel.modelos.forEach(m => {
        const cabeca = m.nome + ' | qtd ' + m.qtd + ' | numeração ' + (m.numeracao || '—')
            + (m.arquivo ? ' | ' + m.arquivo : '');
        const banco = m.usaBanco
            ? ' | linhas ' + m.linhas + ' | códigos ' + m.codigos + ' | repetidos ' + m.repetidosDentro + ' | vazios ' + m.vazios
            : ' | não usa banco';
        // A 1ª linha vai INTEIRA no texto copiado — na tela ela é encurtada para
        // caber na coluna, e é este texto que segue para quem vai corrigir.
        const primeira = m.primeira ? ' | 1ª linha: ' + m.primeira : '';
        linhas.push(cabeca + banco + primeira + (m.avisos.length ? ' | ATENÇÃO: ' + m.avisos.join(' · ') : ''));
    });
    return linhas.join('\n');
}
window.textoDaConferencia = textoDaConferencia;

/**
 * O botão 🔎 Conferência de dados do pedido aberto: relê as numerações do
 * pedido no banco, monta o relatório e mostra numa janela com o resumo no
 * topo, uma linha por modelo e os botões Copiar e Fechar.
 */
async function abrirConferenciaDeDados(osId) {
    osId = osId || state.amostrasOSAtivo;
    if (!osId) { toast('Abra um pedido primeiro.', 'warning'); return; }
    const os = (typeof findOSInState === 'function') ? findOSInState(osId) : null;
    const numero = os ? os.numero : osId;
    toast('⏳ Conferindo os dados do pedido ' + numero + '…', 'info');
    try { await recarregarNumeracoesDoPedido(osId); } catch (e) { /* segue com o que tem */ }
    const rel = conferenciaDeDadosDoPedido(osId);

    // As quatro colunas de contagem não quebram: número quebrado em duas linhas
    // não se lê, e é a quebra delas que empurrava Vazios e Situação para fora.
    const NUM = 'text-align:center; white-space:nowrap;';

    const linhasHtml = rel.modelos.map(m => {
        const banco = m.usaBanco
            ? `<td style="${NUM}">${m.linhas === m.qtd ? '' : '<span style="color:#f87171;font-weight:800;">'}${m.linhas}${m.linhas === m.qtd ? '' : '</span>'} / ${m.qtd}</td>
               <td style="${NUM}">${m.codigos}</td>
               <td style="${NUM}${m.repetidosDentro ? 'color:#f87171;font-weight:800;' : ''}">${m.repetidosDentro}</td>
               <td style="${NUM}${m.vazios ? 'color:#f87171;font-weight:800;' : ''}">${m.vazios}</td>`
            : `<td colspan="4" style="${NUM}color:#94a3b8;">não usa banco (qtd ${m.qtd})</td>`;
        const avisos = m.avisos.length
            ? `<span style="color:#fca5a5;">${escapeHtml(m.avisos.join(' · '))}</span>`
            : '<span style="color:#4ade80;">✓</span>';
        // A 1ª LINHA da fatia: por onde o banco daquele modelo começa. Só os
        // VALORES das colunas que a numeração lê (pedido do usuário, 23/08/2026)
        // — o nome da coluna repetido em cada célula era a mesma palavra dezenas
        // de vezes na mesma tela, e empurrava o resto para fora. Quem quiser
        // saber de que coluna veio cada valor passa o mouse: o title traz a
        // linha com os nomes, e é assim que ela vai no relatório copiado.
        const TETO = 10;
        const valor = p => `<span style="color:#e2e8f0;font-weight:700;">`
            + `${escapeHtml(p.valor || '(vazio)')}</span>`;
        const pares = m.primeiraPares || [];
        const primeira = pares.length
            ? pares.slice(0, TETO).map(valor).join('<span style="color:#475569;"> · </span>')
              + (pares.length > TETO ? `<span style="color:#94a3b8;"> · +${pares.length - TETO}</span>` : '')
            : '<span style="color:#64748b;">—</span>';
        return `<tr style="border-top:1px solid rgba(148,163,184,0.15);">
                    <td><strong>${escapeHtml(m.nome)}</strong></td>
                    <td>${escapeHtml(m.numeracao || '—')}<br><span style="color:#94a3b8;font-size:0.72rem;">${escapeHtml(m.arquivo || '')}</span></td>
                    <td style="max-width:260px; font-size:0.76rem; line-height:1.4; word-break:break-word;" title="${escapeHtml(m.primeira || '')}">${primeira}</td>
                    ${banco}
                    <td style="font-size:0.78rem; min-width:140px; padding-left:16px;">${avisos}</td>
                </tr>`;
    }).join('');

    const resumo = rel.ok
        ? `<div style="padding:10px 14px; border-radius:8px; background:rgba(34,197,94,0.12); border:1px solid rgba(34,197,94,0.4); color:#4ade80; font-weight:700;">✅ Nenhum problema encontrado — ${rel.modelos.length} modelo(s) conferido(s).</div>`
        : `<div style="padding:10px 14px; border-radius:8px; background:rgba(239,68,68,0.10); border:1px solid rgba(239,68,68,0.4); color:#fca5a5; font-weight:600;">
               <div style="font-weight:800; margin-bottom:6px;">⚠️ ${rel.problemas.length} ponto(s) de atenção</div>
               <ul style="margin:0; padding-left:18px; font-size:0.82rem; line-height:1.45;">${rel.problemas.map(pb => '<li>' + escapeHtml(pb) + '</li>').join('')}</ul>
           </div>`;

    const overlay = document.createElement('div');
    overlay.id = 'conferencia-dados-overlay';
    overlay.style.cssText = 'position:fixed; inset:0; background:rgba(2,6,23,0.78); z-index:100000; display:flex; align-items:center; justify-content:center; padding:20px;';
    overlay.innerHTML = `
        <div style="background:#1e293b; border:1px solid rgba(148,163,184,0.25); border-radius:12px; box-shadow:0 24px 60px rgba(0,0,0,0.6); width:100%; max-width:min(1360px, 96vw); max-height:92vh; display:flex; flex-direction:column; overflow:hidden;">
            <div style="padding:16px 22px; border-bottom:1px solid rgba(148,163,184,0.2); display:flex; align-items:center; gap:12px;">
                <h3 style="margin:0; font-size:1.1rem; font-weight:800; color:#e2e8f0;">🔎 Conferência de dados — Pedido ${escapeHtml(String(numero))}</h3>
                <span style="margin-left:auto; color:#94a3b8; font-size:0.8rem;">lido do banco agora</span>
            </div>
            <div style="padding:16px 22px; overflow:auto; color:#e2e8f0; font-size:0.88rem; display:flex; flex-direction:column; gap:14px;">
                ${resumo}
                <!-- A tabela rola na horizontal DENTRO deste box. Sem isto, num
                     pedido com CSV largo as últimas colunas (Vazios e Situação)
                     ficavam fora da janela, sem barra nenhuma para alcançá-las. -->
                <div style="overflow-x:auto;">
                    <table style="width:100%; border-collapse:collapse; font-size:0.82rem;">
                        <thead><tr style="color:#94a3b8; text-align:left; font-size:0.72rem; text-transform:uppercase; letter-spacing:0.04em;">
                            <th style="padding:6px 4px;">Modelo</th><th>Numeração / arquivo</th>
                            <th>1ª linha</th>
                            <th style="${NUM}">Linhas / Qtd</th><th style="${NUM}">Códigos</th>
                            <th style="${NUM}">Repet. dentro</th><th style="${NUM}">Vazios</th>
                            <th style="padding-left:16px;">Situação</th>
                        </tr></thead>
                        <tbody>${linhasHtml}</tbody>
                    </table>
                </div>
                <div style="color:#94a3b8; font-size:0.74rem; line-height:1.4;">
                    "Códigos" são os valores das colunas apontadas pelos elementos de banco de dados — o que vai para o papel. Linhas contam a fatia do modelo.
                    "1ª linha" é por onde a fatia daquele modelo começa: os valores da primeira linha, apenas das colunas que a numeração lê — passe o mouse para ver de que coluna veio cada um, que é como a linha vai no relatório copiado.
                    A conferência cobre: banco incompleto, Qtd × células, repetições dentro do CSV, células vazias e células repetidas entre modelos deste pedido.
                </div>
            </div>
            <div style="padding:14px 22px; border-top:1px solid rgba(148,163,184,0.2); display:flex; justify-content:flex-end; gap:10px;">
                <button type="button" data-role="copiar" style="border:1px solid rgba(148,163,184,0.35); background:transparent; color:#cbd5e1; border-radius:8px; padding:9px 16px; font-weight:700; cursor:pointer;">📋 Copiar relatório</button>
                <button type="button" data-role="fechar" style="border:none; background:linear-gradient(135deg,#3b82f6,#2563eb); color:#fff; border-radius:8px; padding:9px 18px; font-weight:800; cursor:pointer;">Fechar</button>
            </div>
        </div>`;
    const fechar = () => { document.removeEventListener('keydown', onKey, true); overlay.remove(); };
    const onKey = (ev) => { if (ev.key === 'Escape') { ev.preventDefault(); fechar(); } };
    overlay.querySelector('[data-role="fechar"]').addEventListener('click', fechar);
    overlay.querySelector('[data-role="copiar"]').addEventListener('click', async () => {
        const texto = textoDaConferencia(rel, numero);
        try {
            await navigator.clipboard.writeText(texto);
            toast('Relatório copiado.', 'success');
        } catch (e) {
            // Sem clipboard (http na LAN, por exemplo): abre numa janela para copiar à mão.
            const w = window.open('', '_blank');
            if (w) { w.document.write('<pre style="font:13px monospace;white-space:pre-wrap;">' + escapeHtml(texto) + '</pre>'); w.document.close(); }
            else toast('Não consegui copiar — o navegador bloqueou a área de transferência.', 'warning');
        }
    });
    overlay.addEventListener('click', (ev) => { if (ev.target === overlay) fechar(); });
    document.addEventListener('keydown', onKey, true);
    document.body.appendChild(overlay);
}
window.abrirConferenciaDeDados = abrirConferenciaDeDados;

/**
 * A frase do bloqueio. Diz a conta inteira porque quem lê é quem vai corrigi-la:
 * "faltam 250" sozinho não conta de onde saiu o número esperado.
 */
function textoDaDivergenciaDeCelulas(d) {
    if (!d) return '';
    const falta = d.diferenca < 0 ? ('faltam ' + (-d.diferenca)) : ('sobram ' + d.diferenca);
    // Faltando linha E havendo linha descartada, a causa quase sempre e a mesma:
    // celula em branco na coluna do banco. Dizer isso aqui poupa o operador de
    // abrir o CSV para descobrir por que a conta encolheu.
    const causa = (d.diferenca < 0 && d.descartadas)
        ? (' (' + d.descartadas + ' linha(s) do CSV sem nada nas colunas desta numeração)')
        : '';
    return 'Qtd ' + d.qtd + ' · ' + d.modo + ' · esperado ' + d.esperado
         + ' linha(s) · gerado ' + d.gerado + ' · ' + falta + causa;
}
window.textoDaDivergenciaDeCelulas = textoDaDivergenciaDeCelulas;



/**
 * A conta que a barra mostra. `null` quando ainda não dá para calcular — sem
 * formato não há células por folha, e um número inventado seria pior que nenhum.
 */
function contaDaSoma(itens) {

    if (!itens || itens.length < 2) return null;

    const fmt = (state.formatos || []).find(f => String(f.id) === String(itens[0].formato_id));

    const poses = fmt ? (parseInt(fmt.cols) || 0) * (parseInt(fmt.rows) || 0) : 0;

    if (!poses) return null;

    let total = 0, separado = 0;

    itens.forEach(it => {

        const q = quantidadeDoModelo(it);

        if (q <= 0) return;

        total += q;

        separado += Math.ceil(q / poses);

    });

    if (!total) return null;

    const somado = Math.ceil(total / poses);

    return {
        modelos: itens.length, itens: total, poses,
        separado, somado, economia: separado - somado
    };

}
window.contaDaSoma = contaDaSoma;



/**
 * Os modelos cuja blocagem é de verdade — os que sozinhos já formam um bloco
 * completo. Só esses perdem alguma coisa ao aproveitar a folha; um `bloco`
 * preenchido no ERP mas grande demais para a tiragem não perde nada, e é
 * exatamente o caso do pedido 20495.
 */
function modelosComBlocagemReal(itens) {

    const spb = parseInt(document.getElementById('ped-sheets-per-block')?.value
                      || document.getElementById('imp-sheets-per-block')?.value) || 50;

    return (itens || [])

        .filter(it => quantidadeDoModelo(it) >= spb)

        .map((it, i) => rotuloDoModelo(it, i));

}



/** Mostra, esconde e preenche a barra de modelos combinados nas duas abas. */
function atualizarBarraDeSoma() {

    const varias = (state.selectedOSItems || []).length > 1;

    const itens = varias ? itensDaImposicao(true) : [];

    const conta = varias ? contaDaSoma(itens) : null;

    // Sequencial enche a folha na ordem e não corta pilha nenhuma, então não
    // existe "folha própria por modelo" nesse modo: a escolha da barra deixa de
    // ter o que decidir, e um seletor que não decide nada engana quem o lê.
    const sequencial = varias && modoDeImpressaoDaSelecao() === 'sequencial';

    const aproveitando = !sequencial && modoSomaFolha() === 'aproveitar';

    const comBloco = (varias && aproveitando) ? modelosComBlocagemReal(itens) : [];

    const texto = conta
        ? `${conta.modelos} modelos · ${conta.itens.toLocaleString('pt-BR')} itens · `
          + `${conta.poses} por folha · `
          + (sequencial
              ? `${conta.somado.toLocaleString('pt-BR')} folhas — Sequencial enche a folha na ordem`
              : aproveitando
              ? `${conta.somado.toLocaleString('pt-BR')} folhas`
                + (conta.economia > 0 ? ` — economia de ${conta.economia} folha(s)` : '')
              : `${conta.separado.toLocaleString('pt-BR')} folhas`
                + (conta.economia > 0 ? ` — aproveitando a folha seriam ${conta.somado}` : ''))
        : 'Escolha o formato dos modelos para ver a conta das folhas.';

    const aviso = sequencial
        ? 'Sequencial não corta pilha, então não há folha própria por modelo — um começa na folha '
          + 'onde o outro terminou. Para dar folha própria a cada modelo, mude o modo para Blocado '
          + 'em "Opções do modelo".'
        : comBloco.length
        ? `⚠️ Aproveitar a folha desfaz a montagem por bloco de: ${comBloco.join(', ')}. `
          + 'Para manter os blocos, volte para "Cada modelo em folha própria".'
        : '';

    [['imp-soma-bar', 'imp-modo-soma', 'imp-soma-conta', 'imp-soma-aviso'],
     ['ped-soma-bar', 'ped-modo-soma', 'ped-soma-conta', 'ped-soma-aviso']].forEach(ids => {

        const bar = document.getElementById(ids[0]);

        if (!bar) return;

        bar.style.display = varias ? 'flex' : 'none';

        if (!varias) return;

        const sel = document.getElementById(ids[1]);

        if (sel && sel.value !== modoSomaFolha()) sel.value = modoSomaFolha();

        if (sel) {

            sel.disabled = sequencial;

            sel.style.opacity = sequencial ? '0.5' : '';

        }

        const elConta = document.getElementById(ids[2]);

        if (elConta) elConta.textContent = texto;

        const elAviso = document.getElementById(ids[3]);

        if (elAviso) {

            elAviso.textContent = aviso;

            elAviso.style.display = aviso ? 'block' : 'none';

        }

    });

    // O bloco de opções e o selo da sobra pertencem à imposição de agora, e as
    // duas telas que desenham a fila terminam aqui — é o ponto onde os dois já
    // se atualizam sozinhos, com um modelo ou com vários.
    atualizarOpcoesDoModelo();

    atualizarSeloDeSobra();

}
window.atualizarBarraDeSoma = atualizarBarraDeSoma;



// ─────────────────────────────────────────────────────────────────────────────
// AS OPÇÕES QUE O MODELO GUARDA PARA QUANDO ENTRA NUMA FOLHA COMBINADA
//
// Duas escolhas do operador não tinham onde morar e se perdiam a cada troca de
// modelo: se o número do modelo sai impresso em cada item, e se a tiragem é
// sequencial ou blocada. Agora ficam em `pedidos_modelos` e voltam do jeito que
// ficaram.
//
// A FRONTEIRA, e é ela que importa aqui: tudo deste bloco é lido SOMENTE quando
// há dois ou mais modelos marcados. Imprimir um modelo sozinho continua decidido
// pela Regra de Paginação da tela, pelo padrão do Formato e pelo `blocos` do ERP
// — caminho já validado na gráfica, que não muda por causa deste recurso. Foi
// condição do usuário em 18/08/2026. Ver docs/modelos_somados.md.
// ─────────────────────────────────────────────────────────────────────────────

/** Este modelo imprime o próprio número em cada item? Só vale ao combinar. */
function imprimeNumeroDoModelo(item) {

    return !!(item && item.imprimir_numero_modelo);

}
window.imprimeNumeroDoModelo = imprimeNumeroDoModelo;



/**
 * O número do pedido a que um modelo pertence — o número que o ERP mostra, e que
 * o QR Ideal escreve de trás para frente dentro do código.
 *
 * Viaja por arte no payload porque uma folha pode juntar modelos de pedidos
 * diferentes. O pedido do trabalho é o de um deles, e serviria de resposta
 * errada para os outros: coluna errada do pool e prefixo errado no QR — um
 * ingresso que só falha na portaria. Ver docs/qr_ideal.md.
 */
function numeroDoPedidoDoItem(osId) {

    const os = (state.ordens || []).find(o => String(o.id) === String(osId));

    return os && os.numero !== undefined && os.numero !== null ? String(os.numero) : null;

}
window.numeroDoPedidoDoItem = numeroDoPedidoDoItem;



/**
 * Com que modo este modelo entra numa folha combinada: 'sequencial' ou
 * 'blocado'. O que o operador salvou vence; sem nada salvo vale o `blocos` do
 * ERP e, na falta dele, o padrão do Formato — que é quem decidia antes de a
 * escolha existir, e por isso modelo nunca tocado se comporta como sempre.
 */
function modoDeImpressaoDoModelo(item) {

    if (!item) return 'sequencial';

    const salvo = String(item.modo_impressao || '').toLowerCase();

    if (salvo === 'sequencial' || salvo === 'blocado') return salvo;

    if (item.blocos && String(item.blocos).toUpperCase() !== 'N') return 'blocado';

    const fmt = (state.formatos || []).find(f => String(f.id) === String(item.formato_id));

    return (fmt && fmt.default_schema === 'cut_stack') ? 'blocado' : 'sequencial';

}
window.modoDeImpressaoDoModelo = modoDeImpressaoDoModelo;



/**
 * O modo de blocos e as folhas por bloco de um modelo. Sem nada salvo devolve
 * exatamente o que a v634 já mandava ao combinar — montagem estrita com as
 * folhas do `bloco` do ERP —, para que ligar este recurso não mude nenhuma
 * tiragem que já estava saindo certa.
 */
function blocagemDoModelo(item) {

    return {
        modo: (item && item.cutstack_modo) || 'strict_assembly',
        folhas: parseInt(item && item.cutstack_folhas) || parseInt(item && item.bloco) || 50
    };

}
window.blocagemDoModelo = blocagemDoModelo;



/**
 * O modo da folha combinada. A seleção só combina modelos do mesmo modo — ver
 * porQueNaoCombina() —, então o do primeiro vale para a folha inteira.
 */
function modoDeImpressaoDaSelecao() {

    const itens = itensDaImposicao(true);

    return itens.length ? modoDeImpressaoDoModelo(itens[0]) : 'blocado';

}
window.modoDeImpressaoDaSelecao = modoDeImpressaoDaSelecao;



/**
 * A blocagem da folha combinada. Vale o primeiro modelo que tem folhas
 * definidas, e não simplesmente o primeiro da lista: é a mesma regra que a tela
 * já usava para preencher "Folhas por Bloco" a partir do `bloco` do ERP.
 */
function blocagemDaSelecao() {

    const itens = itensDaImposicao(true);

    const comFolhas = itens.find(it => (parseInt(it.cutstack_folhas) || parseInt(it.bloco) || 0) > 0);

    return blocagemDoModelo(comFolhas || itens[0] || null);

}
window.blocagemDaSelecao = blocagemDaSelecao;



/**
 * O esquema que o motor recebe para uma folha combinada.
 *
 * 'sequencial' enche a folha na ordem de leitura, folha a folha. O motor já sabe
 * fazer isso com modelos combinados — o índice é `(folha × poses) + posição` e
 * cada item puxa a arte do próprio modelo. Como não há pilha para cortar, nesse
 * modo não existe "folha própria": os modelos entram em sequência e um começa
 * onde o outro terminou.
 *
 * 'blocado' mantém o que existe desde a v631: a barra de modelos combinados
 * decide entre folha própria (cut_stack) e aproveitar a folha (multi_artes).
 */
function esquemaDaSelecaoCombinada() {

    if (modoDeImpressaoDaSelecao() === 'sequencial') return 'sequential';

    return (modoSomaFolha() === 'aproveitar') ? 'multi_artes' : 'cut_stack';

}
window.esquemaDaSelecaoCombinada = esquemaDaSelecaoCombinada;



/** O cut_stack_mode que acompanha o esquema acima. */
function modoCutStackDaSelecao() {

    // Fora do cut_stack o motor ignora este campo; mandar 'independent' é dizer
    // a verdade no payload, não mudar comportamento.
    if (esquemaDaSelecaoCombinada() !== 'cut_stack') return 'independent';

    return blocagemDaSelecao().modo;

}
window.modoCutStackDaSelecao = modoCutStackDaSelecao;



/**
 * O nome do arquivo de uma imposição com vários modelos: todos eles, porque o
 * operador precisa saber o que tem dentro sem abrir. Acima de oito encurta para
 * o primeiro, o último e a contagem — o caminho no Windows para em 260
 * caracteres, e o motor ainda deriva daqui os nomes `_setN_02_miolo`.
 */
function nomeDosModelosCombinados(itens) {

    const nomes = (itens || []).map(it => String((it && it.modelo) || '').trim()).filter(Boolean);

    if (!nomes.length) return '';

    if (nomes.length <= 8) return nomes.join('_');

    return nomes[0] + '_a_' + nomes[nomes.length - 1] + '_' + nomes.length + 'modelos';

}
window.nomeDosModelosCombinados = nomeDosModelosCombinados;



/**
 * Os modelos que esta impressão deve marcar como impressos. Com vários marcados
 * são todos: imprimir dois e marcar um deixava o outro em Aguardando, e o
 * operador só descobria pela fila, depois.
 */
function alvosDaImpressao(isMultiSelected) {

    if (isMultiSelected) {

        return (state.selectedOSItems || [])

            .filter(s => s && s.itemId)

            .map(s => ({ itemId: s.itemId, osId: s.osId }));

    }

    return (state.activeOSItem && state.activeOSItem.itemId)
        ? [{ itemId: state.activeOSItem.itemId, osId: state.activeOSItem.osId }]
        : [];

}
window.alvosDaImpressao = alvosDaImpressao;



/**
 * Grava a opção do número do modelo e redesenha o que depende dela — inclusive
 * a prévia, que tem de mostrar o que sai no papel.
 */
window.setImprimirNumeroDoModelo = async function(marcado) {

    const item = itemAtivoDoPedido();

    if (!item || !state.activeOSItem) return;

    item.imprimir_numero_modelo = !!marcado;

    await autoSaveOSItemField(item.id, state.activeOSItem.osId, 'imprimir_numero_modelo', !!marcado);

    atualizarOpcoesDoModelo();

    if (typeof drawPedPreview === 'function') drawPedPreview();

};



/**
 * Grava o modo de impressão do modelo. Escolher "Blocado" num modelo que nunca
 * teve escolha grava também o modo de blocos e as folhas, herdados do Formato e
 * do `bloco` do ERP: o que vale fica escrito no modelo, em vez de depender de um
 * padrão que pode mudar depois, sem ninguém notar.
 */
window.setModoImpressaoDoModelo = async function(modo) {

    const item = itemAtivoDoPedido();

    if (!item || !state.activeOSItem) return;

    const osId = state.activeOSItem.osId;

    const valor = (modo === 'blocado') ? 'blocado' : 'sequencial';

    item.modo_impressao = valor;

    await autoSaveOSItemField(item.id, osId, 'modo_impressao', valor);

    if (valor === 'blocado' && !item.cutstack_modo) {

        const fmt = (state.formatos || []).find(f => String(f.id) === String(item.formato_id));

        const modoBloco = (fmt && fmt.default_cut_stack_mode) || 'strict_assembly';

        item.cutstack_modo = modoBloco;

        await autoSaveOSItemField(item.id, osId, 'cutstack_modo', modoBloco);

    }

    if (valor === 'blocado' && !item.cutstack_folhas) {

        const folhas = parseInt(item.bloco) || 50;

        item.cutstack_folhas = folhas;

        await autoSaveOSItemField(item.id, osId, 'cutstack_folhas', folhas);

    }

    atualizarOpcoesDoModelo();

    atualizarBarraDeSoma();

    if (typeof drawPedPreview === 'function') drawPedPreview();

};



/**
 * Pinta o bloco "Opções do modelo" nas duas abas com o que está salvo no modelo
 * aberto. Sem modelo aberto o bloco some — opção precisa dizer de quem é.
 */
function atualizarOpcoesDoModelo() {

    const item = itemAtivoDoPedido();

    const modo = item ? modoDeImpressaoDoModelo(item) : 'sequencial';

    const travadoPorPdf = !!(item && item.modo_pdf);

    const titulo = item ? ((item.modelo ? item.modelo + ' — ' : '') + rotuloDoModelo(item, 0)) : '';

    [['imp-opcoes-modelo', 'imp-opcoes-modelo-nome', 'imp-modo-seq', 'imp-modo-bloc', 'imp-imprimir-numero', 'imp-opcoes-modelo-nota'],
     ['ped-opcoes-modelo', 'ped-opcoes-modelo-nome', 'ped-modo-seq', 'ped-modo-bloc', 'ped-imprimir-numero', 'ped-opcoes-modelo-nota']].forEach(ids => {

        const bloco = document.getElementById(ids[0]);

        if (!bloco) return;

        bloco.style.display = item ? 'block' : 'none';

        if (!item) return;

        // O `if` nao e' defensividade a toa: desde 29/08/2026 a caixa da tela de
        // PEDIDO nao tem mais o `-nome`. Ela desceu para dentro da janela de
        // visualizacao, cujo cabecalho ja diz de que modelo se trata, uma linha
        // acima — repetir o nome ali era a mesma informacao duas vezes na mesma
        // caixa. A da aba Imposicao continua com o dela.
        const elNome = document.getElementById(ids[1]);

        if (elNome) elNome.textContent = titulo;

        [[ids[2], 'sequencial'], [ids[3], 'blocado']].forEach(par => {

            const btn = document.getElementById(par[0]);

            if (!btn) return;

            const ativo = (modo === par[1]);

            btn.classList.toggle('ativo', ativo);

            btn.setAttribute('aria-pressed', ativo ? 'true' : 'false');

            btn.disabled = travadoPorPdf;

        });

        const chk = document.getElementById(ids[4]);

        if (chk) chk.checked = imprimeNumeroDoModelo(item);

        const nota = document.getElementById(ids[5]);

        if (nota) {

            nota.textContent = travadoPorPdf
                ? '🔒 Modo PDF: cada página do arquivo é um ingresso, e a regra é imposta. Para mudar, desligue o Modo PDF na tela de arte do modelo.'
                : '';

            nota.style.display = travadoPorPdf ? 'block' : 'none';

        }

    });

}
window.atualizarOpcoesDoModelo = atualizarOpcoesDoModelo;



// ─────────────────────────────────────────────────────────────────────────────
// APROVEITAMENTO DE FOLHA
//
// Toda tiragem que não é múltiplo das células do formato joga papel fora, e a
// conta é fixa: `sobra = células − (total mod células)`. Imprimir 29 credenciais
// num formato de 4 células gasta 8 folhas e deixa 3 células vazias — três
// quartos de uma folha de PVC.
//
// Até 18/08/2026 nada na tela dizia isso, e não havia como perguntar "tem outro
// modelo que caiba aqui?". O selo responde a primeira parte; a busca, a segunda.
//
// Desenho em docs/superpowers/specs/2026-08-18-aproveitamento-de-folha-entre-pedidos-design.md
// ─────────────────────────────────────────────────────────────────────────────

/**
 * O padrão da gráfica: a partir de que fração de uma folha a sobra merece
 * aviso. Meia folha, ajustável no ADM.
 *
 * É fração e não número de células de propósito: num formato de 4 células
 * sobrar 3 é grave, num de 20 sobrar 3 é ruído.
 */
function limiarPadraoDeSobra() {

    const v = parseFloat(state.limiarSobra);

    return (isFinite(v) && v > 0 && v <= 1) ? v : 0.5;

}
window.limiarPadraoDeSobra = limiarPadraoDeSobra;



/**
 * O limiar deste produto, ou o padrão quando ele não tem o seu.
 *
 * É por produto desde 18/08/2026, a pedido do usuário: o desperdício não custa
 * o mesmo em toda parte — meia folha de PVC de credencial é um prejuízo que meia
 * folha de papel de pulseira não é.
 */
function limiarDoProduto(idProduto) {

    const tabela = state.limiaresPorProduto || {};

    const v = parseFloat(tabela[String(idProduto)]);

    return (isFinite(v) && v > 0 && v <= 1) ? v : limiarPadraoDeSobra();

}
window.limiarDoProduto = limiarDoProduto;



/** O limiar que vale para esta imposição — o do produto do modelo aberto. */
function limiarDeSobra(item) {

    return limiarDoProduto(item && (item._vibe_id_produto || item.id_produto));

}
window.limiarDeSobra = limiarDeSobra;



/**
 * Quanto papel esta imposição vai deixar vazio, ou null quando ainda não dá
 * para saber (sem modelo, sem formato ou sem quantidade).
 *
 * A conta é a sobra do RESTO — `células − (total mod células)` —, e não
 * `folhas × células − total`. As duas dão o mesmo número no sequencial, mas no
 * blocado a montagem gasta folhas a mais de propósito, e essas não são
 * desperdício: são a pilha de tamanho fixo que o operador pediu. O que combinar
 * modelos consegue eliminar é só a sobra do resto, e é ela que se mede.
 */
function sobraDaImposicao() {

    const varias = (state.selectedOSItems || []).length > 1;

    const itens = itensDaImposicao(varias).filter(Boolean);

    let poses = 0;

    let total = 0;

    if (varias) {

        // Vários modelos: a conta é a soma das fatias, a mesma da barra de
        // modelos combinados. O Sumário só sabe do modelo aberto.
        if (!itens.length) return null;

        const fmt = (state.formatos || []).find(f => String(f.id) === String(itens[0].formato_id));

        poses = fmt ? (parseInt(fmt.cols) || 0) * (parseInt(fmt.rows) || 0) : 0;

        itens.forEach(it => { total += quantidadeDoModelo(it) || 0; });

    } else {

        // Um modelo: valem os números que o SUMÁRIO acabou de mostrar. Uma
        // segunda conta própria divergiria dele — e a que o operador lê é a
        // dele. Ver registrarContaDaTela().
        const conta = state.contaDaTela;

        if (!conta) return null;

        poses = parseInt(conta.poses) || 0;

        total = parseInt(conta.total) || 0;

        if (conta.item) itens[0] = conta.item;

    }

    if (!poses) return null;

    if (total <= 0) return null;

    const vazias = (poses - (total % poses)) % poses;

    return {
        modelos: itens.length,
        itens: total,
        poses,
        folhas: Math.ceil(total / poses),
        vazias,
        fracao: vazias / poses,
        // O limiar viaja junto com a conta: ele e' do PRODUTO, e quem tem o
        // produto na mao e' esta funcao. Sem isto, cada chamador teria de achar
        // o item de novo — e um deles esqueceria.
        limiar: limiarDeSobra(itens[0])
    };

}
window.sobraDaImposicao = sobraDaImposicao;



/**
 * O que o Sumário acabou de calcular, publicado para a sobra medir em cima.
 *
 * Existe porque as duas contas precisam ser a mesma. O Sumário tira o total do
 * banco de dados, da faixa De/Até ou das páginas do PDF, e as células do formato
 * ESCOLHIDO NA TELA; medir a sobra por outro caminho — pelo `formato_id` do
 * modelo, por exemplo — dava número diferente, e pior: dava nenhum, porque
 * `formato_id` só existe em memória e nem sempre está preenchido. O selo ficava
 * invisível enquanto o Sumário mostrava tudo, ao lado.
 *
 * `null` quando o Sumário não tem o que mostrar, e aí o selo some junto.
 */
function registrarContaDaTela(total, poses, item) {

    const t = parseInt(total) || 0;

    const p = parseInt(poses) || 0;

    state.contaDaTela = (t > 0 && p > 0) ? { total: t, poses: p, item: item || null } : null;

    atualizarSeloDeSobra();

}
window.registrarContaDaTela = registrarContaDaTela;



/** A sobra passa do limiar deste produto? */
function sobraMereceAviso(s) {

    return !!(s && s.vazias > 0 && s.fracao >= (s.limiar || limiarPadraoDeSobra()));

}
window.sobraMereceAviso = sobraMereceAviso;



/** A frase do selo. Diz a sobra em células E em fração de folha. */
function textoDaSobra(s) {

    if (!s) return '';

    const folhas = `${s.folhas.toLocaleString('pt-BR')} folha(s) · ${s.itens.toLocaleString('pt-BR')} itens`;

    if (!s.vazias) return `📄 ${folhas} · a folha fecha certo, sem sobra`;

    return `📄 ${folhas} · sobram ${s.vazias} célula(s) `
         + `(${Math.round(s.fracao * 100)}% de uma folha)`;

}
window.textoDaSobra = textoDaSobra;



/**
 * Pinta a sobra nas duas abas, em dois lugares e de propósito:
 *
 * - **no Sumário**, ao lado de "Folhas Estimadas", que é onde o operador já lê
 *   os números da imposição. É ali que ele procura, e um número que só existe
 *   noutro canto é um número que ninguém vê;
 * - **no selo acima dos botões**, que é onde mora a ação "Ver aproveitamento" —
 *   e essa só aparece quando a sobra passa do limiar do produto.
 */
function atualizarSeloDeSobra() {

    const s = sobraDaImposicao();

    const texto = textoDaSobra(s);

    const oferecer = sobraMereceAviso(s);

    const noSumario = !s ? '—'
        : (s.vazias
            ? `${s.vazias} (${Math.round(s.fracao * 100)}% de uma folha)`
            : 'nenhuma — a folha fecha certo');

    // A aba Imposicao usa `sum-*` sem prefixo; a aba Pedido usa `ped-sum-*`.
    ['sum-vazias', 'ped-sum-vazias'].forEach(id => {

        const el = document.getElementById(id);

        if (el) el.textContent = noSumario;

    });

    [['imp-sobra-selo', 'imp-sobra-texto', 'imp-sobra-btn'],
     ['ped-sobra-selo', 'ped-sobra-texto', 'ped-sobra-btn']].forEach(ids => {

        const selo = document.getElementById(ids[0]);

        if (!selo) return;

        selo.style.display = s ? 'flex' : 'none';

        if (!s) return;

        // A cor diz o estado antes de o operador ler a frase. O amarelo é
        // reservado à sobra: se "a folha fecha certo" também fosse amarelo, o
        // amarelo deixaria de significar atenção. Acima do limiar do produto
        // ele ainda ganha brilho (.merece-aviso), que é quando o botão aparece.
        selo.classList.toggle('tem-sobra',    s.vazias > 0);
        selo.classList.toggle('fecha-certo',  s.vazias === 0);
        selo.classList.toggle('merece-aviso', oferecer);

        const elTexto = document.getElementById(ids[1]);

        if (elTexto) elTexto.textContent = texto;

        const btn = document.getElementById(ids[2]);

        if (btn) btn.style.display = oferecer ? 'inline-flex' : 'none';

    });

}
window.atualizarSeloDeSobra = atualizarSeloDeSobra;



/**
 * O modelo pode entrar numa folha de aproveitamento?
 *
 * Arte aprovada e ainda não impresso. Decisão do usuário em 18/08/2026: o
 * aproveitamento não pode virar fila furada — nada que a produção ainda não
 * liberou é antecipado só porque caberia na folha.
 */
function modeloLiberadoParaImprimir(item) {

    if (!item) return false;

    // Arte devolvida ao designer nao entra na folha de aproveitamento
    // (02/09/2026). Pelo mesmo motivo do "ja impresso" logo abaixo: o
    // aproveitamento nao pode antecipar o que a producao parou. Sem esta
    // linha, a busca de companhia sugeriria justamente o modelo cuja arte
    // esta errada -- e a trava do imprimir so apareceria no fim, com a folha
    // ja montada. Ver `STATUS_CORRIGIR_ARTE`.
    if (modeloEmCorrecaoDeArte(item)) return false;

    const impressao = String(item.status_impressao || item.impressao || '').toUpperCase();

    if (impressao.indexOf('IMPRESSO') >= 0) return false;

    const arte = String(item.amostra_status || item.status_arte || '').toUpperCase();

    return arte.indexOf('APROVAD') >= 0;

}
window.modeloLiberadoParaImprimir = modeloLiberadoParaImprimir;



/** Os modelos que já estão na folha desta imposição. */
function itensJaNaFolha() {

    return itensDaImposicao((state.selectedOSItems || []).length > 1).filter(Boolean);

}



/** O pedido a que a imposição de agora pertence. */
function osDaImposicao() {

    if (state.selectedOSItems && state.selectedOSItems.length) return state.selectedOSItems[0].osId;

    return (state.activeOSItem || {}).osId || null;

}



/**
 * Os modelos do PEDIDO ABERTO que poderiam entrar nesta folha. Passa pelo mesmo
 * `porQueNaoCombina` da seleção manual — a busca não pode sugerir o que a tela
 * recusaria.
 */
function candidatosDoPedido() {

    const naFolha = itensJaNaFolha();

    if (!naFolha.length) return [];

    const osId = osDaImposicao();

    const jaTem = new Set(naFolha.map(i => String(i.id)));

    return (state.osItens[osId] || [])

        .filter(it => !jaTem.has(String(it.id)))

        .filter(modeloLiberadoParaImprimir)

        .filter(it => !porQueNaoCombina(naFolha[0], it))

        .map(it => ({ item: it, osId, qtd: quantidadeDoModelo(it) || 0 }))

        .filter(c => c.qtd > 0);

}
window.candidatosDoPedido = candidatosDoPedido;



/**
 * O subconjunto de candidatos que melhor fecha a folha, ou null quando nenhum
 * melhora.
 *
 * Não é busca gulosa: é a conta exata. Só o RESTO de cada quantidade importa
 * (`qtd mod células`), então o problema tem no máximo `células` estados — 40 no
 * pior formato deste catálogo. A varredura passa por cada candidato uma vez,
 * guardando, para cada resto alcançável, a menor quantidade de modelos que
 * chega nele. Cada modelo entra no máximo uma vez, e por isso a varredura lê uma
 * cópia do estado anterior.
 *
 * O critério final é a sobra que restaria, e o desempate é o menor número de
 * modelos extras: fechar a folha com um modelo é melhor que fechar com três.
 */
function melhorComposicao(sobra, candidatos) {

    if (!sobra || !sobra.vazias || !candidatos || !candidatos.length) return null;

    const poses = sobra.poses;

    const alcance = new Array(poses).fill(null);

    alcance[0] = { modelos: 0, escolhidos: [] };

    candidatos.forEach((c, idx) => {

        const passo = ((c.qtd % poses) + poses) % poses;

        const antes = alcance.slice();

        for (let r = 0; r < poses; r++) {

            if (!antes[r]) continue;

            const destino = (r + passo) % poses;

            const novo = { modelos: antes[r].modelos + 1, escolhidos: antes[r].escolhidos.concat([idx]) };

            if (!alcance[destino] || novo.modelos < alcance[destino].modelos) {

                alcance[destino] = novo;

            }

        }

    });

    let melhor = null;

    for (let r = 0; r < poses; r++) {

        const passo = alcance[r];

        if (!passo || !passo.modelos) continue;          // "não fazer nada" não é sugestão

        const restante = (poses - ((sobra.itens + r) % poses)) % poses;

        if (restante >= sobra.vazias) continue;          // não melhora, ou piora

        if (!melhor || restante < melhor.restante
            || (restante === melhor.restante && passo.modelos < melhor.modelos)) {

            melhor = { restante, modelos: passo.modelos, escolhidos: passo.escolhidos };

        }

    }

    if (!melhor) return null;

    const escolhidos = melhor.escolhidos.map(i => candidatos[i]);

    const somaExtra = escolhidos.reduce((t, c) => t + c.qtd, 0);

    return {
        candidatos: escolhidos,
        itens: sobra.itens + somaExtra,
        folhas: Math.ceil((sobra.itens + somaExtra) / poses),
        vazias: melhor.restante
    };

}
window.melhorComposicao = melhorComposicao;



/**
 * Traz o limiar da sobra e a lista de produtos liberados a combinar entre
 * pedidos. Falhar aqui não impede imprimir: o selo cai no limiar padrão e a
 * busca entre pedidos simplesmente não acha ninguém.
 */
async function carregarConfigDeAproveitamento() {

    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;

    const [cfg, prods] = await Promise.all([

        supabaseClient.from('producao_config').select('chave, valor').eq('chave', 'limiar_sobra'),

        supabaseClient.from('producao_produtos_combinaveis').select('id_produto, liberado, limiar_sobra')

    ]);

    const linha = cfg && cfg.data && cfg.data.length ? cfg.data[0] : null;

    if (linha && linha.valor !== undefined && linha.valor !== null) {

        const v = parseFloat(linha.valor);

        if (isFinite(v) && v > 0 && v <= 1) state.limiarSobra = v;

    }

    const liberados = new Set();

    const limiares = {};

    ((prods && prods.data) || []).forEach(p => {

        if (p.liberado) liberados.add(String(p.id_produto));

        if (p.limiar_sobra !== undefined && p.limiar_sobra !== null) {

            limiares[String(p.id_produto)] = parseFloat(p.limiar_sobra);

        }

    });

    state.produtosCombinaveis = liberados;

    state.limiaresPorProduto = limiares;

    atualizarSeloDeSobra();

}
window.carregarConfigDeAproveitamento = carregarConfigDeAproveitamento;



/**
 * O nome do produto, do jeito que a gráfica o chama: "Pulseira Triband",
 * "Ingresso MOBI", "Credencial PVC".
 *
 * O campo é `nomeReal` — assim mesmo, com o R maiúsculo, que é como a coluna
 * existe na tabela do parceiro. É o MESMO que o cabeçalho de cada produto usa
 * na Lista de Arte e no Painel de Produção; qualquer outro nome obrigaria o
 * operador a traduzir de cabeça entre duas telas do mesmo sistema.
 */
function nomeDoProdutoGlobal(p) {

    return (p && p.nomeReal) || `Produto #${p && p.id_produto}`;

}



/**
 * Os produtos que a produção enxerga — os que têm setor no PCP.
 *
 * O catálogo do parceiro tem 64 produtos, e só 15 chegam à produção; os outros
 * são itens de estoque e de nota fiscal. Uma lista com os 64 não é a lista que o
 * operador conhece, e ele não teria como dizer qual das duas está errada.
 *
 * É o mesmo recorte das telas de pedido: elas agrupam por `_vibe_id_produto` e
 * mostram `nomeReal` com o selo do `setor_pcp`.
 */
function produtosDaProducao() {

    return (state.produtosGlobais || [])

        .filter(p => p && p.id_produto !== undefined && p.id_produto !== null)

        .filter(p => String(p.setor_pcp || '').trim() !== '')

        .slice()

        .sort((a, b) => nomeDoProdutoGlobal(a).localeCompare(nomeDoProdutoGlobal(b), 'pt-BR'));

}
window.produtosDaProducao = produtosDaProducao;



/** Desenha a aba ADM → Aproveitamento. */
async function renderAdmAproveitamento() {

    try { await carregarConfigDeAproveitamento(); } catch (e) { console.warn('[ADM] aproveitamento', e); }

    const padrao = limiarPadraoDeSobra();

    const inp = document.getElementById('adm-limiar-sobra');

    if (inp) inp.value = Math.round(padrao * 100);

    const ex = document.getElementById('adm-limiar-exemplo');

    if (ex) {

        ex.textContent = `Com ${Math.round(padrao * 100)}%: num formato de 4 celulas o aviso `
            + `aparece a partir de ${Math.ceil(padrao * 4)} celula(s) vazia(s); num de 20, `
            + `a partir de ${Math.ceil(padrao * 20)}.`;

    }

    const lista = document.getElementById('adm-aproveitamento-lista');

    if (!lista) return;

    const produtos = produtosDaProducao();

    if (!produtos.length) {

        lista.innerHTML = '<div style="color:var(--text-dim);">Nenhum produto de producao no catalogo. '
            + 'Abra a Lista de Arte ou o Painel de Producao uma vez para o catalogo carregar, '
            + 'e volte aqui.</div>';

        return;

    }

    lista.innerHTML = produtos.map(p => {

        const id = String(p.id_produto);

        const marcado = state.produtosCombinaveis.has(id) ? 'checked' : '';

        // Produto desativado no ERP continua na lista, e marcado como tal: um
        // pedido antigo em producao ainda pode te-lo, e some-lo em silencio
        // faria a lista parecer completa quando nao esta.
        const inativo = (p.ativo === false)
            ? ' <span style="color:var(--amber,#f59e0b); font-size:0.78rem;">(desativado)</span>'
            : '';

        // O limiar proprio deste produto. Campo vazio = usa o padrao geral, e o
        // placeholder mostra qual e — em vez de deixar o operador adivinhar se
        // vazio significa "sem aviso" ou "o de cima".
        const proprio = (state.limiaresPorProduto || {})[id];

        const valor = (proprio !== undefined && proprio !== null && isFinite(parseFloat(proprio)))
            ? Math.round(parseFloat(proprio) * 100)
            : '';

        return `<div style="display:flex; align-items:center; gap:10px; padding:7px 10px; border:1px solid var(--border); border-radius:6px;">`
             + `<label style="display:flex; align-items:center; gap:10px; cursor:pointer; flex:1;">`
             + `<input type="checkbox" ${marcado} onchange="salvarProdutoCombinavel('${escHtmlSimples(id)}', this.checked)">`
             + `<span>${escHtmlSimples(nomeDoProdutoGlobal(p))}${inativo}</span>`
             + `</label>`
             + `<span style="color:var(--text-dim); font-size:0.8rem;">avisar a partir de</span>`
             + `<input type="number" class="form-control" style="width:78px; padding:3px 6px; font-size:0.82rem; text-align:center;"`
             + ` min="1" max="100" step="1" value="${valor}" placeholder="${Math.round(padrao * 100)}"`
             + ` title="Vazio usa o padrao geral (${Math.round(padrao * 100)}%)"`
             + ` onchange="salvarLimiarDoProduto('${escHtmlSimples(id)}', this.value)">`
             + `<span style="color:var(--text-dim); font-size:0.8rem;">%</span>`
             + `<span class="badge bg-secondary" style="width:64px; text-align:center; font-size:0.72rem; color:#fff;">${escHtmlSimples(String(p.setor_pcp || ''))}</span>`
             + `</div>`;

    }).join('');

}
window.renderAdmAproveitamento = renderAdmAproveitamento;



/**
 * Grava a linha de um produto preservando o que a outra metade da tela ja tinha.
 *
 * As duas configuracoes moram na mesma linha, e cada uma tem o seu controle. Um
 * upsert que mandasse so o campo mexido apagaria o outro — marcar a caixa
 * limparia o limiar, e digitar o limiar desmarcaria a caixa.
 */
async function gravarProdutoCombinavel(idProduto, mudanca) {

    const id = String(idProduto);

    const p = (state.produtosGlobais || []).find(x => String(x.id_produto) === id);

    const atual = {
        liberado: state.produtosCombinaveis.has(id),
        limiar_sobra: (state.limiaresPorProduto || {})[id]
    };

    const linha = Object.assign({
        id_produto: id,
        nome: p ? nomeDoProdutoGlobal(p) : null,
        liberado: atual.liberado,
        limiar_sobra: (atual.limiar_sobra === undefined) ? null : atual.limiar_sobra,
        atualizado_em: new Date().toISOString()
    }, mudanca);

    const { error } = await supabaseClient

        .from('producao_produtos_combinaveis')

        .upsert(linha, { onConflict: 'id_produto' });

    if (error) throw error;

    return linha;

}



/** Liga ou desliga um produto para dividir folha entre pedidos. */
window.salvarProdutoCombinavel = async function(idProduto, liberado) {

    try {

        await gravarProdutoCombinavel(idProduto, { liberado: !!liberado });

        if (liberado) state.produtosCombinaveis.add(String(idProduto));

        else state.produtosCombinaveis.delete(String(idProduto));

        toast(liberado ? 'Produto liberado a dividir folha entre pedidos.'
                       : 'Produto voltou a aproveitar so dentro do proprio pedido.', 'success');

    } catch (e) {

        console.error('[ADM] salvarProdutoCombinavel', e);

        toast('Nao consegui salvar. Recarregue a pagina e tente de novo.', 'error');

        renderAdmAproveitamento();

    }

};



/**
 * Grava o limiar deste produto, em porcentagem de uma folha. Campo vazio volta
 * ao padrão geral — e é assim que se desfaz uma exceção.
 */
window.salvarLimiarDoProduto = async function(idProduto, pct) {

    const texto = String(pct === null || pct === undefined ? '' : pct).trim();

    const v = texto === '' ? null : parseFloat(texto) / 100;

    if (v !== null && (!isFinite(v) || v <= 0 || v > 1)) {

        toast('O limiar precisa ficar entre 1% e 100% de uma folha. '
            + 'Deixe vazio para usar o padrao geral.', 'error');

        return renderAdmAproveitamento();

    }

    try {

        await gravarProdutoCombinavel(idProduto, { limiar_sobra: v });

        if (!state.limiaresPorProduto) state.limiaresPorProduto = {};

        if (v === null) delete state.limiaresPorProduto[String(idProduto)];

        else state.limiaresPorProduto[String(idProduto)] = v;

        atualizarSeloDeSobra();

        renderAdmAproveitamento();

        toast(v === null ? 'Produto voltou a usar o padrao geral.'
                         : `Aviso deste produto a partir de ${Math.round(v * 100)}% de uma folha.`, 'success');

    } catch (e) {

        console.error('[ADM] salvarLimiarDoProduto', e);

        toast('Nao consegui salvar o limiar deste produto.', 'error');

        renderAdmAproveitamento();

    }

};



/** Grava o limiar da sobra, em porcentagem de uma folha. */
window.salvarLimiarDeSobra = async function(pct) {

    const v = parseFloat(pct) / 100;

    if (!isFinite(v) || v <= 0 || v > 1) {

        toast('O limiar precisa ficar entre 1% e 100% de uma folha.', 'error');

        return renderAdmAproveitamento();

    }

    try {

        const { error } = await supabaseClient.from('producao_config').upsert({
            chave: 'limiar_sobra',
            valor: v,
            atualizado_em: new Date().toISOString()
        }, { onConflict: 'chave' });

        if (error) throw error;

        state.limiarSobra = v;

        atualizarSeloDeSobra();

        renderAdmAproveitamento();

        toast('Limiar salvo.', 'success');

    } catch (e) {

        console.error('[ADM] salvarLimiarDeSobra', e);

        toast('Nao consegui salvar o limiar.', 'error');

    }

};



/**
 * Grava que esta folha juntou modelos de pedidos diferentes.
 *
 * Só grava quando cruza pedido: folha de um pedido só não levanta pergunta
 * nenhuma. E grava na CONFIRMAÇÃO da impressão, não na geração do PDF — PDF
 * gerado é conferência, e conferência não muda o status de pedido nenhum.
 *
 * É este registro que responde, semanas depois, "por que o 20508 foi impresso
 * antes da hora". Falhar aqui não desfaz a impressão: o material já saiu, e
 * derrubar a tela por causa do registro seria pior que o registro faltando.
 */
async function registrarCombinacao(alvos) {

    const lista = (alvos || []).filter(a => a && a.itemId);

    if (new Set(lista.map(a => String(a.osId))).size < 2) return;

    try {

        const linhas = lista.map(a => {

            const it = (state.osItens[a.osId] || []).find(i => String(i.id) === String(a.itemId));

            const os = (state.ordens || []).find(o => String(o.id) === String(a.osId));

            return {
                pedido: os ? String(os.numero) : null,
                os_id: String(a.osId),
                modelo: it ? String(it.modelo || '') : String(a.itemId),
                nome: it ? rotuloDoModelo(it, 0) : null,
                qtd: it ? (quantidadeDoModelo(it) || 0) : 0
            };

        });

        const itens = lista

            .map(a => (state.osItens[a.osId] || []).find(i => String(i.id) === String(a.itemId)))

            .filter(Boolean);

        const fmt = itens.length

            ? (state.formatos || []).find(f => String(f.id) === String(itens[0].formato_id))

            : null;

        const poses = fmt ? (parseInt(fmt.cols) || 0) * (parseInt(fmt.rows) || 0) : 0;

        const total = linhas.reduce((t, l) => t + (l.qtd || 0), 0);

        const { error } = await supabaseClient.from('producao_combinacoes').insert({
            criado_por: (window._currentUser && (window._currentUser.email || window._currentUser.id)) || null,
            formato: fmt ? fmt.name : null,
            poses: poses || null,
            itens: total,
            folhas: poses ? Math.ceil(total / poses) : null,
            celulas_vazias: poses ? ((poses - (total % poses)) % poses) : null,
            modelos: linhas
        });

        if (error) throw error;

    } catch (e) {

        console.warn('[aproveitamento] nao consegui registrar a combinacao:', e);

    }

}
window.registrarCombinacao = registrarCombinacao;



/** Este modelo pertence a um produto liberado para dividir folha entre pedidos? */
function produtoLiberadoParaCombinar(item) {

    const liberados = state.produtosCombinaveis;

    if (!liberados || !liberados.size) return false;

    const id = item && (item._vibe_id_produto || item.id_produto);

    return id !== undefined && id !== null && liberados.has(String(id));

}
window.produtoLiberadoParaCombinar = produtoLiberadoParaCombinar;



/**
 * Os modelos de OUTROS pedidos da fila que poderiam entrar nesta folha.
 *
 * Carrega os pedidos que ainda não estão em memória com o mesmo `loadOSItens`
 * que a tela usa — e não com uma consulta própria. O motivo é concreto:
 * `formato_id` e `saida_id` NÃO existem em `pedidos_modelos`, são resolvidos em
 * memória a partir do texto do ERP, e uma consulta crua traria modelos sem
 * formato, que o `porQueNaoCombina` recusaria todos. Reaproveitar o carregador
 * também evita mais uma cópia da regra de mapeamento para envelhecer sozinha.
 *
 * Só roda quando o operador pede: é a única razão de o custo ser aceitável.
 */
async function candidatosDeOutrosPedidos() {

    const naFolha = itensJaNaFolha();

    if (!naFolha.length) return [];

    if (!produtoLiberadoParaCombinar(naFolha[0])) return [];

    const osAtual = String(osDaImposicao());

    // Um teto para o clique não virar espera: a fila da gráfica raramente passa
    // disso, e o que ficar de fora é dito ao operador em vez de sumir calado.
    const TETO = 25;

    const alvos = (state.ordens || [])

        .filter(o => String(o.id) !== osAtual)

        .slice(0, TETO);

    for (const os of alvos) {

        if (!state.osItens[os.id] || !state.osItens[os.id].length) {

            try { await loadOSItens(os.id); } catch (e) { console.warn('[aproveitamento] pedido nao carregou', os.id, e); }

        }

    }

    const fora = [];

    alvos.forEach(os => {

        (state.osItens[os.id] || []).forEach(it => {

            if (!modeloLiberadoParaImprimir(it)) return;

            if (!produtoLiberadoParaCombinar(it)) return;

            if (porQueNaoCombina(naFolha[0], it)) return;

            const qtd = quantidadeDoModelo(it) || 0;

            if (qtd > 0) fora.push({ item: it, osId: os.id, qtd });

        });

    });

    return fora;

}
window.candidatosDeOutrosPedidos = candidatosDeOutrosPedidos;



/** A linha que descreve um candidato no popup. */
function linhaDaComposicao(item, osId, qtd, marca) {

    const os = (state.ordens || []).find(o => String(o.id) === String(osId));

    const pedido = os ? os.numero : '—';

    return `<div style="font-family:monospace; font-size:0.86rem;">`
         + `${escHtmlSimples(String(item.modelo || '—'))} · `
         + `${escHtmlSimples(rotuloDoModelo(item, 0))} · `
         + `pedido ${escHtmlSimples(String(pedido))} · ${qtd}`
         + (marca ? ` <span style="color:#94a3b8;">${marca}</span>` : '')
         + `</div>`;

}



/**
 * Aplica a composição sugerida: a seleção passa a ser exatamente ela.
 *
 * Quando entra modelo de outro pedido, liga `state.combinacaoEntrePedidos` — o
 * sinalizador que diz à trava `problemaNaSelecao()` que este cruzamento foi
 * DECIDIDO, e não sobrou de um pedido anterior. Foi o cruzamento por acidente
 * que fez o 1000277 imprimir sozinho em 18/08/2026; a diferença é esta.
 */
function aplicarComposicao(comp) {

    const osAtual = osDaImposicao();

    const sel = itensJaNaFolha().map(it => ({ itemId: it.id, osId: it.os_id || osAtual }));

    comp.candidatos.forEach(c => sel.push({ itemId: c.item.id, osId: c.osId }));

    state.selectedOSItems = sel;

    state.combinacaoEntrePedidos = sel.some(s => String(s.osId) !== String(osAtual));

    if (typeof renderImpOSQueue === 'function') renderImpOSQueue();

    if (typeof renderPedOSQueue === 'function') renderPedOSQueue();

    atualizarBarraDeSoma();

    if (typeof drawPedPreview === 'function') drawPedPreview();

}
window.aplicarComposicao = aplicarComposicao;



/**
 * O botão "Ver aproveitamento". Procura primeiro dentro do pedido; só depois,
 * e só para produtos liberados no ADM, entre os pedidos da fila.
 */
window.verAproveitamento = async function() {

    const sobra = sobraDaImposicao();

    if (!sobra) return toast('Escolha o modelo e o formato para calcular o aproveitamento.', 'info');

    if (!sobra.vazias) return toast('A folha já fecha certo — não há sobra para aproveitar.', 'info');

    const overlay = document.getElementById('loading-overlay');

    const sub = document.getElementById('loading-sub');

    let comp = melhorComposicao(sobra, candidatosDoPedido());

    if (!comp) {

        if (overlay) overlay.classList.add('active');

        if (sub) sub.textContent = 'Procurando aproveitamento nos outros pedidos...';

        try {

            const fora = await candidatosDeOutrosPedidos();

            comp = melhorComposicao(sobra, candidatosDoPedido().concat(fora));

        } finally {

            if (overlay) overlay.classList.remove('active');

        }

    }

    if (!comp) {

        return toast(
            `Não achei modelo nenhum que aproveite as ${sobra.vazias} célula(s) que sobram. `
            + 'Candidato precisa ter arte aprovada, estar aguardando impressão e dividir a mesma '
            + 'cor, formato, saída, face e modo de impressão. Para buscar em outros pedidos, o '
            + 'produto precisa estar liberado em ADM → Aproveitamento.', 'info');

    }

    const osAtual = String(osDaImposicao());

    const cruzaPedido = comp.candidatos.some(c => String(c.osId) !== osAtual);

    const linhas = itensJaNaFolha().map(it => linhaDaComposicao(it, it.os_id || osAtual, quantidadeDoModelo(it), '(este)'))

        .concat(comp.candidatos.map(c => linhaDaComposicao(c.item, c.osId, c.qtd, '')))

        .join('');

    const resumo = `<div style="font-family:monospace; font-size:0.9rem; line-height:1.6;">`
        + `Hoje:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ${sobra.itens} itens → ${sobra.folhas} folhas, `
        + `sobram ${sobra.vazias} células<br>`
        + `Combinado: ${comp.itens} itens → ${comp.folhas} folhas, `
        + (comp.vazias ? `sobram ${comp.vazias} células` : 'sem sobra')
        + `</div>`;

    const aviso = cruzaPedido
        ? 'Os pedidos acima serão marcados como impressos quando você confirmar a impressão, '
          + 'e fica registrado que saíram juntos.'
        : 'Os modelos acima serão marcados como impressos quando você confirmar a impressão.';

    const usar = await confirmarPopup({
        titulo: '🧩 Aproveitamento encontrado',
        mensagem: resumo + '<div style="margin-top:14px;">' + linhas + '</div>',
        detalhe: aviso,
        textoOk: 'Usar esta composição',
        textoCancelar: 'Imprimir só o que está'
    });

    if (!usar) return;

    aplicarComposicao(comp);

    toast(`Composição aplicada: ${comp.candidatos.length + sobra.modelos} modelos, `
        + (comp.vazias ? `${comp.vazias} célula(s) de sobra.` : 'sem sobra.'), 'success');

};



/**
 * Por que dois modelos não podem sair na mesma folha, ou null quando podem.
 * Cor já era conferida; formato, saída, face e modo PDF não eram — e cada um
 * deles produz uma folha impossível, não só diferente.
 *
 * O modo de impressão entrou em 18/08/2026: uma folha não pode ser sequencial
 * para um modelo e blocada para o outro, porque a ordem das células da folha é
 * uma só. Modelo sem escolha salva não empata a conta — o modo efetivo dele vem
 * do `blocos` do ERP ou do Formato, e é esse que se compara.
 */
function porQueNaoCombina(a, b) {

    const cor = x => String(x.cor || x.padrao || '').toLowerCase().trim();

    const face = x => (x.verso_tipo && x.verso_tipo !== 'Frente' && x.verso_tipo !== 'SÓ FRENTE') ? 'verso' : 'frente';

    if (cor(a) !== cor(b)) return 'a cor do material é outra';

    if (String(a.formato_id || '') !== String(b.formato_id || '')) return 'o formato é outro';

    if (String(a.saida_id || '') !== String(b.saida_id || '')) return 'a saída é outra';

    if (face(a) !== face(b)) return 'um imprime frente e verso e o outro só frente';

    if (!!a.modo_pdf !== !!b.modo_pdf) return 'um está em modo Pdf Paginado e o outro não';

    // A folha combinada tem UM Modo de Impressão só, e o `face()` acima não
    // separa os dois modos de verso: um FxVerso e um FxVersoUnico juntos
    // passariam por aqui e a folha consumiria o arquivo de um deles do jeito
    // errado — em silêncio, porque nada quebra na tela (31/08/2026).
    if (versoUnico(modoDeVersoDoModelo(a)) !== versoUnico(modoDeVersoDoModelo(b))) {

        return 'um é FxVersoUnico e o outro FxVerso — o verso deles sai de lugares diferentes do arquivo';

    }

    if (modoDeImpressaoDoModelo(a) !== modoDeImpressaoDoModelo(b)) {

        return 'um imprime Sequencial e o outro Blocado — mude o modo de um deles em "Opções do modelo"';

    }

    return null;

}
window.porQueNaoCombina = porQueNaoCombina;



/**
 * A selecao multipla vale para UM pedido so. Devolve o recado quando ela esta
 * inconsistente, ou null quando da para impor.
 *
 * Existe por causa do relato de 18/08/2026: marcar 1000277 e 1000278 imprimia
 * so o 1000277. Os dois eram de pedidos DIFERENTES -- Tchequia do 20495 e VIP
 * do 20508 --, e a selecao do pedido anterior tinha sobrevivido a troca.
 *
 * O que torna isso pior do que um erro comum: a fila so desenha o pedido
 * aberto, entao um modelo marcado em outro pedido e INVISIVEL. O operador nao
 * ve e nao consegue desmarcar. E, mais abaixo, `state.osItens[s.osId]` nao tem
 * aquele item, o `sItem` vira undefined, e a arte entra no trabalho com
 * `qtd: 0` -- some da folha sem uma linha de aviso.
 */
function problemaNaSelecao() {

    const sel = state.selectedOSItems || [];

    if (sel.length < 2) return null;

    const pedidos = Array.from(new Set(sel.map(s => String(s.osId))));

    // Cruzar pedidos e permitido quando foi DECIDIDO: o operador viu a
    // composicao listada no popup de aproveitamento e aceitou, e os itens do
    // outro pedido foram carregados na memoria por causa disso. O que continua
    // recusado e o cruzamento por ACIDENTE — a selecao que sobrou do pedido
    // anterior, invisivel na fila, que fez o 1000277 imprimir sozinho.
    if (pedidos.length > 1 && !state.combinacaoEntrePedidos) {

        return 'A selecao tem modelos de mais de um pedido, e a fila so mostra o pedido aberto — '

            + 'os de fora dele nao aparecem na tela e sairiam com zero itens. '

            + 'Desmarque tudo e escolha de novo, so dentro deste pedido. '

            + 'Para juntar pedidos de proposito, use "Ver aproveitamento".';

    }

    const perdidos = sel.filter(s => !(state.osItens[s.osId] || [])

        .find(i => String(i.id) === String(s.itemId)));

    if (perdidos.length) {

        return `${perdidos.length} modelo(s) marcado(s) nao estao mais carregados e sairiam com `

            + 'zero itens, em silencio. Desmarque tudo, reabra o pedido e escolha de novo.';

    }

    return null;

}
window.problemaNaSelecao = problemaNaSelecao;



/**
 * Tira da selecao os modelos de outros pedidos e diz quantos foram. Chamado ao
 * abrir um pedido e ao marcar um modelo: a selecao e do pedido que esta na
 * tela, e o que nao esta na tela nao pode decidir o que sai no papel.
 */
function limparSelecaoDeOutroPedido(osId) {

    const sel = state.selectedOSItems || [];

    const forasteiros = sel.filter(s => String(s.osId) !== String(osId));

    if (!forasteiros.length) return 0;

    state.selectedOSItems = sel.filter(s => String(s.osId) === String(osId));

    // Uma composicao aceita no aproveitamento morre aqui, junto com os modelos
    // que ela trouxe. E deliberado: o operador acabou de mexer na fila de um
    // pedido so, e manter viva uma combinacao invisivel e exatamente o defeito
    // que a trava existe para impedir. Quem chama diz quantos sairam.
    state.combinacaoEntrePedidos = false;

    return forasteiros.length;

}
window.limparSelecaoDeOutroPedido = limparSelecaoDeOutroPedido;



/** Redesenha todos os cards de um pedido (usado depois de distribuir). */
function redesenharCardsDoPedido(osId) {

    (state.osItens[osId] || []).forEach((_, i) => renderItemAmostraCombinada(i, osId));

}



/**
 * O banco de dados a partir do card do modelo. Dois trabalhos, duas telas — a
 * mesma separação que o editor de CSV já fazia:
 *
 *   'editar'      — corrigir o dado: célula, coluna, quais linhas imprimem.
 *                   Grava na numeração, que é onde o banco vive.
 *   'distribuir'  — repartir as linhas entre os modelos do pedido. Grava em
 *                   `pedidos_modelos.csv_selecao`, que é por modelo.
 */
/**
 * A DISTRIBUICAO das linhas deste modelo. Uma coisa so, desde 26/08/2026.
 *
 * Este botao ja abriu duas telas: o "Ver / editar" (o banco da NUMERACAO) e o
 * "Linhas" (a fatia DO MODELO). Elas parecem irmas e nao sao -- a primeira
 * escreve numa coisa que todos os modelos daquela numeracao compartilham.
 *
 * O relato que fechou o assunto: *"2 modelos com a mesma numeracao, ao
 * selecionar A no modelo 1 e B no modelo 2, o modelo 1 vira B"*. Estava
 * correto: a marca de imprimir mora dentro da linha, e a linha e da numeracao.
 * Um aviso chegou a ser posto na frente do botao; o usuario decidiu melhor --
 * tirar a porta em vez de sinalizar o buraco.
 *
 * Editar o banco continua existindo, com uma porta so: abrir a numeracao no
 * lapis e usar o "Ver / Editar" da box "Banco de Dados (CSV)", onde esta claro
 * que se mexe na numeracao inteira.
 */
window.abrirCsvDoModelo = async function(idx, osId) {

    if (typeof window.abrirEditorCsv !== 'function') {

        toast('O editor de CSV não carregou. Recarregue a página.', 'error');

        return;

    }

    const item = (state.osItens[osId] || [])[idx];

    if (!item) return;

    const fonte = fonteDoModelo(item);

    if (!fonte) {

        const vinc = vinculoDeBancoDoModelo(item);
        toast(vinc
            ? 'O banco do pedido deste modelo ainda não chegou. Feche e abra o pedido de novo.'
            : 'A numeração deste modelo não usa banco de dados (CSV).', 'error');

        return;

    }

    return window.abrirDistribuicaoCsv(osId, fonte.chave, item.id);

};



window.addCsvColumnElement = function(colName) {

    state.numElCounter++;

    const id = `el_${state.numElCounter}`;

    const base = { 

        id, 

        type: 'TEXT', 

        name: colName,

        x_mm: 5, 

        y_mm: 5, 

        rotation: 0, 

        color: '#000000',

        font_size: 12,

        font_name: 'helv',

        pad: 0,

        prefix: '',

        suffix: '',

        source: 'database',

        csv_column: colName,

        _centerAnchor: true

    };

    

    state.numElements.push(base);

    state.selectedElId = id;

    renderElementsList();

    drawCanvas();

    selectElementCard(id);

};



