// ──── Handlers de login ───────────────────────────────────────────────────
window.handleLoginSubmit = async function(e) {
    e.preventDefault();
    const email = document.getElementById('auth-email').value.trim();
    const password = document.getElementById('auth-password').value;
    const btn = document.getElementById('btn-auth-submit');

    btn.disabled = true;
    btn.textContent = 'Entrando...';

    try {
        const { data, error } = await supabaseClient.auth.signInWithPassword({ email, password });
        if (error) throw error;

        toast('Login efetuado com sucesso!', 'success');
        document.getElementById('auth-overlay').classList.remove('active');
        document.body.classList.remove('not-logged-in');

        // Carregar permissões e UI
        const user = data.user;
        window._currentUser = user;
        const perms = await ensureUserPermissions(user.id, user.email);
        if (!perms) {
            mostrarFalhaDePermissoes(user.email);
            return;
        }
        applyPermissions(perms);
        updateProfileUI(user, perms);
        abrirTelaInicial(perms.role);
        loadAll();
    } catch (err) {
        toast('Erro: ' + (err.message || err), 'error');
    } finally {
        btn.disabled = false;
        btn.textContent = '🚀 Entrar';
    }
};

window.handleGoogleLogin = async function() {
    const btn = document.getElementById('btn-google-login');
    if (btn) btn.disabled = true;
    try {
        const { error } = await supabaseClient.auth.signInWithOAuth({
            provider: 'google',
            options: { redirectTo: window.location.origin + window.location.pathname }
        });
        if (error) throw error;
    } catch (err) {
        toast('Erro ao entrar com Google: ' + (err.message || err), 'error');
        if (btn) btn.disabled = false;
    }
};

// ══════════════════════════════════════════════════════════════════════════
// ACESSO LOCAL À ESTAÇÃO (NewProd)
//
// O painel servido pelo agente em 127.0.0.1:9000 não pode exigir a conta do
// sistema: o operador não tem conta, e o login dependeria de rede — que é
// exatamente o que o agente local existe para tirar do caminho. No lugar disso,
// um código de 6 caracteres que o administrador gera no Menu Usuários e entrega
// por fora. Quem valida é o próprio agente, contra a cópia em disco.
// ══════════════════════════════════════════════════════════════════════════

const CHAVE_SESSAO_LOCAL = 'newprod_acesso_local';

async function iniciarAcessoLocal(liberarUICompleta) {
    let exigirCodigo = false;
    try {
        const resp = await fetch(`${API_BASE_URL}/api/local/login/estado`);
        const data = await resp.json();
        exigirCodigo = !!(data && data.exigir_codigo);
    } catch (e) {
        // Agente numa versão anterior, sem o endpoint, ou fora do ar. Entrar como
        // antes: parar a produção porque a estação não soube responder seria pior
        // do que o problema que o código resolve.
        console.warn('[acesso local] A estação não respondeu sobre o código:', e);
    }

    if (!exigirCodigo) {
        console.log('[acesso local] Nenhum código cadastrado nesta estação — entrada liberada.');
        liberarUICompleta();
        abrirTelaInicial(null);
        loadAll();
        return;
    }

    let sessao = null;
    try {
        sessao = JSON.parse(sessionStorage.getItem(CHAVE_SESSAO_LOCAL) || 'null');
    } catch (e) { /* sessão ilegível vale como ausente */ }

    if (!sessao || !sessao.nome) {
        mostrarLoginLocal(liberarUICompleta);
        return;
    }

    // Sessão guardada sem código: veio de uma versão anterior do painel, que não
    // o guardava. Vale como está; o próximo login já grava.
    if (!sessao.codigo) {
        aplicarAcessoLocal(sessao, liberarUICompleta);
        return;
    }

    const conferida = await reconferirAcessoLocal(sessao.codigo);
    if (conferida.sessao) {
        aplicarAcessoLocal(conferida.sessao, liberarUICompleta);
        return;
    }
    if (conferida.motivo === 'recusado') {
        // Acesso desativado, excluído, ou código trocado enquanto a aba estava
        // aberta. Sem isto, a sessão antiga valeria até o operador sair por conta
        // própria — ou seja, tirar a permissão de alguém não teria efeito.
        sessionStorage.removeItem(CHAVE_SESSAO_LOCAL);
        mostrarLoginLocal(liberarUICompleta);
        toast('Seu acesso mudou. Entre de novo com o código.', 'warning');
        return;
    }
    // Agente sem resposta: seguir com o que estava guardado. Travar o operador
    // porque o agente demorou seria pior do que uma grade de permissões velha.
    console.warn('[acesso local] Sem resposta da estação; mantendo a sessão guardada.');
    aplicarAcessoLocal(sessao, liberarUICompleta);
}

/**
 * Reconfere o código com o agente e devolve a sessão atualizada.
 *
 * É o que faz uma mudança de permissão valer sem precisar que o operador saia:
 * a estação baixa a lista a cada 5 minutos, e um F5 depois disso já traz a grade
 * nova. Também é o que faz um acesso desativado parar de valer.
 *
 * Distingue "o agente recusou" de "o agente não respondeu": só o primeiro derruba
 * a sessão.
 */
async function reconferirAcessoLocal(codigo) {
    try {
        const resp = await fetch(`${API_BASE_URL}/api/local/login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ codigo })
        });
        if (!resp.ok) return { motivo: 'recusado' };
        const data = await resp.json();
        const sessao = sessaoDoLogin(data, codigo);
        sessionStorage.setItem(CHAVE_SESSAO_LOCAL, JSON.stringify(sessao));
        return { sessao };
    } catch (e) {
        return { motivo: 'sem_resposta' };
    }
}

// O código fica na sessão do navegador para permitir a reconferência acima. É a
// mesma máquina onde ele acabou de ser digitado, e o sessionStorage morre quando
// o navegador fecha — o mesmo limite que a própria sessão já tinha.
function sessaoDoLogin(data, codigo) {
    return {
        nome: data.nome,
        role: data.role || '',
        permissoes: data.permissoes || {},
        codigo,
    };
}

/**
 * Permissões de um operador local.
 *
 * São as mesmas permissões por módulo dos usuários do sistema, cadastradas no
 * Menu Usuários e sincronizadas com a estação. Quem manda é a grade; o `role`
 * decide o rótulo na barra lateral e o que vale para uma chave que a grade
 * NÃO TEM.
 *
 * Chave ausente segue o padrão do perfil (`ROLE_DEFAULTS`), e não um "não"
 * silencioso. A grade de um acesso é um JSON gravado no dia em que o acesso foi
 * criado ou teve o perfil trocado; um módulo que nasce depois — foi o caso do
 * Painel do Acabamento, em 22/08/2026 — não aparece nela, e aplicá-la como
 * estava escondia o menu novo de três operadores por mais que o administrador
 * marcasse caixas na grade dos usuários do SITE, que é outra grade. Chave
 * presente continua mandando, letra por letra, inclusive quando diz "não": a
 * grade é editável caixa a caixa, e é ela a decisão do administrador.
 *
 * Sem grade nenhuma — acesso criado antes das permissões existirem, ou estação
 * com cópia antiga — vale tudo menos a área de administração. Trancar o operador
 * para fora do trabalho dele por causa de um campo vazio seria pior; esconder o
 * Menu Usuários é obrigatório de todo jeito, porque é lá que estão os códigos de
 * todos os colegas.
 */
function permsDoOperadorLocal(permissoes, role) {
    if (permissoes && Object.keys(permissoes).length) {
        const perms = { ...permissoes };
        const padrao = ROLE_DEFAULTS[String(role || '').trim().toLowerCase()] || {};
        for (const key of chavesDaGrade()) {
            if (!(key in perms)) perms[key] = padrao[key] === true;
        }
        return perms;
    }

    const perms = {};
    for (const key of Object.keys(PERM_VIEW_MAP)) perms[key] = true;
    for (const key of Object.keys(PERM_NAV_MAP)) perms[key] = true;
    perms.perm_gerar_pdf = true;
    perms.perm_imprimir = true;
    perms.perm_admin_view = false;
    perms.perm_admin_edit = false;
    return perms;
}

function aplicarAcessoLocal(sessao, liberarUICompleta) {
    window._acessoLocal = sessao;
    liberarUICompleta();

    const perms = permsDoOperadorLocal(sessao.permissoes, sessao.role);
    window._currentPerms = perms;
    applyPermissions(perms);

    const profileBar = document.getElementById('user-profile-bar');
    const emailDisplay = document.getElementById('user-email-display');
    if (profileBar) profileBar.style.display = 'block';
    if (emailDisplay) {
        const rl = ROLE_LABELS[sessao.role] || {};
        const selo = rl.label
            ? `<span style="font-size:0.65rem;background:${rl.color}22;color:${rl.color};padding:1px 6px;border-radius:10px;margin-left:4px;">${rl.label.toUpperCase()}</span>`
            : '';
        emailDisplay.innerHTML = `🖥️ ${escapeHtml(sessao.nome)}${selo}`;
    }
    atualizarIdentidadeNoPainel(sessao.nome, sessao.role);

    abrirTelaInicial(sessao.role);
    loadAll();
}

function mostrarLoginLocal(liberarUICompleta) {
    let overlay = document.getElementById('auth-overlay-local');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.id = 'auth-overlay-local';
        overlay.className = 'auth-overlay active';
        overlay.innerHTML = `
            <div class="auth-card">
                <div class="auth-header">
                    <h2>🖥️ NewProd — Acesso local</h2>
                    <p>Digite o código de 6 caracteres que o administrador entregou</p>
                </div>
                <form onsubmit="handleLoginLocal(event)">
                    <div class="form-group" style="margin-bottom:14px;">
                        <input type="text" id="auth-codigo-local" class="form-control" maxlength="6"
                               autocomplete="off" autocapitalize="characters" spellcheck="false" required
                               placeholder="A2B4C6"
                               style="text-align:center;font-family:ui-monospace,Consolas,monospace;font-size:1.7rem;letter-spacing:10px;text-transform:uppercase;height:56px;">
                    </div>
                    <div id="auth-erro-local" style="display:none;color:var(--red);font-size:0.82rem;text-align:center;margin-bottom:12px;"></div>
                    <div class="auth-actions">
                        <button type="submit" id="btn-auth-local" class="btn btn-primary btn-full" style="height:42px;font-size:0.95rem;">🚀 Entrar</button>
                    </div>
                </form>
                <div style="text-align:center;margin-top:14px;color:var(--text-dim);font-size:0.76rem;">
                    Este código vale só nesta estação. Não é a senha do site.
                </div>
            </div>
        `;
        document.body.appendChild(overlay);
    } else {
        overlay.classList.add('active');
    }
    document.body.classList.add('not-logged-in');
    window._liberarUIAposLoginLocal = liberarUICompleta;
    setTimeout(() => document.getElementById('auth-codigo-local')?.focus(), 50);
}

window.handleLoginLocal = async function(e) {
    e.preventDefault();
    const campo = document.getElementById('auth-codigo-local');
    const erro = document.getElementById('auth-erro-local');
    const btn = document.getElementById('btn-auth-local');
    const codigo = (campo?.value || '').trim().toUpperCase();

    btn.disabled = true;
    btn.textContent = 'Conferindo...';
    if (erro) erro.style.display = 'none';

    try {
        const resp = await fetch(`${API_BASE_URL}/api/local/login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ codigo })
        });
        if (!resp.ok) throw new Error('Código inválido');
        const data = await resp.json();

        const sessao = sessaoDoLogin(data, codigo);
        // sessionStorage e não localStorage: fechou o navegador, pede de novo. Numa
        // estação compartilhada, a sessão não pode sobreviver ao turno.
        sessionStorage.setItem(CHAVE_SESSAO_LOCAL, JSON.stringify(sessao));

        document.getElementById('auth-overlay-local')?.classList.remove('active');
        document.body.classList.remove('not-logged-in');
        toast(`Bem-vindo, ${sessao.nome}!`, 'success');
        aplicarAcessoLocal(sessao, window._liberarUIAposLoginLocal || (() => {}));
    } catch (err) {
        if (erro) {
            erro.textContent = 'Código inválido. Confira com o administrador.';
            erro.style.display = 'block';
        }
        if (campo) { campo.value = ''; campo.focus(); }
    } finally {
        btn.disabled = false;
        btn.textContent = '🚀 Entrar';
    }
};


// ──── Inicialização de auth (DOMContentLoaded) ────────────────────────────
document.addEventListener('DOMContentLoaded', async () => {
    // Antes, qualquer acesso por localhost/127.0.0.1 pulava o login e recebia
    // admin total — inclusive o painel da estação, servido pelo próprio agente.
    // Como o cliente Supabase é inicializado ali do mesmo jeito, as gravações
    // chegavam ao banco como anon: era isso que impedia fechar a escrita por RLS
    // sem quebrar a estação.
    // ADIADO: o bypass volta a valer para localhost/127.0.0.1 até que as contas
    // dos operadores existam. Exigir login na estação é pré-requisito da fase 1
    // do RLS (senão as gravações da estação, feitas como anon, falhariam em
    // silêncio) — mas foi separado da correção de fontes 1.2.10 para não somar
    // duas mudanças de comportamento durante uma regressão em produção.
    // Para reativar: deixar apenas `window.location.protocol === 'file:'`.
    const isLocal = window.location.hostname === 'localhost'
        || window.location.hostname === '127.0.0.1'
        || window.location.protocol === 'file:';

    const liberarUICompleta = () => {
        const profileBar = document.getElementById('user-profile-bar');
        if (profileBar) profileBar.style.display = 'none';
        document.querySelectorAll('.admin-only').forEach(el => el.style.display = '');
        document.querySelectorAll('.nav-btn').forEach(el => el.style.display = '');
        document.querySelectorAll('.nav-group').forEach(el => el.style.display = '');
        atualizarContagemDosGrupos();
        // Quem entrar por cima disto (login local, sessão do site) sobrescreve
        // logo em seguida. Aqui é o estado sem ninguém logado.
        atualizarIdentidadeNoPainel(null);
    };

    if (isLocal) {
        // file:// não tem agente a quem perguntar — segue o bypass de sempre.
        if (window.location.protocol === 'file:') {
            console.log('[auth] file:// — bypass de autenticação');
            liberarUICompleta();
            abrirTelaInicial(null);
            loadAll();
            return;
        }
        await iniciarAcessoLocal(liberarUICompleta);
        return;
    }

    // ── Modo online → verificar sessão Supabase Auth ──
    if (!supabaseClient || !supabaseClient.auth) {
        // Modo offline explícito (?offline=true ou localStorage): sem banco, não
        // há o que proteger — a UI segue liberada como antes.
        console.warn('[auth] Supabase não disponível — modo offline, sem autenticação');
        liberarUICompleta();
        abrirTelaInicial(null);
        loadAll();
        return;
    }

    try {
        const { data: { session }, error } = await supabaseClient.auth.getSession();

        if (error || !session || !session.user) {
            // Sem sessão → mostrar tela de login
            console.log('[auth] Sem sessão — exibindo login');
            showLoginOverlay();
            return;
        }

        // Logado! 
        const user = session.user;
        window._currentUser = user;
        console.log('[auth] Logado como:', user.email);

        // Carregar/criar permissões
        const perms = await ensureUserPermissions(user.id, user.email);
        if (!perms) {
            // Motor sem resposta. Seguir daqui deixaria `_currentPerms` vazio, e
            // grade vazia é passe livre em `podeAbrirView` — a aplicação inteira
            // aberta no exato momento em que ninguém sabe quem é a pessoa.
            mostrarFalhaDePermissoes(user.email);
            return;
        }
        window._currentPerms = perms;

        // Aplicar permissões na UI
        applyPermissions(perms);
        updateProfileUI(user, perms);

        // Só agora, com a grade na mão, dá para saber onde este perfil abre.
        abrirTelaInicial(perms.role);

        // Carregar dados
        loadAll();

    } catch (e) {
        console.error('[auth] Erro na verificação de sessão:', e);
        abrirTelaInicial(null);
        loadAll();
    }

    // Listener para mudança de sessão (logout externo, expiração etc)
    supabaseClient.auth.onAuthStateChange((event, session) => {
        if (event === 'SIGNED_OUT' || !session) {
            showLoginOverlay();
        }
    });

});


// ──────────────────────────────────────────────────────────────────────────

/**
 * A grade de ver/editar por módulo, mais as ações.
 *
 * Uma função só para os dois cards desta tela — usuários do sistema e acessos
 * locais do NewProd. São a MESMA lista de permissões, e duas cópias do mesmo
 * HTML acabariam divergindo no dia em que um módulo novo entrasse no menu.
 *
 * `handler` é o nome da função global chamada a cada clique, porque cada card
 * grava num lugar diferente: toggleUserPerm vai para o Supabase por user_id,
 * toggleAcessoLocalPerm regrava o objeto de permissões do acesso local.
 */
function renderGradePermissoes(perms, handler, id, aberto = false) {
    const p = perms || {};
    const alvo = escapeJsAttr(id);

    const linhaModulo = (m, vKey, eKey) => `
        <div class="perm-linha">
            <span class="perm-nome">
                <strong>${m.icon} ${m.label}</strong>
                <small>${m.tela}</small>
            </span>
            <label class="perm-caixa" title="Ver ${m.label}">
                <input type="checkbox" data-perm-key="${vKey}" ${p[vKey] === true ? 'checked' : ''}
                       onchange="${handler}('${alvo}','${vKey}',this.checked)">
            </label>
            <label class="perm-caixa" title="Editar em ${m.label}">
                <input type="checkbox" data-perm-key="${eKey}" ${p[eKey] === true ? 'checked' : ''}
                       onchange="${handler}('${alvo}','${eKey}',this.checked)">
            </label>
        </div>`;

    // Metade em cada coluna, na ordem em que os módulos estão listados — que é a
    // ordem do trabalho na gráfica, e não a alfabética: produção, arte, pedido e
    // imposição primeiro; cadastros e administração depois.
    const meio = Math.ceil(PERM_MODULES.length / 2);
    const coluna = lista => `
        <div class="perm-grade-col">
            <div class="perm-cabecalho">
                <span>Módulo</span>
                <span title="Pode abrir a tela">VER</span>
                <span title="Pode alterar coisas dentro dela">EDITAR</span>
            </div>
            ${lista.map(m => linhaModulo(m, `perm_${m.key}_view`, `perm_${m.key}_edit`)).join('')}
        </div>`;
    const colunas = coluna(PERM_MODULES.slice(0, meio)) + coluna(PERM_MODULES.slice(meio));

    const linhasAcao = PERM_ACTIONS.map(a => {
        const aKey = `perm_${a.key}`;
        return `
        <div class="perm-linha perm-linha-acao">
            <span class="perm-nome">
                <strong>${a.icon} ${a.label}</strong>
                <small>${a.tela}</small>
            </span>
            <label class="perm-caixa perm-caixa-larga" title="${a.label}">
                <input type="checkbox" data-perm-key="${aKey}" ${p[aKey] === true ? 'checked' : ''}
                       onchange="${handler}('${alvo}','${aKey}',this.checked)">
            </label>
        </div>`;
    }).join('');

    // Duas colunas quando há espaço (`auto-fit`), uma só quando a janela aperta.
    // Antes era uma coluna de 260px de largura fixa com tipo de 0.62rem: treze
    // módulos em fila, letra que mal se lê, e as caixas de marcar de "ver" e
    // "editar" a poucos pixels uma da outra — errar a coluna era o normal.
    // Recolhida por padrão. Treze módulos abertos para cada pessoa davam uma
    // página de rolagem por usuário — com quinze contas, ninguém conseguia
    // comparar duas. O que fica sempre à vista é o resumo, que é o que se olha:
    // qual perfil, onde abre, quantos módulos vê, e se a grade foi mexida.
    return `
        <details class="perm-detalhes" ${aberto ? 'open' : ''}>
            <summary>Ajustar permissões</summary>
            <div class="perm-grade">${colunas}</div>
            <div class="perm-acoes">
                <div class="perm-cabecalho perm-cabecalho-acao"><span>Ações</span><span>PODE</span></div>
                ${linhasAcao}
            </div>
        </details>`;
}

/**
 * Quantos módulos esta grade deixa ver, e se ela ainda é a do perfil.
 *
 * O segundo número é o que faltava na tela: a grade é editável caixa a caixa, e
 * nada dizia que um "🎨 Designer" tinha, na prática, uma grade montada à mão que
 * já não parecia com o perfil. Foi assim que quatro designers ficaram sem a tela
 * do pedido com o crachá de Designer no peito.
 */
function resumoDaGrade(perms, role) {
    const p = perms || {};
    const total = PERM_MODULES.length;
    const vendo = PERM_MODULES.filter(m => p[`perm_${m.key}_view`] === true).length;

    const padrao = ROLE_DEFAULTS[role];
    let personalizada = false;
    if (padrao) {
        personalizada = chavesDaGrade().some(k => (p[k] === true) !== (padrao[k] === true));
    }
    return { vendo, total, personalizada };
}

/**
 * A grade de cada usuário que está na tela, para não reler o servidor a cada
 * caixa marcada. Mesmo motivo de `_acessosLocais`, no card ao lado.
 */
let _permsUsuarios = {};

/** O HTML do bloco "Vê N de 13 módulos" de uma linha. */
function htmlResumoDaLinha(userId) {
    const perms = _permsUsuarios[userId];
    if (!perms) return '';
    const role = perms.role;
    const rl = ROLE_LABELS[role] || {};
    const perfilQuebrado = !ROLE_LABELS[role];
    const r = resumoDaGrade(perms, role);
    return `Vê ${r.vendo} de ${r.total} módulos
        ${r.personalizada && !perfilQuebrado ? `
            <span class="perm-selo-custom" title="A grade abaixo foi editada à mão e já não é a do perfil.">✏️ grade personalizada</span>
            <button class="btn btn-ghost btn-sm perm-btn-restaurar" onclick="changeUserRole('${escapeJsAttr(userId)}','${escapeJsAttr(role)}')"
                    title="Devolve a grade ao padrão do perfil ${rl.label || role}">↩️ Restaurar padrão</button>` : ''}`;
}

function atualizarResumoDaLinha(userId) {
    const alvo = document.querySelector(`tr[data-user-row="${userId}"] .perm-resumo`);
    if (alvo) alvo.innerHTML = htmlResumoDaLinha(userId);
}


window.loadAdminUsers = async function() {
    const tbody = document.getElementById('tbody-admin-users');
    if (!tbody) return;

    tbody.innerHTML = '<tr><td colspan="3" style="text-align:center;">Carregando...</td></tr>';

    try {
        // 1) Buscar TODOS os usuários do sistema parceiro
        let allUsers = [];
        let falhaUsuarios = supabaseClient ? null : 'o painel está em modo local, sem banco';
        try {
            if (supabaseClient) {
                const { data: profiles, error } = await supabaseClient
                    .from('usuarios')
                    .select('user_id, email, setor, avatar, is_admin, telefone')
                    .order('email', { ascending: true });
                if (error) falhaUsuarios = error.message || 'o banco recusou a consulta';
                else if (profiles) allUsers = profiles;
            }
        } catch (e) {
            console.warn('[admin] Erro ao buscar usuarios:', e);
            falhaUsuarios = e.message || 'erro de rede';
        }

        // 2) Buscar permissões do Imposition
        //
        // Sem parar aqui, uma falha de rede desenhava a tela inteira com todo
        // mundo em "SEM ACESSO" — e um administrador que acreditasse nisso sairia
        // concedendo acesso de novo por cima de permissões que existiam.
        let permsMap = {};
        const resp = await fetch(`${API_PAINEL}/api/user/permissions`);
        const data = await resp.json().catch(() => ({}));
        if (!resp.ok || !data.ok || !Array.isArray(data.permissions)) {
            // O 401 tem nome, e dizer o nome economiza a hora de quem procura o
            // defeito no lugar errado: ele significa que a página não tem sessão
            // do site. É o que acontece com o painel aberto NA ESTAÇÃO, onde a
            // entrada é pelo código local e não há login do Supabase para oferecer
            // — e estas duas telas falam com a nuvem de propósito, porque mexem
            // nas tabelas que só a chave de serviço alcança.
            const motivo = data.detail
                || (resp.status === 401 ? 'esta tela precisa da sessão do site — abra o painel pelo endereço da nuvem e entre com o seu login'
                :  resp.status === 403 ? 'a sua conta não tem o módulo "Usuários"'
                :  `servidor sem resposta (HTTP ${resp.status})`);
            tbody.innerHTML = `<tr><td colspan="3" style="text-align:center;color:var(--red);padding:20px;">
                Não deu para ler as permissões (${escapeHtml(motivo)}).<br>
                <small style="color:var(--text-dim);">Nada foi alterado. Clique em Atualizar Lista para tentar de novo.</small>
            </td></tr>`;
            return;
        }
        data.permissions.forEach(p => permsMap[p.user_id] = p);
        _permsUsuarios = permsMap;

        if (!allUsers.length) {
            // Quem some daqui não pode ser gerenciado por ninguém: a lista de
            // pessoas desta tela vem da tabela `usuarios` do parceiro, e não da
            // grade. Dizer "nenhum usuário encontrado" quando a consulta FALHOU
            // mandaria o administrador procurar gente que está lá.
            tbody.innerHTML = falhaUsuarios
                ? `<tr><td colspan="3" style="text-align:center;color:var(--red);padding:20px;">
                    Não deu para ler a lista de pessoas do sistema (${escapeHtml(falhaUsuarios)}).<br>
                    <small style="color:var(--text-dim);">Nada foi alterado. Clique em Atualizar Lista para tentar de novo.</small>
                   </td></tr>`
                : '<tr><td colspan="3" style="text-align:center; color: var(--text-dim);">Nenhum usuário encontrado no sistema.</td></tr>';
            return;
        }

        tbody.innerHTML = allUsers.map(u => {
            const userId = u.user_id;
            const email = u.email || '—';
            const setor = u.setor || '';
            const perms = permsMap[userId];
            const hasAccess = !!perms;
            const role = perms ? perms.role : null;
            const rl = ROLE_LABELS[role] || {};

            // Perfil que não existe na lista: conta criada pela versão que
            // gravava 'operador'. Ela está sem permissão nenhuma, e o seletor
            // mostrava "Administrador" por acidente — nenhuma opção casava, e o
            // navegador exibe a primeira. Dizer a verdade aqui é o que leva o
            // administrador a escolher um perfil e consertar a conta.
            const perfilQuebrado = hasAccess && !ROLE_LABELS[role];

            const statusBadge = !hasAccess
                ? `<span style="font-size:0.72rem;padding:2px 8px;border-radius:12px;background:rgba(255,255,255,0.05);color:var(--text-dim);">SEM ACESSO</span>`
                : perfilQuebrado
                ? `<span title="Esta conta está sem permissão nenhuma. Escolha um perfil abaixo." style="font-size:0.72rem;padding:2px 8px;border-radius:12px;background:rgba(245,158,11,0.18);color:#fbbf24;font-weight:700;">⚠️ PERFIL INVÁLIDO</span>`
                : `<span style="display:inline-flex;align-items:center;gap:4px;font-size:0.72rem;padding:2px 8px;border-radius:12px;background:${rl.color || '#6b7280'}22;color:${rl.color || '#6b7280'};font-weight:600;">${rl.icon || ''} ${rl.label || role}</span>`;

            // Role select com os 7 perfis
            const roleOptions = (perfilQuebrado
                    ? `<option value="" selected disabled>— escolha um perfil —</option>`
                    : '')
                + Object.entries(ROLE_LABELS).map(([k, v]) =>
                    `<option value="${k}" ${role === k ? 'selected' : ''}>${v.icon} ${v.label}</option>`
                ).join('');

            const roleSelect = hasAccess ? `
                <select class="form-control perm-perfil-select" onchange="changeUserRole('${userId}', this.value)">
                    ${roleOptions}
                </select>` : `
                <button class="btn btn-sm btn-secondary" onclick="grantUserAccess('${userId}', '${escapeJsAttr(email)}')" style="font-size:0.78rem;padding:5px 12px;margin-top:6px;">
                    ➕ Conceder Acesso
                </button>`;

            // Onde esta pessoa abre a aplicação. Fica escrito porque é uma regra
            // que roda sozinha: sem esta linha, ninguém tem como saber por que o
            // Designer entra na Lista de Arte e o Impressor no Painel.
            const homeId = hasAccess ? telaInicialDoUsuario(role, perms) : null;
            const homeLabel = { 'view-lista-arte': '🖼️ Lista de Arte', 'view-lista-impressao': '📋 Painel de Produção' }[homeId];
            const homeHtml = homeLabel
                ? `<div class="perm-abre-em" title="Tela em que este usuário abre a aplicação ao entrar">Abre em <strong>${homeLabel}</strong></div>`
                : '';

            const resumoHtml = hasAccess
                ? `<div class="perm-resumo">${htmlResumoDaLinha(userId)}</div>`
                : '';

            // Grid de permissões View/Edit por módulo. Já aberta para a conta de
            // perfil inválido: é a única que exige mesmo a atenção de quem entrou
            // nesta tela, e escondê-la atrás de mais um clique seria esconder o
            // problema junto.
            const permGrid = hasAccess
                ? renderGradePermissoes(perms, 'toggleUserPerm', userId, perfilQuebrado)
                : '<span style="color:var(--text-dim);font-size:0.8rem;">Sem acesso ao Imposition.</span>';

            return `
                <tr class="perm-linha-usuario" data-user-row="${escapeJsAttr(userId)}" style="${!hasAccess ? 'opacity:0.55;' : ''}">
                    <td>
                        <strong style="color:#fff;font-size:0.9rem;">${escapeHtml(email)}</strong>
                        ${setor ? `<br><small style="color:var(--text-dim);font-size:0.75rem;">${escapeHtml(setor)}</small>` : ''}
                    </td>
                    <td>
                        ${statusBadge}
                        ${roleSelect}
                        ${homeHtml}
                        ${resumoHtml}
                    </td>
                    <td>
                        ${permGrid}
                    </td>
                </tr>`;
        }).join('');
    } catch (e) {
        tbody.innerHTML = `<tr><td colspan="3" style="text-align:center; color:var(--red);">Erro: ${e.message}</td></tr>`;
    }
};

// Conceder acesso a um usuário (cria com role visualizador)
window.grantUserAccess = async function(userId, email) {
    try {
        const defaults = ROLE_DEFAULTS.visualizador;
        await salvarPermissoesNoMotor({ user_id: userId, role: 'visualizador', ...defaults });
        toast(`Acesso concedido para ${email}!`, 'success');
        loadAdminUsers();
    } catch (e) {
        toast(`Não deu para conceder acesso a ${email}: ${e.message}`, 'error');
    }
};

window.changeUserRole = async function(userId, newRole) {
    // O placeholder "escolha um perfil" é disabled, então não deveria chegar aqui
    // — mas gravar role vazio recriaria a conta quebrada que este guard existe
    // para eliminar.
    if (!ROLE_LABELS[newRole]) return;
    const rl = ROLE_LABELS[newRole];
    const nome = `${rl.icon || ''} ${rl.label || newRole}`.trim();

    // Dizer que a grade inteira volta ao padrão: quem clica aqui para consertar
    // uma conta não espera perder ajustes finos feitos antes, e quem clica para
    // reverter ajustes finos precisa da confirmação de que é isso mesmo.
    const abre = { 'view-lista-arte': 'Lista de Arte', 'view-lista-impressao': 'Painel de Produção' }[ROLE_HOME[newRole]] || '';
    if (!confirm(`Aplicar o perfil ${nome}?\n\nA grade de permissões deste usuário volta INTEIRA ao padrão do perfil${abre ? `, e ele passa a abrir a aplicação no ${abre}` : ''}.`)) {
        loadAdminUsers();
        return;
    }
    try {
        const defaults = ROLE_DEFAULTS[newRole] || ROLE_DEFAULTS.visualizador;
        await salvarPermissoesNoMotor({ user_id: userId, role: newRole, ...defaults });
        toast(`Perfil alterado para ${nome}`, 'success');
    } catch (e) {
        toast(`O perfil NÃO foi alterado: ${e.message}`, 'error');
    }
    // Recarregar sempre: no sucesso mostra a grade nova, no erro devolve o
    // seletor ao perfil que de fato está gravado — em vez de deixar na tela um
    // perfil que só existe no <select>.
    loadAdminUsers();
};

/**
 * Marca ou desmarca UMA permissão de um usuário do sistema.
 *
 * Desmarca a caixa de volta quando a gravação não é confirmada. Sem isso a tela
 * ficava mostrando o estado que o administrador queria, e não o que o banco
 * tinha — e como o antigo `fetch` sem conferência sempre dizia "✅ ativada", não
 * havia sequer o erro para percebê-lo.
 */
window.toggleUserPerm = async function(userId, permKey, value) {
    const caixa = document.querySelector(
        `tr[data-user-row="${userId}"] input[data-perm-key="${permKey}"]`);
    const label = permKey.replace('perm_', '').replace(/_/g, ' ');
    try {
        await salvarPermissoesNoMotor({ user_id: userId, [permKey]: value });
        toast(`${label} ${value ? '✅ ativada' : '❌ desativada'}`, 'success');
        // Só o resumo é redesenhado, e não a tabela inteira: quem está marcando
        // seis caixas seguidas não pode ver a linha saltar embaixo do cursor a
        // cada clique.
        if (_permsUsuarios[userId]) {
            _permsUsuarios[userId][permKey] = value;
            atualizarResumoDaLinha(userId);
        }
    } catch (e) {
        if (caixa) caixa.checked = !value;
        toast(`${label} NÃO foi salva: ${e.message}`, 'error');
    }
};

