window.clearActiveOS = clearActiveOS;


// -------------------------------------------------------------------------------
// ORDENS DE SERVIÇO -- Integração com banco de dados compartilhado
// -------------------------------------------------------------------------------

// Estado local de OS
if (!state.ordens) state.ordens = [];
if (!state.osItens) state.osItens = {};
if (!state.osExpandedId) state.osExpandedId = null;
if (!state.activeOSItem) state.activeOSItem = null;
// O PEDIDO ABERTO na tela, guardado a parte do MODELO aberto. Desde 28/08/2026
// a tela de Pedido abre sem nenhum modelo selecionado e fechar a janela deixa
// `activeOSItem` nulo — as duas filas (Pedido e Imposicao) precisam de outra
// coisa para saber o que desenhar. Ver renderPedOSQueue().
if (!state.pedidoAberto) state.pedidoAberto = null;
// O modelo cujos campos a gerencia liberou, se algum. Nasce nulo a cada carga
// da pagina de proposito: uma liberacao que sobrevivesse a um F5 seria uma
// porta destrancada que ninguem lembra de ter aberto. Ver a trava da gerencia
// no pedido.js.
if (!state.modeloLiberado) state.modeloLiberado = null;
// Como somar modelos numa folha. Decisão de tiragem, não do pedido: vive aqui e
// não vai ao banco. O padrão é o comportamento de sempre.
if (!state.modoSomaFolha) state.modoSomaFolha = 'separado';
// Cruzar pedidos numa folha so vale quando foi DECIDIDO no aproveitamento.
// Nasce desligado a cada carga da pagina, de proposito: uma combinacao que
// sobrevivesse a um F5 seria invisivel e voltaria a ser cruzamento por acidente.
if (state.combinacaoEntrePedidos === undefined) state.combinacaoEntrePedidos = false;
// Produtos liberados a dividir folha entre pedidos (ADM → Aproveitamento) e o
// limiar da sobra. Carregados de producao_produtos_combinaveis / producao_config.
if (!state.produtosCombinaveis) state.produtosCombinaveis = new Set();
// O limiar da sobra e por produto; o de producao_config e o padrao de quem nao
// tem o seu. Ver limiarDoProduto().
if (!state.limiaresPorProduto) state.limiaresPorProduto = {};

// -------------------------------------------------------------------------------
// STATUS ADIANTADO DESTA MÁQUINA (vibe_status_overrides)
//
// Quando esta estação muda o status de um pedido, ela guarda o valor novo aqui
// para a tela refletir a mudança na hora, sem esperar a próxima leitura do banco.
// É um ADIANTAMENTO, não uma fonte de verdade.
//
// Antes cada entrada valia para sempre, e o `savedStatus || dbStatus` da leitura
// fazia o valor local vencer o banco indefinidamente NESTA estação. Numa gráfica
// com várias estações isso significava: a máquina A grava um status, outra máquina
// muda o pedido depois, e a máquina A segue mostrando o valor velho — sem nenhum
// sinal na tela de que estava desatualizada. O prazo abaixo devolve a palavra final
// ao banco: passados alguns minutos, o adiantamento caduca sozinho.
// -------------------------------------------------------------------------------
const STATUS_OVERRIDE_KEY = 'vibe_status_overrides';
const STATUS_OVERRIDE_VALIDADE_MS = 5 * 60 * 1000; // 5 min — cobre a ida ao banco com folga

function _lerMapaStatusOverrides() {
    try {
        const bruto = JSON.parse(localStorage.getItem(STATUS_OVERRIDE_KEY) || '{}');
        return (bruto && typeof bruto === 'object') ? bruto : {};
    } catch (e) {
        return {};
    }
}

function _descartarStatusOverride(mapa, osId) {
    delete mapa[osId];
    try { localStorage.setItem(STATUS_OVERRIDE_KEY, JSON.stringify(mapa)); } catch (e) {}
    return null;
}

/**
 * Status adiantado por esta máquina para a OS, ou null se não houver ou se já
 * tiver caducado. Entradas vencidas — e as do formato antigo, que eram string
 * pura e não dizem quando foram gravadas — são apagadas aqui mesmo, para que o
 * banco volte a mandar.
 */
function lerStatusOverride(osId) {
    const mapa = _lerMapaStatusOverrides();
    const entrada = mapa[osId];
    if (!entrada) return null;
    if (typeof entrada !== 'object' || !entrada.ts) return _descartarStatusOverride(mapa, osId);
    if (Date.now() - entrada.ts > STATUS_OVERRIDE_VALIDADE_MS) return _descartarStatusOverride(mapa, osId);
    return entrada.status || null;
}

/** Registra, com a hora, o status que esta máquina acabou de gravar. */
function gravarStatusOverride(osId, status) {
    if (!osId) return;
    const mapa = _lerMapaStatusOverrides();
    mapa[osId] = { status: status, ts: Date.now() };
    try { localStorage.setItem(STATUS_OVERRIDE_KEY, JSON.stringify(mapa)); } catch (e) {}
}

window.lerStatusOverride = lerStatusOverride;
window.gravarStatusOverride = gravarStatusOverride;

/**
 * Sincroniza dinamicamente o status da OS em memória e no banco com base nas decisões de amostra do cliente
 */
async function sincronizarStatusOrdensDinamico() {
    // Apenas rodar no painel interno (não na página do cliente)
    if (state.amostrasContainerId === 'cliente-amostras-itens-container') return;

    for (const os of state.ordens) {
        const osId = os.id;
        const itens = state.osItens[osId] || [];
        if (itens.length === 0) continue;

        // Se o status da OS já estiver finalizado em termos de produção, não fazemos override
        if (os.status === 'FINALIZADA' || os.status === 'CANCELADA' || os.status === 'PRODUÇÃO' || os.status === 'EM IMPRESSÃO') {
            continue;
        }

        // Verificar o status de todas as amostras/itens
        const todosAprovados = itens.every(item => item.amostra_status === 'APROVADA');
        const algumReprovado = itens.some(item => item.amostra_status === 'REPROVADA');

        let novoStatus = null;
        if (todosAprovados) {
            novoStatus = 'APROVADO';
        } else if (algumReprovado) {
            novoStatus = 'REPROVADO';
        }

        if (novoStatus && os.status !== novoStatus) {
            console.log(`[Sync] Ajustando status da OS #${os.numero} de ${os.status} para ${novoStatus} com base nas amostras.`);
            
            // 1. Atualizar em memória
            os.status = novoStatus;

            // 2. Adiantar o status nesta máquina (comum para ordens Vibecode e Supabase no front)
            gravarStatusOverride(osId, novoStatus);

            // 3. Atualizar no banco Supabase (somente se for OS local e não for mock/vibe virtual)
            if (typeof supabaseClient !== 'undefined' && supabaseClient && !osId.startsWith('vibe_')) {
                try {
                    await supabaseClient
                        .from('producao_ordens_servico')
                        .update({ status: novoStatus })
                        .eq('id', osId);
                } catch (err) {
                    console.warn(`[Sync] Falha ao gravar status no Supabase para OS #${os.numero}:`, err);
                }
            }
        }
    }

    await sincronizarPedidosProntosParaEnvio();
}

/**
 * Regra: pedido cujos modelos estão TODOS prontos no banco passa a "Enviar Arte".
 *
 * Esta regra já existiu em duas cópias — uma aqui, lendo `pedidos_modelos`, e outra
 * dentro do `renderOrdens()`, lendo o `state.osItens` que estivesse carregado. As
 * duas já tinham divergido nos status aceitos como "pronto", e a cópia do render
 * fazia a função de DESENHAR a tela gravar no banco: como `renderOrdens()` é o
 * `oninput` da caixa de busca, digitar no filtro disparava UPDATE no Supabase.
 *
 * Ficou só esta. Ela lê do banco, então cobre todos os pedidos da lista e não
 * apenas aqueles cujos itens por acaso já tinham sido abertos na tela.
 */
async function sincronizarPedidosProntosParaEnvio() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;

    // Status que já passaram do ponto: mexer neles seria andar para trás.
    const IGNORAR = [
        'ENVIAR ARTE', 'FINALIZADA', 'CANCELADA', 'EM IMPRESSAO', 'PRODUÇÃO',
        'APROVADO', 'APROVADA_CLIENTE', 'AGUARD. APROVAÇÃO', 'AGUARDANDO_APROVACAO'
    ];
    // Status do banco que significam "o designer terminou".
    const PRONTOS = ['PRONTO', 'AGUARDANDO_CLIENTE'];

    try {
        const osParaVerificar = state.ordens.filter(os => !IGNORAR.includes((os.status || '').trim().toUpperCase()));
        if (osParaVerificar.length === 0) return;

        const numerosParaVerificar = osParaVerificar.map(os => parseInt(os.numero)).filter(n => !isNaN(n));
        if (numerosParaVerificar.length === 0) return;

        // Uma única consulta para toda a lista
        const { data: modelos } = await supabaseClient
            .from('pedidos_modelos')
            .select('id_int, status_arte')
            .in('id_int', numerosParaVerificar);
        if (!modelos || modelos.length === 0) return;

        const modelosPorPedido = {};
        modelos.forEach(m => {
            if (!modelosPorPedido[m.id_int]) modelosPorPedido[m.id_int] = [];
            modelosPorPedido[m.id_int].push(m.status_arte || '');
        });

        // O pedido do Vibe grava em `pedidos_links_cliente`, que o `anon` não
        // alcança. Sem sessão, a gravação seria recusada — e o `localStorage`
        // logo abaixo ficaria dizendo "Enviar Arte" numa máquina só, divergindo
        // do banco até alguém abrir o site. Então, sem sessão, ele fica como
        // está. O site, que tem sessão, faz esta mesma sincronização.
        const temSessao = await temSessaoDoSupabase();

        const gravacoes = [];
        for (const os of osParaVerificar) {
            const statusItens = modelosPorPedido[parseInt(os.numero)] || [];
            if (statusItens.length === 0) continue;
            if (!statusItens.every(s => PRONTOS.includes((s || '').toUpperCase()))) continue;

            const ehDoVibe = os.id.startsWith('vibe_');
            if (ehDoVibe && !temSessao) continue;

            console.log('[AUTO-SYNC-DB] Pedido #' + os.numero + ': todos modelos PRONTO no banco -> Enviar Arte');
            os.status = 'Enviar Arte';
            gravarStatusOverride(os.id, 'Enviar Arte');

            gravacoes.push(
                ehDoVibe
                    ? supabaseClient.from('pedidos_links_cliente').update({ status_arte: 'Enviar Arte' }).eq('os_id', os.id)
                    : supabaseClient.from('producao_ordens_servico').update({ status: 'Enviar Arte' }).eq('id', os.id)
            );
        }

        // Antes as gravações eram disparadas com `.then(function(){})` e qualquer
        // falha sumia sem deixar rastro. Agora uma gravação que falhar aparece no
        // console em vez de o status divergir do banco em silêncio.
        const resultados = await Promise.allSettled(gravacoes);
        resultados.forEach((r, i) => {
            const erro = r.status === 'rejected' ? r.reason : (r.value && r.value.error);
            if (erro) console.warn('[AUTO-SYNC-DB] Falha ao gravar "Enviar Arte" (gravação ' + i + '):', erro);
        });
    } catch (syncErr) {
        console.warn('[AUTO-SYNC-DB] Erro na verificacao de status:', syncErr);
    }
}

/**
 * Carrega todas as OS -- Prioridade: Vibecode → Supabase Imposition → API local
 * No Vibecode, cada `id_int` (proposta) = 1 OS. Os produtos_proposta são os itens.
 */
async function loadOrdens() {
    try {
        // Deixar pedidosComerciais fixo vazio já que a tabela 'pedidos' não existe no banco.
        // Isso economiza uma consulta lenta que sempre falharia.
        const pedidosComerciais = [];
        state.hasPedidosComerciais = false;

        // Disparar buscas iniciais em paralelo (incluindo loadUsuarios para não bloquear o início)
        const promises = [
            carregarArtesGlobais(),
            carregarLinksExistentes(),
            carregarTemposNoCard(),
            loadUsuarios()
        ];
        
        // Se o Vibecode estiver ativo, carregamos os produtos em paralelo (excluindo campos de imagem base64 pesados que causavam travamentos)
        let vibeProdutosPromise = null;
        if (typeof vibeClient !== 'undefined' && vibeClient) {
            vibeProdutosPromise = vibeClient
                .from('produtos_proposta')
                .select('id, id_int, id_produto, nome_produto, modelo_descri, qtd, created_at, updated_at, amostra_cor_id, amostra_num_id, amostra_status, amostra_obs, amostra_arte_base64, arte_url')
                .order('created_at', { ascending: false });
            promises.push(vibeProdutosPromise);
        }
        
        const results = await Promise.all(promises);
        
        // Se o Vibecode estiver ativo, a resposta de produtos está na lista de resultados
        if (typeof vibeClient !== 'undefined' && vibeClient && vibeProdutosPromise) {
            const produtosResult = results[results.length - 1] || { data: [] };
            const produtos = produtosResult.data || [];
            
            if (produtos.length > 0) {
                console.log('[OS] Carregando do Vibecode...');
                // Passamos os produtos já carregados em paralelo para o loadOrdensFromVibecode
                const loaded = await loadOrdensFromVibecode(pedidosComerciais, produtos);
                if (loaded) {
                    await carregarModelosGlobais().catch(e => console.warn('Erro ao carregar modelos globais:', e));
                    renderOrdens();

                    // A coluna Pagamento chega depois do primeiro desenho, de
                    // propósito: ela é informação de apoio, e segurar a tabela
                    // por ela atrasaria a lista que o atendimento abre de manhã.
                    // Enquanto não chega, a célula mostra o traço.
                    carregarPagamentosGlobais().then(() => renderOrdens())
                        .catch(e => console.warn('Erro ao carregar pagamentos:', e));

                    sincronizarStatusOrdensDinamico().then(() => {
                        renderOrdens();
                    }).catch(e => console.warn('Erro ao sincronizar status:', e));

                    return;
                }
            }
            console.log('[OS] Vibecode sem dados, tentando fallback...');
        }

        // Buscar propostas para o fluxo de fallback apenas se necessário
        let propostasComerciais = [];
        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            try {
                const { data: propData, error: propError } = await supabaseClient
                    .from('propostas')
                    .select('id_int, cliente, vendedor, status_interno, id_cliente, id_faturado')
                    .order('id_int', { ascending: false })
                    .limit(2000);
                if (!propError && propData) {
                    propostasComerciais = propData;
                }
            } catch (err) {
                console.warn('[Supabase] Falha ao carregar tabela propostas:', err);
            }
        }

        // Fonte 2: Supabase do Imposition (Banco único do Vibecode)
        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            const { data, error } = await supabaseClient
                .from('producao_ordens_servico')
                .select('*, producao_os_itens(*)')
                .order('created_at', { ascending: false });
            if (error) throw error;

            let ordensFiltradas = data || [];
            const isDev = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
            if (!isDev || (pedidosComerciais && pedidosComerciais.length > 0)) {
                // A MESMA porta do caminho principal, com a mesma terceira
                // condição: aqui o status vem de `propostasComerciais`, que é o
                // que esta metade do código leu de `propostas`.
                const jaNaGrafica = pedidosJaNaGrafica(propostasComerciais);
                ordensFiltradas = ordensFiltradas.filter(os =>
                    pedidoEntraNoPainel(parseInt(os.numero), pedidosComerciais, state.todasArtes, jaNaGrafica));
            }

            state.ordens = ordensFiltradas.map(os => {
                const savedStatus = lerStatusOverride(os.id);
                let dbStatus = os.status;
                if (dbStatus === 'PRODUÇÃO') dbStatus = 'EM IMPRESSÃO';
                else if (dbStatus === 'ARTE' || dbStatus === 'NOVO') dbStatus = 'ARTE_EM_ANDAMENTO';
                
                // Pré-carrega no estado local os itens buscados para agilizar o collapse e as estatísticas
                // COMENTADO: O cache via producao_os_itens foi removido, pois agora usamos pedidos_modelos em loadOSItens
                // if (os.producao_os_itens) {
                //     state.osItens[os.id] = os.producao_os_itens;
                // }
                
                // Mapear o status_arte comercial
                const osNumeroInt = parseInt(os.numero);
                const pedidoReal = pedidosComerciais.find(ped => String(ped.id_int) === String(osNumeroInt));
                
                // Sobrescrever cliente e vendedor usando a tabela propostas
                const propReal = propostasComerciais.find(pr => String(pr.id_int) === String(osNumeroInt));
                const clienteProposta = propReal?.cliente || propReal?.cliente_nome || propReal?.dados_cliente || os.cliente || '';
                const vendedorProposta = propReal?.vendedor || propReal?.vendedor_nome || os.vendedor || '';
                
                return {
                    ...os,
                    status: savedStatus || dbStatus,
                    status_arte: pedidoReal?.status_arte || null,
                    status_interno: propReal?.status_interno || null,
                    cliente: clienteProposta,
                    vendedor: vendedorProposta,
                    id_cliente: propReal?.id_faturado || propReal?.id_cliente || null,
                    // O NÚMERO do cliente, que é o que aparece ao lado do nome. Não é o
                    // mesmo que o `id_cliente` acima: aquele cai no `id_faturado` quando
                    // existe, porque serve para buscar dados de faturamento e para casar as
                    // numerações do cliente. Os dois quase sempre coincidem, mas divergem
                    // de verdade — o pedido 20940 é do cliente 43520 e fatura no 66163.
                    numero_cliente: propReal?.id_cliente ?? null,
                    data_liberacao: os.data_liberacao || os.created_at,
                    // Sem prazo real, a coluna mostra "--". Ver propostas_os acima.
                    prazo_entrega: os.prazo_entrega || null,
                    _itens_count: os.producao_os_itens ? os.producao_os_itens.length : 0
                };
            });
        } else {
            // Fonte 3: API local (FastAPI)
            const res = await fetch(`${API_BASE_URL}/api/ordens`);
            if (res.ok) {
                const localData = await res.json();
                const isDev = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
                
                const mappedLocalData = localData.map(os => {
                    const osNumeroInt = parseInt(os.numero);
                    const pedidoReal = pedidosComerciais.find(ped => String(ped.id_int) === String(osNumeroInt));
                    
                    const propReal = propostasComerciais.find(pr => String(pr.id_int) === String(osNumeroInt));
                    const clienteProposta = propReal?.cliente || propReal?.cliente_nome || propReal?.dados_cliente || os.cliente || '';
                    const vendedorProposta = propReal?.vendedor || propReal?.vendedor_nome || os.vendedor || '';
                    
                    return {
                        ...os,
                        cliente: clienteProposta,
                        vendedor: vendedorProposta,
                        id_cliente: propReal?.id_faturado || propReal?.id_cliente || null,
                        // O NÚMERO do cliente, que é o que aparece ao lado do nome. Não é o
                        // mesmo que o `id_cliente` acima: aquele cai no `id_faturado` quando
                        // existe, porque serve para buscar dados de faturamento e para casar as
                        // numerações do cliente. Os dois quase sempre coincidem, mas divergem
                        // de verdade — o pedido 20940 é do cliente 43520 e fatura no 66163.
                        numero_cliente: propReal?.id_cliente ?? null,
                        status_arte: pedidoReal?.status_arte || os.status_arte || null,
                        status_interno: propReal?.status_interno || os.status_interno || null
                    };
                });

                // AUTO-SYNC local: popular state.todasArtes no modo local
                if (typeof supabaseClient === 'undefined' || !supabaseClient) {
                    state.todasArtes = mappedLocalData.map(os => ({
                        id_int: parseInt(os.numero),
                        status: os.status_arte || 'Em Arte',
                        nome_evento: 'Show Local',
                        designer_nome: 'Designer Local',
                        designer_uid: 'local-designer',
                        entrega_dados: ''
                    }));
                }

                if (!isDev || (pedidosComerciais && pedidosComerciais.length > 0)) {
                    state.ordens = mappedLocalData.filter(os => {
                        const osNumeroInt = parseInt(os.numero);
                        const temNoComercial = pedidosComerciais.some(ped => String(ped.id_int) === String(osNumeroInt));
                        // `arteFoiLancada`: a mesma régua da porta dos painéis —
                        // linha de arte vazia não conta como arte lançada.
                        const temNasArtes = (state.todasArtes || []).some(a => String(a.id_int) === String(osNumeroInt) && arteFoiLancada(a));
                        return temNoComercial || temNasArtes;
                    });
                } else {
                    state.ordens = mappedLocalData;
                }
            } else {
                state.ordens = [];
            }
        }
        await sincronizarStatusOrdensDinamico();
        carregarModelosGlobais().then(() => renderOrdens()).catch(e => console.warn('Erro modelos globais:', e));
        carregarPagamentosGlobais().then(() => renderOrdens()).catch(e => console.warn('Erro pagamentos:', e));
        renderOrdens();
    } catch (e) {
        console.error('Erro ao carregar OS:', e);
        toast('Erro ao carregar Ordens de Serviço: ' + e.message, 'error');
    }
}

/**
 * Há sessão do Supabase nesta aba?
 *
 * A estação da gráfica é servida pelo agente local na porta 9000 e roda este
 * mesmo arquivo. Lá o operador entra pelo código local (`iniciarAcessoLocal`),
 * SEM sessão do Supabase — por projeto. Ou seja: toda chamada dela sai como
 * `anon`, e as tabelas fechadas para o `anon` recusam com 401.
 *
 * Quem responde é o próprio supabase-js, lendo o que está guardado no
 * navegador: nenhuma ida à rede, e nenhuma contabilidade nossa
 * (`window._currentUser`) para desencontrar quando a sessão expira sozinha.
 */
async function temSessaoDoSupabase() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return false;
    try {
        const { data } = await supabaseClient.auth.getSession();
        return !!(data && data.session && data.session.user);
    } catch (e) {
        return false;
    }
}

/**
 * Busca todos os links ativos no banco e popula state.linksCliente
 * para que a Fila de Arte exiba os links já existentes ao carregar.
 *
 * Sem sessão, nem pede. `pedidos_links_cliente` guarda o TOKEN do link de cada
 * cliente e foi fechada para a chave pública em 16/08/2026 — de propósito, e
 * continua fechada. O `sql/link_cliente_fechar_a_chave_publica.sql` supôs que
 * "a estação não consome esta tabela", o que vale para a TELA (a Fila de Arte
 * não aparece lá) mas não valia para este carregador, que roda em todo
 * `loadOrdens()`: em 01/09/2026 eram 143 recusas em 26h, todas com
 * `referer: http://127.0.0.1:9000/`.
 */
async function carregarLinksExistentes() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;
    if (!await temSessaoDoSupabase()) return;
    try {
        const { data, error } = await supabaseClient
            .from('pedidos_links_cliente')
            .select('os_id, numero_pedido, token, status_arte, arte_pronta_em, cliente_abriu_em')
            .eq('ativo', true);
        if (error) {
            if (error.code === '42P01') return; // tabela ainda não existe
            throw error;
        }
        if (!state.linksCliente) state.linksCliente = {};
        if (!state.linksClienteData) state.linksClienteData = {};
        const base = window.location.origin;
        (data || []).forEach(row => {
            state.linksCliente[row.os_id] = `${base}/cliente/${row.numero_pedido}-${row.token}`;
            state.linksClienteData[row.os_id] = row;
        });
        console.log(`[Links] ${(data || []).length} link(s) de cliente carregado(s).`);
    } catch (e) {
        console.warn('[Links] Erro ao carregar links existentes:', e.message);
    }
}

/**
 * Busca a tabela pedidos_artes de forma global (simplificada) para 
 * montar as estatísticas reais na Lista de Arte sem depender de cliques individuais.
 */
async function carregarArtesGlobais() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;
    try {
        const { data, error } = await supabaseClient
            .from('pedidos_artes')
            .select('id_int, status, nome_evento, designer_nome, designer_uid, entrega_dados')
            .order('created_at', { ascending: false });
        if (error) {
            if (error.code === '42P01') return; // tabela não existe
            throw error;
        }
        state.todasArtes = data || [];
        console.log(`[Artes] ${state.todasArtes.length} registros de arte carregados globalmente.`);
    } catch (e) {
        console.warn('[Artes] Erro ao carregar artes globais:', e.message);
    }
}

/**
 * As cobranças dos pedidos que estão na tela, para a coluna Pagamento da Lista
 * de Arte.
 *
 * ## O que ela busca, e o que ela deixa para trás
 *
 * Só `id_int` e `status`: a coluna precisa responder UMA pergunta — está pago?
 * `url_cobranca`, `pix_copia_cola` e `linha_digitavel` não têm o que fazer numa
 * listagem, e são justamente o que não se espalha por telas que não vão usar.
 *
 * A cobrança CANCELADA fica fora já na consulta. São 331 no banco, e são
 * cobrança que a gráfica desfez: contá-las impediria para sempre o selo de um
 * pedido recotado. É a mesma exclusão que a `link_cliente_pedido` faz para o
 * cliente — o porquê inteiro está em `pagamento-do-pedido.js`.
 *
 * ## Por que em blocos de 200
 *
 * Mesma razão do `carregarModelosGlobais` logo abaixo: o `.in()` do PostgREST
 * vira lista de valores na URL, e a Lista de Arte abre com milhares de pedidos.
 * Uma URL só estouraria o limite do servidor e a consulta voltaria vazia --
 * sem erro, o que é pior: a coluna inteira ficaria em branco e ninguém saberia
 * por quê.
 *
 * Falhar aqui não trava a tela. Sem esta consulta a coluna mostra o traço de
 * "sem informação", que é a verdade: não sabemos.
 */
async function carregarPagamentosGlobais() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;
    if (!state.ordens || state.ordens.length === 0) return;

    try {
        const numeros = state.ordens.map(os => parseInt(os.numero)).filter(n => !isNaN(n));
        const bloco = 200;
        let todas = [];

        for (let i = 0; i < numeros.length; i += bloco) {
            const { data, error } = await supabaseClient
                .from('pagamentos_v2')
                .select('id_int, status')
                .in('id_int', numeros.slice(i, i + bloco))
                .neq('status', 'CANCELADO');
            if (error) throw error;
            if (data) todas = todas.concat(data);
        }

        state.pagamentosGlobais = {};
        todas.forEach(c => {
            const chave = String(c.id_int);
            if (!state.pagamentosGlobais[chave]) state.pagamentosGlobais[chave] = [];
            state.pagamentosGlobais[chave].push(c);
        });
        console.log(`[Pagamentos] ${todas.length} cobranca(s) carregada(s) para a coluna Pagamento.`);
    } catch (e) {
        console.warn('[Pagamentos] Erro ao carregar as cobrancas:', e.message);
    }
}

/**
 * O carimbo PAGO, no Storage do Supabase.
 *
 * Endereço mandado pelo usuário em 25/08/2026. Fica aqui, e não desenhado em
 * CSS ou SVG: arte da empresa se usa como arquivo -- redesenhar produz uma
 * segunda versão que envelhece separada da que ele controla.
 */
const SELO_PAGO_URL = 'https://vwbtitjlpelrcnsytzqw.supabase.co/storage/v1/object/public/app-imagens/1787495041552_Pago.png';

/**
 * A célula da coluna Pagamento: o selo PAGO, ou o traço de quem ainda deve.
 *
 * O usuário pediu em 25/08/2026 uma coluna entre Status e Itens, com "uma logo
 * com a informação PAGO" nos pedidos sinalizados como pagos. O selo é o arquivo
 * que ele mandou, usado como veio -- carimbo verde, fundo transparente.
 *
 * ## Só o pago ganha marca
 *
 * O pedido em aberto fica com um traço discreto, e não com um selo vermelho.
 * Medido no banco em 25/08/2026, dos 2.629 pedidos hoje na Lista de Arte 1.950
 * estão pagos: um selo em cada um dos outros 679 encheria a coluna de alarme
 * para o estado NORMAL de um pedido que acabou de entrar. Quem precisa saltar
 * aos olhos é o que já foi pago -- que é o que libera o trabalho.
 *
 * O `title` diz em palavras o que o selo diz em imagem, para quem passa o mouse
 * e para o leitor de tela: imagem sozinha não se explica.
 *
 * O `onerror` da imagem cai num badge de texto. Sem ele, uma falha de rede
 * deixaria a célula visualmente IGUAL à do pedido não pago, e o atendente leria
 * "não pago" onde a verdade é "não carregou".
 */
function celulaDePagamentoHtml(os) {
    const cobrancas = (state.pagamentosGlobais || {})[String(os.numero)] || [];
    const pago = typeof pedidoEstaPago === 'function' && pedidoEstaPago(cobrancas);

    if (!pago) {
        const quantas = cobrancas.length;
        const titulo = quantas
            ? (quantas === 1 ? 'Cobrança em aberto' : quantas + ' cobranças, nem todas pagas')
            : 'Sem cobrança gerada';
        return `<td style="text-align: center; vertical-align: middle;">`
             + `<span style="color: var(--text-dim);" title="${titulo}">--</span></td>`;
    }

    return `<td style="text-align: center; vertical-align: middle;">`
         + `<img src="${SELO_PAGO_URL}" alt="Pago" title="Pedido pago" `
         + `style="height: 44px; width: auto; display: inline-block;" `
         + `onerror="this.replaceWith(Object.assign(document.createElement('span'), `
         + `{className:'badge badge-teal', textContent:'✅ PAGO'}));"></td>`;
}

async function carregarModelosGlobais() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;
    if (!state.ordens || state.ordens.length === 0) return;

    try {
        const todosNumeros = state.ordens.map(os => parseInt(os.numero)).filter(n => !isNaN(n));
        const chunkSize = 200;
        let todosModelos = [];
        
        for (let i = 0; i < todosNumeros.length; i += chunkSize) {
            const chunk = todosNumeros.slice(i, i + chunkSize);
            const { data, error } = await supabaseClient
                .from('pedidos_modelos')
                .select('id, id_int, status_arte, status_impressao, status_impressao_em, status_producao, quantidade, ordem, nome_modelo, amostra_arte_base64, arte_url')
                .in('id_int', chunk);
                
            if (error) throw error;
            if (data) todosModelos = todosModelos.concat(data);
        }
        
        state.modelosGlobais = {};
        todosModelos.forEach(m => {
            if (!state.modelosGlobais[m.id_int]) state.modelosGlobais[m.id_int] = [];
            m.impressao = normalizarStatusImpressao(m.status_impressao || m.status_producao);
            m.quantidade = parseInt(m.quantidade || 0);
            m.amostra_status = m.status_arte || m.amostra_status || '';
            m.amostra_arte_base64 = m.amostra_arte_base64 || '';
            m.arte_url = m.arte_url || '';
            m.ordem = m.ordem !== undefined ? m.ordem : null;
            m.modelo = m.nome_modelo || '';
            state.modelosGlobais[m.id_int].push(m);
        });
        console.log(`[Modelos] ${todosModelos.length} modelos carregados globalmente para contagem.`);
        conferirColunasQrIdealDosPedidos();
    } catch (e) {
        console.warn('[Modelos] Erro ao carregar modelos globais:', e.message);
    }
}

/**
 * Avisa quando dois modelos do mesmo pedido caem na mesma coluna do pool do
 * QR Ideal.
 *
 * Dois modelos cujos `id` diferem em exatamente 100 recebem os MESMOS códigos,
 * e como o número do pedido gravado no QR é o mesmo para os dois, nada os
 * separa: sairiam dois ingressos idênticos no mesmo evento. O motor recusa a
 * folha quando isso acontece dentro de um trabalho, mas só o painel conhece o
 * pedido inteiro — é aqui que dá para avisar antes de alguém imprimir.
 */
function conferirColunasQrIdealDosPedidos() {
    if (typeof window.conferirColunasQrIdeal !== 'function') return;
    const avisados = [];
    Object.keys(state.modelosGlobais || {}).forEach((pedido) => {
        const modelos = (state.modelosGlobais[pedido] || []).map(m => m.id);
        if (modelos.length < 2) return;
        const choques = window.conferirColunasQrIdeal(pedido, modelos);
        choques.forEach(c => avisados.push(
            `pedido ${pedido}, coluna ${c.coluna}: modelos ${c.modelos.join(' e ')}`
        ));
    });
    if (!avisados.length) return;
    console.warn('[QR Ideal] choque de coluna:', avisados);
    // Chamava `showToast`, que nao existe em lugar nenhum do frontend -- a
    // funcao de aviso deste projeto chama-se `toast`. O guard `typeof` fazia
    // a chamada falhar em silencio, e o operador nunca via este aviso: so o
    // console. Achado na auditoria da documentacao de 15/08/2026, que dizia
    // "o painel avisa sobre o pedido inteiro" e nao avisava.
    toast(
        `⚠️ QR Ideal — ${avisados.join('; ')}. Estes modelos gerariam ingressos ` +
        `com o mesmo código no mesmo evento. Não imprimir com QR Ideal antes de resolver.`,
        'error'
    );
}



/**
 * Carrega OS do Vibecode agrupando produtos_proposta por id_int
 * Cada id_int = 1 proposta = 1 OS virtual
 * Retorna true se conseguiu carregar, false se não há dados
 */
async function loadOrdensFromVibecode(pedidosComerciais = [], produtosPreloaded = null) {
    try {
        let produtos = produtosPreloaded;
        if (!produtos) {
            const { data, error } = await vibeClient
                .from('produtos_proposta')
                .select('*')
                .order('created_at', { ascending: false });

            if (error) {
                console.error('[Vibecode] Erro ao ler produtos_proposta:', error);
                return false;
            }
            produtos = data;
        }

        if (!produtos || produtos.length === 0) return false;

        // Buscar propostas (tabela pai) se existir e for acessível
        //
        // ## Por que a leitura não se limita aos pedidos que têm produto
        //
        // Até 01/09/2026 esta consulta perguntava só pelos `id_int` que
        // apareciam em `produtos_proposta`, e isso deixava a porta dos painéis
        // fechada por dentro: `pedidosJaNaGrafica` é montado a partir DESTAS
        // linhas, então um pedido sem produto nunca chegava aqui, nunca entrava
        // no conjunto "já está na gráfica" e nunca era desenhado — mesmo com o
        // ERP dizendo EXPEDIÇÃO.
        //
        // Foi o caso do pedido 21347, levantado pelo usuário: proposta em
        // EXPEDIÇÃO, com arte lançada, e invisível em todos os três painéis.
        //
        // São três origens, unidas por `id_int`:
        //   1. quem tem produto     — a consulta de sempre;
        //   2. quem tem arte        — `pedidos_artes`, que é o que "já teve arte
        //      feita" quer dizer neste projeto (`state.todasArtes`). Linha
        //      criada pelo ERP e nunca preenchida não conta: é `arteFoiLancada`
        //      quem responde, a mesma régua da porta dos painéis;
        //   3. quem já está na gráfica — pela palavra do ERP, sem depender de
        //      produto nem de arte (`SINAIS_SAIU_DA_ARTE`).
        //
        // A terceira é consulta por STATUS, e não por lista de números: é
        // justamente a que descobre pedido que nenhuma das outras duas conhece.
        let propostas = [];
        const COLUNAS_PROPOSTA = 'id, id_int, cliente, vendedor, status_interno, created_at, id_cliente, id_faturado, frete_escolhido';
        try {
            const idsComProduto = produtos.map(p => p.id_int).filter(Boolean);
            const idsComArte = (state.todasArtes || []).filter(arteFoiLancada).map(a => a.id_int).filter(Boolean);
            const uniqueIdInts = [...new Set([...idsComProduto, ...idsComArte])];

            const porNumero = new Map();
            const guardar = (linhas) => (linhas || []).forEach(l => {
                if (l && l.id_int != null) porNumero.set(String(l.id_int), l);
            });

            if (uniqueIdInts.length > 0) {
                const { data: propData, error: propError } = await vibeClient
                    .from('propostas')
                    .select(COLUNAS_PROPOSTA)
                    .in('id_int', uniqueIdInts);
                if (!propError) guardar(propData);
            }

            // Quem o ERP já mandou para a gráfica, tendo produto ou não.
            //
            // Do maior número para o menor de propósito: o PostgREST corta a
            // resposta num teto de linhas, e se um dia esta consulta encostar
            // nele o que fica de fora tem de ser o pedido mais antigo — não o
            // que a gráfica está fabricando hoje. São 82 pedidos em 01/09/2026.
            const { data: naGraficaData, error: naGraficaErr } = await vibeClient
                .from('propostas')
                .select(COLUNAS_PROPOSTA)
                .in('status_interno', SINAIS_SAIU_DA_ARTE)
                .order('id_int', { ascending: false });
            if (!naGraficaErr) guardar(naGraficaData);

            propostas = [...porNumero.values()];
        } catch (pe) {
            console.warn('[Vibecode] Não foi possível ler tabela propostas (usando fallbacks):', pe);
        }

        // O PRAZO DE ENTREGA mora em `propostas_os.data_termino`.
        //
        // É o campo real, apontado pelo usuário em 20/08/2026. Até então a
        // coluna mostrava um prazo INVENTADO (`getFallbackPrazo`: data de
        // criação + 3 a 7 dias, pelo resto da divisão do número do pedido) —
        // ele existia só para o filtro "Para Hoje / Atrasados" ter em que se
        // apoiar enquanto o campo verdadeiro não fosse definido.
        //
        // `propostas_os` é tabela nova do parceiro e ainda está sendo
        // preenchida: pedido sem linha ali fica sem prazo, e a coluna mostra
        // "--". É de propósito — data de entrega chutada numa gráfica é pior
        // do que campo vazio, pela mesma razão que derrubou os nomes de cliente
        // de mentira.
        let prazosPorPedido = {};

        // O CÓDIGO DE RASTREIO vem de carona nesta mesma consulta.
        //
        // Pedido do usuário em 25/08/2026: quando já existe o número do
        // conhecimento do SEDEX, clicar nele abre o rastreamento. Até então o
        // código só era mostrado na aba de Entrega do LINK DO CLIENTE -- a
        // gráfica, que é quem posta, não o via em tela nenhuma.
        //
        // Não custou consulta nova: `propostas_os` já era lida aqui pelo prazo
        // de entrega, e bastou pedir mais uma coluna. Uma segunda ida ao banco
        // para um campo de treze caracteres seria desperdício num painel que
        // abre com milhares de pedidos.
        let rastreioPorPedido = {};
        try {
            // Os mesmos pedidos da consulta de propostas acima — inclusive os
            // que não têm produto. Sem isso o pedido sem produto entraria na
            // lista sem prazo e sem código de rastreio, que é justamente a
            // informação que a expedição procura nele.
            const idsParaPrazo = [...new Set([
                ...produtos.map(p => p.id_int),
                ...propostas.map(pr => pr.id_int),
            ].filter(Boolean))];
            if (idsParaPrazo.length > 0) {
                const { data: osData, error: osError } = await vibeClient
                    .from('propostas_os')
                    .select('id_int, data_termino, codigo_rastreamento')
                    .in('id_int', idsParaPrazo);
                if (osError) throw osError;
                (osData || []).forEach(linha => {
                    if (!linha) return;
                    if (linha.data_termino) prazosPorPedido[String(linha.id_int)] = linha.data_termino;
                    const codigo = (linha.codigo_rastreamento || '').trim();
                    if (codigo) rastreioPorPedido[String(linha.id_int)] = codigo;
                });
            }
        } catch (oe) {
            console.warn('[Vibecode] Não foi possível ler propostas_os (prazo de entrega):', oe.message || oe);
        }

        // pedidosComerciais ignorado/tabela 'pedidos' inexistente

        const isDev = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';

        // Quem o ERP já entregou à gráfica. Ver `pedidoEntraNoPainel`.
        const jaNaGrafica = pedidosJaNaGrafica(propostas);

        // Agrupar por id_int (cada id_int = 1 proposta = 1 OS)
        const grouped = {};

        // Monta a OS a partir da PROPOSTA. O produto entra só como data de
        // criação, porque é o único campo dele que a OS usa — e é por isso que
        // um pedido sem produto nenhum consegue nascer aqui do mesmo jeito,
        // com a data da própria proposta no lugar.
        const criarOS = (key, createdAt) => {
            const osId = `vibe_${key}`;
            const dbStatusArte = state.linksClienteData && state.linksClienteData[osId] && state.linksClienteData[osId].status_arte;
            const savedStatus = lerStatusOverride(osId) || dbStatusArte;

            // Buscar dados reais da proposta
            const propReal = propostas.find(pr => pr.id_int === key || pr.id === key || pr.numero === key);

            // Buscar dados do pedido comercial
            const pedidoReal = pedidosComerciais.find(ped => String(ped.id_int) === String(key));

            // Mapear campos com fallbacks determinísticos
            const cliente = propReal?.cliente || propReal?.cliente_nome || propReal?.dados_cliente || '';
            const vendedor = propReal?.vendedor || propReal?.vendedor_nome || '';
            const nascimento = createdAt || propReal?.created_at || null;
            const dataLiberacao = propReal?.data_liberacao || propReal?.data_libera || nascimento;
            const prazoEntrega = prazosPorPedido[String(key)] || null;

            // Dados comerciais reais
            const dataPedido = pedidoReal?.data_pedido || null;
            const valorTotal = pedidoReal?.valor_total || null;

            return {
                id: osId,
                numero: key,
                status: savedStatus || 'Em Arte',
                status_arte: pedidoReal?.status_arte || null,
                status_interno: propReal?.status_interno || null,
                cliente: cliente,
                vendedor: vendedor,
                id_cliente: propReal?.id_faturado || propReal?.id_cliente || null,
                // O NÚMERO do cliente, que é o que aparece ao lado do nome. Não é o
                // mesmo que o `id_cliente` acima: aquele cai no `id_faturado` quando
                // existe, porque serve para buscar dados de faturamento e para casar as
                // numerações do cliente. Os dois quase sempre coincidem, mas divergem
                // de verdade — o pedido 20940 é do cliente 43520 e fatura no 66163.
                numero_cliente: propReal?.id_cliente ?? null,
                data_liberacao: dataLiberacao,
                data_pedido: dataPedido,
                valor_total: valorTotal,
                prazo_entrega: prazoEntrega,
                // O número do conhecimento, quando o pedido já foi postado.
                // Quem o mostra é a coluna Frete do Painel do Acabamento.
                codigo_rastreamento: rastreioPorPedido[String(key)] || null,
                frete_escolhido: propReal?.frete_escolhido || null,
                observacoes: `Proposta #${key} -- Vibecode`,
                criado_por: null,
                created_at: nascimento,
                updated_at: nascimento,
                _itens_count: 0,
                _source: 'vibecode',
                _itens_raw: []
            };
        };

        produtos.forEach(p => {
            const key = p.id_int;

            // FILTRAR: Se for produção (não-dev) ou se tiver pedidosComerciais populada, filtra
            if (!isDev || (pedidosComerciais && pedidosComerciais.length > 0)) {
                if (!pedidoEntraNoPainel(key, pedidosComerciais, state.todasArtes, jaNaGrafica)) {
                    return; // ignora este produto e não cria a OS
                }
            }

            if (!grouped[key]) grouped[key] = criarOS(key, p.created_at);
            grouped[key]._itens_count++;
            grouped[key]._itens_raw.push(p);

            // Usar a data mais recente
            if (p.updated_at && p.updated_at > grouped[key].updated_at) {
                grouped[key].updated_at = p.updated_at;
            }
        });

        // ── O pedido que passa na porta mas não tem produto ─────────────────
        //
        // O laço acima percorre PRODUTOS, então quem não tem nenhum jamais era
        // montado — e some das três telas por inteiro, mesmo com arte lançada e
        // com o ERP dizendo que o material é da gráfica. A porta
        // (`pedidoEntraNoPainel`) já o aceitava desde 24/08/2026; o que faltava
        // era alguém construí-lo.
        //
        // Ele entra com zero itens, que é a verdade do que o ERP tem: a coluna
        // Itens mostra 0 e a linha abre normalmente. Preferir a linha com zero
        // itens à ausência dela é a mesma escolha de 24/08 — pedido fabricado e
        // invisível é pior do que pedido visível e incompleto.
        (propostas || []).forEach(pr => {
            const key = pr.id_int;
            if (!key || grouped[key]) return;
            if (!pedidoEntraNoPainel(key, pedidosComerciais, state.todasArtes, jaNaGrafica)) return;
            grouped[key] = criarOS(key, pr.created_at);
        });

        // Converter para array ordenado por número (desc)
        state.ordens = Object.values(grouped).sort((a, b) => b.numero - a.numero);

        // Pré-carregar itens no formato esperado pelo Imposition
        state.ordens.forEach(os => {
            state.osItens[os.id] = (os._itens_raw || []).map(p => mapVibecodeProdutoToOSItem(p, os.id));
            delete os._itens_raw; // limpar dados brutos
        });

        console.log(`[Vibecode] ${state.ordens.length} OS carregadas, ${produtos.length} itens totais`);
        return true;
    } catch (e) {
        console.error('[Vibecode] Erro na leitura:', e);
        return false;
    }
}

/**
 * Transforma um produto_proposta do Vibecode → formato os_itens do Imposition
 */
function mapVibecodeProdutoToOSItem(p, osId) {
    // Detectar tipo de produto pelo nome
    const nomeProd = (p.nome_produto || '').toUpperCase();
    
    // Buscar o setor real do produto globalmente cadastrado.
    // Sem setor_pcp o item fica SEM setor, e não em PVC: quem manda é a coluna
    // da tabela produtos. O padrão antigo jogava em PVC todo produto ainda não
    // cadastrado, e o operador de PVC via pedido que não era dele.
    const prodObj = (state.produtosGlobais || []).find(pg => String(pg.id_produto) === String(p.id_produto));
    let setor = prodObj && prodObj.setor_pcp ? prodObj.setor_pcp : '';
    
    let produto = nomeProd;
    
    // Mapear nomes conhecidos
    if (nomeProd.includes('TRIBAND')) produto = 'TRIBAND';
    else if (nomeProd.includes('MOBI')) produto = 'MOBI';
    else if (nomeProd.includes('BRACELETE')) produto = 'TEX PLUS';
    else if (nomeProd.includes('CORD')) produto = 'CORDÃO';
    else if (nomeProd.includes('TEX')) produto = 'TEX';
    else if (nomeProd.includes('PULSEIRA')) produto = 'TEX';

    // Extrair formato da descrição (ex: "25×2cm" → "Mobi")
    const formato = p.modelo_descri || 'Mobi';

    return {
        id: `vibe_item_${p.id}`,
        os_id: osId,
        setor: setor,
        produto: produto,
        modelo: `VIBE-${p.id_int}-${p.id}`,
        formato: formato,
        formato_id: null, // matching automático vai preencher
        quantidade: p.qtd || 0,
        num_inicial: 1,
        num_final: p.qtd || 0,
        cor_id: null,
        blocos: 'N',
        verso: false,
        numeracao: 'SEQUENCIAL',
        numeracao_id: null,
        aprovacao: 'APROVADA',
        impressao: (() => {
            const impOverrides = JSON.parse(localStorage.getItem('vibe_item_impressao_overrides') || '{}');
            return impOverrides[`vibe_item_${p.id}`] || 'AGUARD.';
        })(),
        sheets_per_block: p.bloco && parseInt(p.bloco) > 0 ? parseInt(p.bloco) : (() => {
            const format = state.formatos.find(f => String(f.id) === String(p.formato_id));
            return format ? (parseInt(format.default_sheets_per_block) || 50) : 50;
        })(),
        
        c_ini: p.C_INI || p.c_ini || 1,
        q_cam: p.Q_CAM || p.q_cam || p.qtd_locais || p.qtd_cam || 0,
        l_cam: p.L_CAM || p.l_cam || p.lotacao_cam || p.lotacao || p.lotacao_por_local || 1,
        observacoes: p.modelo_descri || p.nome_produto || '',
        amostra_arte_base64: p.amostra_arte_base64 || p.arte_url || '',
        arte_url: p.arte_url || p.amostra_arte_base64 || '',
        created_at: p.created_at,
        updated_at: p.updated_at || p.created_at,
        
        // --- Campos de Amostra (salvos no BD) ---
        amostra_cor_id: p.amostra_cor_id || null,
        amostra_num_id: p.amostra_num_id || null,
        amostra_arte_base64: p.amostra_arte_base64 || null,
        amostra_status: (() => {
            const overrides = JSON.parse(localStorage.getItem('vibe_item_amostra_overrides') || '{}');
            return (overrides[`vibe_item_${p.id}`] && overrides[`vibe_item_${p.id}`].amostra_status) || p.amostra_status || 'PENDENTE';
        })(),
        amostra_obs: (() => {
            const overrides = JSON.parse(localStorage.getItem('vibe_item_amostra_overrides') || '{}');
            return (overrides[`vibe_item_${p.id}`] && overrides[`vibe_item_${p.id}`].amostra_obs) || p.amostra_obs || '';
        })(),
        
        _source: 'vibecode',
        _vibe_produto_id: p.id,
        _vibe_id_produto: p.id_produto,
        _nome_original: p.nome_produto
    };
}

// ─────────────────────────────────────────────────────────────────────────────
// REPARO DO SETOR DOS ITENS
//
// Os itens de um pedido são mapeados assim que as OS chegam, e o setor sai de
// produtos.setor_pcp via state.produtosGlobais. Só que as duas cargas são
// independentes e o loadAll atribui produtosGlobais apenas quando TODAS as seis
// buscas do Promise.all terminam. Medido na produção: itens mapeados aos
// 1.501 ms, produtosGlobais preenchido aos 3.207 ms.
//
// Nessa janela o find não acha nada, o item nasce sem setor e o resultado fica
// gravado — ninguém remapeia depois. O efeito era mascarado pelo padrão 'PVC'
// (removido na v515): antes tudo caía em PVC, agora os quatro filtros de setor
// ficam vazios.
//
// Em vez de tentar ordenar duas cargas assíncronas, o setor é reparado sempre
// que der: ao chegarem os produtos e a cada render. É idempotente e só toca em
// item que está sem setor, então não desfaz escolha nenhuma.
// ─────────────────────────────────────────────────────────────────────────────

/** Índice id_produto -> setor_pcp. */
function _mapaSetorPorProduto() {
    const mapa = new Map();
    for (const p of (state.produtosGlobais || [])) {
        if (p && p.id_produto !== null && p.id_produto !== undefined) {
            mapa.set(String(p.id_produto), p.setor_pcp || '');
        }
    }
    return mapa;
}

/**
 * Preenche o setor dos itens que nasceram sem ele por terem sido mapeados
 * antes de os produtos chegarem. Devolve quantos foram reparados.
 */
function repararSetoresDosItens() {
    if (!state.produtosGlobais || !state.produtosGlobais.length) return 0;
    if (!state.osItens) return 0;

    const mapa = _mapaSetorPorProduto();
    let reparados = 0;

    for (const osId of Object.keys(state.osItens)) {
        for (const item of (state.osItens[osId] || [])) {
            if (!item || item.setor) continue;   // já tem setor: não mexe
            const pid = item._vibe_id_produto || item.id_produto || item.produto_id;
            if (pid === null || pid === undefined || pid === '') continue;
            const setor = mapa.get(String(pid));
            if (setor) { item.setor = setor; reparados++; }
        }
    }
    return reparados;
}
window.repararSetoresDosItens = repararSetoresDosItens;

/**
 * Carrega os itens de uma OS específica
 */
async function loadOSItens(osId) {
    try {
        if (!state._loadingOSItens) state._loadingOSItens = {};
        if (state._loadingOSItens[osId]) return;
        state._loadingOSItens[osId] = true;

        const os = typeof findOSInState === 'function' ? findOSInState(osId) : (state.ordens ? state.ordens.find(o => o.id === osId || String(o.id) === String(osId) || String(o.numero) === String(osId)) : null);
        if (!os) {
            state._loadingOSItens[osId] = false;
            return;
        }
        const targetId = os.id || osId;

        // Se não carregado ainda, ou se tem apenas o cache básico do Vibecode, busca a fonte de dados principal
        const needsFullLoad = !state.osItens[osId] || state.osItens[osId].length === 0 || state.osItens[osId].some(i => i._dbLoaded !== true);
        if (needsFullLoad) {
            if (typeof supabaseClient !== 'undefined' && supabaseClient) {
                const queryNum = parseInt(os.numero);
                const { data, error } = await supabaseClient
                    .from('pedidos_modelos')
                    .select('*')
                    .eq('id_int', queryNum)
                    .order('ordem', { ascending: true });
                if (error) throw error;
                
                // Buscar nome do produto original da proposta e os IDs de cor/numeração salvos pelo parceiro
                const { data: propData } = await supabaseClient
                    .from('produtos_proposta')
                    .select('*')
                    .eq('id_int', queryNum);
                
                if (data && data.length > 0) {
                    // Trocas que o pedido impos por cima do que estava escolhido.
                    // Vao para um aviso na tela: mudar a cor ou a numeracao muda o
                    // que sai na impressora, e o operador precisa ver acontecer —
                    // ainda mais porque um gabarito RENOMEADO no catalogo produz o
                    // mesmo desencontro que uma troca feita pelo parceiro, e so
                    // quem esta olhando o pedido sabe distinguir os dois.
                    const seguiramOPedido = [];

                    // Usar pedidos_modelos como fonte principal
                    state.osItens[osId] = data.map(item => {
                        const prop = propData?.find(p => p.id === item.id_produto_proposta_origem);
                        
                        // Remapear o status_arte do banco para o amostra_status usado pela UI
                        let statusFrontend = 'PENDENTE';
                        if (item.status_arte === 'AGUARDANDO_CLIENTE' || item.status_arte === 'PRONTO') statusFrontend = 'PRONTO';
                        else if (item.status_arte === 'APROVADA_CLIENTE' || item.status_arte === 'APROVADA') statusFrontend = 'APROVADA';
                        else if (item.status_arte === 'REPROVADA_CLIENTE' || item.status_arte === 'REPROVADA') statusFrontend = 'REPROVADA';

                        // O parceiro edita a cor e a numeracao pelo NOME (padrao /
                        // gabarito_operacional); os ids sao cache nosso. Sem esta
                        // conferencia o id velho vencia para sempre e a troca feita
                        // no ERP nunca chegava a tela — nem apertando F5, porque o
                        // desencontro esta na linha do banco. A regra (e o motivo de
                        // ela nao ser igual para os dois) esta em
                        // frontend/cor-numeracao-do-modelo.js.
                        const idsDoBanco = (typeof reconciliarCorNumDoModelo === 'function')
                            ? reconciliarCorNumDoModelo(item, state.cores, state.numeracoes)
                            : { corId: item.amostra_cor_id, numId: item.amostra_num_id };

                        // So avisa quando havia uma escolha anterior sendo substituida.
                        // Preencher um campo que estava vazio nao e novidade para ninguem.
                        const _nomeNoCatalogo = (catalogo, id) => {
                            const linha = id ? (catalogo || []).find(x => String(x.id) === String(id)) : null;
                            return linha ? (linha.name || linha.tipo || '') : '';
                        };
                        const _modelo = item.nome_modelo || 'Modelo';
                        if (idsDoBanco.corTrocada && item.amostra_cor_id) {
                            seguiramOPedido.push(`${_modelo}: cor ${_nomeNoCatalogo(state.cores, item.amostra_cor_id)} → ${_nomeNoCatalogo(state.cores, idsDoBanco.corId)}`);
                        }
                        if (idsDoBanco.numTrocada && item.amostra_num_id) {
                            seguiramOPedido.push(`${_modelo}: numeração ${_nomeNoCatalogo(state.numeracoes, item.amostra_num_id)} → ${_nomeNoCatalogo(state.numeracoes, idsDoBanco.numId)}`);
                        }

                        const resolvedNumId = idsDoBanco.numId || (prop ? prop.amostra_num_id : null);
                        const matchedNum = resolvedNumId ? (state.numeracoes || []).find(n => String(n.id) === String(resolvedNumId)) : null;
                        const numIsDuplex = isNumeracaoDuplex(matchedNum);
                        // Fonte de verdade: print_mode da numeração em producao_numeracoes
                        let resolvedVersoTipo;
                        if (matchedNum) {
                            // Numeração encontrada: usar print_mode da numeração
                            resolvedVersoTipo = numIsDuplex ? 'FxVerso' : 'Frente';
                        } else {
                            // Sem numeração: usar verso_tipo salvo no pedido, convertendo valores legados
                            const vt = item.verso_tipo;
                            if (vt === 'FxVerso' || vt === 'VERSO COMUM' || vt === 'VERSO VARIÁVEL' || vt === 'VERSO VARIAVEL' || vt === 'FRENTE E VERSO') {
                                resolvedVersoTipo = 'FxVerso';
                            } else {
                                resolvedVersoTipo = 'Frente';
                            }
                        }
                        const itemVerso = (resolvedVersoTipo === 'FxVerso');

                        const resolvedNumeracao = matchedNum ? (matchedNum.name || matchedNum.tipo) : (item.gabarito_operacional || item.tipo_numeracao || item.numeracao);
                        const resolvedGabarito = matchedNum ? (matchedNum.name || matchedNum.tipo) : (item.gabarito_operacional || null);

                        const mapped = {
                            ...item,
                            produto: item.nome_modelo || 'Modelo',
                            nome_produto_real: prop ? prop.nome_produto : null,
                            id_produto: prop ? prop.id_produto : (item.id_produto || null),
                            modelo: item.id ? item.id.toString() : '--',
                            cor: item.padrao || item.cor || 'STD',
                            numeracao: resolvedNumeracao,
                            gabarito_operacional: resolvedGabarito,
                            numeracao_id: resolvedNumId || null,
                            tipo_numeracao: item.tipo_numeracao || item.gabarito_operacional || null,
                            qtd: item.quantidade || item.qtd || 0,
                            num_inicial: item.numeracao_inicio || item.num_inicial,
                            num_final: item.numeracao_fim || item.num_final,
                            verso: itemVerso,
                            verso_tipo: resolvedVersoTipo,
                            impressao: normalizarStatusImpressao(item.status_impressao || item.status_producao || item.impressao),
                            nome_produto_real: prop ? prop.nome_produto : null,
                            amostra_cor_id: idsDoBanco.corId || item.id_cor || item.cor_id || (prop ? (prop.amostra_cor_id || prop.id_cor) : null),
                            amostra_num_id: resolvedNumId || null,
                            amostra_arte_base64: item.amostra_arte_base64 || (prop ? prop.amostra_arte_base64 : null),
                            verso_amostra_arte_base64: item.verso_amostra_arte_base64 || (prop ? prop.verso_amostra_arte_base64 : null),
                            arte_url: item.arte_url || item.url_arquivo_arte || item.url_arquivo || (prop ? (prop.arte_url || prop.url_arquivo_arte || prop.url_arquivo) : null),
                            verso_arte_url: item.verso_arte_url || item.url_arquivo_arte_verso || item.verso_url_arquivo || (prop ? (prop.verso_arte_url || prop.url_arquivo_arte_verso || prop.verso_url_arquivo) : null),
                            url_arquivo_arte: item.url_arquivo_arte || item.arte_url || (prop ? (prop.url_arquivo_arte || prop.arte_url) : null),
                            url_arquivo_arte_verso: item.url_arquivo_arte_verso || item.verso_arte_url || (prop ? (prop.url_arquivo_arte_verso || prop.verso_arte_url) : null),
                            amostra_obs: item.observacao_arte || item.amostra_obs || (prop ? prop.observacao_arte : null) || '',
                            os_id: osId,
                            _pedidoModeloId: item.id,
                            amostra_status: statusFrontend,
                            _vibe_id_produto: prop ? prop.id_produto : null,
                            setor: (() => {
                                const vibeProdId = prop ? prop.id_produto : null;
                                const prodObj = vibeProdId ? (state.produtosGlobais || []).find(pg => String(pg.id_produto) === String(vibeProdId)) : null;
                                return prodObj ? (prodObj.setor_pcp || '') : '';
                            })() || item.setor || '',   // sem setor_pcp = sem setor, nunca PVC
                            _dbLoaded: true
                        };
                        return mapped;
                    });
                    // Resolver amostra_cor_id / amostra_num_id por nome agora que a lista existe.
                    // -1 = não procurar nos selects da tela: no carregamento os selects de amostra
                    // ainda são os do pedido anterior, e ler deles atribuiria a cor errada a este.
                    const SEM_SELECT_NA_TELA = -1;
                    state.osItens[osId].forEach(it => resolveItemCorNumIds(it, SEM_SELECT_NA_TELA));
                    // DEBUG: mostrar campos de cor de cada item
                    state.osItens[osId].forEach(it => {
                        console.log(`[COR DEBUG] id=${it.id} padrao=${it.padrao} cor=${it.cor} amostra_cor_id=${it.amostra_cor_id} id_cor=${it.id_cor} cor_raw=${it._rawCor}`);
                    });

                    if (seguiramOPedido.length && typeof toast === 'function') {
                        const lista = seguiramOPedido.slice(0, 3).join(' | ');
                        const resto = seguiramOPedido.length > 3 ? ` (+${seguiramOPedido.length - 3})` : '';
                        toast(`Atualizado conforme o pedido — ${lista}${resto}`, 'info');
                        console.log('[PEDIDO] Cor/numeração seguiram o banco:', seguiramOPedido);
                    }
                } else if (propData && propData.length > 0) {
                    // Fallback: usar produtos_proposta diretamente quando pedidos_modelos está vazio
                    console.log('[loadOSItens] Fallback: usando produtos_proposta para id_int=' + queryNum);
                    const mappedItems = propData.map((pp, idx) => {
                        const resolvedNumId = pp.amostra_num_id || null;
                        const matchedNum = resolvedNumId ? (state.numeracoes || []).find(n => String(n.id) === String(resolvedNumId)) : null;
                        
                        const resolvedNumeracao = matchedNum ? (matchedNum.name || matchedNum.tipo) : (pp.tipo_numeracao || null);
                        const resolvedGabarito = matchedNum ? (matchedNum.name || matchedNum.tipo) : (pp.gabarito_operacional || null);

                        return {
                            id: pp.id,
                            id_int: pp.id_int,
                            nome_modelo: pp.nome_produto || `Modelo ${idx + 1}`,
                            produto: pp.nome_produto || `Modelo ${idx + 1}`,
                            modelo: pp.id ? pp.id.toString() : '--',
                            cor: pp.padrao || 'STD',
                            numeracao: resolvedNumeracao,
                            gabarito_operacional: resolvedGabarito,
                            numeracao_id: resolvedNumId || null,
                            num_inicial: pp.numeracao_inicio || null,
                            num_final: pp.numeracao_fim || null,
                            verso: pp.frente_verso || false,
                            impressao: 'AGUARD.',
                            nome_produto_real: pp.nome_produto,
                            padrao: pp.padrao || null,
                            largura: pp.largura || null,
                            altura: pp.altura || null,
                            qtd: pp.qtd || null,
                            amostra_cor_id: pp.amostra_cor_id || null,
                            amostra_num_id: resolvedNumId || null,
                            amostra_arte_base64: pp.amostra_arte_base64 || null,
                            arte_url: pp.arte_url || null,
                            ordem: idx + 1,
                            os_id: osId,
                            id_produto_proposta_origem: pp.id,
                            created_at: pp.created_at,
                            updated_at: pp.updated_at,
                            setor: (() => {
                                const vibeProdId = pp.id_produto || null;
                                const prodObj = vibeProdId ? (state.produtosGlobais || []).find(pg => String(pg.id_produto) === String(vibeProdId)) : null;
                                return prodObj ? (prodObj.setor_pcp || '') : '';
                            })() || '',   // sem setor_pcp = sem setor, nunca PVC
                            _dbLoaded: true
                        };
                    });

                    // Auto-criar registros em pedidos_modelos para que salvamentos futuros funcionem
                    try {
                        const insertPayloads = propData.map((pp, idx) => ({
                            id_int: pp.id_int,
                            id_produto_proposta_origem: pp.id,
                            nome_modelo: pp.nome_produto || `Modelo ${idx + 1}`,
                            quantidade: pp.qtd || 0,
                            ordem: idx + 1,
                            status_arte: 'PENDENTE',
                            status_producao: 'PENDENTE',
                            amostra_cor_id: pp.amostra_cor_id || null,
                            amostra_num_id: pp.amostra_num_id || null,
                            amostra_arte_base64: pp.amostra_arte_base64 || null,
                            arte_url: pp.arte_url || null,
                            gabarito_operacional: pp.gabarito_operacional || null
                        }));

                        const { data: insertedModelos, error: insertError } = await supabaseClient
                            .from('pedidos_modelos')
                            .insert(insertPayloads)
                            .select('id, id_produto_proposta_origem');

                        if (!insertError && insertedModelos) {
                            // Atualizar itens no state com _pedidoModeloId dos registros criados
                            mappedItems.forEach(item => {
                                const modelo = insertedModelos.find(m => String(m.id_produto_proposta_origem) === String(item.id_produto_proposta_origem));
                                if (modelo) {
                                    item._pedidoModeloId = modelo.id;
                                    item.id = modelo.id; // Usar o ID real de pedidos_modelos
                                }
                            });
                            console.log(`[loadOSItens] Auto-criou ${insertedModelos.length} registros em pedidos_modelos para id_int=${queryNum}`);
                        } else if (insertError) {
                            console.warn('[loadOSItens] Erro ao auto-criar pedidos_modelos:', insertError);
                        }
                    } catch (autoCreateErr) {
                        console.warn('[loadOSItens] Falha no auto-create de pedidos_modelos:', autoCreateErr);
                    }

                    state.osItens[osId] = mappedItems;
                } else {
                    state.osItens[osId] = [];
                }
            } else {
                const res = await fetch(`${API_BASE_URL}/api/ordens/${osId}/itens`);
                if (res.ok) {
                    state.osItens[osId] = await res.json();
                } else {
                    state.osItens[osId] = [];
                }
            }
        }

        // Buscar dados dinâmicos da arte (pedidos_artes) e mesclar nos itens
        if (typeof supabaseClient !== 'undefined' && supabaseClient && os.numero) {
            try {
                const queryNum = parseInt(os.numero);
                if (!isNaN(queryNum)) {
                    const { data: artes, error: artesError } = await supabaseClient
                        .from('pedidos_artes')
                        .select('*')
                        .eq('id_int', queryNum);
                    
                    if (!artesError && artes && artes.length > 0) {
                        state.osItens[osId].forEach(item => {
                            // Encontrar artes vinculadas a este item
                            const artesDoItem = artes.filter(a => 
                                String(a.id_modelo) === String(item.id) || 
                                (item._pedidoModeloId && String(a.id_modelo) === String(item._pedidoModeloId))
                            );
                            if (artesDoItem.length > 0) {
                                // Ordenar por versão decrescente para pegar a mais recente
                                artesDoItem.sort((a, b) => b.versao - a.versao);
                                const ultimaArte = artesDoItem[0];
                                
                                // Atualizar metadados de visualização
                                item.aprovacao = ultimaArte.status;
                                item.nome_arquivo_arte = ultimaArte.nome_arquivo;
                                item.versao_arte = ultimaArte.versao;
                                item.url_arquivo_arte = ultimaArte.url_arquivo;
                                item.url_arquivo_arte_verso = ultimaArte.verso_url_arquivo || null;
                                item.nome_arquivo_arte_verso = ultimaArte.verso_nome_arquivo || null;
                                if (ultimaArte.url_arquivo) {
                                    item.arte_url = ultimaArte.url_arquivo;
                                }
                                if (ultimaArte.verso_url_arquivo) {
                                    item.verso_arte_url = ultimaArte.verso_url_arquivo;
                                }
                                if (ultimaArte.comentarios_revisao && !item.amostra_obs) {
                                    item.amostra_obs = ultimaArte.comentarios_revisao;
                                }
                            }
                        });
                    }
                }
            } catch (err) {
                console.warn('[Supabase] Erro ao integrar dados de pedidos_artes:', err);
            }
        }

        renderOSItens(osId);
        // Não chamar renderOrdens() aqui para evitar re-renderizar a tabela durante a navegação para amostras
    } catch (e) {
        console.error('Erro ao carregar itens da OS:', e);
        toast('Erro ao carregar itens: ' + e.message, 'error');
    } finally {
        if (state._loadingOSItens) state._loadingOSItens[osId] = false;
    }
}


/**
 * Formata data para exibição
 */
function formatDate(dateStr) {
    if (!dateStr) return '--';
    const d = new Date(dateStr);
    return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' }) +
        ' ' + d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
}

/**
 * Retorna badge HTML para status
 */
// -------------------------------------------------------------------------------
// ESCAPE DE DADO EXTERNO EM HTML
//
// Nome de cliente, nome de evento, designer, frete e nome de modelo vêm do Vibe
// (sistema parceiro) ou do banco — não são digitados aqui e não estão sob nosso
// controle. Interpolar esses valores crus num template `innerHTML` significa que
// um apóstrofo já quebra a linha da tabela e um "<" quebra a tabela inteira.
//
// Use escapeHtml() para texto dentro de uma tag ou atributo, e escapeJsAttr()
// para valor que vai PARAR DENTRO de uma string JS num onclick — lá são duas
// camadas de parsing (HTML e depois JS) e escapar só uma não resolve.
// -------------------------------------------------------------------------------
function escapeHtml(valor) {
    if (valor === null || valor === undefined) return '';
    return String(valor)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

/**
 * Para `onclick="fn('${escapeJsAttr(v)}')"`. Escapa primeiro para a string JS e
 * depois para o HTML: o navegador desfaz a camada HTML ao ler o atributo e
 * entrega ao JS exatamente o texto escapado que ele espera.
 */
function escapeJsAttr(valor) {
    if (valor === null || valor === undefined) return '';
    return escapeHtml(
        String(valor)
            .replace(/\\/g, '\\\\')
            .replace(/'/g, "\\'")
            .replace(/\r/g, '\\r')
            .replace(/\n/g, '\\n')
    );
}

window.escapeHtml = escapeHtml;
window.escapeJsAttr = escapeJsAttr;

