/**
 * Alterna manualmente o status de Entrega/Faturamento (APROVADO -> ALTERADO -> CORRIGIR -> ----)
 */
window.alterarEntregaDadosStatus = async function(osIntNum, currentStatus) {
    const perms = window._currentPerms || {};
    if (perms.perm_lista_arte_edit !== true) {
        toast('Você não tem permissão para alterar o status de Entrega/Faturamento.', 'warning');
        return;
    }

    const numInt = parseInt(osIntNum);
    if (isNaN(numInt)) return;

    const statusOptions = ['APROVADO', 'ALTERADO', 'CORRIGIR', '----'];
    const currUpper = (currentStatus || '----').toUpperCase();
    const currIdx = statusOptions.indexOf(currUpper);
    const nextStatus = statusOptions[(currIdx + 1) % statusOptions.length];
    const valToSave = nextStatus === '----' ? null : nextStatus;

    try {
        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            await supabaseClient.from('pedidos_artes')
                .update({ entrega_dados: valToSave })
                .eq('id_int', numInt);
        }

        const arteGlobal = state.todasArtes?.find(a => a.id_int === numInt);
        if (arteGlobal) arteGlobal.entrega_dados = valToSave;

        toast(`Status Entrega/Faturam. do Pedido #${numInt} alterado para "${nextStatus}"`, 'info');
        renderOrdens();
    } catch (e) {
        console.error('Erro ao alterar entrega_dados:', e);
        toast('Erro ao alterar status: ' + e.message, 'error');
    }
};

/**
 * Liberar pedido para Produção (muda status_interno para 'EM PRODUCAO').

 * Usado quando a arte foi aprovada e o pedido pode ir para impressão.
 */
window.liberarParaProducao = async function(osId) {
    // Aqui, e não só no botão: quem digitar a função no console passaria direto.
    if (!podeLiberarParaProducao()) {
        toast('Só o administrador libera um pedido para produção. Peça a ele.', 'warning');
        return;
    }

    if (!confirm('Liberar este pedido para PRODUÇÃO / IMPRESSÃO?')) return;

    try {
        const os = state.ordens.find(o => o.id === osId);

        // Mudar status_interno para EM PRODUCAO (aparece na Lista de Impressão)
        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            // Atualizar na proposta o status_interno
            const numInt = os ? parseInt(os.numero) : null;
            if (numInt) {
                await supabaseClient.from('propostas')
                    .update({ status_interno: 'EM PRODUCAO' })
                    .eq('id_int', numInt);
            }

            // Atualizar status da OS de arte
            if (osId.startsWith('vibe_')) {
                await supabaseClient.from('pedidos_links_cliente')
                    .update({ status_arte: 'EM PRODUCAO' })
                    .eq('os_id', osId);
            } else {
                await supabaseClient.from('producao_ordens_servico')
                    .update({ status: 'EM PRODUCAO' })
                    .eq('id', osId);
            }
        }

        // Atualizar estado local
        if (os) {
            os.status = 'EM PRODUCAO';
            os.status_interno = 'EM PRODUCAO';
        }

        gravarStatusOverride(osId, 'EM PRODUCAO');

        toast(`Pedido #${os ? os.numero : ''} liberado para PRODUÇÃO! 🖨️`, 'success');
        renderOrdens();
    } catch (err) {
        console.error('Erro ao liberar para produção:', err);
        toast('Erro: ' + err.message, 'error');
    }
};


/**
 * Ao selecionar cor em um card dinâmico, filtrar numerações compatíveis
 * (idêntico ao onAmostraCorSelect do card avulso)
 */
function onItemCorSelect(idx, osId, itemId, isInitialLoad = false) {
    const corSelect = document.getElementById(`amostra-item-cor-${idx}`);
    const numSelect = document.getElementById(`amostra-item-num-${idx}`);
    if (!corSelect || !numSelect) return;

    const corId = corSelect.value;
    const cor = corId ? (state.cores || []).find(c => String(c.id) === String(corId)) : null;
    const selectedText = corSelect.selectedIndex >= 0 ? corSelect.options[corSelect.selectedIndex].text : '';
    const corNome = cor ? (cor.name || cor.padrao || cor.cor || cor.nome) : (selectedText && !selectedText.startsWith('--') ? selectedText : null);

    const item = state.osItens[osId]?.find(i => String(i.id) === String(itemId));

    if (item) {
        item.amostra_cor_id = corId || null;
        if (corNome) {
            item.cor = corNome;
            item.padrao = corNome;
        }
        if (!isInitialLoad) item._needsSnapshot = true;
    }

    // Se não for carga inicial, salva no banco
    if (!isInitialLoad) {
        saveAmostraToDB(itemId, osId, { 
            amostra_cor_id: corId || null,
            padrao: corNome || null,
            cor: corNome || null
        }).then(() => {
            toast(`Cor "${corNome || 'Padrão'}" atualizada no banco e no Vibe!`, 'success');
        }).catch(err => {
            console.error('Erro ao salvar cor:', err);
            toast('Erro ao salvar cor no banco: ' + (err.message || err), 'error');
        });
    }

    // Filtrar numerações pelo formato da COR selecionada
    const curNumVal = numSelect.value;
    const corFormatoId = cor ? cor.formato_id : null;
    const os = typeof findOSInState === 'function' ? findOSInState(osId) : state.ordens.find(o => o.id === osId);
    const idCliente = os ? os.id_cliente : null;

    const filteredNums = (state.numeracoes || []).filter(n => {
        // Sempre exibe a numeração atualmente selecionada (para não sumir do select)
        if (curNumVal && n.id === curNumVal) return true;

        // Se for customizada
        if (n.is_custom) {
            if (n.Cli_Num) {
                // Se for vinculada a um cliente, só exibe se for o cliente desta OS
                if (String(n.Cli_Num) !== String(idCliente)) return false;
            } else {
                // Fallback legado: se não tiver Cli_Num, só exibe se for vinculada a este item específico
                if (!item || String(n.os_item_id) !== String(item.id)) return false;
            }
        }
        
        // Se tivermos cor selecionada com formato_id, filtra por ele
        if (corFormatoId) {
            const ids = n.formato_ids || (n.formato_id ? [n.formato_id] : []);
            return ids.some(id => String(id) === String(corFormatoId));
        }
        return false;
    });

    numSelect.innerHTML = '<option value="">-- Selecione uma Numeração --</option>' +
        filteredNums.map(n => opcaoDeNumeracaoDoModelo(n, idCliente, false)).join('');

    if (filteredNums.some(n => String(n.id) === String(curNumVal))) {
        numSelect.value = curNumVal;
    } else {
        numSelect.value = '';
    }
    pintarSelectDeNumeracao(numSelect);

    if (!isInitialLoad) {
        renderItemAmostraCombinada(idx, osId);
    }
}

function onItemNumSelect(idx, osId, itemId) {
    const numSelect = document.getElementById(`amostra-item-num-${idx}`);
    if (!numSelect) return;
    pintarSelectDeNumeracao(numSelect);
    
    const numId = numSelect.value;
    const numObj = numId ? state.numeracoes.find(n => String(n.id) === String(numId)) : null;
    const numNome = numObj ? numObj.name : null;
    const item = state.osItens[osId]?.find(i => String(i.id) === String(itemId));
    
    let versoStateChanged = false;
    let limparAmostraVerso = false;
    if (item) {
        sincronizarNumeracaoDoItem(item, numId);
        item.gabarito_operacional = numNome || null;
        item.numeracao = numNome || null;
        item.tipo_numeracao = numNome || null;
        item._needsSnapshot = true;

        const isDuplexNum = isNumeracaoDuplex(numObj);
        const oldVerso = !!item.verso;

        if (isDuplexNum) {
            item.verso = true;
            if (!item.verso_tipo || item.verso_tipo === 'Frente' || item.verso_tipo === 'SÓ FRENTE' || item.verso_tipo === 'SO FRENTE') {
                item.verso_tipo = 'FxVerso';
            }
        } else {
            if (item.verso_tipo === 'FxVerso' || item.verso_tipo === 'VERSO COMUM') {
                item.verso_tipo = 'Frente';
                item.verso = false;
            } else {
                item.verso = !!(item.verso_tipo && item.verso_tipo !== 'Frente');
            }

            // Numeração só Frente: a amostra de verso que o cliente veria deixa de
            // fazer sentido e precisa sair do banco. A arte enviada pelo operador
            // (verso_arte_url / verso_arte_json) é preservada de propósito, para
            // poder ser recomposta se a numeração voltar a ser FxVerso.
            // Só quando há uma numeração escolhida: limpar o select não apaga nada.
            if (numObj && item.verso_amostra_arte_base64) {
                item.verso_amostra_arte_base64 = null;
                limparAmostraVerso = true;
            }
        }
        if (oldVerso !== item.verso) {
            versoStateChanged = true;
        }
    }
    
    const dataToSave = { 
        amostra_num_id: numId || null,
        gabarito_operacional: numNome || null,
        tipo_numeracao: numNome || null
    };
    if (item && item.verso_tipo) {
        dataToSave.verso_tipo = item.verso_tipo;
    }
    if (limparAmostraVerso) {
        // _isExplicitRemove é obrigatório: sem ele o guard do saveAmostraToDB
        // descarta o null em silêncio e a amostra continuaria no banco.
        // Só afeta as chaves presentes neste payload.
        dataToSave.verso_amostra_arte_base64 = null;
        dataToSave._isExplicitRemove = true;
    }

    saveAmostraToDB(itemId, osId, dataToSave).then(() => {
        toast(`Numeração "${numNome || 'Nenhuma'}" atualizada no banco e no Vibe!`, 'success');
    }).catch(err => {
        console.error('Erro ao salvar numeração:', err);
        toast('Erro ao salvar numeração no banco: ' + (err.message || err), 'error');
    });

    if (versoStateChanged) {
        const containerId = state.amostrasContainerId || 'amostras-itens-container';
        if (containerId === 'cliente-amostras-itens-container' && typeof renderClienteAmostrasItens === 'function') {
            renderClienteAmostrasItens(osId);
        } else if (typeof renderAmostrasOSItens === 'function') {
            renderAmostrasOSItens(osId);
        } else {
            renderItemAmostraCombinada(idx, osId);
        }
    } else {
        renderItemAmostraCombinada(idx, osId);
    }

    if (item && item.modo_pdf && pdfViewerState[idx]) {
        renderPdfViewerPage(idx, pdfViewerState[idx].currentPage || 1);
    }
}

/**
 * Um "Upload de Arte" convencional (ou uma colagem de link) substitui a arte do
 * modelo por um arquivo pronto -- entao a estrutura vetorial da ultima edicao no
 * Criador de Arte fica obsoleta e PRECISA ser descartada.
 *
 * Sem isso, setupEditorWorkspace() prioriza o arte_json e reabre a arte antiga,
 * ignorando o arquivo recem-enviado.
 *
 * O arte_json nao existe no banco (saveAmostraToDB o remove do payload): ele vive
 * so na memoria e no localStorage -- exatamente os dois lugares limpos aqui.
 */
function invalidarArteVetorial(item, osId, idx, faceKey) {
    if (!item) return;

    if (faceKey === 'verso') item.verso_arte_json = null;
    else item.arte_json = null;

    const ids = [item.id, item._pedidoModeloId, item.id_produto_proposta_origem].filter(Boolean);
    ids.forEach(id => localStorage.removeItem(`ideal_arte_json_${id}_${faceKey}`));
    localStorage.removeItem(`ideal_arte_json_${osId}_${idx}_${faceKey}`);
}
window.invalidarArteVetorial = invalidarArteVetorial;

async function onItemArteUpload(idx, osId, itemId, face = 'frente') {
    const inputId = face === 'verso' ? `amostra-item-arte-verso-${idx}` : `amostra-item-arte-${idx}`;
    const nameLabelId = face === 'verso' ? `amostra-item-arte-verso-name-${idx}` : `amostra-item-arte-name-${idx}`;
    const removeBtnId = face === 'verso' ? `btn-remove-amostra-arte-verso-${idx}` : `btn-remove-amostra-arte-${idx}`;

    const input = document.getElementById(inputId);
    const nameLabel = document.getElementById(nameLabelId);
    const removeBtn = document.getElementById(removeBtnId);
    
    if (input && input.files && input.files[0]) {
        const file = input.files[0];
        if (nameLabel) nameLabel.textContent = file.name;
        if (removeBtn) removeBtn.style.display = 'inline-block';
        
        try {
            toast('Enviando arte original para o servidor...', 'info');
            const fileExt = file.name.split('.').pop();
            const fileName = `arte_${face}_${osId}_${itemId}_${Date.now()}.${fileExt}`;
            
            const { data, error } = await supabaseClient
                .storage
                .from('artes')
                .upload(fileName, file, { cacheControl: '3600', upsert: true });
                
            if (error) throw error;
            
            const { data: urlData } = supabaseClient
                .storage
                .from('artes')
                .getPublicUrl(fileName);
                
            const publicUrl = urlData.publicUrl;

            // Atualizar o state PRIMEIRO
            const osItems = state.osItens[osId];
            const item = osItems?.find(i => String(i.id) === String(itemId));
            if (item) {
                item._needsSnapshot = true;
                resolveItemCorNumIds(item, idx);
                const faceKey = face === 'verso' ? 'verso' : 'frente';
                if (face === 'verso') {
                    item.verso_arte_url = publicUrl;
                } else {
                    item.arte_url = publicUrl;
                }
                if (item.id) localStorage.setItem(`ideal_arte_url_${item.id}_${faceKey}`, publicUrl);
                localStorage.setItem(`ideal_arte_url_${osId}_${idx}_${faceKey}`, publicUrl);

                // O arquivo enviado agora e a arte do modelo: a estrutura vetorial
                // da edicao anterior nao vale mais e nao pode reaparecer no editor.
                invalidarArteVetorial(item, osId, idx, faceKey);
            }

            // Se modo PDF, gerar snapshot da primeira página e inicializar viewer
            if (item && item.modo_pdf && file.type === 'application/pdf') {
                try {
                    const arrayBuf = await file.arrayBuffer();
                    const pdf = await pdfjsLib.getDocument({ data: arrayBuf }).promise;
                    const page = await pdf.getPage(1);
                    const vp = page.getViewport({ scale: 2.0 });
                    const offCanvas = document.createElement('canvas');
                    offCanvas.width = vp.width;
                    offCanvas.height = vp.height;
                    const octx = offCanvas.getContext('2d');
                    await page.render({ canvasContext: octx, viewport: vp }).promise;
                    const snapshotBase64 = offCanvas.toDataURL('image/png');
                    item.amostra_arte_base64 = snapshotBase64;
                    await saveAmostraToDB(itemId, osId, { amostra_arte_base64: snapshotBase64 });
                } catch (snapErr) {
                    console.warn('[PDF MODE] Erro ao gerar snapshot da página 1:', snapErr);
                }
                // Salvar URL no banco E no state local ANTES de qualquer re-render
                const dbField = face === 'verso' ? 'verso_arte_url' : 'arte_url';
                if (face === 'verso') { item.verso_arte_url = publicUrl; }
                else { item.arte_url = publicUrl; }
                await saveAmostraToDB(itemId, osId, { [dbField]: publicUrl });
                // Limpar viewer state antigo — re-renderizar apenas o card (não a tela toda)
                const pdfKey = `${osId}_${idx}`;
                delete pdfViewerState[pdfKey];
                delete pdfViewerState[idx];
                // Renderizar o card com arte_url já no state para garantir que o viewer apareça
                await renderItemAmostraCombinada(idx, osId);
                // Inicializar o viewer após o DOM estar pronto
                await initPdfViewer(pdfKey, publicUrl, osId, idx);
            } else {
                // Renderizar IMEDIATAMENTE a arte (modo padrão)
                renderItemAmostraCombinada(idx, osId);

                // Salvar no banco
                const dbField = face === 'verso' ? 'verso_arte_url' : 'arte_url';
                await saveAmostraToDB(itemId, osId, { [dbField]: publicUrl });
            }
            toast('Arte enviada com sucesso!', 'success');
        } catch(e) {
            console.error('Upload falhou:', e);
            toast('Falha ao enviar arte: ' + e.message, 'error');
        }
    }
}

// ──── "Este item tem arte?" ────────────────────────────────────────────────
// O campo amostra_arte_base64 guarda DUAS coisas: a arte do modelo e, quando um
// snapshot e gerado, a URL da previa composta (cor+arte+numeracao) no bucket
// amostras_renderizadas. Para saber se ha ARTE, o render nao vale — senao o
// botao Remover aparece em item sem arte, e o editor abre a previa como se fosse
// a arte. A previa continua sendo usada onde ela e o que interessa: as imagens
// de visualizacao e o resumo enviado ao cliente.
function ehRenderComposto(v) {
    return typeof v === 'string' && v.includes('/amostras_renderizadas/');
}

function itemTemArte(item, face = 'frente') {
    if (!item) return false;
    const url  = face === 'verso' ? item.verso_arte_url  : item.arte_url;
    const json = face === 'verso' ? item.verso_arte_json : item.arte_json;
    const b64  = face === 'verso' ? item.verso_amostra_arte_base64 : item.amostra_arte_base64;
    return !!(url || json || (b64 && !ehRenderComposto(b64)));
}
window.itemTemArte = itemTemArte;

async function onItemArteRemove(idx, osId, itemId, face = 'frente') {
    // Confirmação desenhada na página, não o confirm() do navegador: ver o porquê
    // em confirmarNaTela(). Com o diálogo nativo suprimido, este botão virava um
    // botão que não faz nada e não explica.
    const confirmou = await confirmarNaTela({
        titulo: '✕ Excluir a arte deste modelo?',
        mensagem: `A arte da ${face === 'verso' ? 'face de verso' : 'frente'} será removida do modelo `
            + 'e do banco de dados.\n\nNão será possível reverter a ação.',
        textoConfirmar: 'Excluir arte',
    });
    if (!confirmou) return;

    const inputId = face === 'verso' ? `amostra-item-arte-verso-${idx}` : `amostra-item-arte-${idx}`;
    const nameLabelId = face === 'verso' ? `amostra-item-arte-verso-name-${idx}` : `amostra-item-arte-name-${idx}`;
    const removeBtnId = face === 'verso' ? `btn-remove-amostra-arte-verso-${idx}` : `btn-remove-amostra-arte-${idx}`;
    const copyBtnId = face === 'verso' ? `btn-copy-amostra-arte-verso-${idx}` : `btn-copy-amostra-arte-${idx}`;

    const input = document.getElementById(inputId);
    const nameLabel = document.getElementById(nameLabelId);
    const removeBtn = document.getElementById(removeBtnId);
    const copyBtn = document.getElementById(copyBtnId);
    
    if (input) input.value = '';
    if (nameLabel) nameLabel.textContent = '';
    if (removeBtn) removeBtn.style.display = 'none';
    if (copyBtn) copyBtn.style.display = 'none';
    
    const osItems = state.osItens[osId];
    const item = osItems ? osItems.find(i => String(i.id) === String(itemId)) : null;
    if (item) {
        item._needsSnapshot = true;
        if (face === 'verso') {
            item.verso_arte_url = null;
            item.verso_amostra_arte_base64 = null;
            item.url_arquivo_arte_verso = null;
            item.verso_url_arquivo = null;
            item.verso_arte_json = null;
        } else {
            item.arte_url = null;
            item.amostra_arte_base64 = null;
            item.url_arquivo_arte = null;
            item.url_arquivo = null;
            item.arte_json = null;
        }

        // Limpar do localStorage
        const faceKey = face === 'verso' ? 'verso' : 'frente';
        const itemIds = [item.id, item._pedidoModeloId, item.id_produto_proposta_origem].filter(Boolean);
        itemIds.forEach(id => {
            localStorage.removeItem(`ideal_arte_url_${id}_${faceKey}`);
            localStorage.removeItem(`ideal_arte_json_${id}_${faceKey}`);
        });
        localStorage.removeItem(`ideal_arte_url_${osId}_${idx}_${faceKey}`);
        localStorage.removeItem(`ideal_arte_json_${osId}_${idx}_${faceKey}`);
    }

    // Limpar cache de PDF viewer se houver
    const pdfKey = `${osId}_${idx}`;
    if (typeof pdfViewerState !== 'undefined') {
        delete pdfViewerState[pdfKey];
        delete pdfViewerState[idx];
    }

    // Re-renderizar imediatamente a janela combinada sem a camada de arte
    renderItemAmostraCombinada(idx, osId);

    // Salvar no banco zerando URL, base64 e JSON vetorial
    const payload = face === 'verso' ? {
        verso_arte_url: null,
        verso_amostra_arte_base64: null,
        verso_arte_json: null,
        _isExplicitRemove: true
    } : {
        arte_url: null,
        amostra_arte_base64: null,
        arte_json: null,
        _isExplicitRemove: true
    };

    saveAmostraToDB(itemId, osId, payload)
        .then(() => toast('Arte removida do banco com sucesso!', 'success'))
        .catch((err) => toast('Falha ao remover arte: ' + (err.message || err), 'error'));
}

// Funções globais de Copiar/Colar links de arte entre modelos
window.copiarArte = function(url, face) {
    if (!url) {
        toast('Nenhum link de arte para copiar.', 'warning');
        return;
    }
    if (!state.copiedArte) state.copiedArte = {};
    state.copiedArte = { url, face };
    localStorage.setItem('imposicao_copied_arte', JSON.stringify({ url, face }));
    
    navigator.clipboard.writeText(url)
        .then(() => {
            toast(`Link da arte (${face.toUpperCase()}) copiado!`, 'success');
        })
        .catch(err => {
            toast(`Link da arte (${face.toUpperCase()}) copiado na memória!`, 'success');
        });
};

window.colarArte = async function(idx, osId, itemId, face = 'frente') {
    let sourceUrl = state.copiedArte ? state.copiedArte.url : null;
    
    if (!sourceUrl) {
        const stored = localStorage.getItem('imposicao_copied_arte');
        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                if (parsed && parsed.url) {
                    sourceUrl = parsed.url;
                    state.copiedArte = parsed;
                }
            } catch(e) {}
        }
    }
    
    if (!sourceUrl) {
        try {
            const clipboardText = await navigator.clipboard.readText();
            if (clipboardText && (clipboardText.startsWith('http://') || clipboardText.startsWith('https://'))) {
                sourceUrl = clipboardText.trim();
            }
        } catch (err) {
            console.log('Clipboard read blocked or empty:', err);
        }
    }
    
    if (!sourceUrl) {
        toast('Nenhuma arte copiada na memória. Copie a arte de outro modelo primeiro!', 'warning');
        return;
    }
    
    try {
        toast('Colando link da arte...', 'info');
        
        // Limpar inputs de arquivo locais correspondentes
        const inputId = face === 'verso' ? `amostra-item-arte-verso-${idx}` : `amostra-item-arte-${idx}`;
        const input = document.getElementById(inputId);
        if (input) input.value = '';
        
        const osItems = state.osItens[osId];
        const item = osItems ? osItems.find(i => String(i.id) === String(itemId)) : null;
        if (item) {
            if (face === 'verso') {
                item.verso_arte_url = sourceUrl;
            } else {
                item.arte_url = sourceUrl;
            }
            // Mesma regra do upload: a arte colada substitui a edicao anterior.
            invalidarArteVetorial(item, osId, idx, face === 'verso' ? 'verso' : 'frente');
        }
        
        // CRITICAL: Montar payload preservando explicitamente cor e numeração já cadastradas.
        // Uma colagem de arte NUNCA deve zerar amostra_cor_id/amostra_num_id —
        // apenas a URL da arte é alterada; cor e num permanecem intactos.
        const dbField = face === 'verso' ? 'verso_arte_url' : 'arte_url';
        const payload = { [dbField]: sourceUrl };
        if (item && item.amostra_cor_id) payload.amostra_cor_id = item.amostra_cor_id;
        if (item && item.amostra_num_id) payload.amostra_num_id = item.amostra_num_id;

        await saveAmostraToDB(itemId, osId, payload);

        // Só re-renderizar a janela combinada se os canvases estiverem no DOM
        // (evita renderAmostrasOSItens fora do editor, que dispara onItemCorSelect
        // e pode salvar amostra_cor_id/amostra_num_id = null por engano)
        const containerId = state.amostrasContainerId || 'amostras-itens-container';
        const hasCanvas = !!(document.getElementById(`amostra-item-canvas-${idx}`) ||
                             document.querySelector(`#${containerId} canvas[id*="amostra-item-canvas-${idx}"]`));
        if (hasCanvas) {
            renderItemAmostraCombinada(idx, osId);
        }

        toast('Arte vinculada com sucesso!', 'success');
    } catch (e) {
        console.error('Falha ao colar arte:', e);
        toast('Falha ao colar arte: ' + e.message, 'error');
    }
};

/**
 * Auto-resolve os IDs de Cor (amostra_cor_id) e Numeração (amostra_num_id) de um modelo
 * lendo dos selects do DOM, do objeto do item ou por correspondência de texto em state.cores / state.numeracoes.
 */
function resolveItemCorNumIds(item, itemIdx = null) {
    if (!item) return { corId: null, numId: null };

    let corId = item.amostra_cor_id || item.id_cor || item.cor_id || null;
    let numId = item.amostra_num_id || item.numeracao_id || null;

    // 1. Tentar ler dos selects no DOM se os IDs não estiverem preenchidos no objeto
    let idx = itemIdx;
    if (idx === null && typeof state !== 'undefined' && state.osItens && item.os_id) {
        const itemsList = state.osItens[item.os_id] || [];
        const foundIdx = itemsList.findIndex(i => String(i.id) === String(item.id));
        if (foundIdx >= 0) idx = foundIdx;
    }
    if (idx !== null && idx >= 0) {
        if (!corId) {
            const corSel = document.getElementById(`amostra-item-cor-${idx}`) || document.getElementById('amostra-cor-select');
            if (corSel && corSel.value) corId = corSel.value;
        }
        if (!numId) {
            const numSel = document.getElementById(`amostra-item-num-${idx}`) || document.getElementById('amostra-num-select');
            if (numSel && numSel.value) numId = numSel.value;
        }
    }

    const normStr = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

    // 2. Tentar resolver ID da COR por busca textual em state.cores se ainda nulo
    if (!corId && typeof state !== 'undefined' && state.cores && state.cores.length > 0) {
        const corNome = item.cor || item.padrao || item._rawCor;
        if (corNome && corNome !== '--' && corNome !== 'STD') {
            const targetNorm = normStr(corNome);
            const foundCor = state.cores.find(c => {
                const cName = normStr(c.name || c.padrao || c.cor || c.nome);
                return cName === targetNorm || (targetNorm.length >= 3 && (cName.includes(targetNorm) || targetNorm.includes(cName)));
            });
            if (foundCor) corId = foundCor.id;
        }
    }

    // 3. Tentar resolver ID da NUMERAÇÃO por busca textual em state.numeracoes se ainda nulo
    if (!numId && typeof state !== 'undefined' && state.numeracoes && state.numeracoes.length > 0) {
        const numNome = item.gabarito_operacional || item.numeracao || item.tipo_numeracao;
        if (numNome && numNome !== '--') {
            const targetNorm = normStr(numNome);
            const foundNum = state.numeracoes.find(n => {
                const nName = normStr(n.name || n.tipo);
                return nName === targetNorm || (targetNorm.length >= 3 && (nName.includes(targetNorm) || targetNorm.includes(nName)));
            });
            if (foundNum) numId = foundNum.id;
        }
    }

    // Persistir os IDs resolvidos no objeto em memória
    if (corId) item.amostra_cor_id = corId;
    if (numId) item.amostra_num_id = numId;

    return { corId, numId };
}
window.resolveItemCorNumIds = resolveItemCorNumIds;

async function saveAmostraToDB(itemId, osId, dataToUpdate) {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;

    const itemLocal = state.osItens[osId]?.find(i => String(i.id) === String(itemId));
    if (!itemLocal) {
        console.warn('[SAVE] Item não encontrado no state. itemId=', itemId, '| osId=', osId);
        return;
    }

    // Modelo aprovado pelo cliente não se altera (regra do usuário, 19/08/2026).
    // Aqui, e não só nos controles da tela: botão cinza não impede ninguém de
    // chamar a função pelo console, e esta é a única porta que todas as
    // gravações de modelo atravessam.
    const bloqueio = bloqueioDeModeloAprovado(itemLocal, dataToUpdate);
    if (bloqueio) {
        if (!bloqueio.silencioso) toast(bloqueio.motivo, 'warning');
        return;
    }

    const modeloId = itemLocal._pedidoModeloId || itemLocal.id;

    try {
        const dbData = { ...dataToUpdate };
        
        // Auto-resolver amostra_cor_id e amostra_num_id se ausentes no payload ou no item
        const resolved = resolveItemCorNumIds(itemLocal);
        if (resolved.corId && !('amostra_cor_id' in dbData)) {
            dbData.amostra_cor_id = resolved.corId;
        }
        if (resolved.numId && !('amostra_num_id' in dbData)) {
            dbData.amostra_num_id = resolved.numId;
        }

        // Mapear amostra_status para status_arte (coluna oficial do Supabase)
        if (dbData.amostra_status) {
            if (dbData.amostra_status === 'PRONTO') {
                dbData.status_arte = 'AGUARDANDO_CLIENTE';
            } else if (dbData.amostra_status === 'APROVADA') {
                // QUEM aprovou fica registrado no próprio valor, e não numa coluna
                // nova: 'APROVADA_CLIENTE' é o botão APROVAR do link do cliente;
                // 'APROVADA' é o ✅ APROVADO do painel, apertado pelo atendente.
                //
                // Os dois valores já eram lidos como aprovado em todo o código
                // (as listas de aprovado — `ARTE_APROVADOS` e `validApproved` —,
                // o mapa de selos, o remapeamento da
                // carga em `statusFrontend`), e 'APROVADA' já é gravado NESTA
                // MESMA coluna pelo modal de artes — então não é vocabulário
                // novo para o sistema parceiro, é o que ele já recebe hoje.
                //
                // O link do cliente não passa por aqui: `cliente.js` tem o
                // próprio `saveAmostraToDB` e a página dele não carrega este
                // arquivo. A conferência abaixo é rede de segurança para o dia
                // em que o painel desenhar a tela do cliente.
                dbData.status_arte =
                    (state.amostrasContainerId === 'cliente-amostras-itens-container')
                        ? 'APROVADA_CLIENTE' : 'APROVADA';
            } else if (dbData.amostra_status === 'REPROVADA') {
                dbData.status_arte = 'REPROVADA_CLIENTE';
            }
        }

        // Mapear observação
        if ('amostra_obs' in dbData) {
            dbData.observacao_arte = dbData.amostra_obs;
        }

        // Garantir que padrao e gabarito_operacional estão preenchidos para pedidos_modelos
        if (!dbData.padrao && dbData.cor) {
            dbData.padrao = dbData.cor;
        }
        if (!dbData.gabarito_operacional && (dbData.numeracao || dbData.tipo_numeracao)) {
            dbData.gabarito_operacional = dbData.numeracao || dbData.tipo_numeracao;
        }

        // Remover campos virtuais ou não existentes na tabela pedidos_modelos
        delete dbData.amostra_obs;
        delete dbData.amostra_status;
        delete dbData.cor;
        delete dbData.numeracao;
        delete dbData.tipo_numeracao;
        delete dbData.url_arquivo_arte;
        delete dbData.url_arquivo;
        delete dbData.url_arquivo_arte_verso;
        delete dbData.verso_url_arquivo;
        delete dbData.arte_json;
        delete dbData.verso_arte_json;

        // GUARD: Nunca zerar arte_url/verso_arte_url/amostra_arte_base64 se já existir no item local, a menos que seja uma remoção explícita
        if ('arte_url' in dbData && dbData.arte_url === null && itemLocal.arte_url && !dataToUpdate._isExplicitRemove) {
            delete dbData.arte_url;
        }
        if ('amostra_arte_base64' in dbData && dbData.amostra_arte_base64 === null && itemLocal.amostra_arte_base64 && !dataToUpdate._isExplicitRemove) {
            delete dbData.amostra_arte_base64;
        }
        if ('verso_arte_url' in dbData && dbData.verso_arte_url === null && itemLocal.verso_arte_url && !dataToUpdate._isExplicitRemove) {
            delete dbData.verso_arte_url;
        }
        if ('verso_amostra_arte_base64' in dbData && dbData.verso_amostra_arte_base64 === null && itemLocal.verso_amostra_arte_base64 && !dataToUpdate._isExplicitRemove) {
            delete dbData.verso_amostra_arte_base64;
        }
        delete dbData._isExplicitRemove;

        // GUARD: Quando salvando qualquer dado do modelo, SEMPRE preservar/garantir amostra_cor_id e amostra_num_id
        if (!('amostra_cor_id' in dbData) && itemLocal.amostra_cor_id) {
            dbData.amostra_cor_id = itemLocal.amostra_cor_id;
        }
        if (!('amostra_num_id' in dbData) && itemLocal.amostra_num_id) {
            dbData.amostra_num_id = itemLocal.amostra_num_id;
        }

        // Se não sobrou nenhum campo para atualizar, evita fazer a requisição
        if (Object.keys(dbData).length === 0) {
            return;
        }

        // 1. Atualizar em pedidos_modelos (se não for item virtual não carregado)
        if (itemLocal._source === 'vibecode' && !itemLocal._dbLoaded) {
            console.log('[SAVE] Item virtual Vibecode: salvando overrides locais:', itemLocal.id);
            Object.assign(itemLocal, dataToUpdate);
            // O `Object.assign` copia a chave que veio e mais nada. Quando ela é
            // a numeração — e é: é assim que o modelo passa a apontar para uma
            // numeração nova salva no editor —, o espelho `numeracao_id` ficaria
            // para trás.
            if ('amostra_num_id' in dataToUpdate) {
                sincronizarNumeracaoDoItem(itemLocal, dataToUpdate.amostra_num_id);
            }
            const overrides = JSON.parse(localStorage.getItem('vibe_item_amostra_overrides') || '{}');
            const cacheKey = itemLocal.id;
            if (!overrides[cacheKey]) overrides[cacheKey] = {};
            Object.assign(overrides[cacheKey], dataToUpdate);
            localStorage.setItem('vibe_item_amostra_overrides', JSON.stringify(overrides));
        }
        
        let updatedCount = 0;

        // A) Tentar update por _pedidoModeloId ou ID do item
        if (modeloId && modeloId !== '') {
            const queryModeloId = (!isNaN(parseInt(modeloId)) && !String(modeloId).includes('vibe')) ? parseInt(modeloId) : modeloId;
            const { data: updateResult, error } = await vibeClient
                .from('pedidos_modelos')
                .update(dbData)
                .eq('id', queryModeloId)
                .select('id');

            if (!error && updateResult && updateResult.length > 0) {
                updatedCount = updateResult.length;
                console.log('[SAVE] OK por ID -> pedidos_modelos id=', queryModeloId, dbData);
            } else if (error) {
                console.error('[SAVE] Erro pedidos_modelos por ID:', error.message);
            }
        }

        // B) Tentar update por id_produto_proposta_origem
        if (updatedCount === 0 && itemId && !isNaN(parseInt(itemId))) {
            const propOrigemId = parseInt(itemId);
            const { data: res, error: err } = await vibeClient
                .from('pedidos_modelos')
                .update(dbData)
                .eq('id_produto_proposta_origem', propOrigemId)
                .select('id');
            if (!err && res && res.length > 0) {
                updatedCount = res.length;
                itemLocal._pedidoModeloId = res[0].id;
                console.log('[SAVE] OK por id_produto_proposta_origem=', propOrigemId, dbData);
            }
        }

        // C) Tentar update por id_int (número da OS) + ordem
        const osObj = typeof findOSInState === 'function' ? findOSInState(osId) : null;
        const osNum = osObj ? parseInt(osObj.numero) : parseInt(String(osId).replace('vibe_', ''));

        if (updatedCount === 0 && !isNaN(osNum)) {
            const itemOrdem = itemLocal ? (itemLocal.ordem || 1) : 1;
            const { data: res, error: err } = await vibeClient
                .from('pedidos_modelos')
                .update(dbData)
                .eq('id_int', osNum)
                .eq('ordem', itemOrdem)
                .select('id');
            if (!err && res && res.length > 0) {
                updatedCount = res.length;
                itemLocal._pedidoModeloId = res[0].id;
                console.log('[SAVE] OK por id_int + ordem=', osNum, itemOrdem, dbData);
            }
        }

        // D) Tentar update por id_int (qualquer linha da OS)
        if (updatedCount === 0 && !isNaN(osNum)) {
            const { data: res, error: err } = await vibeClient
                .from('pedidos_modelos')
                .update(dbData)
                .eq('id_int', osNum)
                .select('id');
            if (!err && res && res.length > 0) {
                updatedCount = res.length;
                itemLocal._pedidoModeloId = res[0].id;
                console.log('[SAVE] OK por id_int=', osNum, dbData);
            }
        }

        // E) Se NENHUMA linha existia em pedidos_modelos, AUTO-CRIAR (INSERT) a linha agora!
        if (updatedCount === 0 && !isNaN(osNum)) {
            const insertPayload = {
                id_int: osNum,
                id_produto_proposta_origem: (!isNaN(parseInt(itemId))) ? parseInt(itemId) : null,
                nome_modelo: itemLocal ? (itemLocal.nome_modelo || itemLocal.produto || 'Modelo') : 'Modelo',
                quantidade: itemLocal ? (itemLocal.qtd || itemLocal.quantidade || 0) : 0,
                ordem: itemLocal ? (itemLocal.ordem || 1) : 1,
                status_arte: 'PENDENTE',
                status_producao: 'PENDENTE',
                ...dbData
            };
            const { data: insData, error: insErr } = await vibeClient
                .from('pedidos_modelos')
                .insert([insertPayload])
                .select('id');
            if (!insErr && insData && insData.length > 0) {
                updatedCount = insData.length;
                if (itemLocal) itemLocal._pedidoModeloId = insData[0].id;
                console.log('[SAVE] INSERT OK em pedidos_modelos id=', insData[0].id, insertPayload);
            } else if (insErr) {
                console.error('[SAVE] Erro INSERT em pedidos_modelos:', insErr.message);
            }
        }

        // 2. ATUALIZAR PRODUTOS_PROPOSTA NO SUPABASE (SISTEMA VIBE)
        const propData = {};
        if ('amostra_cor_id' in dataToUpdate) propData.amostra_cor_id = dataToUpdate.amostra_cor_id;
        if ('amostra_num_id' in dataToUpdate) propData.amostra_num_id = dataToUpdate.amostra_num_id;
        if ('arte_url' in dataToUpdate) {
            propData.arte_url = dataToUpdate.arte_url;
        }
        if ('amostra_arte_base64' in dataToUpdate) propData.amostra_arte_base64 = dataToUpdate.amostra_arte_base64;

        if (Object.keys(propData).length > 0) {
            const propId = itemLocal.id_produto_proposta_origem || (typeof itemLocal.id === 'number' || (!isNaN(parseInt(itemLocal.id)) && !String(itemLocal.id).includes('vibe')) ? parseInt(itemLocal.id) : null);
            let propUpdated = false;

            if (propId) {
                const { error: propErr } = await vibeClient
                    .from('produtos_proposta')
                    .update(propData)
                    .eq('id', propId);
                if (!propErr) {
                    propUpdated = true;
                    console.log('[SAVE VIBE] OK -> produtos_proposta por ID=', propId, propData);
                } else {
                    console.warn('[SAVE VIBE] Erro ao atualizar produtos_proposta por ID:', propErr.message);
                }
            }

            if (!propUpdated && osId) {
                const osObj = typeof findOSInState === 'function' ? findOSInState(osId) : null;
                const osNum = osObj ? parseInt(osObj.numero) : parseInt(String(osId).replace('vibe_', ''));
                if (!isNaN(osNum)) {
                    let query = vibeClient.from('produtos_proposta').update(propData).eq('id_int', osNum);
                    if (itemLocal.nome_modelo || itemLocal.produto) {
                        query = query.eq('nome_produto', itemLocal.nome_modelo || itemLocal.produto);
                    }
                    const { error: propErr2 } = await query;
                    if (!propErr2) {
                        console.log('[SAVE VIBE] OK -> produtos_proposta por id_int=', osNum, propData);
                    } else {
                        console.warn('[SAVE VIBE] Erro ao atualizar produtos_proposta por id_int:', propErr2.message);
                    }
                }
            }
        }

        Object.assign(itemLocal, dataToUpdate);
        // `dataToUpdate` não tem `status_arte` — ele é derivado aqui. Sem copiar,
        // a faixa do card só saberia quem aprovou depois de um F5.
        if (dbData.status_arte) itemLocal.status_arte = dbData.status_arte;
        if ('arte_url' in dataToUpdate) {
            itemLocal.url_arquivo_arte = dataToUpdate.arte_url;
            itemLocal.url_arquivo = dataToUpdate.arte_url;
        }
        if ('verso_arte_url' in dataToUpdate) {
            itemLocal.url_arquivo_arte_verso = dataToUpdate.verso_arte_url;
            itemLocal.verso_url_arquivo = dataToUpdate.verso_arte_url;
        }
    } catch (e) {
        console.error('[SAVE] Erro em saveAmostraToDB:', e);
        throw e;
    }
}

// ========== MODO PDF MULTI-PÁGINA ==========
const pdfViewerState = {};

async function toggleModoPdf(idx, osId, itemId) {
    const items = state.osItens[osId] || [];
    const item = items.find(i => String(i.id) === String(itemId));
    if (!item) return;
    
    const novoModoPdf = !item.modo_pdf;
    item.modo_pdf = novoModoPdf;
    
    // Persiste no banco
    try {
        await saveAmostraToDB(itemId, osId, { modo_pdf: item.modo_pdf });
    } catch (e) {
        console.error('[PDF MODE] Erro ao salvar modo_pdf:', e);
    }
    
    // Ao desativar modo PDF: zerar a arte_url explicitamente
    if (!novoModoPdf && item.arte_url) {
        item.arte_url = null;
        try {
            await saveAmostraToDB(itemId, osId, { arte_url: null, _isExplicitRemove: true });
        } catch (e) {
            console.warn('[PDF MODE] Erro ao limpar arte_url:', e);
        }
    }
    
    // Re-renderiza a tela (necessário para criar/remover o canvas do DOM)
    // Preservar a arte_url e pdfViewerState antes do render
    const savedArteUrl = item.arte_url;
    const pdfKey = `${osId}_${idx}`;
    const savedViewerState = pdfViewerState[pdfKey] || pdfViewerState[idx];
    
    renderAmostrasOSItens(osId);
    
    // Após o DOM ser reconstruído, restaurar o viewer se havia PDF
    if (novoModoPdf && savedArteUrl) {
        setTimeout(async () => {
            if (savedViewerState && savedViewerState.pdfUrl === savedArteUrl) {
                pdfViewerState[pdfKey] = savedViewerState;
                pdfViewerState[idx] = savedViewerState;
                await renderPdfViewerPage(pdfKey, savedViewerState.currentPage || 1, idx);
            } else {
                await initPdfViewer(pdfKey, savedArteUrl, osId, idx);
            }
        }, 50);
    }
    
    toast(item.modo_pdf ? '📄 Modo PDF ativado — numeração mantida' : '🎨 Modo padrão restaurado', 'info');
}

function getPdfUrlForItem(item, face, osId, idx) {
    if (!item) return null;
    const faceKey = face === 'back' ? 'verso' : 'frente';
    
    // 1. Procurar em campos diretos de URL de PDF do item
    let candidate = face === 'back'
        ? (item.verso_arte_url || item.url_arquivo_arte_verso || item.verso_url_arquivo)
        : (item.arte_url || item.url_arquivo_arte || item.url_arquivo);
        
    // 2. Se não achou no item, procurar no localStorage local da máquina
    if (!candidate) {
        candidate = (item.id ? localStorage.getItem(`ideal_arte_url_${item.id}_${faceKey}`) : null) ||
                    localStorage.getItem(`ideal_arte_url_${osId}_${idx}_${faceKey}`);
    }
    
    // 3. Se ainda não achou, procurar em pedidos_artes no state global
    if (!candidate && typeof state !== 'undefined' && state.todasArtes && state.todasArtes.length > 0) {
        const queryNum = parseInt(String(osId).replace('vibe_', ''));
        if (!isNaN(queryNum)) {
            const artesDoItem = state.todasArtes.filter(a => 
                (a.id_int === queryNum || String(a.id_int) === String(queryNum)) && 
                (String(a.id_modelo) === String(item.id) || (item._pedidoModeloId && String(a.id_modelo) === String(item._pedidoModeloId)))
            );
            if (artesDoItem.length > 0) {
                artesDoItem.sort((a, b) => (b.versao || 0) - (a.versao || 0));
                candidate = face === 'back' ? artesDoItem[0].verso_url_arquivo : artesDoItem[0].url_arquivo;
            }
        }
    }

    // 4. Fallback de imagem snapshot se não houver PDF
    if (!candidate) {
        candidate = face === 'back' ? item.verso_amostra_arte_base64 : item.amostra_arte_base64;
    }
    
    return candidate || null;
}

async function renderImageModeInPdfViewer(idx, imgUrl, item, osId) {
    const canvas = document.getElementById(`amostra-pdf-canvas-${idx}`);
    if (!canvas) return;
    
    const img = new Image();
    img.crossOrigin = 'Anonymous';
    await new Promise((resolve) => {
        img.onload = resolve;
        img.onerror = resolve;
        img.src = imgUrl;
    });
    
    if (img.width > 0 && img.height > 0) {
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
        
        // Estampar numeração sobre a imagem
        const containerId = state.amostrasContainerId || 'amostras-itens-container';
        const container = document.getElementById(containerId);
        const numSelect = container ? container.querySelector(`#amostra-item-num-${idx}`) : null;
        const numId = (numSelect && numSelect.value) ? numSelect.value : (item ? (item.amostra_num_id || item.numeracao_id || item.numeracao || item.gabarito_operacional) : null);
        let num = null;
        if (numId && state.numeracoes) {
            const numIdStr = String(numId).trim().toLowerCase();
            num = state.numeracoes.find(n => 
                String(n.id) === String(numId) || 
                String(n.name).trim().toLowerCase() === numIdStr || 
                String(n.tipo).trim().toLowerCase() === numIdStr
            );
        }
        if (num && num.elements && num.elements.length > 0) {
            // A arte dos elementos SVG/PDF precisa estar carregada ANTES de desenhar:
            // esta funcao e async, entao da para esperar de verdade e sair certo de
            // primeira, sem o vai-e-volta de carregar e mandar redesenhar.
            await precarregarArtesDosElementos(num.elements, linhasDaPagina(num, item, 1));
            drawNumeracaoElementsOverCanvas(ctx, num, item, 1, canvas.width, canvas.height);
        }

        canvas.style.display = 'block';

        const nav = document.getElementById(`amostra-pdf-nav-${idx}`);
        if (nav) nav.style.display = 'none';
        
        const empty = document.getElementById(`amostra-item-empty-${idx}`);
        if (empty) empty.style.display = 'none';
    }
}

/* ═══ A ESCALA DA CAMADA DE ARTE (31/08/2026) ═══════════════════════════════
 *
 * Pedido do usuário: no modo PDF Multi-Página, dois campos — % horizontal e %
 * vertical — que esticam SÓ a arte, mantendo-a centralizada na célula, e que
 * valem igual na tela e no papel ("mesma escala para arte no motor de
 * impressão, imposição, gerar pdf").
 *
 * 100/100 é o tamanho natural do arquivo, que é o que o motor sempre fez: por
 * isso todo modelo que já existe nasce com esse par e nada muda para ele.
 *
 * Onde ela é lida, além daqui: no payload da imposição (`runImposition`, e o
 * gêmeo do pedido.js), na prévia da imposição (pedido.js) e no `engine.py`, na
 * função `_arte_na_celula`. Quem grava é `salvarEscalaDaArte`, nas colunas
 * `arte_escala_h` / `arte_escala_v` de `pedidos_modelos`.
 */
const ESCALA_ARTE_MIN = 1;
const ESCALA_ARTE_MAX = 400;

/** A escala da arte deste modelo, em %. Sem nada gravado, 100 e 100. */
function escalaDaArteDoModelo(item) {
    const ler = (v) => {
        const n = parseFloat(v);
        if (!isFinite(n) || n <= 0) return 100;
        return Math.min(ESCALA_ARTE_MAX, Math.max(ESCALA_ARTE_MIN, n));
    };
    return { h: ler(item?.arte_escala_h), v: ler(item?.arte_escala_v) };
}
window.escalaDaArteDoModelo = escalaDaArteDoModelo;

/** A escala está no padrão? Então nenhum desenho precisa mudar de caminho. */
function escalaDaArteEhPadrao(esc) {
    return !esc || (esc.h === 100 && esc.v === 100);
}
window.escalaDaArteEhPadrao = escalaDaArteEhPadrao;

/**
 * A escala da arte do modelo que está sendo imposto ou impresso agora.
 *
 * Numa folha que combina modelos ela não serve: ali cada arte leva a sua em
 * `multi_artes[].escala_h/_v`, e esta vira só a reserva do motor.
 */
function escalaDaArteDoTrabalho() {
    const alvo = state.activeOSItem;
    if (!alvo || !state.osItens || !state.osItens[alvo.osId]) return { h: 100, v: 100 };
    const item = state.osItens[alvo.osId].find(i => String(i.id) === String(alvo.itemId));
    return escalaDaArteDoModelo(item);
}
window.escalaDaArteDoTrabalho = escalaDaArteDoTrabalho;

/**
 * Mostra ou esconde os dois campos de escala do card, e devolve a eles o que
 * está gravado.
 *
 * A regra é uma só, valha a arte para o modo PDF Multi-Página ou para o upload
 * comum: **os campos aparecem quando há arte na tela**. Sem arte não há o que
 * escalar, e dois campos mudos ao lado do "faça upload" só fariam pergunta.
 *
 * O campo que está sendo digitado não é sobrescrito — um redesenho do card no
 * meio da digitação apagaria o número pela metade.
 */
function atualizarCaixaDeEscalaDaArte(idx, item, container) {
    const onde = container || document;
    const caixa = onde.querySelector
        ? onde.querySelector(`#amostra-escala-${idx}`)
        : document.getElementById(`amostra-escala-${idx}`);
    if (!caixa) return;

    const temArte = !!(item && (itemTemArte(item, 'frente') || itemTemArte(item, 'verso')));
    caixa.style.display = temArte ? 'flex' : 'none';
    if (!temArte) return;

    const esc = escalaDaArteDoModelo(item);
    const campoH = document.getElementById(`amostra-escala-h-${idx}`);
    const campoV = document.getElementById(`amostra-escala-v-${idx}`);
    if (campoH && document.activeElement !== campoH) campoH.value = esc.h;
    if (campoV && document.activeElement !== campoV) campoV.value = esc.v;
}
window.atualizarCaixaDeEscalaDaArte = atualizarCaixaDeEscalaDaArte;

/**
 * O formato cadastrado deste modelo, ou null.
 *
 * Devolve null de propósito quando não acha: quem precisa de um palpite decide
 * qual — a prévia do card usa o primeiro do catálogo há muito tempo, e a janela
 * do modo PDF prefere continuar usando a própria página da arte a inventar uma
 * célula de outro trabalho.
 */
/**
 * O aviso de que o modelo está sem formato, escrito no lugar da peça.
 *
 * Regra do usuário (02/09/2026): *"todo modelo exige obrigatoriamente um formato
 * vinculado"*. Quando nenhum dos três caminhos do `formatoDoModelo` responde, a
 * tela não inventa medida — diz o que falta e o que fazer, que é a regra de toda
 * trava deste projeto.
 *
 * Escreve em todos os canvas da peça (frente, verso e o do modo PDF), porque
 * qualquer um deles que ficasse desenhado com a medida anterior continuaria
 * mentindo na tela.
 */
function avisarModeloSemFormato(container, idx, temVerso) {
    const alvos = [`#amostra-item-canvas-${idx}`, `#amostra-pdf-canvas-${idx}`];
    if (temVerso) alvos.push(`#amostra-item-canvas-verso-${idx}`);
    alvos.forEach(sel => {
        const canvas = container ? container.querySelector(sel) : null;
        if (!canvas) return;
        canvas.width = 300;
        canvas.height = 200;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#f8fafc';
        ctx.fillRect(0, 0, 300, 200);
        ctx.textAlign = 'center';
        ctx.fillStyle = '#b45309';
        ctx.font = '13px Inter, sans-serif';
        ctx.fillText('Sem formato para este modelo.', 150, 92);
        ctx.fillStyle = '#64748b';
        ctx.font = '12px Inter, sans-serif';
        ctx.fillText('Escolha a Cor ou a Numeração acima —', 150, 116);
        ctx.fillText('é delas que sai o tamanho da peça.', 150, 134);
        canvas.style.display = 'block';
    });
}
window.avisarModeloSemFormato = avisarModeloSemFormato;

function formatoDoModelo(item, cor, num) {
    if (!state.formatos || !state.formatos.length) return null;
    if (cor && cor.formato_id) {
        const f = state.formatos.find(x => String(x.id) === String(cor.formato_id));
        if (f) return f;
    }
    if (num && num.formato_id) {
        const f = state.formatos.find(x => String(x.id) === String(num.formato_id));
        if (f) return f;
    }
    // O FORMATO DO PRÓPRIO MODELO, POR ÚLTIMO (02/09/2026).
    //
    // Regra do usuário: *"todo modelo exige obrigatoriamente um formato
    // vinculado"*. `pedidos_modelos` não tem coluna de formato — ele chega ao
    // modelo por três caminhos, e esta função só olhava dois. O terceiro é o
    // `item.formato_id`, preenchido em memória a partir do produto do ERP (ver
    // `formatoPadraoId`).
    //
    // Sem esta linha, um modelo que ainda não tem cor nem numeração era tratado
    // como "sem formato", e quem chama caía num palpite: a moldura do
    // visualizador virava a PÁGINA DA ARTE e mudava junto com o arquivo. Medido
    // com um modelo de célula 105 x 148: a arte de 104,35 x 158,35 desenhava a
    // moldura em 104,42 x 158,40, e a de 110,70 x 164,70 em 110,77 x 164,75.
    //
    // Por ÚLTIMO de propósito: a cor e a numeração são a escolha explícita do
    // operador para aquele card, e a célula tem de ser a que elas implicam. O
    // formato do produto vale enquanto ninguém escolheu — com cor ou numeração
    // presentes, nada muda.
    if (item && item.formato_id) {
        const f = state.formatos.find(x => String(x.id) === String(item.formato_id));
        if (f) return f;
    }
    return null;
}
window.formatoDoModelo = formatoDoModelo;

/**
 * Grava a escala digitada e redesenha a janela.
 *
 * A gravação passa pelo `saveAmostraToDB` de sempre, e é ele quem recusa a
 * escrita num modelo já aprovado pelo cliente — a mesma trava do resto do card,
 * com a mesma mensagem.
 */
async function salvarEscalaDaArte(idx, osId, itemId) {
    const item = (state.osItens[osId] || []).find(i => String(i.id) === String(itemId));
    if (!item) return;

    const campoH = document.getElementById(`amostra-escala-h-${idx}`);
    const campoV = document.getElementById(`amostra-escala-v-${idx}`);
    if (!campoH || !campoV) return;

    // Uma casa decimal basta para o ajuste fino e evita o 99,99999 do float.
    const limpar = (campo) => {
        const n = parseFloat(String(campo.value).replace(',', '.'));
        if (!isFinite(n) || n <= 0) return 100;
        return Math.round(Math.min(ESCALA_ARTE_MAX, Math.max(ESCALA_ARTE_MIN, n)) * 10) / 10;
    };
    const h = limpar(campoH);
    const v = limpar(campoV);
    // O campo volta a mostrar o valor já aparado: digitar 900 e ver 900 na tela
    // enquanto o papel sai a 400 seria mentir para o operador.
    campoH.value = h;
    campoV.value = v;

    if (h === parseFloat(item.arte_escala_h ?? 100) && v === parseFloat(item.arte_escala_v ?? 100)) {
        return;
    }

    item.arte_escala_h = h;
    item.arte_escala_v = v;
    // A arte de aprovação do cliente é refeita no MARCAR PRONTO; marcar aqui faz
    // a prévia guardada acompanhar quem já estava pronto antes da mudança.
    item._needsSnapshot = true;

    try {
        await saveAmostraToDB(itemId, osId, { arte_escala_h: h, arte_escala_v: v });
    } catch (e) {
        console.error('[Escala da arte] Erro ao salvar:', e);
        toast('Não consegui salvar a escala da arte: ' + (e.message || e), 'error');
        return;
    }

    // Redesenhar pelo caminho deste card: no modo PDF quem desenha é o leitor de
    // páginas; na arte comum é a composição das camadas do card. Chamar só um
    // dos dois deixava metade dos modelos com a escala nova gravada e a arte
    // antiga na tela até alguém recarregar.
    const key = `${osId}_${idx}`;
    const vs = pdfViewerState[key] || pdfViewerState[idx];
    if (item.modo_pdf && vs && vs.pdf) {
        await renderPdfViewerPage(key in pdfViewerState ? key : idx, vs.currentPage || 1, idx);
    } else {
        await renderItemAmostraCombinada(idx, osId);
    }

    toast(`Escala da arte: ${h}% na horizontal, ${v}% na vertical.`, 'success');
}
window.salvarEscalaDaArte = salvarEscalaDaArte;

/** Volta a arte ao tamanho natural do arquivo. */
async function zerarEscalaDaArte(idx, osId, itemId) {
    const campoH = document.getElementById(`amostra-escala-h-${idx}`);
    const campoV = document.getElementById(`amostra-escala-v-${idx}`);
    if (campoH) campoH.value = 100;
    if (campoV) campoV.value = 100;
    await salvarEscalaDaArte(idx, osId, itemId);
}
window.zerarEscalaDaArte = zerarEscalaDaArte;

async function initPdfViewer(key, pdfUrl, osId = null, idx = 0) {
    if (!pdfUrl) return;
    
    try {
        let arrayBuffer;
        // Tentar buscar diretamente (Supabase Storage permite CORS para buckets públicos)
        try {
            const directResponse = await fetch(pdfUrl);
            if (directResponse.ok) {
                arrayBuffer = await directResponse.arrayBuffer();
            } else {
                throw new Error('Direct fetch failed: ' + directResponse.status);
            }
        } catch (directErr) {
            console.warn('[PDF Viewer] Fetch direto falhou, tentando proxy...', directErr);
            // Fallback: usar proxy local (quando rodando com backend Python)
            const proxyUrl = urlDoProxy(pdfUrl);
            const proxyResponse = await fetch(proxyUrl);
            if (!proxyResponse.ok) throw new Error('Proxy fetch failed: ' + proxyResponse.status);
            arrayBuffer = await proxyResponse.arrayBuffer();
        }
        
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        
        const stateObj = {
            pdf: pdf,
            pdfUrl: pdfUrl,
            currentPage: 1,
            totalPages: pdf.numPages,
            osId: osId,
            idx: idx
        };
        pdfViewerState[key] = stateObj;
        pdfViewerState[idx] = stateObj;
        
        await renderPdfViewerPage(key, 1, idx);
    } catch (err) {
        console.error('[PDF Viewer] Erro ao carregar PDF:', err);
        delete pdfViewerState[key];
        delete pdfViewerState[idx];

        // Fallback: se houver imagem (amostra_arte_base64), renderizar como imagem
        const item = (osId && state.osItens && state.osItens[osId]) ? state.osItens[osId][idx] : null;
        if (item && item.amostra_arte_base64) {
            renderImageModeInPdfViewer(idx, item.amostra_arte_base64, item, osId);
        }
    }
}

function drawNumeracaoElementsOverCanvas(ctx, num, item, pageNum, canvasWidth, canvasHeight) {
    if (!ctx || !num || !num.elements || !num.elements.length) return;

    let fmt = null;
    if (num.formato_id && state.formatos) {
        fmt = state.formatos.find(f => String(f.id) === String(num.formato_id));
    }
    const width_mm = (fmt && fmt.width_mm) ? fmt.width_mm : 180;
    const height_mm = (fmt && fmt.height_mm) ? fmt.height_mm : 50;

    const Sx = canvasWidth / width_mm;
    const Sy = canvasHeight / height_mm;
    const S = Sx;

    const seqStart = parseInt(
        item?.numeracao_inicio || item?.num_inicial || item?.NUMERACAO_INICIO || 1
    ) || 1;

    num.elements.forEach(el => {
        if (el.face === 'back') return;

        const x = el.x_mm * Sx;
        const y = el.y_mm * Sy;
        const color = el.color || '#000000';
        const rot = (el.rotation || 0) * Math.PI / 180;

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(rot);

        if (el.type === 'TEXT' || el.type === 'FIXED' || el.type.startsWith('TEATRO_') || el.type.startsWith('CAMAROTE_')) {
            const fs = (el.font_size || 12) * S / 2.8346;
            ctx.font = buildCanvasFont(fs, el.font_name);
            ctx.fillStyle = color;

            let label = '';
            if (el.type === 'FIXED') {
                label = el.fixed_value || 'TEXTO';
            } else if (el.type === 'TEATRO_FILA') {
                const _fVal = (state.csvData && state.csvData[pageNum - 1]) ? state.csvData[pageNum - 1].Fila || 'A' : 'A';
                label = `${el.prefix || ''}${_fVal}`;
            } else if (el.type === 'TEATRO_LUGAR') {
                const _lVal = (state.csvData && state.csvData[pageNum - 1]) ? state.csvData[pageNum - 1].Numero || String(pageNum) : String(pageNum);
                label = `${el.prefix || ''}${_lVal}`;
            } else if (el.type === 'TEATRO_COMBO') {
                const _fVal = (state.csvData && state.csvData[pageNum - 1]) ? state.csvData[pageNum - 1].Fila || 'A' : 'A';
                const _lVal = (state.csvData && state.csvData[pageNum - 1]) ? state.csvData[pageNum - 1].Numero || String(pageNum) : String(pageNum);
                const fila = `${el.prefix_fila || ''}${_fVal}`;
                const lugar = `${el.prefix_lugar || ''}${_lVal}`;
                label = el.layout === '2lines' ? `${fila}\n${lugar}` : `${fila} - ${lugar}`;
            } else if (el.type === 'CAMAROTE_LOCAL') {
                const _cIni = parseInt(item?.c_ini || item?.C_INI || 1);
                label = `${el.prefix || ''}${_cIni}`;
            } else if (el.type === 'CAMAROTE_PESSOA') {
                label = `${el.prefix || ''}${pageNum}`;
            } else if (el.type === 'CAMAROTE_PESSOA_TOTAL') {
                const _lCamB = parseInt(item?.l_cam || item?.L_CAM || 5);
                label = `${el.prefix || ''}${pageNum}/${_lCamB}`;
            } else if (el.source === 'database') {
                const colName = el.csv_column || '';
                // A pagina N do PDF mostra a linha N da FATIA deste modelo. Antes
                // indexava o banco inteiro: um modelo cuja fatia comeca na linha
                // 601 exibia a linha 1 na primeira pagina.
                const csvData = (typeof linhasDaAmostra === 'function')
                    ? linhasDaAmostra(item, num)
                    : (num?.csv_data || item?.csv_data || []);
                const csvRow = csvData[pageNum - 1] || null;
                if (csvRow && typeof csvRow[colName] !== 'undefined' && csvRow[colName] !== '') {
                    label = `${el.prefix || ''}${csvRow[colName]}${el.suffix || ''}`;
                } else {
                    label = textoDeExemploDoElemento(el);
                }
            } else {
                const padVal = typeof el.pad !== 'undefined' ? parseInt(el.pad) : 6;
                let current_val = seqStart + (pageNum - 1);
                if (num && num.tipo === "TICKET") {
                    const pos = parseInt(el.ticket_pos) || 1;
                    const ticketQtd = parseInt(num.ticket_qtd) || 1;
                    current_val = seqStart + ((pageNum - 1) * ticketQtd) + (pos - 1);
                }
                label = `${el.prefix || ''}${String(current_val).padStart(padVal, '0')}${el.suffix || ''}`;
            }

            window.desenharTextoAjustado(
                ctx, el, label, fs, Sx,
                (f) => buildCanvasFont(f, el.font_name)
            );
        } else if (el.type === 'QR_IDEAL') {
            // Aqui o pedido e o modelo existem: `item` é a linha de
            // `pedidos_modelos`, com `id_int` (pedido) e `id` (modelo). O número
            // do ingresso segue a MESMA conta do elemento de numeração acima —
            // se divergissem, a tela mostraria um código e o papel sairia outro.
            let _qiVal = seqStart + (pageNum - 1);
            if (num && num.tipo === "TICKET") {
                const _qiPos = parseInt(el.ticket_pos) || 1;
                const _qiQtd = parseInt(num.ticket_qtd) || 1;
                _qiVal = seqStart + ((pageNum - 1) * _qiQtd) + (_qiPos - 1);
            }
            window.desenharQRIdeal(
                ctx, el, (el.size_mm || 15) * S, el.color || '#000000',
                item?.id_int, item?.id, _qiVal
            );

        } else if (el.type === 'QR') {
            const sz = (el.size_mm || 15) * S;
            let qrText = '';
            if (el.fixed) {
                qrText = el.fixed_value || '';
            } else if (el.source === 'database') {
                const colName = el.csv_column || '';
                const csvData = (typeof linhasDaAmostra === 'function')
                    ? linhasDaAmostra(item, num)
                    : (num?.csv_data || item?.csv_data || []);
                const csvRow = csvData[pageNum - 1] || null;
                if (csvRow && typeof csvRow[colName] !== 'undefined' && csvRow[colName] !== '') {
                    qrText = `${el.prefix || ''}${csvRow[colName]}${el.suffix || ''}`;
                } else {
                    qrText = `${el.prefix || ''}[${colName || 'coluna'}]${el.suffix || ''}`;
                }
            } else {
                const padVal = typeof el.pad !== 'undefined' ? parseInt(el.pad) : 4;
                let current_val = seqStart + (pageNum - 1);
                const raw = padVal > 0 ? String(current_val).padStart(padVal, '0') : String(current_val);
                qrText = `${el.prefix || ''}${raw}${el.suffix || ''}`;
            }
            if (typeof renderQRCodeOnCtx === 'function') {
                renderQRCodeOnCtx(ctx, qrText, 0, 0, sz, color);
            }
        } else if (el.type === 'BARCODE') {
            const bw = (el.barcode_width_mm || el.width_mm || 30) * S;
            const bh = (el.barcode_height_mm || el.height_mm || 8) * S;
            let bcText = '';
            if (el.fixed) {
                bcText = el.fixed_value || '';
            } else if (el.source === 'database') {
                const colName = el.csv_column || '';
                const csvData = (typeof linhasDaAmostra === 'function')
                    ? linhasDaAmostra(item, num)
                    : (num?.csv_data || item?.csv_data || []);
                const csvRow = csvData[pageNum - 1] || null;
                if (csvRow && typeof csvRow[colName] !== 'undefined' && csvRow[colName] !== '') {
                    bcText = `${el.prefix || ''}${csvRow[colName]}${el.suffix || ''}`;
                } else {
                    bcText = `${el.prefix || ''}${colName || 'COLUNA'}${el.suffix || ''}`;
                }
            } else {
                const padVal = typeof el.pad !== 'undefined' ? parseInt(el.pad) : 4;
                const current_val = seqStart + (pageNum - 1);
                const raw = padVal > 0 ? String(current_val).padStart(padVal, '0') : String(current_val);
                bcText = `${el.prefix || ''}${raw}${el.suffix || ''}`;
            }
            window.renderBarcodeOnCtx(ctx, bcText, 0, 0, bw, bh, color, el.barcode_format);
        } else if (el.type === 'PICOTE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 2.0;
            ctx.setLineDash([6, 3]);
            ctx.beginPath();
            ctx.moveTo(0, -y);
            ctx.lineTo(0, canvasHeight - y);
            ctx.stroke();
            ctx.setLineDash([]);
        } else if (el.type === 'FOTO') {
            // Modo PDF (multipaginas): a pagina N mostra a linha N da FATIA deste
            // modelo, nao do banco inteiro — a mesma regra do texto variavel logo
            // acima. Indexar o banco inteiro faria o modelo cuja fatia comeca na
            // linha 601 estampar o rosto da pessoa 1.
            const _linhasFoto = (typeof linhasDaAmostra === 'function')
                ? linhasDaAmostra(item, num)
                : (num?.csv_data || item?.csv_data || []);
            desenharElementoFoto(ctx, el, S, false, _linhasFoto[pageNum - 1] || null, null);
        } else if (el.type === 'SVG' || el.type === 'PDF') {
            // Sem este ramo, o modo PDF (multipaginas) desenhava todos os outros tipos
            // e simplesmente pulava SVG e PDF: o forEach caia fora de todos os else-if
            // e nao pintava nada. A arte ja vinha carregada — quem chama esta funcao
            // aguarda precarregarArtesDosElementos() —, faltava so desenhar.
            const w = (el.width_mm || 20) * S;
            const h = (el.height_mm || 20) * S;
            const hw = w / 2, hh_el = h / 2;
            const imgObj = el.type === 'PDF' ? (el._pdfCanvas || null) : (el._svgImage || null);

            ctx.save();
            ctx.beginPath();
            ctx.rect(-hw, -hh_el, w, h);
            ctx.clip();

            if (imgObj) {
                // Tamanho original, escala 100%, sem distorcao — como o engine.py impoe
                drawArteDoElemento(ctx, imgObj, -hw, -hh_el, w, h, el);
            } else {
                // Caixa com o nome do tipo, o mesmo aviso visual dos outros renderizadores
                ctx.strokeStyle = color;
                ctx.lineWidth = 1;
                ctx.strokeRect(-hw, -hh_el, w, h);
                ctx.font = `${Math.max(6, h * 0.15)}px Inter, sans-serif`;
                ctx.fillStyle = color;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(el.type, 0, 0);
                ctx.textAlign = 'left';
                ctx.textBaseline = 'alphabetic';
            }
            ctx.restore();
        }
        ctx.restore();
    });
}

async function renderPdfViewerPage(keyOrIdx, pageNum, idxParam = null) {
    const viewerState = pdfViewerState[keyOrIdx] || pdfViewerState[idxParam];
    if (!viewerState || !viewerState.pdf) return;
    
    // Extrair SEMPRE o índice numérico real do card na DOM (0, 1, 2...)
    let idx = (idxParam !== null && idxParam !== undefined) ? idxParam : viewerState.idx;
    if (idx === undefined || idx === null || isNaN(parseInt(idx))) {
        if (typeof keyOrIdx === 'string' && keyOrIdx.includes('_')) {
            const parts = keyOrIdx.split('_');
            idx = parseInt(parts[parts.length - 1]);
            if (isNaN(idx)) idx = 0;
        } else {
            idx = parseInt(keyOrIdx);
            if (isNaN(idx)) idx = 0;
        }
    }
    
    try {
        const page = await viewerState.pdf.getPage(pageNum);
        const scale = 2.0;
        const viewport = page.getViewport({ scale });

        const canvas = document.getElementById(`amostra-pdf-canvas-${idx}`);
        if (!canvas) {
            console.warn(`[PDF Viewer] Canvas #amostra-pdf-canvas-${idx} não encontrado no DOM (keyOrIdx=${keyOrIdx}).`);
            return;
        }

        // Quem é este modelo e qual a numeração dele — resolvido ANTES de medir
        // o canvas, porque é daí que saem a escala da arte e o tamanho da célula.
        const containerId = state.amostrasContainerId || 'amostras-itens-container';
        const container = document.getElementById(containerId);
        const numSelect = container ? container.querySelector(`#amostra-item-num-${idx}`) : null;
        const osId = viewerState.osId;
        const items = (osId && state.osItens && state.osItens[osId]) ? state.osItens[osId] : [];
        const item = items[idx] || (state.activeOSItem ? state.activeOSItem : null);

        let numId = (numSelect && numSelect.value) ? numSelect.value : (item ? (item.amostra_num_id || item.numeracao_id || item.numeracao || item.gabarito_operacional) : null);
        let num = null;
        if (numId && state.numeracoes) {
            const numIdStr = String(numId).trim().toLowerCase();
            num = state.numeracoes.find(n =>
                String(n.id) === String(numId) ||
                String(n.name).trim().toLowerCase() === numIdStr ||
                String(n.tipo).trim().toLowerCase() === numIdStr
            );
        }

        // O CANVAS É A CÉLULA, E NÃO A PÁGINA DA ARTE (31/08/2026).
        //
        // Enquanto o canvas era a própria página do PDF, escalar a arte não teria
        // como aparecer: a moldura crescia junto e a peça continuava parecendo
        // cheia. Medindo a célula, a arte a 80% aparece menor DENTRO dela, com o
        // papel em volta — que é o que a impressora vai fazer.
        //
        // O formato preferido é o da NUMERAÇÃO porque é dele que o
        // `drawNumeracaoElementsOverCanvas` tira os milímetros logo abaixo; usar
        // outro aqui poria os elementos fora do lugar. Sem formato nenhum, o
        // canvas continua sendo a página da arte, exatamente como antes.
        const cor = (item && item.amostra_cor_id && state.cores)
            ? state.cores.find(c => String(c.id) === String(item.amostra_cor_id)) : null;
        const fmt = formatoDoModelo(item, null, num) || formatoDoModelo(item, cor, null);
        const MM_EM_PT = 2.8346;
        // A MOLDURA É O FORMATO, NUNCA A ARTE (02/09/2026).
        //
        // Aqui havia um plano B: sem formato, a célula virava `viewport.width` —
        // a página do arquivo. A moldura passava a mudar de tamanho conforme a
        // arte carregada, e duas faces com arquivos diferentes apareciam em
        // molduras diferentes. Regra do usuário: o que define o tamanho da janela
        // é o formato, não a arte, e todo modelo tem um formato vinculado.
        //
        // O `formatoDoModelo` agora enxerga também o formato do próprio modelo,
        // então o caso "não achei formato" ficou restrito a catálogo não
        // carregado. Nesse caso a janela não desenha: mostrar uma peça de medida
        // inventada é pior do que dizer que falta — e a frase diz o que fazer.
        if (!fmt || !fmt.width_mm || !fmt.height_mm) {
            const ctxAviso = canvas.getContext('2d');
            canvas.width = 300; canvas.height = 200;
            ctxAviso.fillStyle = '#f8fafc';
            ctxAviso.fillRect(0, 0, 300, 200);
            ctxAviso.fillStyle = '#b45309';
            ctxAviso.font = '13px Inter, sans-serif';
            ctxAviso.textAlign = 'center';
            ctxAviso.fillText('Sem formato para este modelo.', 150, 92);
            ctxAviso.fillStyle = '#64748b';
            ctxAviso.font = '12px Inter, sans-serif';
            ctxAviso.fillText('Escolha a Cor ou a Numeração acima —', 150, 116);
            ctxAviso.fillText('é delas que sai o tamanho da peça.', 150, 134);
            canvas.style.display = 'block';
            return;
        }
        const larguraCelula = fmt.width_mm * MM_EM_PT * scale;
        const alturaCelula = fmt.height_mm * MM_EM_PT * scale;

        const esc = escalaDaArteDoModelo(item);
        const larguraArte = viewport.width * esc.h / 100;
        const alturaArte = viewport.height * esc.v / 100;
        const arteX = (larguraCelula - larguraArte) / 2;
        const arteY = (alturaCelula - alturaArte) / 2;

        canvas.width = Math.max(1, Math.round(larguraCelula));
        canvas.height = Math.max(1, Math.round(alturaCelula));
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        // O papel por baixo: sem ele, a arte menor que a célula deixaria o vazio
        // transparente, e o operador veria o fundo da tela onde vai haver papel.
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // A arte, esticada em cada eixo e centralizada. O `transform` do pdf.js
        // desenha na resolução final — nada é ampliado depois, então a página
        // continua nítida em qualquer escala. O que passa da borda do canvas é
        // aparado pelo próprio canvas, como o motor apara na célula.
        await page.render({
            canvasContext: ctx,
            viewport: viewport,
            transform: [esc.h / 100, 0, 0, esc.v / 100, arteX, arteY],
        }).promise;

        if (num && num.elements && num.elements.length > 0) {
            // Ver o comentario em renderImageModeInPdfViewer: a arte dos elementos
            // SVG/PDF e aguardada aqui, antes de desenhar.
            await precarregarArtesDosElementos(num.elements, linhasDaPagina(num, item, pageNum));
            // A numeração é carimbada sobre a CÉLULA, e não sobre a arte: ela
            // não anda nem estica junto com a escala — a arte é a única camada
            // que muda de tamanho. Por isso as medidas vêm do canvas.
            drawNumeracaoElementsOverCanvas(ctx, num, item, pageNum, canvas.width, canvas.height);
        }

        canvas.style.display = 'block';

        // Update navigation
        const nav = document.getElementById(`amostra-pdf-nav-${idx}`);
        if (nav) nav.style.display = 'flex';

        // Os campos de escala aparecem junto com a navegação: agora existe uma
        // arte na tela para escalar. A regra e a atualização dos valores são as
        // mesmas da arte comum — ver `atualizarCaixaDeEscalaDaArte`.
        atualizarCaixaDeEscalaDaArte(idx, item, container);

        const pageInfo = document.getElementById(`amostra-pdf-page-info-${idx}`);
        if (pageInfo) pageInfo.textContent = `Página ${pageNum} / ${viewerState.totalPages}`;
        
        // Hide empty state
        const empty = document.getElementById(`amostra-item-empty-${idx}`);
        if (empty) empty.style.display = 'none';
        
        viewerState.currentPage = pageNum;
    } catch (err) {
        console.error('[PDF Viewer] Erro ao renderizar página:', err);
    }
}

function pdfViewerPrevPage(idx) {
    const key = (state.activeOSId ? `${state.activeOSId}_${idx}` : idx);
    const viewerState = pdfViewerState[key] || pdfViewerState[idx];
    if (!viewerState || viewerState.currentPage <= 1) return;
    renderPdfViewerPage(key in pdfViewerState ? key : idx, viewerState.currentPage - 1, idx);
}

function pdfViewerNextPage(idx) {
    const key = (state.activeOSId ? `${state.activeOSId}_${idx}` : idx);
    const viewerState = pdfViewerState[key] || pdfViewerState[idx];
    if (!viewerState || viewerState.currentPage >= viewerState.totalPages) return;
    renderPdfViewerPage(key in pdfViewerState ? key : idx, viewerState.currentPage + 1, idx);
}

/**
 * Renderiza o canvas de preview combinada para um card de item individual.
 * Usa exatamente a mesma lógica do card avulso:
 * - Cor: renderiza PDF via pdf.js em offscreen canvas
 * - Numeração: desenha elements (TEXT, FIXED, QR, BARCODE) em offscreen canvas
 * - Arte: carrega imagem do upload
 * - Compõe tudo no canvas final
 */
/**
 * Confirmação destrutiva desenhada na própria página.
 *
 * Substitui o `confirm()` nativo nas ações que apagam trabalho. O motivo é
 * concreto: depois de algumas caixas seguidas, o Chrome oferece "Impedir que esta
 * página crie caixas de diálogo adicionais". Marcada — inclusive sem querer —, toda
 * chamada a `confirm()` passa a devolver `false` **sem mostrar nada**. Numa ação de
 * apagar, isso vira um botão que não faz nada e não explica: o operador clica,
 * não aparece pergunta nenhuma, e a arte continua lá.
 *
 * Esta caixa é DOM da aplicação, então não há como o navegador suprimi-la.
 *
 * Devolve uma Promise que resolve `true` (confirmou) ou `false` (cancelou, apertou
 * Esc ou clicou fora).
 */
function confirmarNaTela({ titulo, mensagem, textoConfirmar = 'Confirmar', textoCancelar = 'Cancelar' }) {
    return new Promise(resolve => {
        const anterior = document.getElementById('modal-confirmar-acao');
        if (anterior) anterior.remove();

        const overlay = document.createElement('div');
        overlay.id = 'modal-confirmar-acao';
        overlay.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.75); z-index:100000;'
            + ' display:flex; align-items:center; justify-content:center; backdrop-filter:blur(4px);';

        overlay.innerHTML = `
            <div style="background:var(--bg-card,#1e293b); border:1px solid var(--border,#334155); border-radius:12px;
                        max-width:440px; width:calc(100% - 40px); padding:22px; box-shadow:0 25px 50px -12px rgba(0,0,0,0.7);">
                <div style="font-size:1.05rem; font-weight:800; color:var(--text,#e2e8f0); margin-bottom:10px;">
                    ${escapeHtml(titulo || 'Confirmar ação')}
                </div>
                <div style="font-size:0.9rem; color:var(--text-dim,#94a3b8); line-height:1.5; white-space:pre-line;">
                    ${escapeHtml(mensagem || '')}
                </div>
                <div style="display:flex; gap:10px; justify-content:flex-end; margin-top:20px;">
                    <button type="button" id="btn-confirmar-nao" class="btn btn-sm btn-secondary">${escapeHtml(textoCancelar)}</button>
                    <button type="button" id="btn-confirmar-sim" class="btn btn-sm btn-danger"
                            style="background:#ef4444; border-color:#ef4444; color:#fff; font-weight:700;">${escapeHtml(textoConfirmar)}</button>
                </div>
            </div>`;

        const fechar = (resposta) => {
            document.removeEventListener('keydown', onKey, true);
            overlay.remove();
            resolve(resposta);
        };
        // Só o Esc é tratado aqui. O Enter fica com o comportamento nativo: aciona o
        // botão em foco, que é o Cancelar. Interceptar o Enter para confirmar
        // transformaria um toque distraído em arte apagada.
        const onKey = (e) => {
            if (e.key === 'Escape') { e.stopPropagation(); fechar(false); }
        };

        document.body.appendChild(overlay);
        overlay.querySelector('#btn-confirmar-nao').onclick = () => fechar(false);
        overlay.querySelector('#btn-confirmar-sim').onclick = () => fechar(true);
        // Clicar fora cancela — nunca confirma, porque a ação é destrutiva
        overlay.onclick = (e) => { if (e.target === overlay) fechar(false); };
        document.addEventListener('keydown', onKey, true);
        // Foco no Cancelar: um Enter distraído não pode apagar trabalho
        overlay.querySelector('#btn-confirmar-nao').focus();
    });
}
window.confirmarNaTela = confirmarNaTela;

/**
 * Apaga a visualização do modo PDF de um item: o desenho, o canvas e o navegador
 * de páginas.
 *
 * Zerar `width`/`height` não é enfeite — é o que solta o bitmap da memória e
 * garante que nenhum pixel da arte anterior sobreviva se o canvas voltar a ser
 * exibido antes de a próxima página terminar de renderizar.
 */
function limparVisualizadorPdf(idx) {
    const pdfCanvas = document.getElementById(`amostra-pdf-canvas-${idx}`);
    if (pdfCanvas) {
        try {
            const pctx = pdfCanvas.getContext('2d');
            if (pctx) pctx.clearRect(0, 0, pdfCanvas.width, pdfCanvas.height);
        } catch (_) { /* canvas sem contexto: só esconder já resolve */ }
        pdfCanvas.width = 1;
        pdfCanvas.height = 1;
        pdfCanvas.style.display = 'none';
    }
    const nav = document.getElementById(`amostra-pdf-nav-${idx}`);
    if (nav) nav.style.display = 'none';
    const pageInfo = document.getElementById(`amostra-pdf-page-info-${idx}`);
    if (pageInfo) pageInfo.textContent = 'Página 1 / 1';
}
window.limparVisualizadorPdf = limparVisualizadorPdf;

/**
 * Pré-carrega os elementos PDF da numeração e repinta quem estava esperando.
 *
 * O objeto do elemento é o MESMO para todos os modelos que compartilham a
 * numeração — ele vem de `state.numeracoes`, não é uma cópia por modelo. Antes,
 * o primeiro modelo marcava `_pdfLoading` e agendava o próprio redesenho; os
 * modelos seguintes caíam fora pela mesma flag e nunca eram repintados,
 * ficando com o retângulo escrito "PDF" no lugar do elemento gráfico. Num
 * pedido em que vários modelos dividem a numeração, só o primeiro saía
 * completo. Agora todo modelo que depende do elemento assina a espera, e o fim
 * do carregamento repinta todos. O gêmeo desta função vive no `cliente.js`.
 */
function preloadAmostraItemPdfElements(numeracao, idx, osId, item) {
    if (!numeracao || !numeracao.elements) return;

    // As FOTOS primeiro, e por fora do laço de PDF abaixo: o card não tem
    // repinte próprio, então a foto que não for pedida aqui nunca aparece. O
    // gêmeo desta função vive no `cliente.js`.
    if (typeof window.fotosPendentes === 'function') {
        const linha = (typeof linhaDaAmostra === 'function') ? linhaDaAmostra(item, numeracao, osId) : null;
        const linhas = [linha].filter(Boolean);
        // Perguntar o que falta ANTES evita o laço: no repinte não falta nada e
        // ele não pede outro repinte.
        if (window.fotosPendentes(numeracao.elements, linhas).length) {
            window.precarregarFotosDosElementos(numeracao.elements, linhas)
                .then(() => { if (typeof renderItemAmostraCombinada === 'function') renderItemAmostraCombinada(idx, osId); })
                .catch(() => { });
        }
    }

    const assinatura = idx + '|' + osId;

    numeracao.elements.forEach(el => {
        if (el.type !== 'PDF' || !el.pdf_content || el._pdfCanvas || el._preloadFalhou) return;

        (el._assinantes || (el._assinantes = new Set())).add(assinatura);

        // Já há carregamento em voo: a assinatura acima basta — quem disparou
        // repinta este modelo junto com o dele.
        if (el._pdfLoading) return;
        el._pdfLoading = true;

        (async () => {
            try {
                let bytes;
                if (el.pdf_content.startsWith('http') || el.pdf_content.startsWith('/')) {
                    bytes = await fetchPdfBytes(el.pdf_content);
                } else {
                    const base64Data = el.pdf_content.includes('base64,') ? el.pdf_content.split('base64,')[1] : el.pdf_content;
                    const binStr = atob(base64Data);
                    bytes = new Uint8Array(binStr.length);
                    for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
                }

                if (!bytes) throw new Error('Falha ao obter os bytes do PDF do elemento');

                const pdf = await pdfjsLib.getDocument({ data: bytes }).promise;
                const page = await pdf.getPage(1);
                const vp = page.getViewport({ scale: 2.0 });

                const offCanvas = document.createElement('canvas');
                offCanvas.width = Math.round(vp.width);
                offCanvas.height = Math.round(vp.height);
                const octx = offCanvas.getContext('2d', { colorSpace: 'srgb' });
                await page.render({ canvasContext: octx, viewport: vp, background: 'rgba(0,0,0,0)' }).promise;

                el._pdfCanvas = offCanvas;
            } catch (err) {
                console.error('[Amostra Item] Erro pré-carregando PDF do elemento:', err);
                // Marca de falha permanente. Sem ela, o redesenho abaixo chama
                // este preload de novo, que tenta de novo, que falha de novo —
                // laço infinito. O elemento fica sem desenho nesta sessão.
                el._preloadFalhou = true;
            } finally {
                delete el._pdfLoading;
                repintarAssinantesDoPreload([el]);
            }
        })();
    });
}

/** Repinta TODO modelo que estava esperando estes elementos, não só o primeiro. */
function repintarAssinantesDoPreload(elementos) {
    const alvos = new Set();
    (elementos || []).forEach(el => {
        if (el._assinantes) el._assinantes.forEach(a => alvos.add(a));
        delete el._assinantes;
    });
    alvos.forEach(a => {
        // Corta na PRIMEIRA barra: o índice é sempre numérico, então o resto da
        // string é o osId inteiro mesmo que um dia ele contenha uma barra.
        const corte = a.indexOf('|');
        const i = parseInt(a.slice(0, corte), 10);
        const os = a.slice(corte + 1);
        if (!isNaN(i)) renderItemAmostraCombinada(i, os);
    });
}

async function drawAmostraFace(item, face, canvas, empty, fmt, cor, num, idx, osId, S) {
    // Esperar as fontes da numeração antes de desenhar. Aqui dá para aguardar
    // de verdade (função async), então não há redesenho: sai certo de primeira.
    try {
        await garantirFontesCarregadas(fontesDosElementos(num && num.elements));
    } catch (_) { /* seguir mesmo assim */ }

    // Em modo PDF, o canvas tradicional (#amostra-item-canvas-X) não existe —
    // o viewer usa #amostra-pdf-canvas-X. Permitir passagem para o bloco modo_pdf.
    const itemForPdf = (state.osItens[osId] || [])[idx] || item;
    if (!canvas && !(itemForPdf && itemForPdf.modo_pdf)) return;

    // O visualizador paginado é da FRENTE. Num modelo com verso, o verso tem
    // tela própria (`amostra-item-canvas-verso-N`) e se compõe como sempre:
    // no FxVersoUnico ele é OUTRO arquivo, de uma página só, e mandar a face
    // `back` para o visualizador faria as duas faces disputarem o mesmo canvas
    // — a última a desenhar apagaria a outra (31/08/2026).
    const usaVisualizadorPaginado = !!(itemForPdf && itemForPdf.modo_pdf)
        && !(face === 'back' && itemForPdf.verso);

    // Se modo PDF ativo, não compor multicamada — usar PDF viewer dedicado
    if (usaVisualizadorPaginado) {
        if (canvas) canvas.style.display = 'none';
        
        // Pega a URL do PDF (com busca em 4 níveis)
        const pdfUrl = getPdfUrlForItem(itemForPdf, face, osId, idx);
            
        if (pdfUrl) {
            if (empty) empty.style.display = 'none';
            const key = `${osId}_${idx}`;
            
            const isImage = typeof pdfUrl === 'string' && (
                pdfUrl.startsWith('data:image/') || 
                (pdfUrl.includes('amostras_renderizadas') && !pdfUrl.endsWith('.pdf'))
            );
            
            if (isImage) {
                renderImageModeInPdfViewer(idx, pdfUrl, itemForPdf, osId);
            } else {
                const existing = pdfViewerState[key] || pdfViewerState[idx];
                if (!existing || existing.pdfUrl !== pdfUrl) {
                    initPdfViewer(key, pdfUrl, osId, idx);
                } else {
                    pdfViewerState[key] = existing;
                    pdfViewerState[key].osId = osId;
                    pdfViewerState[key].idx = idx;
                    renderPdfViewerPage(key, existing.currentPage || 1, idx);
                }
            }
        } else {
            // Sem arte/PDF: mostrar o estado vazio não basta, é preciso APAGAR o que
            // ficou desenhado. O `canvas` escondido lá em cima é o canvas tradicional
            // (#amostra-item-canvas-N); o do modo PDF é outro elemento, e ninguém o
            // escondia — depois de excluir a arte, a página do PDF continuava na tela,
            // ao lado do aviso de "faça upload", e parecia que a exclusão não pegou.
            limparVisualizadorPdf(idx);
            if (empty) empty.style.display = 'block';
        }
        return;
    }

    // Determinar se tem arte selecionada ou salva para esta face
    const inputId = face === 'back' ? `amostra-item-arte-verso-${idx}` : `amostra-item-arte-${idx}`;
    const containerId = state.amostrasContainerId || 'amostras-itens-container';
    const container = document.getElementById(containerId);
    const arteInput = container ? container.querySelector(`#${inputId}`) : null;

    const hasArte = arteInput && arteInput.files && arteInput.files.length > 0;
    let faceArteUrl = face === 'back' ? item.verso_arte_url : item.arte_url;
    if (!faceArteUrl && item) {
        const faceKey = face === 'back' ? 'verso' : 'frente';
        faceArteUrl = (item.id ? localStorage.getItem(`ideal_arte_url_${item.id}_${faceKey}`) : null) ||
                      localStorage.getItem(`ideal_arte_url_${osId}_${idx}_${faceKey}`);
        if (faceArteUrl) {
            if (face === 'back') item.verso_arte_url = faceArteUrl;
            else item.arte_url = faceArteUrl;
        }
    }
    const hasSavedArte = !!faceArteUrl;

    // Se nada selecionado (sem cor, sem numeração, sem arte para esta face), esconder canvas e mostrar vazio
    const corId = (cor ? cor.id : '') || item.amostra_cor_id || '';
    const numId = (num ? num.id : '') || item.amostra_num_id || '';
    if (!corId && !numId && !hasArte && !hasSavedArte) {
        canvas.style.display = 'none';
        if (empty) empty.style.display = 'block';
        return;
    }


    let targetW = fmt.width_mm;
    let targetH = fmt.height_mm;
    if (cor && cor.width_mm && cor.height_mm) {
        targetW = cor.width_mm;
        targetH = cor.height_mm;
    }

    const finalWidth = Math.round(targetW * S);
    const finalHeight = Math.round(targetH * S);
    if (finalWidth <= 0 || finalHeight <= 0) return;

    canvas.width = finalWidth;
    canvas.height = finalHeight;
    canvas.style.display = 'block';
    if (empty) empty.style.display = 'none';

    // Dois desenhos podem se cruzar no MESMO canvas: enquanto o primeiro ainda
    // espera a arte chegar do Storage, o carregamento de um elemento PDF/SVG da
    // numeracao dispara outro. Sem controle, os dois chegam ao fim e compoem o
    // grupo com 'multiply' sobre a mesma cor — a amostra sai escura, como se a
    // arte tivesse sido multiplicada duas vezes. Some ao navegar porque ai o
    // elemento ja esta em cache e o desenho fica sozinho.
    //
    // Quem chega depois carimba o canvas; quem estava em voo percebe o carimbo
    // novo e desiste antes de encostar no contexto.
    const _geracao = (canvas.__geracaoDesenho = (canvas.__geracaoDesenho || 0) + 1);
    const _desatualizado = () => canvas.__geracaoDesenho !== _geracao;

    const ctx = canvas.getContext('2d', { colorSpace: 'srgb' });
    ctx.clearRect(0, 0, finalWidth, finalHeight);
    ctx.globalCompositeOperation = 'source-over';

    // ====== CAMADA 1: COR (PDF via pdf.js) ======
    // O PDF da cor não vem no catálogo (ver garantirPdfDaCor). Sem esta
    // linha a amostra sairia sem a camada da cor, calada.
    if (cor) await garantirPdfDaCor(cor);
    let corRendered = false;
    if (cor && (cor.pdf_base64 || (face === 'back' && cor.pdf_verso_base64)) && typeof pdfjsLib !== 'undefined') {
        try {
            const hasVersoFile = (face === 'back' && cor.pdf_verso_base64);
            const rawPdfData = hasVersoFile ? cor.pdf_verso_base64 : cor.pdf_base64;
            const base64Data = rawPdfData.includes('base64,') ? rawPdfData.split('base64,')[1] : rawPdfData;
            const binStr = atob(base64Data);
            const bytes = new Uint8Array(binStr.length);
            for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);

            const loadingTask = pdfjsLib.getDocument({ data: bytes });
            const pdf = await loadingTask.promise;
            
            // Usar página 2 se for verso e o PDF tiver 2 ou mais páginas e não tivermos arquivo de verso separado
            const pageNum = (face === 'back' && !hasVersoFile && pdf.numPages >= 2) ? 2 : 1;
            const page = await pdf.getPage(pageNum);

            const viewport = page.getViewport({ scale: 1.0 });
            const pdfScale = (fmt.width_mm * 2.8346) / viewport.width;
            const scaledViewport = page.getViewport({ scale: pdfScale * (S / 2.8346) });

            const offCanvas = document.createElement('canvas');
            offCanvas.width = scaledViewport.width;
            offCanvas.height = scaledViewport.height;
            const offCtx = offCanvas.getContext('2d', { colorSpace: 'srgb' });
            await page.render({ canvasContext: offCtx, viewport: scaledViewport }).promise;

            const dx = (finalWidth - offCanvas.width) / 2;
            const dy = (finalHeight - offCanvas.height) / 2;
            ctx.drawImage(offCanvas, dx, dy, offCanvas.width, offCanvas.height);
            corRendered = true;
        } catch (e) {
            console.warn(`[Item ${idx} - Face ${face}] Erro ao renderizar cor PDF:`, e);
        }
    }
    if (_desatualizado()) return;

    if (!corRendered) {
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, finalWidth, finalHeight);
    }

    // ====== GRUPO ARTE + NUMERACAO ======
    // A numeracao NAO funde com a arte: ela sobrepoe a arte normalmente, e sao as duas
    // JUNTAS que multiplicam sobre a cor do papel. Por isso as duas camadas sao pintadas
    // antes num canvas transparente proprio (o grupo) e so no fim esse grupo e composto
    // sobre o ctx -- que a esta altura tem so a cor -- com 'multiply'. Compor cada camada
    // direto no ctx faria o multiply em cascata: a numeracao escureceria onde caisse em
    // cima da arte.
    const grupoCanvas = document.createElement('canvas');
    grupoCanvas.width = finalWidth;
    grupoCanvas.height = finalHeight;
    const grupoCtx = grupoCanvas.getContext('2d', { colorSpace: 'srgb' });
    let grupoTemConteudo = false;

    // ====== CAMADA 2: ARTE (imagem ou PDF do upload ou salva) ======
    if (hasArte || hasSavedArte) {
        try {
            let isPdf = false;
            let file = null;
            if (hasArte) {
                file = arteInput.files[0];
                isPdf = file.name.toLowerCase().endsWith('.pdf') || file.type === 'application/pdf';
            } else {
                isPdf = faceArteUrl && (faceArteUrl.toLowerCase().endsWith('.pdf') || faceArteUrl.includes('data:application/pdf'));
            }

            if (isPdf && typeof pdfjsLib !== 'undefined') {
                pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
                
                let bytes;
                if (hasArte) {
                    const arrayBuffer = await file.arrayBuffer();
                    bytes = new Uint8Array(arrayBuffer);
                } else {
                    if (faceArteUrl.startsWith('http') || faceArteUrl.startsWith('/')) {
                        const bufferData = await fetchPdfBytes(faceArteUrl);
                        bytes = new Uint8Array(bufferData);
                    } else {
                        const base64Data = faceArteUrl.includes('base64,') ? faceArteUrl.split('base64,')[1] : faceArteUrl;
                        const binStr = atob(base64Data);
                        bytes = new Uint8Array(binStr.length);
                        for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
                    }
                }

                const loadingTask = pdfjsLib.getDocument({ data: bytes });
                const pdf = await loadingTask.promise;
                const page = await pdf.getPage(1);

                // A arte em PDF entra no TAMANHO REAL dela, centrada na peca, e o
                // que passar da peca fica de fora. E o que a impressora faz:
                // engine.py abre a arte em PDF e a coloca na celula com o rect
                // do tamanho da PROPRIA PAGINA (`base_w`/`base_h`), nunca
                // reduzida para caber. Encolher aqui fazia a tela mostrar a arte
                // menor do que ela sai no papel, com uma faixa branca em volta
                // que o papel nao tem -- foi o que o usuario viu em 18/08/2026
                // comparando a janela com a impressao.
                //
                // A pagina do PDF vem em PONTOS (2,8346 pt = 1 mm) e o canvas
                // tem S pixels por milimetro: a escala do tamanho real e
                // S / 2,8346. Arte em IMAGEM continua encaixando proporcional-
                // mente (ramo abaixo), porque e isso que o motor faz com ela em
                // `_load_base_as_pdf`.
                const escalaTamanhoReal = S / 2.8346;
                const scaledViewport = page.getViewport({ scale: escalaTamanhoReal });

                // A ESCALA DA ARTE DO MODELO (31/08/2026). Multiplica o tamanho
                // real, cada eixo por conta própria; 100/100 é exatamente o
                // desenho de antes. O `transform` do pdf.js desenha já na medida
                // final — nada é ampliado depois, então a arte continua nítida.
                const escA = escalaDaArteDoModelo(item);
                const fx = escA.h / 100, fy = escA.v / 100;

                const offCanvas = document.createElement('canvas');
                offCanvas.width = Math.round(scaledViewport.width * fx);
                offCanvas.height = Math.round(scaledViewport.height * fy);
                const offCtx = offCanvas.getContext('2d', { colorSpace: 'srgb' });
                await page.render({
                    canvasContext: offCtx,
                    viewport: scaledViewport,
                    ...(fx === 1 && fy === 1 ? {} : { transform: [fx, 0, 0, fy, 0, 0] }),
                }).promise;

                // Centralizada na peça, como o motor faz. O que passar da peça é
                // aparado pelo canvas do grupo — no papel, pela célula.
                const dx = (finalWidth - offCanvas.width) / 2;
                const dy = (finalHeight - offCanvas.height) / 2;

                grupoCtx.drawImage(offCanvas, dx, dy, offCanvas.width, offCanvas.height);
                grupoTemConteudo = true;
            } else {
                let url;
                if (hasArte) {
                    url = URL.createObjectURL(file);
                } else {
                    url = faceArteUrl;
                }
                const arteImg = new Image();
                arteImg.crossOrigin = "Anonymous";
                await new Promise((resolve, reject) => {
                    arteImg.onload = resolve;
                    arteImg.onerror = reject;
                    arteImg.src = url;
                });
                if (arteImg.width > 0 && arteImg.height > 0) {
                    const tempArte = document.createElement('canvas');
                    tempArte.width = finalWidth;
                    tempArte.height = finalHeight;
                    const tempCtx = tempArte.getContext('2d', { colorSpace: 'srgb' });

                    const artRatio = arteImg.width / arteImg.height;
                    const canvasRatio = finalWidth / finalHeight;
                    let dw, dh, ddx, ddy;
                    if (artRatio > canvasRatio) {
                        dw = finalWidth;
                        dh = finalWidth / artRatio;
                        ddx = 0;
                        ddy = (finalHeight - dh) / 2;
                    } else {
                        dh = finalHeight;
                        dw = finalHeight * artRatio;
                        ddx = (finalWidth - dw) / 2;
                        ddy = 0;
                    }
                    // A ESCALA DA ARTE (31/08/2026), sobre o encaixe acima. A
                    // arte em imagem tem esse encaixe como tamanho de partida
                    // porque é o que o motor faz com ela em `_load_base_as_pdf`;
                    // a escala multiplica dali, e recentraliza. A 100/100 as
                    // contas dão o mesmo de antes.
                    const escI = escalaDaArteDoModelo(item);
                    if (escI.h !== 100 || escI.v !== 100) {
                        dw *= escI.h / 100;
                        dh *= escI.v / 100;
                        ddx = (finalWidth - dw) / 2;
                        ddy = (finalHeight - dh) / 2;
                    }
                    tempCtx.drawImage(arteImg, ddx, ddy, dw, dh);

                    grupoCtx.drawImage(tempArte, 0, 0);
                    grupoTemConteudo = true;
                }
                if (hasArte) {
                    URL.revokeObjectURL(url);
                }
            }
        } catch (e) {
            console.warn(`[Item ${idx} - Face ${face}] Erro ao renderizar arte:`, e);
        }
    }

    // ====== CAMADA 3: NUMERAÇÃO ======
    if (num && num.elements && num.elements.length > 0) {
        const numCanvas = document.createElement('canvas');
        numCanvas.width = Math.round(fmt.width_mm * S);
        numCanvas.height = Math.round(fmt.height_mm * S);
        const numCtx = numCanvas.getContext('2d', { colorSpace: 'srgb' });

        // Fundo transparente. NAO desenhar contorno do formato aqui: este canvas
        // e composto POR CIMA da arte, entao um strokeRect na borda cobria a
        // fileira de pixels da beirada do desenho -- a arte aparecia cortada em
        // cima e embaixo na tela, e so na tela, porque o motor redesenha a
        // numeracao do zero e nunca pinta esta moldura. Quem mostra ate onde vai
        // o ingresso e a propria borda do canvas, com a sombra do CSS.

        // A linha do banco e a PAGINA que esta face vai mostrar. Resolvidas
        // uma vez, antes do laco: todos os elementos variaveis leem a mesma
        // pagina, senao a tela mostraria a linha 3 do banco no ingresso 1 --
        // uma peca que o motor nunca vai imprimir.
        const _linhaCsv = (typeof linhaDaAmostra === 'function') ? linhaDaAmostra(item, num, osId) : null;
        const _pagAmostra = (typeof paginaDaAmostra === 'function' && typeof linhasDaAmostra === 'function')
            ? paginaDaAmostra(item, linhasDaAmostra(item, num).length, osId)
            : 0;
        // O numero inicial do modelo (NI), base de tudo o que anda com a pagina.
        const _niAmostra = parseInt(
            item?.numeracao_inicio || item?.num_inicial ||
            item?.NUMERACAO_INICIO || 1
        ) || 1;
        const _ticketQtdAmostra = parseInt(num?.ticket_qtd || item?.ticket_qtd || 1) || 1;
        // Desenhar cada elemento da numeração
        num.elements.forEach(el => {
            const elFace = el.face || 'both';

            // Filtrar elementos por face
            if (face === 'back') {
                if (el.type !== 'PICOTE' && elFace !== 'back' && elFace !== 'both') return;
            } else {
                if (elFace !== 'front' && elFace !== 'both' && el.type !== 'PICOTE') return;
            }

            let x = el.x_mm * S;
            const y = el.y_mm * S;
            const color = el.color || '#000000';
            const rot = (el.rotation || 0) * Math.PI / 180;

            // PICOTE: espelhamento no verso
            if (face === 'back' && el.type === 'PICOTE') {
                x = (fmt.width_mm - el.x_mm) * S;
            }

            numCtx.save();
            numCtx.translate(x, y);
            numCtx.rotate(rot);


            if (el.type === 'TEXT' || el.type === 'FIXED' || el.type.startsWith('TEATRO_') || el.type.startsWith('CAMAROTE_')) {
                const fs = (el.font_size || 12) * S / 2.8346;
                numCtx.font = buildCanvasFont(fs, el.font_name);
                numCtx.fillStyle = color;

                let label = '';
                if (el.type === 'FIXED') {
                    label = el.fixed_value || 'TEXTO';
                } else if (el.type === 'TEATRO_FILA') {
                    const _fVal = _linhaCsv ? (_linhaCsv.Fila || 'A') : 'A';
                    label = `${el.prefix || ''}${_fVal}`;
                } else if (el.type === 'TEATRO_LUGAR') {
                    const _lVal = _linhaCsv ? (_linhaCsv.Numero || '22') : '22';
                    label = `${el.prefix || ''}${_lVal}`;
                } else if (el.type === 'TEATRO_COMBO') {
                    const _fVal = _linhaCsv ? (_linhaCsv.Fila || 'A') : 'A';
                    const _lVal = _linhaCsv ? (_linhaCsv.Numero || '22') : '22';
                    const fila = `${el.prefix_fila || ''}${_fVal}`;
                    const lugar = `${el.prefix_lugar || ''}${_lVal}`;
                    label = el.layout === '2lines' ? `${fila}\n${lugar}` : `${fila} - ${lugar}`;
                } else if (el.type.startsWith('CAMAROTE_')) {
                    // C_INI = Início do local (mesa/camarote) — NÃO confundir com NI (num_inicial)
                    // A pagina anda pessoa a pessoa e vira o local quando a
                    // lotacao fecha, como o _resolve_camarote_val do engine.py.
                    const _cam = window.NumeroDaPagina.camarote({
                        pagina: _pagAmostra,
                        lotacao: item?.l_cam || item?.L_CAM ||
                                 item?.lotacao_cam || item?.LOTACAO_CAM ||
                                 item?.lotacao || 5,
                        cIni: item?.c_ini || item?.C_INI || 1
                    });
                    if (el.type === 'CAMAROTE_LOCAL') {
                        label = `${el.prefix || ''}${_cam.local}`;
                    } else if (el.type === 'CAMAROTE_PESSOA') {
                        label = `${el.prefix || ''}${_cam.pessoa}`;
                    } else {
                        label = `${el.prefix || ''}${_cam.pessoa}/${_cam.lotacao}`;
                    }

                } else if (el.source === 'database') {
                    const colName = el.csv_column || '';
                    const csvRow = _linhaCsv;
                    if (csvRow && typeof csvRow[colName] !== 'undefined' && csvRow[colName] !== '') {
                        label = `${el.prefix || ''}${csvRow[colName]}${el.suffix || ''}`;
                    } else {
                        label = textoDeExemploDoElemento(el);
                    }
                } else {
                    const padVal = typeof el.pad !== 'undefined' ? el.pad : 6;
                    // Folhear o banco folheia a PECA: a linha N sai no ingresso
                    // `NI + N`, do mesmo jeito que o motor imprime.
                    const current_val = window.NumeroDaPagina.sequencial({
                        start: _niAmostra, pagina: _pagAmostra,
                        tipo: num && num.tipo, ticketPos: el.ticket_pos,
                        ticketQtd: _ticketQtdAmostra
                    });
                    label = `${el.prefix || ''}${String(current_val).padStart(padVal, '0')}${el.suffix || ''}`;
                }
                window.desenharTextoAjustado(
                    numCtx, el, label, fs, S,
                    (f) => buildCanvasFont(f, el.font_name)
                );
            } else if (el.type === 'QR_IDEAL') {
                // O card do pedido conhece o pedido e o modelo. O número do
                // ingresso segue a mesma conta do elemento de numeração acima —
                // se divergissem, a tela mostraria um código e o papel sairia
                // outro. Por isso o QR também anda com a página.
                const _qiVal = window.NumeroDaPagina.sequencial({
                    start: _niAmostra, pagina: _pagAmostra,
                    tipo: num && num.tipo, ticketPos: el.ticket_pos,
                    ticketQtd: _ticketQtdAmostra
                });
                window.desenharQRIdeal(
                    numCtx, el, (el.size_mm || 15) * S, el.color || '#000000',
                    item?.id_int, item?.id, _qiVal
                );

            } else if (el.type === 'QR') {
                const sz = (el.size_mm || 15) * S;
                let qrText = '';
                if (el.fixed) {
                    qrText = el.fixed_value || '';
                } else if (el.source === 'database') {
                    const colName = el.csv_column || '';
                    const csvRow = _linhaCsv;
                    if (csvRow && typeof csvRow[colName] !== 'undefined' && csvRow[colName] !== '') {
                        qrText = `${el.prefix || ''}${csvRow[colName]}${el.suffix || ''}`;
                    } else {
                        qrText = `${el.prefix || ''}[${colName || 'coluna'}]${el.suffix || ''}`;
                    }
                } else {
                    const padVal = typeof el.pad !== 'undefined' ? parseInt(el.pad) : 4;
                    // Mesma conta do texto sequencial: o QR da pagina N carrega
                    // o numero do ingresso N.
                    const val = window.NumeroDaPagina.sequencial({
                        start: _niAmostra, pagina: _pagAmostra
                    });
                    const raw = padVal > 0 ? String(val).padStart(padVal, '0') : String(val);
                    qrText = `${el.prefix || ''}${raw}${el.suffix || ''}`;
                }
                renderQRCodeOnCtx(numCtx, qrText, 0, 0, sz, color);
            } else if (el.type === 'BARCODE') {
                const bw = (el.barcode_width_mm || el.width_mm || 30) * S;
                const bh = (el.barcode_height_mm || el.height_mm || 8) * S;
                let bcText = '';
                if (el.fixed) {
                    bcText = el.fixed_value || '';
                } else if (el.source === 'database') {
                    const colName = el.csv_column || '';
                    const csvRow = _linhaCsv;
                    if (csvRow && typeof csvRow[colName] !== 'undefined' && csvRow[colName] !== '') {
                        bcText = `${el.prefix || ''}${csvRow[colName]}${el.suffix || ''}`;
                    } else {
                        bcText = `${el.prefix || ''}${colName || 'COLUNA'}${el.suffix || ''}`;
                    }
                } else {
                    const padVal = typeof el.pad !== 'undefined' ? parseInt(el.pad) : 4;
                    const val = window.NumeroDaPagina.sequencial({
                        start: _niAmostra, pagina: _pagAmostra
                    });
                    const raw = padVal > 0 ? String(val).padStart(padVal, '0') : String(val);
                    bcText = `${el.prefix || ''}${raw}${el.suffix || ''}`;
                }
                window.renderBarcodeOnCtx(numCtx, bcText, 0, 0, bw, bh, color, el.barcode_format);
            } else if (el.type === 'PICOTE') {
                numCtx.strokeStyle = color;
                numCtx.lineWidth = 2.0;
                numCtx.setLineDash([6, 3]);
                numCtx.beginPath();
                numCtx.moveTo(0, -y);
                numCtx.lineTo(0, numCanvas.height - y);
                numCtx.stroke();
                numCtx.setLineDash([]);
            } else if (el.type === 'FOTO') {
                desenharElementoFoto(numCtx, el, S, false, _linhaCsv, null);
            } else if (el.type === 'SVG' || el.type === 'PDF') {
                const w = (el.width_mm || 20) * S;
                const h = (el.height_mm || 20) * S;
                const hw = w / 2, hh_el = h / 2;

                numCtx.save();
                numCtx.beginPath();
                numCtx.rect(-hw, -hh_el, w, h);
                numCtx.clip();

                if (el.type === 'PDF') {
                    const imgObj = el._pdfCanvas || null;
                    if (imgObj) {
                        drawArteDoElemento(numCtx, imgObj, -hw, -hh_el, w, h, el);
                    } else {
                        numCtx.strokeStyle = color;
                        numCtx.lineWidth = 1;
                        numCtx.strokeRect(-hw, -hh_el, w, h);
                        numCtx.font = `${Math.max(6, h * 0.15)}px Inter, sans-serif`;
                        numCtx.fillStyle = color;
                        numCtx.textAlign = 'center';
                        numCtx.textBaseline = 'middle';
                        numCtx.fillText('PDF', 0, 0);
                        numCtx.textAlign = 'left';
                        numCtx.textBaseline = 'alphabetic';
                    }
                } else {
                    if (el.svg_content) {
                        if (!el._svgImage && !el._svgLoading) {
                            el._svgLoading = true;
                            const img = new Image();
                            img.onload = () => {
                                el._svgImage = img;
                                delete el._svgLoading;
                                renderItemAmostraCombinada(idx, osId);
                            };
                            img.onerror = () => {
                                console.error('[Amostra Item] Erro ao carregar SVG');
                                delete el._svgLoading;
                            };
                            if (el.svg_content.startsWith('http') || el.svg_content.startsWith('data:')) {
                                img.src = el.svg_content;
                            } else {
                                img.src = 'data:image/svg+xml;utf8,' + encodeURIComponent(el.svg_content);
                            }
                        }
                        if (el._svgImage) {
                            drawArteDoElemento(numCtx, el._svgImage, -hw, -hh_el, w, h, el);
                        } else {
                            numCtx.strokeStyle = color;
                            numCtx.lineWidth = 1;
                            numCtx.strokeRect(-hw, -hh_el, w, h);
                            numCtx.font = `${Math.max(6, h * 0.15)}px Inter, sans-serif`;
                            numCtx.fillStyle = color;
                            numCtx.textAlign = 'center';
                            numCtx.textBaseline = 'middle';
                            numCtx.fillText('SVG', 0, 0);
                            numCtx.textAlign = 'left';
                            numCtx.textBaseline = 'alphabetic';
                        }
                    } else {
                        numCtx.strokeStyle = color;
                        numCtx.lineWidth = 1;
                        numCtx.strokeRect(-hw, -hh_el, w, h);
                        numCtx.font = `${Math.max(6, h * 0.15)}px Inter, sans-serif`;
                        numCtx.fillStyle = color;
                        numCtx.textAlign = 'center';
                        numCtx.textBaseline = 'middle';
                        numCtx.fillText('SVG', 0, 0);
                        numCtx.textAlign = 'left';
                        numCtx.textBaseline = 'alphabetic';
                    }
                }
                numCtx.restore();
            }
            numCtx.restore();
        });

        // A numeracao entra NO GRUPO, por cima da arte e sem multiply: ela cobre a arte.
        const ndx = (finalWidth - numCanvas.width) / 2;
        const ndy = (finalHeight - numCanvas.height) / 2;
        grupoCtx.drawImage(numCanvas, ndx, ndy, numCanvas.width, numCanvas.height);
        grupoTemConteudo = true;
    }

    if (_desatualizado()) return;

    // Agora sim: o grupo (arte + numeracao) multiplica, de uma vez so, sobre a cor.
    if (grupoTemConteudo) {
        ctx.globalCompositeOperation = 'multiply';
        ctx.drawImage(grupoCanvas, 0, 0);
        ctx.globalCompositeOperation = 'source-over';
    }

    // Sem borda decorativa: ela era desenhada DENTRO do bitmap, na ultima
    // fileira de pixels, entao cobria a beirada da arte e viajava junto para
    // todo lugar que copia este canvas -- a janela ampliada, o link do cliente
    // e o JPEG de aprovacao. Enfeite de tela nao entra na imagem (ver
    // docs/editor_de_arte.md).
}

/**
 * Redesenha os cards de amostra que estao na tela.
 *
 * O conteudo do QR Ideal nao se calcula no navegador: vem da estacao, por uma
 * consulta que responde DEPOIS de o canvas ja ter sido pintado. Quem avisa que
 * a resposta chegou e o `repintar()` do qr-canvas.js, e ele so conhecia o
 * editor e a previa do pedido — o card do modelo ficava com o QR de exemplo.
 */
window.repintarAmostrasCombinadas = function () {
    const abertos = state._amostrasNaTela;
    if (!abertos) return;
    const containerId = state.amostrasContainerId || 'amostras-itens-container';
    const container = document.getElementById(containerId);
    if (!container) return;
    Object.keys(abertos).forEach(chave => {
        const alvo = abertos[chave];
        // Card que saiu da tela sai da lista: sem isto ela cresceria a cada
        // pedido aberto e o repinte percorreria fantasmas.
        if (!container.querySelector(`#amostra-item-canvas-${alvo.idx}`) &&
            !container.querySelector(`#amostra-pdf-canvas-${alvo.idx}`)) {
            delete abertos[chave];
            return;
        }
        try { renderItemAmostraCombinada(alvo.idx, alvo.osId); } catch (_) { }
    });
};

async function renderItemAmostraCombinada(idx, osId) {
    const containerId = state.amostrasContainerId || 'amostras-itens-container';
    const container = document.getElementById(containerId);
    if (!container) return;

    const item = state.osItens[osId] ? state.osItens[osId][idx] : null;
    if (!item) return;

    // Quem esta desenhado agora, para o repinte do QR Ideal saber a quem voltar.
    if (!state._amostrasNaTela) state._amostrasNaTela = {};
    state._amostrasNaTela[`${osId}:${idx}`] = { idx, osId };

    const corSelect = container.querySelector(`#amostra-item-cor-${idx}`);
    const numSelect = container.querySelector(`#amostra-item-num-${idx}`);
    const corId = corSelect ? corSelect.value : item.amostra_cor_id;
    const numId = numSelect ? numSelect.value : item.amostra_num_id;

    // Atualizar labels e remover btns para Frente e Verso
    const hasFrontArte = container.querySelector(`#amostra-item-arte-${idx}`)?.files?.length > 0;
    const hasSavedFrontArte = !!item.arte_url;
    const frontNameSpan = container.querySelector(`#amostra-item-arte-name-${idx}`);
    const removeFrontBtn = container.querySelector(`#btn-remove-amostra-arte-${idx}`);
    const copyFrontBtn = container.querySelector(`#btn-copy-amostra-arte-${idx}`);

    if (frontNameSpan) {
        if (hasFrontArte) frontNameSpan.textContent = container.querySelector(`#amostra-item-arte-${idx}`).files[0].name;
        else if (hasSavedFrontArte) frontNameSpan.textContent = '(Arte Salva na Nuvem)';
        else frontNameSpan.textContent = '';
    }
    if (removeFrontBtn) removeFrontBtn.style.display = (hasFrontArte || hasSavedFrontArte) ? '' : 'none';
    if (copyFrontBtn) {
        copyFrontBtn.style.display = (hasFrontArte || hasSavedFrontArte) ? '' : 'none';
        if (hasSavedFrontArte) {
            copyFrontBtn.setAttribute('onclick', `copiarArte('${item.arte_url}', 'frente')`);
        }
    }

    if (item.verso) {
        const hasVersoArte = container.querySelector(`#amostra-item-arte-verso-${idx}`)?.files?.length > 0;
        const hasSavedVersoArte = !!item.verso_arte_url;
        const versoNameSpan = container.querySelector(`#amostra-item-arte-verso-name-${idx}`);
        const removeVersoBtn = container.querySelector(`#btn-remove-amostra-arte-verso-${idx}`);
        const copyVersoBtn = container.querySelector(`#btn-copy-amostra-arte-verso-${idx}`);

        if (versoNameSpan) {
            if (hasVersoArte) versoNameSpan.textContent = container.querySelector(`#amostra-item-arte-verso-${idx}`).files[0].name;
            else if (hasSavedVersoArte) versoNameSpan.textContent = '(Arte Salva na Nuvem)';
            else versoNameSpan.textContent = '';
        }
        if (removeVersoBtn) removeVersoBtn.style.display = (hasVersoArte || hasSavedVersoArte) ? '' : 'none';
        if (copyVersoBtn) {
            copyVersoBtn.style.display = (hasVersoArte || hasSavedVersoArte) ? '' : 'none';
            if (hasSavedVersoArte) {
                copyVersoBtn.setAttribute('onclick', `copiarArte('${item.verso_arte_url}', 'verso')`);
            }
        }
    }

    // Obter cor, formato e numeração
    const cor = corId ? state.cores.find(c => c.id === corId) : null;
    // O card mostra a peca RESOLVIDA pelo banco do pedido: sem isto, o modelo
    // ligado a um banco desenhava a peca crua — sem linhas, sem paginacao, com
    // numero sequencial no lugar do dado (28/08/2026). O find continua pelo
    // seletor (numId), porque o operador pode estar trocando a numeracao.
    let num = numId ? state.numeracoes.find(n => String(n.id) === String(numId)) : null;
    num = resolverNumeracaoParaModelo(num, item);

    const numIsDuplex = isNumeracaoDuplex(num);
    const oldVersoInCanvas = !!item.verso;

    if (numIsDuplex) {
        if (!item.verso) {
            item.verso = true;
            if (!item.verso_tipo || item.verso_tipo === 'Frente' || item.verso_tipo === 'SÓ FRENTE' || item.verso_tipo === 'SO FRENTE') {
                item.verso_tipo = 'FxVerso';
            }
        }
    } else {
        if (item.verso_tipo === 'FxVerso' || item.verso_tipo === 'VERSO COMUM') {
            item.verso_tipo = 'Frente';
            item.verso = false;
        } else {
            item.verso = !!(item.verso_tipo && item.verso_tipo !== 'Frente');
        }
    }

    if (num) {
        preloadAmostraItemPdfElements(num, idx, osId, item);
    }

    // A MESMA CADEIA DO `formatoDoModelo` (02/09/2026): cor, numeração e, por
    // último, o formato do próprio modelo. Antes o card parava nos dois
    // primeiros e caía no PRIMEIRO FORMATO DO CATÁLOGO — um formato qualquer, de
    // outro produto, com outra medida —, o que dava à peça um tamanho que a
    // impressora nunca faria. Ver `formatoDoModelo`, onde a ordem é explicada.
    const fmt = formatoDoModelo(item, cor, num);
    if (!fmt || !fmt.width_mm || !fmt.height_mm) {
        // Nenhum dos três caminhos deu formato. Antes o card caía no primeiro do
        // catálogo, e desenhava a peça com a medida de OUTRO produto — o mesmo
        // tipo de palpite que fazia a janela mostrar um tamanho que a impressora
        // nunca ia produzir. Melhor dizer que falta, com a saída na frase.
        avisarModeloSemFormato(container, idx, !!item.verso);
        return;
    }

    const S = 150 / 25.4;

    const canvasBackInDOM = container.querySelector(`#amostra-item-canvas-verso-${idx}`);
    if (oldVersoInCanvas !== item.verso || (item.verso && !canvasBackInDOM) || (!item.verso && canvasBackInDOM)) {
        const containerId = state.amostrasContainerId || 'amostras-itens-container';
        if (containerId === 'cliente-amostras-itens-container' && typeof renderClienteAmostrasItens === 'function') {
            renderClienteAmostrasItens(osId);
            return;
        } else if (typeof renderAmostrasOSItens === 'function') {
            renderAmostrasOSItens(osId);
            return;
        }
    }

    atualizarNavCsvDaAmostra(idx, item, num, container, osId);
    atualizarBotoesCsvDaAmostra(idx, item, num, container, osId);
    // Os campos de escala da arte seguem a mesma ideia dos controles do banco:
    // aparecem quando há do que falar. No modo PDF quem chama de novo é o
    // `renderPdfViewerPage`, depois de a página entrar na tela.
    atualizarCaixaDeEscalaDaArte(idx, item, container);

    if (item.verso) {
        const canvasFront = container.querySelector(`#amostra-item-canvas-${idx}`);
        const emptyFront = container.querySelector(`#amostra-item-empty-${idx}`);
        const canvasBack = container.querySelector(`#amostra-item-canvas-verso-${idx}`);
        const emptyBack = container.querySelector(`#amostra-item-empty-verso-${idx}`);

        await drawAmostraFace(item, 'front', canvasFront, emptyFront, fmt, cor, num, idx, osId, S);
        await drawAmostraFace(item, 'back', canvasBack, emptyBack, fmt, cor, num, idx, osId, S);
        
        // Snapshot para link do cliente (Frente e Verso) - somente se editado
        if (state.amostrasContainerId !== 'cliente-amostras-itens-container' && item._needsSnapshot) {
            delete item._needsSnapshot;
            if (item._snapshotTimer) clearTimeout(item._snapshotTimer);
            item._snapshotTimer = setTimeout(() => {
                snapshotAmostraAndUpload(idx, osId, item, canvasFront, 'frente');
                snapshotAmostraAndUpload(idx, osId, item, canvasBack, 'verso');
            }, 2000);
        }

        if (window.AmostraModal) window.AmostraModal.atualizar(idx, osId);
    } else {
        const canvas = container.querySelector(`#amostra-item-canvas-${idx}`);
        const empty = container.querySelector(`#amostra-item-empty-${idx}`);
        
        await drawAmostraFace(item, 'front', canvas, empty, fmt, cor, num, idx, osId, S);
        
        if (state.amostrasContainerId !== 'cliente-amostras-itens-container' && item._needsSnapshot) {
            delete item._needsSnapshot;
            if (item._snapshotTimer) clearTimeout(item._snapshotTimer);
            item._snapshotTimer = setTimeout(() => {
                snapshotAmostraAndUpload(idx, osId, item, canvas);
            }, 2000);
        }

        if (window.AmostraModal) window.AmostraModal.atualizar(idx, osId);
    }
}

async function snapshotAmostraAndUpload(idx, osId, item, canvas, face = 'frente') {
    if (!supabaseClient) return;
    if (!canvas || typeof canvas.toBlob !== 'function') {
        const pdfCanvas = document.getElementById(`amostra-pdf-canvas-${idx}`);
        if (pdfCanvas && typeof pdfCanvas.toBlob === 'function' && pdfCanvas.width > 0) {
            canvas = pdfCanvas;
        } else {
            return;
        }
    }
    try {
        canvas.toBlob(async (blob) => {
            if (!blob) return;
            const fileName = `amostra_${face}_${osId}_${item.id}_${Date.now()}.jpg`;
            const { error } = await supabaseClient
                .storage
                .from('amostras_renderizadas')
                .upload(fileName, blob, { contentType: 'image/jpeg', cacheControl: '3600', upsert: true });
            
            if (error) {
                console.warn('[Snapshot] Não pôde enviar render final (bucket existe?):', error);
                return;
            }

            const { data: urlData } = supabaseClient.storage.from('amostras_renderizadas').getPublicUrl(fileName);
            const publicUrl = urlData.publicUrl;
            
            const dbField = face === 'verso' ? 'verso_amostra_arte_base64' : 'amostra_arte_base64';
            await saveAmostraToDB(item.id, osId, { [dbField]: publicUrl });
            if (face === 'verso') {
                item.verso_amostra_arte_base64 = publicUrl;
            } else {
                item.amostra_arte_base64 = publicUrl;
            }
        }, 'image/jpeg', 0.85);
    } catch(e) {
        console.warn('[Snapshot] Erro ao gerar snapshot:', e);
    }
}

// Versão promisificada do snapshot — aguarda upload completar antes de resolver
function snapshotAmostraSync(idx, osId, item, canvas, face) {
    return new Promise((resolve) => {
        if (!canvas || canvas.width === 0 || canvas.height === 0) {
            const pdfCanvas = document.getElementById(`amostra-pdf-canvas-${idx}`);
            if (pdfCanvas && pdfCanvas.width > 0) {
                canvas = pdfCanvas;
            } else {
                resolve();
                return;
            }
        }
        if (!supabaseClient) {
            resolve();
            return;
        }
        try {
            canvas.toBlob(async (blob) => {
                if (!blob) { resolve(); return; }
                try {
                    const fileName = `amostra_${face}_${osId}_${item.id}_${Date.now()}.jpg`;
                    const { error } = await supabaseClient
                        .storage
                        .from('amostras_renderizadas')
                        .upload(fileName, blob, { contentType: 'image/jpeg', cacheControl: '3600', upsert: true });

                    if (!error) {
                        const { data: urlData } = supabaseClient.storage.from('amostras_renderizadas').getPublicUrl(fileName);
                        const publicUrl = urlData.publicUrl;
                        const dbField = face === 'verso' ? 'verso_amostra_arte_base64' : 'amostra_arte_base64';
                        await saveAmostraToDB(item.id, osId, { [dbField]: publicUrl });
                        if (face === 'verso') {
                            item.verso_amostra_arte_base64 = publicUrl;
                        } else {
                            item.amostra_arte_base64 = publicUrl;
                        }
                    } else {
                        console.warn('[Snapshot Sync] Upload error:', error);
                    }
                } catch(e) {
                    console.warn('[Snapshot Sync] Erro no upload:', e);
                }
                resolve();
            }, 'image/jpeg', 0.85);
        } catch(e) {
            console.warn('[Snapshot Sync] toBlob error:', e);
            resolve();
        }
    });
}

/**
 * Cor, numeração e formato em memória. A regeneração pode ser chamada de fora do
 * editor — do botão MARCAR PRONTO, do Criador de Arte —, e sem as tabelas o
 * desenho sairia sem a camada que falta, calado.
 */
async function garantirTabelasDaAmostra() {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return;
    if (!state.cores  || !state.cores.length)         try { const { data } = await supabaseClient.from('producao_cores').select(COLUNAS_DA_COR_NA_LISTA); if (data) state.cores = data; } catch(e) {}
    // Sem `csv_data`: quem desenha e o `regenerarAmostraDoModelo`, e e la que
    // o banco da numeracao do modelo desce, um por vez.
    if (!state.numeracoes || !state.numeracoes.length) try { const { data } = await supabaseClient.from('producao_numeracoes').select(COLUNAS_DA_NUMERACAO_NA_LISTA); if (data) state.numeracoes = data; } catch(e) {}
    if (!state.formatos || !state.formatos.length)     try { const { data } = await supabaseClient.from('producao_formatos').select('*');   if (data) state.formatos = data;   } catch(e) {}
}
window.garantirTabelasDaAmostra = garantirTabelasDaAmostra;

/** A escala da amostra: 150 DPI, a mesma da janela combinada do editor. */
const ESCALA_DA_AMOSTRA = 150 / 25.4;

/**
 * Regera e salva a arte de amostra de UM modelo — a imagem que o cliente vê no
 * link de aprovação.
 *
 * Saiu de dentro do `forceRegenerateSnapshots`, que continua chamando-a item a
 * item: é o mesmo trabalho, e duplicá-lo faria a arte que o cliente aprova
 * divergir da que o painel mostra no dia em que só um dos dois fosse corrigido.
 *
 * Compõe em canvas próprio, fora da tela, e por isso não depende de o card estar
 * aberto nem de o desenho visível ter terminado.
 *
 * Devolve `false` quando não havia o que gerar (modo PDF, modelo sem camada
 * nenhuma) e LANÇA quando a geração falhou. Quem chama decide o que fazer: a
 * regeneração em lote engole, porque não pode parar por causa de um item; o
 * MARCAR PRONTO avisa, porque ali uma amostra velha vira aprovação do cliente
 * sobre uma arte que ele não viu.
 */
async function regenerarAmostraDoModelo(osId, item, idx, S) {
    S = S || ESCALA_DA_AMOSTRA;
    if (item.modo_pdf) return false;

    resolveItemCorNumIds(item, idx);
    const corId      = item.amostra_cor_id || '';
    const numId      = item.amostra_num_id || '';
    const hasArteUrl  = !!(item.arte_url);
    const hasVersoUrl = !!(item.verso_arte_url);

    if (!corId && !numId && !hasArteUrl && !hasVersoUrl) {
        console.log(`[Snapshot] Item ${idx} sem camadas, nada a gerar.`);
        return false;
    }

    // O banco de dados da numeracao deste modelo, se ela tiver um.
    //
    // O catalogo em memoria vem sem `csv_data` desde 26/08/2026, e amostra
    // desenhada sem as linhas nao sai vazia: sai com o numero SEQUENCIAL no
    // lugar do nome da pessoa -- uma arte errada que o cliente aprovaria sem
    // desconfiar. Uma numeracao por vez, e so a que vai ser desenhada.
    if (numId) {
        await garantirCsvDaNumeracao(
            (state.numeracoes || []).find(n => String(n.id) === String(numId)));
    }

    console.log(`[Snapshot] Item ${idx} — cor:${corId||'—'} num:${numId||'—'} arte:${hasArteUrl} verso:${hasVersoUrl}`);

    // ════════════════════════════════════════════════════════════════
    // CAMINHO RÁPIDO: só tem arte_url — sem cor nem numeração
    // Copia a URL diretamente para amostra_arte_base64 no banco
    // (evita falha silenciosa de preload de elementos do DOM)
    // ════════════════════════════════════════════════════════════════
    if (!corId && !numId) {
        try {
            const updates = {};
            if (hasArteUrl)  { updates.amostra_arte_base64       = item.arte_url;       item.amostra_arte_base64       = item.arte_url; }
            if (hasVersoUrl) { updates.verso_amostra_arte_base64 = item.verso_arte_url; item.verso_amostra_arte_base64 = item.verso_arte_url; }
            if (Object.keys(updates).length > 0 && typeof saveAmostraToDB === 'function') {
                await saveAmostraToDB(item.id, osId, updates);
                console.log(`[Snapshot] Item ${idx} — URL da arte copiada diretamente (sem canvas).`);
            }
        } catch(e) { throw new Error('não consegui salvar a arte de amostra: ' + (e && e.message || e)); }
        return true;
    }

    // ════════════════════════════════════════════════════════════════
    // CAMINHO COMPOSTO: tem cor e/ou numeração — compor as camadas via canvas
    // ════════════════════════════════════════════════════════════════
    const cor = corId ? (state.cores || []).find(c => c.id === corId) : null;
    // Resolvida pelo banco do pedido — mesmo motivo do card (28/08/2026): a
    // amostra regenerada e a que o cliente ve, e tem de mostrar o dado real.
    let num = numId ? (state.numeracoes || []).find(n => String(n.id) === String(numId)) : null;
    num = resolverNumeracaoParaModelo(num, item);

    // Preload SVG/PDF e aguardar carregamento real dos elementos
    if (num && num.elements && num.elements.length > 0 && typeof preloadAmostraItemPdfElements === 'function') {
        preloadAmostraItemPdfElements(num, idx, osId, item);
        const svgEls = num.elements.filter(e => e && (e.type === 'SVG' || e.type === 'PDF'));
        if (svgEls.length > 0) {
            await new Promise(resolve => {
                let waited = 0;
                const check = setInterval(() => {
                    waited += 100;
                    const allReady = svgEls.every(e => e._svgImage || e._pdfCanvas || waited >= 3000);
                    if (allReady) { clearInterval(check); resolve(); }
                }, 100);
            });
        } else {
            await new Promise(r => setTimeout(r, 300));
        }
    }

    // Resolver formato: cor > num > primeiro do state > fallback
    let fmt = null;
    if (cor && cor.formato_id)  fmt = (state.formatos || []).find(f => String(f.id) === String(cor.formato_id));
    if (!fmt && num && num.formato_id) fmt = (state.formatos || []).find(f => String(f.id) === String(num.formato_id));
    if (!fmt && state.formatos && state.formatos.length > 0) fmt = state.formatos[0];
    if (!fmt) fmt = { width_mm: 180, height_mm: 50 };

    try {
        // ── FRENTE ──
        const canvasFront = document.createElement('canvas');
        await drawAmostraFace(item, 'front', canvasFront, null, fmt, cor, num, idx, osId, S);
        if (canvasFront.width > 0 && canvasFront.height > 0) {
            await snapshotAmostraSync(idx, osId, item, canvasFront, 'frente');
            console.log(`[Snapshot] Item ${idx} FRENTE composto e salvo.`);
        }
        // ── VERSO ──
        if (item.verso || hasVersoUrl) {
            const canvasBack = document.createElement('canvas');
            await drawAmostraFace(item, 'back', canvasBack, null, fmt, cor, num, idx, osId, S);
            if (canvasBack.width > 0 && canvasBack.height > 0) {
                await snapshotAmostraSync(idx, osId, item, canvasBack, 'verso');
                console.log(`[Snapshot] Item ${idx} VERSO composto e salvo.`);
            }
        }
    } catch (e) { throw new Error('não consegui compor a arte de amostra: ' + (e && e.message || e)); }

    return true;
}
window.regenerarAmostraDoModelo = regenerarAmostraDoModelo;

// Força a regeneração de TODOS os snapshots de uma OS usando canvas offscreen.
// Garante que a imagem do link do cliente seja idêntica à janela combinada do
// editor. Um item que falhar não pode parar os outros — por isso, e só por isso,
// o erro é engolido aqui.
async function forceRegenerateSnapshots(osId) {
    // SEMPRE recarregar do banco para pegar a arte mais recente (após alterações)
    if (typeof loadOSItens === 'function') {
        try { await loadOSItens(osId); } catch (e) { console.warn('[Snapshot] Erro ao carregar itens:', e); }
    }
    const itens = state.osItens[osId] || [];
    if (!itens.length) { console.log('[Snapshot] Nenhum item para OS', osId); return { gerados: 0, falhas: [] }; }

    await garantirTabelasDaAmostra();

    const falhas = [];
    let gerados = 0;

    for (let idx = 0; idx < itens.length; idx++) {
        try {
            if (await regenerarAmostraDoModelo(osId, itens[idx], idx, ESCALA_DA_AMOSTRA)) gerados++;
        } catch (e) {
            // Engolir para não parar os outros itens continua certo — o que
            // estava errado era engolir e não CONTAR. Sem esta lista, quem
            // chamou não tinha como saber que a arte de um modelo ficou velha.
            const nome = itens[idx].nome_modelo || itens[idx].produto || ('modelo ' + (idx + 1));
            console.warn(`[Snapshot] Item ${idx} (${nome}):`, e && e.message || e);
            falhas.push({ idx: idx, nome: nome, motivo: (e && e.message) || String(e) });
        }
    }
    console.log(`[Snapshot] Regeneração concluída para OS ${osId}: ${gerados} gerado(s), ${falhas.length} falha(s)`);
    return { gerados: gerados, falhas: falhas };
}
window.forceRegenerateSnapshots = forceRegenerateSnapshots;

// Expor globalmente
window.renderItemAmostraCombinada = renderItemAmostraCombinada;

window.customNumeracaoEditState = null;

function editCustomNumeracao(idx, osId, itemId) {
    const numSelect = document.getElementById(`amostra-item-num-${idx}`);
    if (!numSelect || !numSelect.value) {
        toast('Selecione uma numeração base primeiro antes de editar!', 'warning');
        return;
    }
    
    const baseNumId = numSelect.value;
    const baseNum = state.numeracoes.find(n => String(n.id) === String(baseNumId));
    if (!baseNum) {
        toast('Numeração ID ' + baseNumId + ' não encontrada. IDs disponíveis: ' + state.numeracoes.slice(0,5).map(n => n.id).join(', '), 'warning');
        return;
    }
    
    const osItens = state.osItens[osId];
    if (!osItens) {
        toast('Itens da OS não carregados. Tente recarregar.', 'error');
        return;
    }
    
    const item = osItens.find(i => String(i.id) === String(itemId));
    if (!item) {
        toast('Item não encontrado nos itens da OS.', 'error');
        return;
    }
    
    const modelName = `${item.produto} (Modelo ${idx + 1})`;
    
    const os = (state.ordens || []).find(o => String(o.id) === String(osId) || String(o.id_int) === String(osId));
    const cliNum = os ? os.id_cliente : null;

    // Set custom state
    window.customNumeracaoEditState = {
        active: true,
        osId,
        itemId,
        idx,
        modelName,
        baseNumId,
        cliNum
    };
    
    // Mudar view
    showView('view-numeracao');
    
    setTimeout(async () => {
        // Carrega numerao base
        await editNumeracao(baseNumId);
        
        setTimeout(() => {
            // Editar no lugar, ou clonar? Ver `comoEditarNumeracaoDoModelo`.
            //
            // Até 26/08/2026 estas duas linhas eram sempre "limpa o id para
            // forçar INSERT e escreve o nome do modelo" — e era por isso que
            // renomear uma numeração exclusiva criava outra em vez de renomear
            // a que estava aberta.
            const modo = comoEditarNumeracaoDoModelo(baseNum, itemId, cliNum);

            if (modo.noLugar) {
                // Mantém id e nome: o save vira UPDATE deste mesmo registro.
                toast(modo.motivo === 'compartilhada'
                    ? `Editando "${baseNum.name}", compartilhada entre os modelos deste cliente.`
                    : `Editando a numeração deste modelo: ${baseNum.name}`, 'info');
            } else {
                document.getElementById('num-id').value = '';
                document.getElementById('num-name').value = String(itemId);
                toast(`Criando a numeração exclusiva do modelo: ${itemId}`, 'info');
            }

            // A saída. Depois do `editNumeracao`, que passa pelo `cancelNumEdit`
            // e esconderia o botão de novo.
            mostrarVoltarDaNumeracaoDoModelo();
        }, 150);
    }, 100);
}

/**
 * Acende o botão "← Voltar sem salvar" do editor de numeração.
 *
 * Ele só existe para quem chegou ali de dentro de um pedido: no catálogo, a
 * saída é o próprio menu lateral, e o vínculo com o modelo não existe para
 * desfazer.
 *
 * Precisa ser chamado DEPOIS do `editNumeracao()`, porque ele passa pelo
 * `cancelNumEdit()`, que esconde o botão junto com o resto do formulário.
 */
function mostrarVoltarDaNumeracaoDoModelo() {
    const btn = document.getElementById('btn-num-voltar');
    if (btn) btn.style.display = '';
    atualizarDicaDoNomeDaNumeracao();
    atualizarMarcaDaNumeracaoExclusiva();
}

/**
 * Acende a dica embaixo do campo Nome.
 *
 * O nome faz duas coisas na numeração exclusiva de cliente, e nenhuma delas é
 * visível: diz a quem ela pertence (igual ao id do modelo = só dele) e decide o
 * que o Salvar faz (mesmo nome atualiza, nome novo duplica). Quem aprende essas
 * duas regras sem a frase, aprende perdendo trabalho.
 *
 * Aparece para qualquer numeração de cliente aberta no editor — inclusive uma
 * aberta pela Lista de Numerações —, e não só para quem veio de um pedido.
 */
function atualizarDicaDoNomeDaNumeracao() {
    const dica = document.getElementById('num-name-dica-modelo');
    if (!dica) return;
    dica.style.display = numeracaoDoEditorGuardaFundo() ? '' : 'none';
}
window.atualizarDicaDoNomeDaNumeracao = atualizarDicaDoNomeDaNumeracao;

/**
 * De que cliente é a numeração aberta no editor — ou `null`, se for do catálogo.
 *
 * São duas origens, e as duas contam: a numeração que já existe no banco
 * (`num-id` preenchido, `Cli_Num` na linha) e a que está nascendo de dentro de
 * um modelo (`customNumeracaoEditState`, que carrega o cliente do pedido).
 */
function clienteDaNumeracaoDoEditor() {
    const id = document.getElementById('num-id')?.value || '';
    if (id) {
        const n = (state.numeracoes || []).find(x => String(x.id) === String(id));
        if (n && n.Cli_Num) return n.Cli_Num;
    }
    if (window.customNumeracaoEditState) {
        return window.customNumeracaoEditState.cliNum || null;
    }
    return null;
}
window.clienteDaNumeracaoDoEditor = clienteDaNumeracaoDoEditor;

/**
 * ── O editor muda de cor quando a numeração é exclusiva de cliente ──────────
 *
 * Pedido do usuário em 27/08/2026. O editor é o mesmo para as duas famílias, e
 * nada na tela dizia em qual delas o operador estava — a diferença aparecia só
 * nas consequências, todas invisíveis no momento de editar: salvar com o mesmo
 * nome repassa a mudança para todos os modelos daquele cliente, a arte de fundo
 * fica guardada no registro, e a numeração não aparece no catálogo depois.
 *
 * O âmbar é o mesmo que marca a exclusiva no seletor de Numeração do modelo, de
 * propósito: "amarelo = exclusiva de cliente" passa a valer no aplicativo
 * inteiro, em vez de ser uma convenção por tela.
 *
 * O selo traz o NÚMERO do cliente, e não só a palavra "exclusiva": é o número
 * que identifica o cliente no ERP e o que se digita na busca do catálogo.
 */
function atualizarMarcaDaNumeracaoExclusiva() {
    const view = document.getElementById('view-numeracao');
    const selo = document.getElementById('num-selo-exclusiva');
    const btn = document.getElementById('btn-num-tornar-padrao');

    const cli = clienteDaNumeracaoDoEditor();
    const idNoEditor = document.getElementById('num-id')?.value || '';

    if (view) view.classList.toggle('editando-exclusiva', !!cli);

    if (selo) {
        selo.style.display = cli ? '' : 'none';
        selo.textContent = cli ? ('👤 EXCLUSIVA · CLIENTE ' + cli) : '';
        selo.title = cli
            ? ('Esta numeração pertence ao cliente ' + cli + '. Ela não aparece no '
               + 'catálogo geral, e salvar com o mesmo nome vale para todos os modelos dele.')
            : '';
    }

    // Duplicar exige um original gravado. Com o editor numa numeração que ainda
    // não existe no banco, não há o que duplicar — o botão sairia prometendo
    // uma cópia de coisa nenhuma.
    if (btn) btn.style.display = (cli && idNoEditor) ? '' : 'none';
}
window.atualizarMarcaDaNumeracaoExclusiva = atualizarMarcaDaNumeracaoExclusiva;

/**
 * ── Tornar padrão: a exclusiva vira uma numeração do catálogo geral ─────────
 *
 * Pedido do usuário em 27/08/2026: *"ao editar as numerações exclusivas, ter uma
 * opção de transformá-las em numerações padrão, fazendo com que ela seja
 * duplicada e mudada de exclusiva para padrão"*.
 *
 * **Duplica, não converte.** A exclusiva fica exatamente como está, e os
 * modelos que apontam para ela continuam apontando. Converter no lugar mudaria
 * o material de todo mundo que a usa hoje — inclusive de pedidos já aprovados —
 * e faria isso calado, que é o oposto do que o resto desta tela faz.
 *
 * O que a cópia perde, e por quê:
 *
 *   `Cli_Num`     é o que a prendia ao cliente. Sem ele a numeração aparece no
 *                 catálogo para qualquer pedido — que é o pedido inteiro.
 *   `os_item_id`  a origem era um modelo daquele cliente; a cópia não tem.
 *   `is_custom`   a marca de "nasceu de dentro de um pedido".
 *   arte de fundo só a numeração de cliente guarda (regra de 26/08/2026); a do
 *                 catálogo tira o fundo da cor do formato base.
 *   `preview_jpg` como em toda duplicação: duas linhas apontando para o mesmo
 *                 arquivo no Storage fariam salvar uma mudar o preview da outra.
 *                 A cópia ganha o dela no primeiro save — que é este mesmo.
 *
 * A gravação é o `saveNumeracao()` de sempre, e é de propósito: ele já sabe
 * subir preview, recusar nome ocupado e montar os `elements`. Zerar o `num-id`
 * e o `customNumeracaoEditState` antes de chamá-lo é o que faz o INSERT sair
 * sem dono — os três campos de posse do save saem todos do `registroEmEdicao`,
 * que sem id não existe.
 */
async function tornarNumeracaoPadrao() {
    const id = document.getElementById('num-id')?.value || '';
    const cli = clienteDaNumeracaoDoEditor();

    if (!id || !cli) {
        return toast('Esta opção vale para uma numeração exclusiva de cliente já salva.', 'warning');
    }

    const atual = (state.numeracoes || []).find(x => String(x.id) === String(id));
    // O CAMPO primeiro, e não o nome gravado: quem já digitou um nome novo sem
    // salvar veria a digitação sumir se o caminho de recusa devolvesse o nome
    // do banco por cima dela.
    const nomeAtual = document.getElementById('num-name')?.value || (atual && atual.name) || '';

    const novoNome = prompt(
        'Nome da numeração PADRÃO que vai ser criada.\n\n'
        + 'A exclusiva do cliente ' + cli + ' continua como está, e os modelos que usam '
        + 'ela seguem nela. A cópia entra no catálogo geral, disponível para qualquer pedido.',
        nomeAtual);

    if (novoNome === null) return;
    const nome = String(novoNome).trim();
    if (!nome) return toast('A cópia precisa de um nome.', 'warning');

    // Zera o vínculo: sem `num-id` o save INSERE, e sem `customNumeracaoEditState`
    // ele não marca a linha nova como exclusiva de modelo nenhum.
    const vinculo = window.customNumeracaoEditState;
    document.getElementById('num-id').value = '';
    window.customNumeracaoEditState = null;
    const btnVoltar = document.getElementById('btn-num-voltar');
    if (btnVoltar) btnVoltar.style.display = 'none';
    document.getElementById('num-name').value = nome;

    const novoId = await window.saveNumeracao();

    if (!novoId) {
        // O save já explicou o que houve — nome ocupado e recusado, ou erro do
        // banco. Ele sai por um `return` que NÃO passa pelo `cancelNumEdit()`,
        // então o formulário continua preenchido; o que ficou errado é o que
        // esta função mexeu. Devolver os três é o que impede o próximo Salvar
        // de gravar uma numeração nova em vez de atualizar a exclusiva.
        document.getElementById('num-id').value = id;
        document.getElementById('num-name').value = nomeAtual;
        window.customNumeracaoEditState = vinculo;
        if (btnVoltar && vinculo) btnVoltar.style.display = '';
        atualizarMarcaDaNumeracaoExclusiva();
        return;
    }

    toast('"' + nome + '" agora é uma numeração padrão do catálogo. '
        + 'A exclusiva do cliente ' + cli + ' continua como estava.', 'success');

    await editNumeracao(novoId);
}
window.tornarNumeracaoPadrao = tornarNumeracaoPadrao;
window.mostrarVoltarDaNumeracaoDoModelo = mostrarVoltarDaNumeracaoDoModelo;

/**
 * Sai do editor de numeração sem gravar nada, e volta para de onde se veio.
 *
 * Pedido do usuário em 25/08/2026: *"ao editar a numeração de um modelo, precisa
 * ter o botão Voltar para poder sair sem salvar"*.
 *
 * Antes, o único caminho de volta era o menu lateral — que sai da tela e deixa
 * o `customNumeracaoEditState` pendurado. Esse estado diz "a numeração que for
 * salva agora pertence ao modelo X do pedido Y": com ele vivo, a próxima
 * numeração salva, mesmo uma do catálogo geral aberta pelo menu, nascia marcada
 * como exclusiva daquele modelo e era amarrada a ele. Mais um caminho para a
 * numeração fantasma, e nada na tela denunciava.
 *
 * Quem apaga o vínculo é o `cancelNumEdit()`, e é por isso que ele é chamado
 * aqui — este botão não repete a limpeza, ele a usa.
 *
 * **Não pergunta "tem certeza?".** O rótulo já diz "sem salvar", e pedir
 * confirmação para uma saída que a pessoa acabou de escolher é atrito em cima
 * de uma decisão consciente. O que se perde é o posicionamento não salvo; o que
 * estava gravado no banco continua lá, intacto.
 */
function voltarDaNumeracaoDoModelo() {
    const de = window.customNumeracaoEditState;

    cancelNumEdit();   // limpa o formulário E zera o vínculo com o modelo

    // Sem estado nenhum (o operador recarregou a página no meio, por exemplo):
    // o catálogo é o destino honesto — é de lá que esta tela nasce.
    if (!de) {
        showView('view-catalogo');
        return;
    }

    if (de.view === 'imposicao') {
        showView('view-imposicao');
    } else {
        showView('view-amostras');
        if (typeof renderAmostrasOSItens === 'function' && de.osId) {
            renderAmostrasOSItens(de.osId);
        }
    }

    toast('Você saiu sem salvar. A numeração do modelo continua como estava.', 'info');
}
window.voltarDaNumeracaoDoModelo = voltarDaNumeracaoDoModelo;
window.onItemCorSelect = onItemCorSelect;
window.onItemNumSelect = onItemNumSelect;
window.onItemArteUpload = onItemArteUpload;
window.onItemArteRemove = onItemArteRemove;
window.saveAmostraToDB = saveAmostraToDB;
window.editCustomNumeracao = editCustomNumeracao;

