window.showClienteNumeracoesModal = function(fieldId, forceIdCliente = null) {
    console.log('[showClienteNumeracoesModal] started. fieldId:', fieldId, 'forceIdCliente:', forceIdCliente);
    let idCliente = forceIdCliente;
    if (!idCliente) {
        const activeOSItem = state.activeOSItem;
        console.log('[showClienteNumeracoesModal] activeOSItem:', activeOSItem);
        if (activeOSItem) {
            const os = (state.ordens || []).find(o => String(o.id) === String(activeOSItem.osId) || String(o.id_int) === String(activeOSItem.osId));
            console.log('[showClienteNumeracoesModal] Found OS:', os);
            if (os) idCliente = os.id_cliente;
        }
    }
    
    console.log('[showClienteNumeracoesModal] idCliente resolved to:', idCliente);
    if (!idCliente) {
        toast('Este pedido não está associado a um cliente válido! (Cliente ID: ' + idCliente + ')', 'warning');
        return;
    }

    const modal = document.getElementById('modal-cliente-numeracoes');
    const list = document.getElementById('cliente-numeracoes-list');
    if (!modal || !list) return;

    // Filtrar numerações que tenham Cli_Num igual ao idCliente
    const filtered = (state.numeracoes || []).filter(n => String(n.Cli_Num || '') === String(idCliente));

    if (filtered.length === 0) {
        list.innerHTML = `<p style="text-align: center; color: var(--text-dim); padding: 20px;">Nenhuma numeração customizada encontrada para este cliente.</p>`;
    } else {
        list.innerHTML = filtered.map(n => `
            <div class="cliente-num-item" style="display: flex; justify-content: space-between; align-items: center; padding: 10px; background: rgba(0,0,0,0.25); border: 1px solid var(--border); border-radius: 6px; margin-bottom: 8px;">
                <div style="flex: 1; padding-right: 12px;">
                    <strong style="color: #fff; font-size: 0.9rem;">${n.name}</strong>
                    <div style="font-size: 0.75rem; color: var(--text-dim); margin-top: 2px;">
                        Tipo: ${n.tipo || 'SEQUENCIAL'} | Formatos: ${(n.formato_ids || [n.formato_id]).map(id => state.formatos.find(f => String(f.id) === String(id))?.name || id).join(', ')}
                    </div>
                </div>
                <button class="btn btn-primary btn-sm" onclick="selectClienteNumeracaoForField('${fieldId}', '${n.id}')">Selecionar</button>
            </div>
        `).join('');
    }

    modal.style.display = 'flex';
};

window.closeClienteNumeracoesModal = function() {
    const modal = document.getElementById('modal-cliente-numeracoes');
    if (modal) modal.style.display = 'none';
};

window.selectClienteNumeracaoForField = function(fieldId, numId) {
    const numSelect = document.getElementById(fieldId);
    if (numSelect) {
        const newNum = state.numeracoes.find(n => String(n.id) === String(numId));
        if (newNum) {
            if (!Array.from(numSelect.options).some(o => o.value === newNum.id)) {
                const opt = document.createElement('option');
                opt.value = newNum.id;
                opt.textContent = newNum.name;
                numSelect.appendChild(opt);
            }
            numSelect.value = newNum.id;
            numSelect.dispatchEvent(new Event('change'));
        }
    }
    window.closeClienteNumeracoesModal();
};

window.editImposicaoCustomNumeracao = async function(fieldId) {
    const numSelect = document.getElementById(fieldId);
    if (!numSelect || !numSelect.value) {
        toast('Selecione uma numeração base primeiro antes de editar!', 'warning');
        return;
    }
    
    const impName = document.getElementById('imp-name').value.trim() || 'Modelo Imposição';
    const numId = numSelect.value;
    const baseNum = state.numeracoes.find(n => String(n.id) === String(numId));
    if (!baseNum) return;
    
    const activeOSItem = state.activeOSItem;
    let cliNum = null;
    if (activeOSItem) {
        const os = (state.ordens || []).find(o => String(o.id) === String(activeOSItem.osId) || String(o.id_int) === String(activeOSItem.osId));
        if (os) cliNum = os.id_cliente;
    }

    // Configura o state para que no saveNumeracao volte para Imposição
    window.customNumeracaoEditState = {
        view: 'imposicao',
        fieldId: fieldId,
        modeloName: impName,
        // O modelo de origem também aqui: sem ele, o `os_item_id` da numeração
        // gravada por este caminho saía `undefined`, e a regra do nome (que
        // compara `name` com `os_item_id`) ficava sem o lado direito.
        itemId: activeOSItem ? activeOSItem.itemId : null,
        cliNum: cliNum
    };
    
    // Abre a numeração
    await editNumeracao(numId);

    // Editar no lugar, ou clonar? A mesma decisão do `editCustomNumeracao`.
    const itemIdAtual = activeOSItem ? activeOSItem.itemId : null;
    const modoImp = itemIdAtual
        ? comoEditarNumeracaoDoModelo(baseNum, itemIdAtual, cliNum)
        : { noLugar: false };

    if (modoImp.noLugar) {
        toast(`Editando "${baseNum.name}" — o save grava nela mesma.`, 'info');
    } else if (itemIdAtual) {
        document.getElementById('num-name').value = String(itemIdAtual);
        document.getElementById('num-id').value = '';
        toast(`Clonando base "${baseNum.name}" para edição customizada.`, 'info');
    } else {
        // Sem modelo ativo não há a quem pertencer: clona sem renomear, que é
        // o mais perto do comportamento antigo sem estourar num `undefined`.
        document.getElementById('num-id').value = '';
        toast(`Clonando base "${baseNum.name}".`, 'info');
    }

    // A saída, igual à do outro caminho. Depois do `editNumeracao`, que passa
    // pelo `cancelNumEdit` e esconderia o botão de novo.
    mostrarVoltarDaNumeracaoDoModelo();
};

/**
 * Salva a decisão (APROVADA/REPROVADA) de um item de amostra
 */
async function decisionAmostraItem(itemId, osId, status, opts = {}) {
    // `opts.emLote`: chamada pelo botão em lote do pedido (`acaoEmLoteNoPedido`).
    // Grava e valida igual; só não avisa nem redesenha por modelo — o lote faz
    // isso uma vez no fim. `opts.obs` substitui a leitura do textarea. Devolve
    // true quando gravou e false em qualquer saída antecipada; o botão do card
    // ignora o retorno.
    const emLote = !!(opts && opts.emLote);
    const obsEl = document.getElementById(`amostra-obs-${itemId}`);
    const obs = (opts && opts.obs !== undefined) ? String(opts.obs) : (obsEl ? obsEl.value : '');

    // Qtd × linhas do banco (regra do usuário, 19/08/2026). O modelo não pode
    // ser marcado PRONTO enquanto o banco não fechar com a quantidade que o
    // pedido comprou — e, como o pedido só vira "Enviar Arte" com TODOS os
    // modelos PRONTO, isso segura o pedido inteiro até alguém corrigir.
    //
    // Só o PRONTO do painel interno: o APROVAR/ALTERAR do link do cliente
    // também passa por aqui, e travar o cliente seria travar justamente quem
    // não tem como consertar a numeração.
    if (status === 'PRONTO' && state.amostrasContainerId !== 'cliente-amostras-itens-container') {
        const itens = state.osItens[osId] || [];
        const idxAlvo = itens.findIndex(i => String(i.id) === String(itemId));
        const itemAlvo = idxAlvo >= 0 ? itens[idxAlvo] : null;

        // A fatia orfa vem primeiro: a de Qtd descreve o mesmo sintoma e manda
        // consertar o lugar errado. Ver `distribuicaoOrfaDoModelo`.
        const orfa = distribuicaoOrfaDoModelo(itemAlvo, osId);
        if (orfa) {
            toast('Este modelo não pode ser marcado PRONTO: ' + orfa.texto
                + ' Remova a distribuição no aviso do card — o banco volta a valer inteiro.', 'warning');
            return false;
        }

        const divergencia = divergenciaDeCelulasDoModelo(itemAlvo);
        if (divergencia) {
            toast('Este modelo não pode ser marcado PRONTO: ' + textoDaDivergenciaDeCelulas(divergencia)
                + '. Corrija as linhas do banco — a quantidade do pedido não se altera aqui.', 'warning');
            return false;
        }
        // Elemento de banco de dados sem CSV ou sem coluna (regra do usuário,
        // 22/08/2026): mesma trava, mesmo lugar — aqui e não só no botão.
        const bancoIncompleto = bancoDeDadosIncompletoDoModelo(itemAlvo);
        if (bancoIncompleto) {
            toast('Este modelo não pode ser marcado PRONTO: ' + bancoIncompleto.texto
                + ' Abra a numeração no lápis, carregue o CSV e aponte a coluna do elemento.', 'warning');
            return false;
        }
        // Caractere que a fonte não desenha: mesma trava, mesmo lugar. O botão
        // já nasce desabilitado, mas o lote e o atalho de teclado entram por
        // aqui — e é aqui que a última palavra tem de ser dada.
        const semGlifo = fonteSemGlifoDoModelo(itemAlvo);
        if (semGlifo) {
            toast('Este modelo não pode ser marcado PRONTO: ' + semGlifo.texto
                + ' Troque a fonte do elemento na numeração — na tela o nome aparece inteiro,'
                + ' no papel sai com buraco.', 'warning');
            return false;
        }

        // A arte de aprovação é regerada AQUI, e esperada até o fim (regra do
        // usuário, 19/08/2026: "deve ser gerada e salva novamente sempre que
        // clicar em Arte Pronta").
        //
        // Antes ela dependia de dois gatilhos frouxos: o `_needsSnapshot`, que
        // só é ligado por certas edições e dispara 2 s DEPOIS do desenho, e a
        // regeneração em segundo plano do "Gerar Link", disparada sem espera
        // logo após o link já ter sido copiado. Nos dois casos o atendente podia
        // mandar o link antes de a imagem nova subir, e o cliente aprovava a
        // arte ANTERIOR à correção — sem nada na tela dizendo isso.
        //
        // Marcar PRONTO é o momento em que o designer declara que a arte está
        // pronta. É o lugar certo para congelá-la, e o único que o fluxo
        // garante que sempre acontece antes de o cliente ver.
        if (itemAlvo) {
            try {
                if (!emLote) toast('⏳ Gerando a arte de aprovação...', 'info');
                await garantirTabelasDaAmostra();
                await regenerarAmostraDoModelo(osId, itemAlvo, idxAlvo, ESCALA_DA_AMOSTRA);
            } catch (e) {
                // Falhar aqui e marcar PRONTO assim mesmo seria mandar o cliente
                // aprovar a arte velha. Melhor não avançar e dizer por quê.
                console.error('[Arte Pronta] Falha ao gerar a amostra:', e);
                toast('Não consegui gerar a arte de aprovação: ' + (e && e.message || e)
                    + ' — o modelo NÃO foi marcado como pronto. Tente de novo.', 'error');
                return false;
            }
        }
    }

    if (status === 'REPROVADA' && (!obs || obs.trim() === '')) {
        toast('Anotar alteração no campo ANOTAÇÕES', 'warning');
        if (obsEl) obsEl.focus();
        return false;
    }
    
    try {
        const gravar = { amostra_status: status, amostra_obs: obs };

        // O PRONTO DO DESIGNER LIBERA A IMPRESSÃO (02/09/2026).
        //
        // A outra ponta do "Corrigir Arte": a produção devolveu o modelo, o
        // designer arrumou a arte e marcou PRONTO — a partir daqui a impressora
        // pode voltar a trabalhar, sem ninguém ter de lembrar de mexer no
        // seletor de status na outra tela.
        //
        // Volta para **Aguardando**, e nunca para o que era antes: se estava
        // Impresso, o que saiu era da arte velha e não serve. Decisão do
        // usuário no dia — por isso não guardamos o status anterior em lugar
        // nenhum, e o seletor não tem memória a restaurar.
        //
        // Só o PRONTO do painel: o APROVAR do link do cliente também chega
        // aqui, e o cliente não é quem destrava a impressora.
        const itemParaLiberar = (state.osItens[osId] || []).find(i => String(i.id) === String(itemId));
        const liberaImpressao = status === 'PRONTO'
            && state.amostrasContainerId !== 'cliente-amostras-itens-container'
            && modeloEmCorrecaoDeArte(itemParaLiberar);
        if (liberaImpressao) gravar.status_impressao = 'Aguardando';

        await saveAmostraToDB(itemId, osId, gravar);

        if (liberaImpressao) {
            // Os DOIS nomes do mesmo dado, e nos dois lugares em que ele mora:
            // a linha da fila lê `status_impressao`, o card do pedido lê
            // `impressao`, e a Lista de Arte lê `state.modelosGlobais`. Deixar
            // um para trás faria a tela continuar dizendo "Corrigir Arte" até
            // o próximo F5 — e o pedido continuaria no card errado.
            if (itemParaLiberar) {
                itemParaLiberar.status_impressao = 'Aguardando';
                itemParaLiberar.impressao = 'Aguardando';
            }
            const numOs = parseInt(String(osId).replace('vibe_', ''));
            const globais = (state.modelosGlobais && state.modelosGlobais[numOs]) || [];
            const globalDoModelo = globais.find(m => String(m.id) === String(itemId));
            if (globalDoModelo) {
                globalDoModelo.status_impressao = 'Aguardando';
                globalDoModelo.impressao = 'Aguardando';
            }
        }
        
        // Se for na página do cliente, vamos notificar no chat do pedido!
        const isClientePage = (state.amostrasContainerId === 'cliente-amostras-itens-container');
        if (isClientePage) {
            const item = state.osItens[osId].find(i => String(i.id) === String(itemId));
            const prodNome = item ? item.produto : 'Produto';
            
            // Enviar mensagem no chat da proposta
            try {
                await supabaseClient.from('propostas_chat').insert({
                    id_int: parseInt(clienteState.numero),
                    tipo: 'PRODUCAO',
                    setor: 'Cliente',
                    visivel_externo: true,
                    mensagem: status === 'APROVADA' 
                        ? `✅ O cliente APROVOU a amostra do item: "${prodNome}".`
                        : `❌ O cliente solicitou ALTERAÇÃO na amostra do item: "${prodNome}".\nObservações: ${obs || '(Sem observações)'}`,
                    autor_nome: 'Cliente (via link)',
                });
            } catch (chatErr) {
                console.warn('Erro ao inserir mensagem no chat:', chatErr);
            }
            
            // Se for reprovado e for o fluxo do cliente, podemos atualizar a tabela pedidos_artes também
            if (status === 'REPROVADA') {
                try {
                    await supabaseClient
                        .from('pedidos_artes')
                        .update({ status: 'REPROVADA_CLIENTE', comentarios_revisao: obs })
                        .eq('id_modelo', itemId)
                        .order('versao', { ascending: false })
                        .limit(1);
                } catch (e) { /* silencioso */ }
            }
        }
        
        let msg = '';
        let toastType = 'info';
        if (status === 'APROVADA') {
            msg = 'Item aprovado!';
            toastType = 'success';
        } else if (status === 'REPROVADA') {
            msg = 'Item marcado para alteração!';
            toastType = 'warning';
        } else if (status === 'PRONTO') {
            msg = 'Item marcado como Pronto!';
            toastType = 'success';
        } else {
            msg = `Status atualizado para ${status}`;
        }
        if (!emLote) toast(msg, toastType);

        // Em lote, quem recarrega e redesenha — uma vez, no fim — é
        // `acaoEmLoteNoPedido`. Aqui só o caminho do botão do card.
        if (!emLote) {
            // Recarregar itens do banco antes de re-renderizar para garantir que arte_url
            // e modo_pdf estejam atualizados no state (evita sumiço do PDF no modo PDF)
            if (state.osItens && state.osItens[osId]) {
                state.osItens[osId] = state.osItens[osId].map(i => ({ ...i, _dbLoaded: false }));
            }
            try { await loadOSItens(osId); } catch (e) { console.warn('[decisionAmostraItem] loadOSItens err:', e); }
            renderAmostrasOSItens(osId);

            // AUTO-STATUS: se o designer marcou um item como PRONTO (contexto interno, não cliente),
            // verificar se TODOS os modelos da OS estão PRONTO. Se sim → 'Enviar Arte'.
            const isInternal = (state.amostrasContainerId !== 'cliente-amostras-itens-container');
            if (status === 'PRONTO' && isInternal) await promoverPedidoSeTodosProntos(osId);
        }
        return true;
    } catch (err) {
        console.error('Erro na decisão do item:', err);
        toast('Erro ao registrar decisão: ' + err.message, 'error');
        return false;
    }
}

/**
 * Todos os modelos do pedido PRONTO (ou aprovados) → o pedido vira "Enviar
 * Arte" sozinho, sem precisar clicar em "Voltar para Atendimento".
 *
 * Era um bloco dentro de `decisionAmostraItem`; virou função para o botão em
 * lote chamar UMA vez no fim, depois de reler os modelos, em vez de uma vez
 * por modelo com a lista ainda velha. Lê `state.osItens[osId]` como está —
 * quem chama garante que ele foi recarregado.
 */
async function promoverPedidoSeTodosProntos(osId) {
    const todosItens = state.osItens[osId] || [];
    const todosProntos = todosItens.length > 0 && todosItens.every(i => i.amostra_status === 'PRONTO' || i.amostra_status === 'APROVADA');
    if (!todosProntos) return false;

    const novoStatusOS = 'Enviar Arte';
    const os = state.ordens.find(o => o.id === osId);
    if (!os || os.status === novoStatusOS) return false;

    // Adiantar nesta máquina
    gravarStatusOverride(osId, novoStatusOS);
    // Atualizar memória
    os.status = novoStatusOS;
    // Atualizar banco
    try {
        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            if (osId.startsWith('vibe_')) {
                await supabaseClient.from('pedidos_links_cliente')
                    .update({ status_arte: novoStatusOS })
                    .eq('os_id', osId);
            } else {
                await supabaseClient.from('producao_ordens_servico')
                    .update({ status: novoStatusOS })
                    .eq('id', osId);
            }
        }
    } catch (autoErr) {
        console.warn('[AUTO-STATUS] Erro ao atualizar status para Enviar Arte:', autoErr);
    }
    toast(`🎉 Todos os modelos prontos! Pedido #${os.numero} mudou para "Enviar Arte" automaticamente.`, 'success');
    return true;
}
window.promoverPedidoSeTodosProntos = promoverPedidoSeTodosProntos;

/**
 * O botão em lote do pedido: Marcar PRONTO, Colocar em Alteração ou Aprovar
 * TODOS os modelos de uma vez (regra do usuário, 22/08/2026).
 *
 * Passo a passo: (1) o porteiro de papel — Aprovar e Alterar em lote são de
 * ADM e Atendimento; (2) o plano, que separa quem entra de quem fica de fora
 * e diz o motivo; (3) para Alteração, UMA anotação, obrigatória como no card,
 * escrita nos modelos sem anotação e acrescentada nos que já têm; (4) uma
 * confirmação com o plano inteiro; (5) `decisionAmostraItem` modelo a modelo,
 * em sequência — são as mesmas travas e gravações do botão do card, inclusive
 * a arte de aprovação regerada no PRONTO; (6) uma releitura, um redesenho, a
 * promoção para "Enviar Arte" se couber, e um único aviso com o resultado.
 */
window.acaoEmLoteNoPedido = async function(osId, acao) {
    const rotulo = ROTULO_DA_ACAO_EM_LOTE[acao] || acao;
    if (!podeAgirEmLoteNoPedido(acao)) {
        toast(rotulo + ' em lote: só ADM e Atendimento.', 'warning');
        return;
    }
    const itens = state.osItens[osId] || [];
    if (!itens.length) {
        toast('Este pedido não tem modelos carregados.', 'warning');
        return;
    }

    const ctx = {
        podeDestravar: podeDestravarModeloAprovado(),
        divergencia: item => {
            const d = divergenciaDeCelulasDoModelo(item);
            return d ? textoDaDivergenciaDeCelulas(d) : null;
        },
        bancoIncompleto: item => {
            const b = bancoDeDadosIncompletoDoModelo(item);
            return b ? b.texto : null;
        },
        semGlifo: item => {
            const g = fonteSemGlifoDoModelo(item);
            return g ? g.texto : null;
        },
    };
    const plano = planoDaAcaoEmLote(itens, acao, ctx);
    if (!plano.aplicar.length) {
        toast(textoDoPlanoEmLote(plano, itens.length), 'warning');
        return;
    }

    let textoDaAlteracao = null;
    if (acao === 'REPROVADA') {
        textoDaAlteracao = prompt('Anotação da alteração — vale para todos os modelos do pedido (obrigatória):', '');
        if (textoDaAlteracao === null) return;
        textoDaAlteracao = textoDaAlteracao.trim();
        if (!textoDaAlteracao) {
            toast('Anotar alteração: a anotação é obrigatória para colocar em alteração.', 'warning');
            return;
        }
    }

    if (!confirm(textoDoPlanoEmLote(plano, itens.length) + '\n\nConfirmar?')) return;

    let feitos = 0;
    let falhas = 0;
    const n = plano.aplicar.length;
    for (let i = 0; i < n; i++) {
        const item = plano.aplicar[i];
        toast('⏳ ' + (i + 1) + '/' + n + ' — ' + nomeDoModeloParaLista(item), 'info');
        const opts = { emLote: true };
        if (acao === 'REPROVADA') {
            const atual = String(item.amostra_obs || '').trim();
            opts.obs = atual ? atual + '\n' + textoDaAlteracao : textoDaAlteracao;
        }
        let ok = false;
        try {
            ok = await decisionAmostraItem(item.id, osId, acao, opts);
        } catch (e) {
            console.error('[lote] Falha no modelo', item.id, e);
            ok = false;
        }
        if (ok) feitos++; else falhas++;
    }

    if (state.osItens && state.osItens[osId]) {
        state.osItens[osId] = state.osItens[osId].map(i => ({ ...i, _dbLoaded: false }));
    }
    try { await loadOSItens(osId); } catch (e) { console.warn('[lote] loadOSItens err:', e); }
    renderAmostrasOSItens(osId);
    if (acao === 'PRONTO') await promoverPedidoSeTodosProntos(osId);

    const deFora = plano.pulados.length
        ? ' ' + plano.pulados.length + (plano.pulados.length === 1 ? ' ficou' : ' ficaram') + ' de fora (veja a confirmação).'
        : '';
    if (falhas) {
        toast(rotulo + ': ' + feitos + (feitos === 1 ? ' feito' : ' feitos') + ', ' + falhas
            + (falhas === 1 ? ' falhou' : ' falharam') + ' — veja os avisos.' + deFora, 'warning');
    } else {
        toast(rotulo + ': ' + feitos + (feitos === 1 ? ' modelo' : ' modelos') + '.' + deFora, 'success');
    }
};

/**
 * A linha "Todos os modelos:" do banner do pedido, com os botões em lote.
 *
 * Desenhada a cada `renderAmostrasOSItens`, e não escrita fixa no HTML, porque
 * o papel de quem está logado pode chegar depois do primeiro desenho — e são
 * ele e só ele que decidem se ❌ e ✅ nascem. Quem não é ADM nem Atendimento
 * lê por que só vê um botão. No link do cliente a linha não existe.
 */
function renderAcoesEmLoteDoPedido(osId) {
    const el = document.getElementById('amostras-acoes-em-lote');
    if (!el) return;
    const ehTelaDoCliente = (state.amostrasContainerId === 'cliente-amostras-itens-container');
    const itens = state.osItens[osId] || [];
    if (ehTelaDoCliente || !osId || !itens.length) {
        el.style.display = 'none';
        el.innerHTML = '';
        return;
    }
    const podeDecidir = podeAgirEmLoteNoPedido('APROVADA');
    const id = escapeJsAttr(String(osId));
    const base = 'font-weight: 700; height: 32px; padding: 0 12px; display: inline-flex; align-items: center; gap: 6px; border: 1px solid; border-radius: 6px; cursor: pointer; font-size: 0.78rem;';
    el.innerHTML = `
        <span style="font-size: 0.78rem; font-weight: 700; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.04em;">Todos os modelos:</span>
        <button class="btn btn-sm" id="btn-lote-pronto" style="${base} background: rgba(59,130,246,0.10); border-color: rgba(59,130,246,0.45); color: #60a5fa;"
                onclick="acaoEmLoteNoPedido('${id}', 'PRONTO')"
                title="Marca PRONTO todos os modelos do pedido que podem ser marcados — pula os já prontos, os aprovados e os com banco ou células em divergência, e diz quais antes de fazer.">🎨 Marcar todos PRONTO</button>
        ${podeDecidir ? `
        <button class="btn btn-sm" id="btn-lote-alteracao" style="${base} background: rgba(239,68,68,0.10); border-color: rgba(239,68,68,0.45); color: #f87171;"
                onclick="acaoEmLoteNoPedido('${id}', 'REPROVADA')"
                title="Coloca em ALTERAÇÃO todos os modelos do pedido, com uma anotação única — pula os que já estão em alteração.">❌ Todos em ALTERAÇÃO</button>
        <button class="btn btn-sm" id="btn-lote-aprovar" style="${base} background: rgba(34,197,94,0.10); border-color: rgba(34,197,94,0.45); color: #4ade80;"
                onclick="acaoEmLoteNoPedido('${id}', 'APROVADA')"
                title="Aprova pelo painel todos os modelos ainda não aprovados — mesmo efeito do ✅ APROVADO de cada card.">✅ Aprovar todos</button>`
        : `<span style="font-size: 0.74rem; color: var(--text-dim);">Aprovar e colocar em alteração em lote: só ADM e Atendimento.</span>`}`;
    el.style.display = 'flex';
}
window.renderAcoesEmLoteDoPedido = renderAcoesEmLoteDoPedido;

