// LINK DO CLIENTE -- PÁGINA PÚBLICA (FASE 2)
// ==========================================

/**
 * Gera token alfanumérico aleatório de 6 caracteres
 */
function generateClientToken(length = 6) {
    const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
    let result = '';
    const array = new Uint8Array(length);
    crypto.getRandomValues(array);
    for (let i = 0; i < length; i++) {
        result += chars[array[i] % chars.length];
    }
    return result;
}

/**
 * Gera ou recupera o link público do cliente para uma OS
 */
/**
 * Cria ou recupera o link do cliente para uma OS.
 * Retorna a URL completa, ou null em caso de erro.
 * Uso interno — não copia nem exibe toast.
 */
/**
 * Garante que o pedido tenha linha em `pedidos_artes` ANTES de ir ao cliente.
 *
 * A tela do cliente roda como `anon` -- o link não tem sessão do Supabase -- e a
 * RLS de `pedidos_artes` recusa INSERT vindo dali ("new row violates row-level
 * security policy", conferido em 20/08/2026). Ela consegue LER e ATUALIZAR, mas
 * não CRIAR. E a linha quase nunca existia: 38 para 8.263 propostas, porque só
 * nascia quando alguém preenchia o briefing no painel.
 *
 * O resultado era a solicitação de alteração do cliente sumindo: um UPDATE que
 * não acha linha nenhuma responde 200 com `[]`, sem erro nenhum.
 *
 * Aqui, no painel, quem chama está logado -- e este é o momento certo: o pedido
 * está indo para o cliente. Falhar aqui não pode impedir o link de sair, então
 * o erro só avisa no console.
 */
async function garantirLinhaDePedidoArte(numInt) {
    const n = parseInt(numInt);
    if (!n || isNaN(n) || typeof supabaseClient === 'undefined' || !supabaseClient) return false;

    try {
        const { data, error } = await supabaseClient
            .from('pedidos_artes')
            .select('id')
            .eq('id_int', n)
            .limit(1);

        if (error) throw error;
        if (data && data.length > 0) return true;

        const { error: erroInsert } = await supabaseClient
            .from('pedidos_artes')
            .insert({ id_int: n, observacoes: {} });

        if (erroInsert) throw erroInsert;
        console.log('[pedidos_artes] Linha criada para o pedido ' + n + ' (o cliente vai poder escrever nela).');
        return true;
    } catch (e) {
        console.warn('[pedidos_artes] Nao consegui garantir a linha do pedido ' + numInt + ':', e.message || e);
        return false;
    }
}
window.garantirLinhaDePedidoArte = garantirLinhaDePedidoArte;

async function getOrCreateLinkCliente(osId, numero) {
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return null;
    try {
        const { data: existing, error: fetchError } = await supabaseClient
            .from('pedidos_links_cliente')
            .select('*')
            .eq('os_id', osId)
            .eq('ativo', true)
            .maybeSingle();

        if (fetchError && fetchError.code !== 'PGRST116') {
            if (fetchError.code === '42P01') return null; // tabela não existe ainda
            throw fetchError;
        }

        let token;
        const os = state.ordens.find(o => o.id === osId);
        const currentStatus = os ? (os.status || 'Enviar Arte') : 'Enviar Arte';
        
        if (existing) {
            token = existing.token;
            await supabaseClient
                .from('pedidos_links_cliente')
                .update({ status_arte: currentStatus })
                .eq('id', existing.id);
            if (!state.linksClienteData) state.linksClienteData = {};
            state.linksClienteData[osId] = { ...existing, status_arte: currentStatus };
        }
 else {
            token = generateClientToken(6);
            const { error: insertError } = await supabaseClient
                .from('pedidos_links_cliente')
                .insert({
                    os_id: osId,
                    numero_pedido: String(numero),
                    token: token,
                    id_int: os ? (os.numero || numero) : numero,
                    status_arte: currentStatus
                });
            if (insertError) throw insertError;
        }

        // O pedido está indo ao cliente: a linha em `pedidos_artes` precisa
        // existir agora, enquanto quem está aqui é um usuário logado. Depois,
        // na tela do cliente, a RLS não deixa criar -- só atualizar.
        await garantirLinhaDePedidoArte(os ? (os.numero || numero) : numero);

        return `${window.location.origin}/cliente/${numero}-${token}`;
    } catch (e) {
        console.error('Erro ao obter/criar link do cliente:', e);
        return null;
    }
}

async function abrirLinkClienteEAtualizarStatus(osId, numero, linkUrl) {
    const novoStatus = 'Aguard. Aprovação';
    const host = window.location.origin;
    const finalUrl = linkUrl || `${host}/cliente.html?os=${osId}`;

    // Sempre a MESMA aba do cliente — modal de email é aberto SOMENTE quando o
    // usuário clicar no ícone ✉️ separado na linha do pedido (não automaticamente)
    window.open(finalUrl, ABA_DO_CLIENTE);

    // 2. Atualizar status e recarregar em segundo plano
    const os = state.ordens ? state.ordens.find(o => o.id === osId) : null;
    if (os && os.status !== 'Aprovada' && os.status !== 'APROVADO') {
        os.status = novoStatus;
        os.status_calculado = novoStatus;
        gravarStatusOverride(osId, novoStatus);

        if (typeof supabaseClient !== 'undefined' && supabaseClient) {
            if (osId.startsWith('vibe_')) {
                await supabaseClient.from('pedidos_links_cliente').update({ status_arte: novoStatus }).eq('os_id', osId);
            } else {
                await supabaseClient.from('producao_ordens_servico').update({ status: novoStatus }).eq('id', osId);
            }
        }
        loadOrdens();
    }
}
window.abrirLinkClienteEAtualizarStatus = abrirLinkClienteEAtualizarStatus;
