// ═══════════════════════════════════════════════════════════
// MÓDULO: IMPRESSÃO DIRETA COM DRIVER WINDOWS
// ═══════════════════════════════════════════════════════════

// Estado da fila de impressão
let _printBlobQueue = [];   // [{name, blob}]
let _printQueueIndex = 0;   // índice atual na fila

// Nome com que o trabalho entra no spool.
//
// O prefixo de 5 digitos e a ORDEM DE ENVIO, nao o numero do arquivo: 00001 e o
// primeiro que sai daqui, 00002 o segundo, e assim por diante. Ele existe porque
// a fila do Windows (e o painel da impressora) e ordenavel por nome — sem um
// numero na frente, capa, miolo e contracapa aparecem em ordem alfabetica e o
// operador imprime na sequencia errada. Reinicia em 00001 a cada lote enviado,
// entao o operador sempre le "de 00001 ate o total do lote".
//
// O nome do arquivo vem inteiro depois do prefixo — nenhuma marca do programa,
// so o que identifica o material.
function nomeParaSpool(ordem, nomeArquivo) {
    const seq = String(ordem).padStart(5, '0');
    const base = (nomeArquivo || 'impressao.pdf').replace(/\.pdf$/i, '');
    return `${seq}_${base}.pdf`;
}

// O relay guarda o arquivo no Storage antes do agente busca-lo, e o nome do
// objeto e o que o agente le para titular o job. Acento e espaco nao sobrevivem
// a uma chave de Storage, entao caem aqui — mesma normalizacao que db.py aplica
// ao enviar as fontes.
function nomeObjetoStorage(nome) {
    let saida = '';
    for (const ch of (nome || 'impressao.pdf').normalize('NFD')) {
        const cod = ch.codePointAt(0);
        if (cod >= 0x300 && cod <= 0x36f) continue;   // acento solto pela NFD: descarta
        saida += /[A-Za-z0-9._-]/.test(ch) ? ch : '_';
    }
    return saida;
}

// Carrega impressoras do agente cloud ou, em último caso, do agente local
async function _loadPrinterListIfEmpty() {
    if (_printerList && _printerList.length > 0) return;

    // 1. Da nuvem: o heartbeat do agente já publica a lista no Supabase. É o
    //    único caminho que funciona com o painel servido pela Vercel, porque o
    //    navegador bloqueia chamadas de página HTTPS para o localhost.
    const daNuvem = window._activeAgentData?.printers_json?.printers;
    if (Array.isArray(daNuvem) && daNuvem.length > 0) {
        _printerList = daNuvem.map(p => typeof p === 'object' ? p.name : p);
        return;
    }

    // 2. Do agente local. Só alcança quando o painel está na própria máquina.
    //    O endereço era montado com o hostname da PÁGINA, o que na nuvem virava
    //    http://imposicao.vercel.app:9000 — um endereço que não existe.
    try {
        const res = await fetch(`${AGENTE_LOCAL_URL}/api/printers`);
        if (res.ok) {
            const data = await res.json();
            _printerList = (data.printers || data || []).map(p => typeof p === 'object' ? p.name : p);
        }
    } catch (e) {
        console.warn('[PrintModal] Agente local inalcançável e nada publicado na nuvem. Escolha a estação em Impressoras.');
    }
}

// Popula o select de impressoras no modal
function _populatePrinterSelect() {
    const sel = document.getElementById('print-direct-printer');
    if (!sel) return;
    const current = sel.value;
    sel.innerHTML = '<option value="">Selecione a impressora...</option>';
    if (_printerList && _printerList.length > 0) {
        _printerList.forEach(name => {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name;
            if (name === current) opt.selected = true;
            sel.appendChild(opt);
        });
    } else {
        const opt = document.createElement('option');
        opt.value = '';
        opt.disabled = true;
        opt.textContent = '— Nenhuma impressora detectada —';
        sel.appendChild(opt);
    }
}

// Abre o modal para um único blob
async function openPrintModal(blob) {
    _printBlobQueue = [{ name: 'imposicao.pdf', blob }];
    _printQueueIndex = 0;
    _lastImposedBlob = blob;
    await _openModalUI();
}

// Abre o modal para uma fila de blobs (impressão sequencial)
async function openPrintModalQueue(queue) {
    _printBlobQueue = queue || [];
    _printQueueIndex = 0;
    _lastImposedBlob = _printBlobQueue.length > 0 ? _printBlobQueue[0].blob : null;
    await _openModalUI();
}

// Exibe a UI do modal
async function _openModalUI() {
    const modal = document.getElementById('modal-print-direct');
    if (!modal) return;
    modal.style.display = 'flex';

    // Resetar estado
    const optDiv = document.getElementById('print-direct-options');
    const loadDiv = document.getElementById('print-options-loading');
    const statusDiv = document.getElementById('print-send-status');
    const btnSend = document.getElementById('btn-send-print');
    const driverStatus = document.getElementById('print-driver-status');

    if (optDiv) optDiv.style.display = 'none';
    if (loadDiv) loadDiv.style.display = 'none';
    if (statusDiv) statusDiv.style.display = 'none';
    if (driverStatus) driverStatus.style.display = 'none';
    if (btnSend) { btnSend.disabled = true; btnSend.style.opacity = '0.5'; }

    // Exibir indicador de fila se múltiplos arquivos
    const queueIndicator = document.getElementById('print-queue-indicator');
    const queueList = document.getElementById('print-queue-list');
    const queueCounter = document.getElementById('print-queue-counter');
    if (queueIndicator && _printBlobQueue.length > 1) {
        queueIndicator.style.display = 'block';
        if (queueCounter) queueCounter.textContent = `${_printBlobQueue.length} arquivo(s)`;
        if (queueList) {
            queueList.innerHTML = _printBlobQueue.map((item, i) =>
                `<div style="display:flex;align-items:center;gap:8px;padding:4px 8px;background:rgba(255,255,255,0.04);border-radius:6px;" id="print-queue-item-${i}">
                    <span style="width:20px;height:20px;background:rgba(99,102,241,0.3);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.7rem;font-weight:700;color:#a5b4fc;flex-shrink:0;">${i+1}</span>
                    <span style="font-size:0.78rem;color:${i === 0 ? '#f1f5f9' : 'var(--text-dim)'};">${item.name}</span>
                    <span id="print-queue-status-${i}" style="margin-left:auto;font-size:0.72rem;color:${i === 0 ? '#fbbf24' : 'var(--text-dim)'};">${i === 0 ? '⏳ Atual' : '⌛ Aguardando'}</span>
                </div>`
            ).join('');
        }
    } else if (queueIndicator) {
        queueIndicator.style.display = 'none';
    }

    // Atualizar subtítulo
    const subtitle = document.getElementById('print-modal-subtitle');
    if (subtitle) {
        if (_printBlobQueue.length > 1) {
            subtitle.textContent = `${_printBlobQueue.length} arquivo(s) — impressão sequencial`;
        } else {
            subtitle.textContent = _printBlobQueue[0]?.name || 'Configurar opções do driver';
        }
    }

    // Carregar impressoras
    await _loadPrinterListIfEmpty();
    _populatePrinterSelect();
}

function closePrintModal() {
    const modal = document.getElementById('modal-print-direct');
    if (modal) modal.style.display = 'none';
    _printBlobQueue = [];
    _printQueueIndex = 0;
    // Modal fechado sem enviar: descartar a confirmação pendente
    window._printConfirmTargets = null;
}

// Recarregar lista de impressoras manualmente
async function reloadPrinterList() {
    _printerList = [];
    const btn = event?.currentTarget;
    if (btn) btn.style.animation = 'spin 0.6s linear';
    await _loadPrinterListIfEmpty();
    _populatePrinterSelect();
    if (btn) btn.style.animation = '';
    
    const driverStatus = document.getElementById('print-driver-status');
    const driverStatusText = document.getElementById('print-driver-status-text');
    if (driverStatus && driverStatusText) {
        driverStatusText.textContent = `✓ ${_printerList.length} impressora(s) detectada(s) no sistema`;
        driverStatus.style.display = 'block';
        setTimeout(() => { if (driverStatus) driverStatus.style.display = 'none'; }, 3000);
    }
}

// Ao mudar impressora no modal, carregar opções do driver
async function onPrintPrinterChange() {
    const sel = document.getElementById('print-direct-printer');
    const optDiv = document.getElementById('print-direct-options');
    const loadDiv = document.getElementById('print-options-loading');
    const btnSend = document.getElementById('btn-send-print');

    const printerName = sel ? sel.value : '';
    if (btnSend) { btnSend.disabled = !printerName; btnSend.style.opacity = printerName ? '1' : '0.5'; }

    if (!optDiv) return;
    if (!printerName) {
        optDiv.style.display = 'none';
        return;
    }

    // Mostrar loading
    if (loadDiv) loadDiv.style.display = 'block';
    if (optDiv) optDiv.style.display = 'none';

    // Buscar capacidades do driver
    let caps = null;

    // 1. Tentar via agente cloud (já carregado no heartbeat)
    if (window._activeAgentData?.printers_json?.capabilities) {
        caps = window._activeAgentData.printers_json.capabilities[printerName];
    }

    // 2. Tentar via API local (porta 9000 no mesmo servidor)
    if (!caps) {
        try {
            const apiBase = AGENTE_LOCAL_URL;   // 127.0.0.1: o hostname da pagina apontava para a Vercel
            const res = await fetch(`${apiBase}/api/printers/${encodeURIComponent(printerName)}/capabilities`);
            if (res.ok) caps = await res.json();
        } catch (e) {
            console.warn('[PrintModal] Não foi possível ler capacidades do driver:', e.message);
        }
    }

    // 3. Fallback padrão
    if (!caps) {
        caps = {
            duplex_supported: true,
            papers: [{id: 9, name: 'A4'}, {id: 8, name: 'A3'}],
            trays: [{id: 7, name: 'Auto'}],
            defaults: { duplex: 1, paper_size: 9, tray: 7, color: 2, copies: 1 }
        };
    }

    // Esconder loading
    if (loadDiv) loadDiv.style.display = 'none';
    if (optDiv) optDiv.style.display = 'block';

    // Preencher selects com os dados do driver
    const defaultTray = caps.defaults?.tray ?? 7;
    const defaultPaper = caps.defaults?.paper_size ?? 9;
    const defaultDuplex = caps.defaults?.duplex ?? 1;
    const defaultColor = caps.defaults?.color ?? 2;
    const defaultCopies = caps.defaults?.copies ?? 1;

    const traySel = document.getElementById('print-option-tray');
    if (traySel) {
        traySel.innerHTML = (caps.trays?.length
            ? caps.trays.map(t => `<option value="${t.id}" ${t.id === defaultTray ? 'selected' : ''}>${t.name}</option>`)
            : [`<option value="7" selected>Auto</option>`]
        ).join('');
    }

    const paperSel = document.getElementById('print-option-paper-size');
    if (paperSel) {
        paperSel.innerHTML = (caps.papers?.length
            ? caps.papers.map(p => `<option value="${p.id}" ${p.id === defaultPaper ? 'selected' : ''}>${p.name}</option>`)
            : [`<option value="9" selected>A4</option>`, `<option value="8">A3</option>`]
        ).join('');
    }

    const duplexSel = document.getElementById('print-option-duplex');
    if (duplexSel) {
        duplexSel.disabled = false;
        const isJobDuplex = temVerso(state.printMode) || (state.activeOSItem && !!state.activeOSItem.verso);
        const targetDuplex = isJobDuplex ? 2 : (defaultDuplex || 1);
        duplexSel.value = String(targetDuplex);
    }

    const colorSel = document.getElementById('print-option-color');
    if (colorSel) {
        colorSel.querySelectorAll('option').forEach(opt => {
            opt.selected = parseInt(opt.value) === defaultColor;
        });
    }

    const copiesInput = document.getElementById('print-option-copies');
    if (copiesInput) copiesInput.value = defaultCopies;

    // Exibir status do driver
    const driverStatus = document.getElementById('print-driver-status');
    const driverStatusText = document.getElementById('print-driver-status-text');
    if (driverStatus && driverStatusText) {
        const hasRealData = caps.papers?.length > 0 || caps.trays?.length > 0;
        if (hasRealData) {
            driverStatusText.textContent = `✓ Driver detectado — ${caps.papers?.length || 0} papel(is), ${caps.trays?.length || 0} bandeja(s)`;
            driverStatus.style.background = 'rgba(34,197,94,0.1)';
            driverStatus.style.borderColor = 'rgba(34,197,94,0.2)';
            driverStatusText.style.color = '#4ade80';
        } else {
            driverStatusText.textContent = '⚠ Capacidades padrão (driver não respondeu)';
            driverStatus.style.background = 'rgba(251,191,36,0.1)';
            driverStatus.style.borderColor = 'rgba(251,191,36,0.2)';
            driverStatusText.style.color = '#fbbf24';
        }
        driverStatus.style.display = 'block';
    }
}

// Enviar job de impressão (suporta modo Local direto e Cloud Relay)
// Quando há fila, processa sequencialmente
async function sendPrintJob() {
    const sel = document.getElementById('print-direct-printer');
    const printerName = sel ? sel.value : '';
    if (!printerName) { toast('Selecione uma impressora.', 'error'); return; }

    const orientation = document.querySelector('input[name="print-orientation"]:checked')?.value || '1';
    const options = {
        paper_size: parseInt(document.getElementById('print-option-paper-size')?.value) || 9,
        tray: parseInt(document.getElementById('print-option-tray')?.value) || 7,
        duplex: parseInt(document.getElementById('print-option-duplex')?.value) || 1,
        color: parseInt(document.getElementById('print-option-color')?.value) || 2,
        copies: parseInt(document.getElementById('print-option-copies')?.value) || 1,
        orientation: parseInt(orientation)
    };

    const btnSend = document.getElementById('btn-send-print');
    const statusDiv = document.getElementById('print-send-status');
    const statusText = document.getElementById('print-status-text');
    const statusBar = document.getElementById('print-status-bar');

    if (btnSend) { btnSend.disabled = true; btnSend.style.opacity = '0.5'; }
    if (statusDiv) statusDiv.style.display = 'block';

    const isLocalMode = !window._activeAgentData ||
        window.location.hostname === 'localhost' ||
        window.location.hostname === '127.0.0.1';

    const queue = _printBlobQueue.length > 0 ? _printBlobQueue : [{ name: 'imposicao.pdf', blob: _lastImposedBlob }];
    const loteId = Date.now();   // pasta do lote no Storage (so o relay usa)
    let successCount = 0;
    let failCount = 0;

    for (let i = 0; i < queue.length; i++) {
        const item = queue[i];
        const progress = Math.round((i / queue.length) * 100);

        if (statusText) statusText.textContent = `Enviando ${i + 1}/${queue.length}: ${item.name}...`;
        if (statusBar) statusBar.style.width = `${progress}%`;

        // Atualizar indicador de fila
        const queueStatusEl = document.getElementById(`print-queue-status-${i}`);
        if (queueStatusEl) { queueStatusEl.textContent = '⏳ Enviando...'; queueStatusEl.style.color = '#fbbf24'; }

        try {
            if (isLocalMode) {
                const formData = new FormData();
                formData.append('file', item.blob, nomeParaSpool(i + 1, item.name));
                formData.append('printer_name', printerName);
                formData.append('options', JSON.stringify(options));

                const res = await fetch('/api/print/submit', { method: 'POST', body: formData });
                if (!res.ok) {
                    const errText = await res.text();
                    throw new Error(errText || 'Falha ao enviar para impressora local.');
                }
            } else {
                // Cloud Relay via Supabase
                if (!_printerAgentActive || !window._activeAgentData) {
                    throw new Error('Agente de Impressão inativo. Inicie o NewProd.exe.');
                }
                // O nome do objeto E o titulo que o agente dara ao job, entao
                // ele carrega o prefixo de ordem. O carimbo de tempo saiu do
                // nome e virou PASTA do lote: assim dois lotes do mesmo modelo
                // nao colidem no Storage sem sujar o nome que o operador le.
                const fileName = nomeObjetoStorage(nomeParaSpool(i + 1, item.name));
                const filePath = `${window._activeAgentData.id}/${loteId}/${fileName}`;

                const { error: uploadError } = await supabaseClient.storage
                    .from('print_jobs')
                    .upload(filePath, item.blob, { contentType: 'application/pdf', upsert: false });
                if (uploadError) throw new Error(`Falha no upload: ${uploadError.message}`);

                const { data: urlData } = supabaseClient.storage.from('print_jobs').getPublicUrl(filePath);
                const { error: dbError } = await supabaseClient.from('print_queue').insert({
                    agent_id: window._activeAgentData.id,
                    file_url: urlData.publicUrl,
                    printer_name: printerName,
                    ppd_options: options,
                    status: 'pending'
                });
                if (dbError) throw new Error(`Falha ao registrar job: ${dbError.message}`);
            }

            successCount++;
            if (queueStatusEl) { queueStatusEl.textContent = '✓ Enviado'; queueStatusEl.style.color = '#4ade80'; }
        } catch (e) {
            failCount++;
            if (queueStatusEl) { queueStatusEl.textContent = '✗ Erro'; queueStatusEl.style.color = '#ef4444'; }
            console.error(`[PrintModal] Erro ao enviar ${item.name}:`, e);
            toast(`Erro ao imprimir "${item.name}": ${e.message}`, 'error');
        }
    }

    if (statusBar) statusBar.style.width = '100%';

    if (failCount === 0) {
        if (statusText) statusText.textContent = `✓ Todos os ${successCount} arquivo(s) enviados para "${printerName}"!`;
        toast(`${successCount} arquivo(s) enviado(s) para "${printerName}" com sucesso!`, 'success');
        // Guardar antes de fechar o modal (closePrintModal limpa a pendência)
        const alvosConfirmacao = window._printConfirmTargets;
        setTimeout(async () => {
            closePrintModal();
            // O status só vira IMPRESSO depois que o operador confirmar
            if (alvosConfirmacao && alvosConfirmacao.length && typeof confirmarImpressaoModelos === 'function') {
                await confirmarImpressaoModelos(alvosConfirmacao);
            }
        }, 1500);
    } else {
        if (statusText) statusText.textContent = `${successCount} enviado(s), ${failCount} com erro.`;
        if (btnSend) { btnSend.disabled = false; btnSend.style.opacity = '1'; }
    }
}

// Verificar agente ao abrir aba de impressoras
const _origSwitchView = window.switchView || null;
function switchViewWithPrinterCheck(viewId) {
    if (_origSwitchView) _origSwitchView(viewId);
    if (viewId === 'view-impressoras') checkPrinterAgent();
}

// Inicializar: verificar agente silenciosamente ao carregar
//
// O setTimeout(0) e obrigatorio, nao um ajuste de timing. Rodando direto aqui,
// esta checagem executava no meio da AVALIACAO do script.js: checkPrinterAgent()
// chama descobrirAgentIdLocal(), que le _agentIdLocalCache -- um `let` declarado
// ~2000 linhas abaixo (linha 25895). A funcao ja existe (declaracoes de funcao
// sao hoisted por inteiro), mas o `let` ainda esta na temporal dead zone, entao
// a leitura lancava ReferenceError a cada carregamento da pagina.
//
// O catch de checkPrinterAgent engolia o erro num console.error, e o resultado
// era _printerAgentActive = false sempre: o indicador so ficava correto depois
// que o operador abria a aba Impressoras (que chama checkPrinterAgent de novo,
// ai sim com o script todo avaliado).
//
// Adiar para o proximo tick faz a checagem rodar com o arquivo inteiro ja
// avaliado -- e protege qualquer outra referencia tardia que ela venha a usar.
setTimeout(async function initPrinterModule() {
    try {
        await checkPrinterAgent();
    } catch (_) {}
}, 0);

// Exportar funções globais
window.checkPrinterAgent = checkPrinterAgent;
window.loadPrinters = loadPrinters;
window.loadPPDs = loadPPDs;
window.uploadPPD = uploadPPD;
window.savePrinterPPDMap = savePrinterPPDMap;
window.openPrintModal = openPrintModal;
window.openPrintModalQueue = openPrintModalQueue;
window.closePrintModal = closePrintModal;
window.reloadPrinterList = reloadPrinterList;
window.onPrintPrinterChange = onPrintPrinterChange;
window.sendPrintJob = sendPrintJob;
window.onPPDMapChange = onPPDMapChange;

// ═══════════════════════════════════════════════════════════
// PAINEL LATERAL DE DRIVER — na área de preview do pedido
// ═══════════════════════════════════════════════════════════

// Inicializa o painel de impressão lateral quando um item é selecionado
async function initPedPrintPanel() {
    const panel = document.getElementById('ped-print-driver-panel');
    if (!panel) return;

    // As pastas do hot folder sao da estacao, como as impressoras, e a tela
    // precisa delas ANTES de o produto ser aplicado: o _applyPrintConfig marca
    // o ladrilho da pasta gravada, e sem a grade desenhada nao ha o que marcar.
    // Nao segura o painel se o agente nao responder — a funcao trata sozinha.
    await carregarHotFolders();

    // Popular select de impressoras
    await _loadPrinterListIfEmpty();
    const sel = document.getElementById('ped-print-printer');
    if (!sel) return;

    const current = sel.value;
    sel.innerHTML = '<option value="">Selecione...</option>';
    if (_printerList && _printerList.length > 0) {
        _printerList.forEach(name => {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name;
            if (name === current) opt.selected = true;
            sel.appendChild(opt);
        });
        // Se só há uma impressora, selecionar automaticamente
        if (_printerList.length === 1 && !current) {
            sel.value = _printerList[0];
            await onPedPrinterChange();
        }
        // Se havia uma seleção anterior, manter e recarregar opções
        else if (current && _printerList.includes(current)) {
            await onPedPrinterChange();
        }
    }
}

// Recarregar lista de impressoras no painel lateral
async function reloadPedPrinterList() {
    _printerList = [];
    const btn = document.getElementById('ped-print-reload-btn');
    if (btn) btn.style.animation = 'spin 0.6s linear';
    await _loadPrinterListIfEmpty();
    await initPedPrintPanel();
    if (btn) btn.style.animation = '';

    const statusEl = document.getElementById('ped-driver-status');
    if (statusEl) {
        statusEl.textContent = `✓ ${_printerList.length} impressora(s) detectada(s)`;
        statusEl.style.display = 'block';
        statusEl.style.background = 'rgba(34,197,94,0.1)';
        statusEl.style.border = '1px solid rgba(34,197,94,0.2)';
        statusEl.style.color = '#4ade80';
        setTimeout(() => { statusEl.style.display = 'none'; }, 3000);
    }
}

// ──── Gerenciamento de Cores (perfil ICC por impressora) ────────────────────
// O perfil e do EQUIPAMENTO: escolhido uma vez, vale para todo pedido que va
// para aquela impressora. O mapa vive no agente da estacao
// (printer_icc_map.json), ao lado do mapa de PPDs.

let _corPerfisCache = null;

async function carregarCorImpressora(printerName) {
    const selPerfil = document.getElementById('ped-print-cor-perfil');
    const selIntento = document.getElementById('ped-print-cor-intento');
    const chkAtivo = document.getElementById('ped-print-cor-ativo');
    if (!selPerfil || !printerName) return;
    try {
        // 127.0.0.1 e nao caminho relativo: o mapa e os perfis vivem no AGENTE
        // (`printer_icc_map.json`), como diz o comentario acima deste bloco. Com
        // caminho relativo, o painel aberto pela Vercel perguntava ao servidor
        // da nuvem — que tinha outro disco, e efemero. O seletor vinha vazio, e o
        // que fosse salvo ali sumia na publicacao seguinte, sem erro na tela.
        //
        // Aquele servidor saiu do ar em 17/08/2026, e hoje o caminho relativo nao
        // chega a lugar nenhum: o sintoma seria seletor vazio direto.
        //
        // E o MESMO desvio que ja tinha sido corrigido em `carregarCapacidades`
        // e no mapa de PPDs; este bloco ficou para tras.
        const [perfis, mapa] = await Promise.all([
            fetch(`${AGENTE_LOCAL_URL}/api/icc`).then(r => r.json()),
            fetch(`${AGENTE_LOCAL_URL}/api/printers/icc-map`).then(r => r.json())
        ]);
        _corPerfisCache = perfis;
        selPerfil.innerHTML = '<option value="">— sem perfil —</option>' +
            perfis.map(p => p.erro
                ? `<option value="${p.filename}" disabled>${p.filename} (inválido)</option>`
                : `<option value="${p.filename}">${p.nome} (${p.classe})</option>`
            ).join('');
        const cfg = (mapa && mapa[printerName]) || {};
        selPerfil.value = cfg.perfil || '';
        if (selPerfil.value !== (cfg.perfil || '')) selPerfil.value = '';
        selIntento.value = cfg.intento || 'relativo';
        chkAtivo.checked = cfg.ativo === true;
        _corAjustes = cfg.ajustes && cfg.ajustes.curvas ? cfg.ajustes : AJUSTES_NEUTROS();
        _refletirAjustesNaTela();
        atualizarStatusCor();
    } catch (e) {
        console.warn('[cores] Falha ao carregar perfis ICC:', e);
    }
}

/* O `alternarGerenciamentoDeCores` saiu em 28/08/2026.
 *
 * Ele abria e fechava um bloco DENTRO da caixa de cores, por um botao
 * "Mostrar" proprio. Com a janela de visualizacao reorganizada em grupos, o
 * Gerenciamento de Cores virou um dos quatro grupos da coluna direita — e o
 * grupo ja abre e fecha sozinho. Eram dois interruptores para a mesma coisa.
 *
 * O que ele protegia continua protegido, e agora pelo `atualizarStatusCor`: o
 * ESTADO nao se esconde com os controles. O selo `#ped-cor-selo-ativo` fica no
 * botao do grupo, visivel com o grupo fechado, dizendo que ha conversao de cor
 * ligada e qual perfil. Sem isso o operador imprimiria com um perfil valendo
 * sem nada na tela dizendo isso, e so descobriria olhando o papel. */




function atualizarStatusCor() {
    const st = document.getElementById('ped-print-cor-status');
    const chkAtivo = document.getElementById('ped-print-cor-ativo');
    const selPerfil = document.getElementById('ped-print-cor-perfil');

    // O ESTADO TEM DE APARECER COM O GRUPO FECHADO.
    //
    // Esconder o seletor de perfil e os deslizadores e economia de tela;
    // esconder o fato de haver conversao de cor LIGADA seria outra coisa: o
    // operador imprimiria com um perfil valendo sem nada na tela dizendo isso,
    // e so descobriria olhando o papel. Este selo mora no botao do grupo, que
    // continua visivel com o grupo fechado.
    const selo = document.getElementById('ped-cor-selo-ativo');
    if (selo) {
        const ligado = chkAtivo?.checked === true;
        selo.style.display = ligado ? 'inline-block' : 'none';
        if (ligado) {
            const p = (_corPerfisCache || []).find(x => x.filename === selPerfil?.value);
            selo.textContent = p ? p.nome : 'ativo';
        }
    }

    if (!st) return;
    const temAjustes = typeof _ajustesSaoNeutros === 'function' && !_ajustesSaoNeutros(_corAjustes);
    if (!chkAtivo?.checked) {
        st.textContent = 'Desligado: a impressão sai sem conversão de cores nem ajustes, como sempre saiu.';
    } else if (!selPerfil?.value) {
        st.textContent = temAjustes
            ? 'Sem perfil, mas os ajustes de cor valem nas impressões desta impressora.'
            : 'Ligado, mas sem perfil nem ajustes: nada muda na impressão até configurar algo.';
    } else {
        const p = (_corPerfisCache || []).find(x => x.filename === selPerfil.value);
        st.textContent = `As cores desta impressora serão convertidas para "${p ? p.nome : selPerfil.value}"` +
            (p && p.classe ? ` (${p.classe})` : '') +
            (temAjustes ? ', com os ajustes de cor aplicados antes.' : ' na hora de imprimir.');
    }

    // A frase inteira vai para o selo do grupo fechado: quem passa o mouse le
    // o mesmo que leria abrindo o grupo.
    if (selo) selo.title = st.textContent;
}

async function salvarCorImpressora() {
    const printerName = document.getElementById('ped-print-printer')?.value;
    if (!printerName) return;
    try {
        const mapa = await fetch(`${AGENTE_LOCAL_URL}/api/printers/icc-map`).then(r => r.json()) || {};
        mapa[printerName] = {
            perfil: document.getElementById('ped-print-cor-perfil')?.value || '',
            intento: document.getElementById('ped-print-cor-intento')?.value || 'relativo',
            ativo: document.getElementById('ped-print-cor-ativo')?.checked === true,
            ajustes: _corAjustes
        };
        await fetch(`${AGENTE_LOCAL_URL}/api/printers/icc-map`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(mapa)
        });
        atualizarStatusCor();
    } catch (e) {
        console.warn('[cores] Falha ao salvar config de cor:', e);
    }
}

async function enviarPerfilIcc(input) {
    const file = input.files && input.files[0];
    if (!file) return;
    const fd = new FormData();
    fd.append('file', file);
    try {
        const res = await fetch(`${AGENTE_LOCAL_URL}/api/icc/upload`, { method: 'POST', body: fd });
        const corpo = await res.json().catch(() => ({}));
        if (!res.ok) {
            alert('Perfil recusado: ' + (corpo.detail || 'arquivo inválido.'));
            return;
        }
        const printerName = document.getElementById('ped-print-printer')?.value;
        await carregarCorImpressora(printerName);
        const selPerfil = document.getElementById('ped-print-cor-perfil');
        if (selPerfil) { selPerfil.value = corpo.perfil.filename; }
        await salvarCorImpressora();
    } catch (e) {
        alert('Falha ao enviar o perfil: ' + e);
    } finally {
        input.value = '';
    }
}

// ──── Ajustes de cor (saturacao, brilho, contraste, curvas) ─────────────────
// A matematica daqui ESPELHA a do aplicar_ajustes() do color_profiles.py:
// ordem saturacao -> brilho -> contraste -> curvas (master, depois canal),
// interpolacao LINEAR nas curvas. Mudou la, muda aqui — senao a previa mente.

const CURVA_NEUTRA = () => [[0, 0], [255, 255]];
const AJUSTES_NEUTROS = () => ({
    saturacao: 100, brilho: 0, contraste: 0,
    curvas: { master: CURVA_NEUTRA(), r: CURVA_NEUTRA(), g: CURVA_NEUTRA(), b: CURVA_NEUTRA() }
});

let _corAjustes = AJUSTES_NEUTROS();
let _corCanalAtivo = 'master';
let _corSaveTimer = null;

function _lutCurvaJS(pontos) {
    const pts = (pontos && pontos.length ? pontos : CURVA_NEUTRA())
        .map(([x, y]) => [Math.max(0, Math.min(255, Math.round(x))), Math.max(0, Math.min(255, Math.round(y)))])
        .sort((a, b) => a[0] - b[0]);
    const lut = new Array(256);
    for (let v = 0; v < 256; v++) {
        if (v <= pts[0][0]) { lut[v] = pts[0][1]; continue; }
        if (v >= pts[pts.length - 1][0]) { lut[v] = pts[pts.length - 1][1]; continue; }
        for (let i = 0; i < pts.length - 1; i++) {
            const [x0, y0] = pts[i], [x1, y1] = pts[i + 1];
            if (v >= x0 && v <= x1) {
                lut[v] = x1 === x0 ? y1 : Math.round(y0 + (v - x0) * (y1 - y0) / (x1 - x0));
                break;
            }
        }
    }
    return lut;
}

function _ajustesSaoNeutros(a) {
    if (!a) return true;
    if ((a.saturacao ?? 100) !== 100 || (a.brilho ?? 0) !== 0 || (a.contraste ?? 0) !== 0) return false;
    for (const canal of ['master', 'r', 'g', 'b']) {
        const lut = _lutCurvaJS(a.curvas?.[canal]);
        for (let v = 0; v < 256; v++) if (lut[v] !== v) return false;
    }
    return true;
}

function aplicarAjustesImageData(data, a) {
    // data: Uint8ClampedArray RGBA. Mesma ordem do Python.
    const sat = (a.saturacao ?? 100) / 100;
    const brilho = (a.brilho ?? 0) * 1.28;
    const k = ((a.contraste ?? 0) + 100) / 100;
    const lutM = _lutCurvaJS(a.curvas?.master);
    const lutR = _lutCurvaJS(a.curvas?.r), lutG = _lutCurvaJS(a.curvas?.g), lutB = _lutCurvaJS(a.curvas?.b);
    const bc = v => Math.max(0, Math.min(255, Math.round((v + brilho - 128) * k + 128)));
    for (let i = 0; i < data.length; i += 4) {
        let r = data[i], g = data[i + 1], b = data[i + 2];
        if (sat !== 1) {
            const luma = 0.299 * r + 0.587 * g + 0.114 * b;
            r = Math.max(0, Math.min(255, Math.round(luma + (r - luma) * sat)));
            g = Math.max(0, Math.min(255, Math.round(luma + (g - luma) * sat)));
            b = Math.max(0, Math.min(255, Math.round(luma + (b - luma) * sat)));
        }
        data[i]     = lutR[lutM[bc(r)]];
        data[i + 1] = lutG[lutM[bc(g)]];
        data[i + 2] = lutB[lutM[bc(b)]];
    }
}

// ─── faixa de teste da previa ───
function _desenharFaixaTeste(ctx, w, h) {
    // metade de cima: gradiente de cinza; metade de baixo: cores e tons de pele
    const grad = ctx.createLinearGradient(0, 0, w, 0);
    grad.addColorStop(0, '#000'); grad.addColorStop(1, '#fff');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h / 2);
    const cores = ['#ef4444', '#22c55e', '#3b82f6', '#06b6d4', '#d946ef', '#eab308', '#f1c27d', '#8d5524'];
    const pw = w / cores.length;
    cores.forEach((c, i) => { ctx.fillStyle = c; ctx.fillRect(i * pw, h / 2, pw + 1, h / 2); });
}

function desenharPreviaCor() {
    const antes = document.getElementById('ped-cor-previa-antes');
    const depois = document.getElementById('ped-cor-previa-depois');
    if (!antes || !depois) return;
    const ctxA = antes.getContext('2d');
    _desenharFaixaTeste(ctxA, antes.width, antes.height);
    const ctxD = depois.getContext('2d');
    _desenharFaixaTeste(ctxD, depois.width, depois.height);
    const img = ctxD.getImageData(0, 0, depois.width, depois.height);
    aplicarAjustesImageData(img.data, _corAjustes);
    ctxD.putImageData(img, 0, 0);
}

// ─── editor de curvas ───
const _CANAL_COR = { master: '#f1f5f9', r: '#f87171', g: '#4ade80', b: '#60a5fa' };
let _curvaArrastando = -1;

function desenharCurvaCor() {
    const cv = document.getElementById('ped-cor-curva-canvas');
    if (!cv) return;
    const ctx = cv.getContext('2d');
    const W = cv.width, H = cv.height;
    ctx.clearRect(0, 0, W, H);
    // grade nos quartos
    ctx.strokeStyle = 'rgba(255,255,255,0.07)';
    ctx.lineWidth = 1;
    for (let q = 1; q < 4; q++) {
        ctx.beginPath(); ctx.moveTo(W * q / 4, 0); ctx.lineTo(W * q / 4, H); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, H * q / 4); ctx.lineTo(W, H * q / 4); ctx.stroke();
    }
    // diagonal neutra de referencia
    ctx.strokeStyle = 'rgba(255,255,255,0.12)';
    ctx.setLineDash([3, 3]);
    ctx.beginPath(); ctx.moveTo(0, H); ctx.lineTo(W, 0); ctx.stroke();
    ctx.setLineDash([]);
    // curva do canal ativo
    const lut = _lutCurvaJS(_corAjustes.curvas[_corCanalAtivo]);
    ctx.strokeStyle = _CANAL_COR[_corCanalAtivo];
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    for (let v = 0; v < 256; v++) {
        const x = v / 255 * W, y = H - lut[v] / 255 * H;
        v === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.stroke();
    // pontos
    for (const [px, py] of _corAjustes.curvas[_corCanalAtivo]) {
        ctx.fillStyle = _CANAL_COR[_corCanalAtivo];
        ctx.beginPath();
        ctx.arc(px / 255 * W, H - py / 255 * H, 4, 0, Math.PI * 2);
        ctx.fill();
    }
}

function trocarCanalCurva(canal) {
    _corCanalAtivo = canal;
    for (const c of ['master', 'r', 'g', 'b']) {
        const btn = document.getElementById('ped-cor-canal-' + c);
        if (btn) btn.style.background = c === canal ? 'rgba(255,255,255,0.12)' : 'transparent';
    }
    desenharCurvaCor();
}

function _curvaPontoDoEvento(cv, ev) {
    const rect = cv.getBoundingClientRect();
    const x = Math.max(0, Math.min(255, Math.round((ev.clientX - rect.left) / rect.width * 255)));
    const y = Math.max(0, Math.min(255, Math.round((1 - (ev.clientY - rect.top) / rect.height) * 255)));
    return [x, y];
}

function _instalarEditorCurvas() {
    const cv = document.getElementById('ped-cor-curva-canvas');
    if (!cv || cv._curvaInstalada) return;
    cv._curvaInstalada = true;

    cv.addEventListener('mousedown', ev => {
        const [x, y] = _curvaPontoDoEvento(cv, ev);
        const pontos = _corAjustes.curvas[_corCanalAtivo];
        let idx = pontos.findIndex(([px, py]) => Math.abs(px - x) < 12 && Math.abs(py - y) < 12);
        if (idx === -1) {
            pontos.push([x, y]);
            pontos.sort((a, b) => a[0] - b[0]);
            idx = pontos.findIndex(([px]) => px === x);
        }
        _curvaArrastando = idx;
    });
    cv.addEventListener('mousemove', ev => {
        if (_curvaArrastando === -1) return;
        const [x, y] = _curvaPontoDoEvento(cv, ev);
        const pontos = _corAjustes.curvas[_corCanalAtivo];
        pontos[_curvaArrastando] = [x, y];
        desenharCurvaCor();
    });
    const soltar = () => {
        if (_curvaArrastando === -1) return;
        _curvaArrastando = -1;
        _corAjustes.curvas[_corCanalAtivo].sort((a, b) => a[0] - b[0]);
        desenharCurvaCor();
        desenharPreviaCor();
        agendarSalvarAjustesCor();
    };
    cv.addEventListener('mouseup', soltar);
    cv.addEventListener('mouseleave', soltar);
    cv.addEventListener('dblclick', ev => {
        const [x, y] = _curvaPontoDoEvento(cv, ev);
        const pontos = _corAjustes.curvas[_corCanalAtivo];
        if (pontos.length <= 2) return;   // uma curva precisa de 2 pontos
        const idx = pontos.findIndex(([px, py]) => Math.abs(px - x) < 12 && Math.abs(py - y) < 12);
        if (idx !== -1) {
            pontos.splice(idx, 1);
            desenharCurvaCor();
            desenharPreviaCor();
            agendarSalvarAjustesCor();
        }
    });
}

// ─── sliders, estado e persistencia ───
function _lerSlidersAjustes() {
    _corAjustes.saturacao = parseInt(document.getElementById('ped-cor-saturacao')?.value ?? 100);
    _corAjustes.brilho = parseInt(document.getElementById('ped-cor-brilho')?.value ?? 0);
    _corAjustes.contraste = parseInt(document.getElementById('ped-cor-contraste')?.value ?? 0);
}

function _refletirAjustesNaTela() {
    const s = document.getElementById('ped-cor-saturacao');
    const b = document.getElementById('ped-cor-brilho');
    const c = document.getElementById('ped-cor-contraste');
    if (s) { s.value = _corAjustes.saturacao; document.getElementById('ped-cor-saturacao-val').textContent = _corAjustes.saturacao; }
    if (b) { b.value = _corAjustes.brilho; document.getElementById('ped-cor-brilho-val').textContent = _corAjustes.brilho; }
    if (c) { c.value = _corAjustes.contraste; document.getElementById('ped-cor-contraste-val').textContent = _corAjustes.contraste; }
    _instalarEditorCurvas();
    trocarCanalCurva(_corCanalAtivo);
    desenharPreviaCor();
}

function onAjusteCorInput() {
    _lerSlidersAjustes();
    document.getElementById('ped-cor-saturacao-val').textContent = _corAjustes.saturacao;
    document.getElementById('ped-cor-brilho-val').textContent = _corAjustes.brilho;
    document.getElementById('ped-cor-contraste-val').textContent = _corAjustes.contraste;
    desenharPreviaCor();
    agendarSalvarAjustesCor();
}

function resetarAjustesCor() {
    _corAjustes = AJUSTES_NEUTROS();
    _refletirAjustesNaTela();
    agendarSalvarAjustesCor();
}

function agendarSalvarAjustesCor() {
    // debounce: arrastar um slider dispara dezenas de eventos por segundo
    clearTimeout(_corSaveTimer);
    _corSaveTimer = setTimeout(() => salvarCorImpressora(), 400);
}

// Ao mudar impressora no painel lateral → carregar opções do driver
async function onPedPrinterChange() {
    const sel = document.getElementById('ped-print-printer');
    const optDiv = document.getElementById('ped-driver-options');
    const loadDiv = document.getElementById('ped-driver-loading');
    const hintDiv = document.getElementById('ped-driver-hint');
    const statusEl = document.getElementById('ped-driver-status');

    const printerName = sel ? sel.value : '';

    // O Gerenciamento de Cores virou um grupo proprio da janela, fora da
    // Configuracao de Impressao. Como os ajustes sao da IMPRESSORA e nao do
    // pedido, sem impressora escolhida o grupo precisa dizer isso e para onde
    // ir — senao ele abriria com os controles vazios, sem explicacao.
    const semImpressora = document.getElementById('ped-cor-sem-impressora');
    const caixaDeCor = document.getElementById('ped-print-cor-box');

    if (!printerName) {
        if (optDiv) optDiv.style.display = 'none';
        if (hintDiv) hintDiv.style.display = 'flex';
        if (statusEl) statusEl.style.display = 'none';
        if (semImpressora) semImpressora.style.display = 'block';
        if (caixaDeCor) caixaDeCor.style.display = 'none';
        return;
    }

    if (semImpressora) semImpressora.style.display = 'none';
    if (caixaDeCor) caixaDeCor.style.display = 'flex';
    if (hintDiv) hintDiv.style.display = 'none';
    if (loadDiv) loadDiv.style.display = 'block';
    if (optDiv) optDiv.style.display = 'none';

    // Config de cor e independente das capacidades do driver: carrega em paralelo
    carregarCorImpressora(printerName);

    // Buscar capacidades
    let caps = null;
    if (window._activeAgentData?.printers_json?.capabilities) {
        caps = window._activeAgentData.printers_json.capabilities[printerName];
    }
    if (!caps) {
        try {
            // Sempre usar o hostname atual na porta 9000
            const apiBase = AGENTE_LOCAL_URL;   // 127.0.0.1: o hostname da pagina apontava para a Vercel
            const url = `${apiBase}/api/printers/${encodeURIComponent(printerName)}/capabilities`;
            console.log('[PedDriverPanel] Buscando capacidades:', url);
            const res = await fetch(url);
            if (res.ok) {
                caps = await res.json();
                console.log('[PedDriverPanel] Capacidades recebidas:', caps);
            } else {
                console.warn('[PedDriverPanel] Resposta não-OK:', res.status, res.statusText);
            }
        } catch (e) {
            console.warn('[PedDriverPanel] Erro ao buscar capacidades do driver:', e.message);
        }
    }
    if (!caps) {
        caps = {
            duplex_supported: true,
            papers: [{id: 9, name: 'A4'}, {id: 8, name: 'A3'}],
            trays: [{id: 7, name: 'Auto'}],
            defaults: { duplex: 1, paper_size: 9, tray: 7, color: 2, copies: 1 }
        };
    }

    if (loadDiv) loadDiv.style.display = 'none';
    if (optDiv) optDiv.style.display = 'flex';

    const defaultTray = caps.defaults?.tray ?? 7;
    const defaultPaper = caps.defaults?.paper_size ?? 9;
    const defaultDuplex = caps.defaults?.duplex ?? 1;
    const defaultColor = caps.defaults?.color ?? 2;
    const defaultCopies = caps.defaults?.copies ?? 1;

    // Detectar se o formato ativo tem "Gerar Capa e Contracapa"
    const fmtId = document.getElementById('ped-formato')?.value;
    const fmtObj = fmtId ? (state.formatos || []).find(f => String(f.id) === String(fmtId)) : null;
    const hasCover = fmtObj?.has_cover === true;

    const traySingle = document.getElementById('ped-tray-single');
    const trayDual = document.getElementById('ped-tray-dual');
    if (traySingle) traySingle.style.display = hasCover ? 'none' : 'block';
    if (trayDual) trayDual.style.display = hasCover ? 'block' : 'none';

    const trayOptionsHtml = (caps.trays?.length
        ? caps.trays.map(t => `<option value="${t.id}" ${t.id === defaultTray ? 'selected' : ''}>${t.name}</option>`)
        : ['<option value="7" selected>Auto</option>']
    ).join('');

    const traySel = document.getElementById('ped-print-tray');
    if (traySel) traySel.innerHTML = trayOptionsHtml;

    // Popular bandejas duplas com as mesmas opções
    const trayCapaSel = document.getElementById('ped-print-tray-capa');
    const trayMioloSel = document.getElementById('ped-print-tray-miolo');
    if (trayCapaSel) trayCapaSel.innerHTML = trayOptionsHtml;
    if (trayMioloSel) trayMioloSel.innerHTML = trayOptionsHtml;

    const paperSel = document.getElementById('ped-print-paper');
    if (paperSel) {
        paperSel.innerHTML = (caps.papers?.length
            ? caps.papers.map(p => `<option value="${p.id}" ${p.id === defaultPaper ? 'selected' : ''}>${p.name}</option>`)
            : ['<option value="9" selected>A4</option>', '<option value="8">A3</option>']
        ).join('');
    }

    const duplexSel = document.getElementById('ped-print-duplex');
    if (duplexSel) {
        duplexSel.disabled = false;
        const isJobDuplex = temVerso(state.printMode) || (state.activeOSItem && !!state.activeOSItem.verso);
        const targetDuplex = isJobDuplex ? 2 : (defaultDuplex || 1);
        duplexSel.value = String(targetDuplex);
    }

    const colorSel = document.getElementById('ped-print-color');
    if (colorSel) {
        colorSel.querySelectorAll('option').forEach(opt => {
            opt.selected = parseInt(opt.value) === defaultColor;
        });
    }

    const copiesInput = document.getElementById('ped-print-copies');
    if (copiesInput) copiesInput.value = defaultCopies;

    // Status do driver
    if (statusEl) {
        const hasRealData = caps.papers?.length > 0 || caps.trays?.length > 0;
        if (hasRealData) {
            statusEl.textContent = `✓ ${caps.papers?.length || 0} papel(is), ${caps.trays?.length || 0} bandeja(s)`;
            statusEl.style.background = 'rgba(34,197,94,0.1)';
            statusEl.style.border = '1px solid rgba(34,197,94,0.2)';
            statusEl.style.color = '#4ade80';
        } else {
            statusEl.textContent = '⚠ Opções padrão';
            statusEl.style.background = 'rgba(251,191,36,0.1)';
            statusEl.style.border = '1px solid rgba(251,191,36,0.2)';
            statusEl.style.color = '#fbbf24';
        }
        statusEl.style.display = 'block';
    }
}

// Retorna as opções configuradas no painel lateral para uso direto no sendPrintJob
// ═══════════════════════════════════════════════════════════════════════
// HOT FOLDER
// ═══════════════════════════════════════════════════════════════════════
// A Epson SureColor F9470H nao recebe trabalho pela fila do Windows: quem a
// conduz e o RIP Epson Edge Print, que observa uma pasta, importa o PDF que
// aparece ali e aplica a ele o preset daquela pasta. Marcada a caixa, o material
// imposto e gravado na pasta em vez de ir para a impressora.

// O estado do hot folder e' UMA coisa so': ha' pasta escolhida, ou nao ha'.
// Ate 29/08/2026 eram duas — uma caixa "ativar" e um caminho —, e elas podiam
// discordar: caixa marcada sem pasta chegava ate o botao Imprimir para ser
// barrada la'. Escolher a pasta E' ativar; tirar a escolha E' desligar.
function _hotFolderAtivo() {
    return _hotFolderPath() !== '';
}

function _hotFolderPath() {
    return (document.getElementById('ped-hotfolder-path')?.value || '').trim();
}

function _hotFolderStatus(html, tipo) {
    const el = document.getElementById('ped-hotfolder-status');
    if (!el) return;
    if (!html) { el.style.display = 'none'; return; }
    const cores = {
        ok:    ['rgba(34,197,94,0.1)',  'rgba(34,197,94,0.25)',  '#4ade80'],
        aviso: ['rgba(245,158,11,0.1)', 'rgba(245,158,11,0.28)', '#fbbf24'],
        erro:  ['rgba(239,68,68,0.1)',  'rgba(239,68,68,0.28)',  '#f87171'],
    };
    const [bg, borda, cor] = cores[tipo] || cores.aviso;
    el.style.background = bg;
    el.style.border = `1px solid ${borda}`;
    el.style.color = cor;
    el.innerHTML = html;
    el.style.display = 'block';
}

// ── Os ladrilhos ────────────────────────────────────────────────────────────
// A lista de pastas autorizadas sempre existiu na estacao (hot_folders.json),
// mas era invisivel: cada trabalho recomecava do seletor nativo do Windows, e o
// operador tinha de reencontrar no disco uma pasta que a maquina ja conhecia.
// Agora ela vira ladrilho, com o nome da pasta e uma cor.

let _hotFoldersDaEstacao = [];      // o que o agente respondeu
let _hotFoldersCarregando = false;

/** O nome curto: o ultimo trecho do caminho, que e' o que distingue as pastas. */
function _nomeDaPasta(caminho) {
    const c = String(caminho || '').trim().replace(/[\\/]+$/, '');
    if (!c) return '';
    const partes = c.split(/[\\/]/);
    return partes[partes.length - 1] || c;
}

/**
 * A cor do ladrilho, tirada do PROPRIO caminho.
 *
 * Deliberadamente derivada, e nao escolhida: cor guardada seria mais um campo
 * para alguem preencher, mais uma tela para edita-lo, e um valor a menos que a
 * estacao consegue responder sozinha. Derivada, a mesma pasta tem sempre a
 * mesma cor — hoje, amanha e na estacao do lado — e e' isso que faz o operador
 * reconhecer o ladrilho sem ler.
 *
 * As 12 matizes sao espacadas de 30 graus para nao nascerem duas cores que so
 * um colorimetro distingue.
 */
function _corDaPasta(caminho) {
    const c = String(caminho || '').toLowerCase();
    let h = 0;
    for (let i = 0; i < c.length; i++) h = ((h << 5) - h + c.charCodeAt(i)) | 0;
    const matiz = (Math.abs(h) % 12) * 30;
    return {
        forte: `hsl(${matiz}, 70%, 58%)`,
        fraca: `hsla(${matiz}, 70%, 58%, 0.14)`,
        borda: `hsla(${matiz}, 70%, 58%, 0.45)`,
    };
}

async function carregarHotFolders({ redesenhar = true } = {}) {
    if (_hotFoldersCarregando) return _hotFoldersDaEstacao;
    _hotFoldersCarregando = true;
    try {
        const resp = await fetch(`${AGENTE_LOCAL_URL}/api/hotfolder/listar`);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        _hotFoldersDaEstacao = Array.isArray(data.pastas) ? data.pastas : [];
    } catch (e) {
        // Agente parado ou painel fora da estacao. Nao e' erro de tela: a lista
        // fica vazia e o "cole o caminho" continua sendo a saida.
        console.warn('[hotFolder] nao consegui listar as pastas da estacao:', e);
        _hotFoldersDaEstacao = [];
    } finally {
        _hotFoldersCarregando = false;
    }
    if (redesenhar) desenharGradeHotFolders();
    return _hotFoldersDaEstacao;
}
window.carregarHotFolders = carregarHotFolders;

/**
 * O desenho da pasta, em SVG.
 *
 * NAO e' o emoji 📁, e a diferenca e' o recurso inteiro: o emoji vem colorido
 * pela fonte do sistema, ignora `color` e ignora `filter` — as pastas sairiam
 * todas do mesmo amarelo, e "icones de pastas coloridas" viraria "icones de
 * pastas iguais". O SVG pinta com `currentColor`, entao a cor do ladrilho
 * chega mesmo ao desenho.
 */
function _svgDaPasta() {
    return '<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true">'
         + '<path fill="currentColor" d="M10 4H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-8l-2-2z"/>'
         + '</svg>';
}

/** A mesma pasta, com um x — a que a estacao nao acha agora. */
function _svgDaPastaSumida() {
    return '<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true">'
         + '<path fill="currentColor" opacity="0.55" d="M10 4H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-8l-2-2z"/>'
         + '<path stroke="currentColor" stroke-width="2.2" stroke-linecap="round" d="M9 11l6 6M15 11l-6 6"/>'
         + '</svg>';
}

/** Dois caminhos apontam para a mesma pasta? Espelha hotfolder.normalizar(). */
function _mesmaPasta(a, b) {
    const n = s => String(s || '').trim().replace(/[\\/]+$/, '').replace(/\//g, '\\').toLowerCase();
    const na = n(a);
    return na !== '' && na === n(b);
}

/**
 * Desenha os ladrilhos.
 *
 * A pasta gravada para o produto entra na grade mesmo que o agente nao a tenha
 * listado (estacao trocada, agente parado): esconder o ladrilho da pasta que
 * ESTA valendo faria a tela mentir sobre o que vai acontecer ao imprimir.
 */
function desenharGradeHotFolders() {
    const grade = document.getElementById('ped-hotfolder-grade');
    if (!grade) return;

    const escolhida = _hotFolderPath();
    const lista = _hotFoldersDaEstacao.slice();
    if (escolhida && !lista.some(p => _mesmaPasta(p.path, escolhida))) {
        lista.unshift({ path: escolhida, nome: _nomeDaPasta(escolhida), existe: true });
    }

    const esc = s => (typeof escapeHtml === 'function')
        ? escapeHtml(String(s == null ? '' : s))
        : String(s == null ? '' : s).replace(/[&<>"']/g, c => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    // O caminho vai para dentro de um atributo onclick com aspas simples: a
    // contrabarra do Windows precisa ser dobrada, senao "C:\novo" vira quebra de
    // linha dentro do JavaScript e o ladrilho nasce morto.
    const arg = s => String(s == null ? '' : s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");

    const partes = lista.map(p => {
        const cor = _corDaPasta(p.path);
        const sel = _mesmaPasta(p.path, escolhida);
        const sumiu = p.existe === false;
        const nome = esc(p.nome || _nomeDaPasta(p.path));
        const dica = esc(p.path) + (sumiu ? ' — a pasta nao esta acessivel agora' : '');
        const a = arg(p.path);
        return `
            <div class="hf-ladrilho${sel ? ' hf-sel' : ''}${sumiu ? ' hf-sumiu' : ''}"
                 style="--hf-forte:${cor.forte};--hf-fraca:${cor.fraca};--hf-borda:${cor.borda};"
                 title="${dica}" role="button" tabindex="0"
                 onclick="escolherHotFolderDaGrade('${a}')"
                 onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();escolherHotFolderDaGrade('${a}');}">
                <span class="hf-icone">${sumiu ? _svgDaPastaSumida() : _svgDaPasta()}</span>
                <span class="hf-nome">${nome}</span>
                <button type="button" class="hf-tirar" title="Tirar esta pasta da lista desta estacao"
                        onclick="event.stopPropagation(); esquecerHotFolder('${a}')">&times;</button>
            </div>`;
    });

    partes.push(`
        <div class="hf-ladrilho hf-add" role="button" tabindex="0"
             title="Abrir o seletor de pastas nesta estacao"
             onclick="escolherHotFolder()"
             onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();escolherHotFolder();}">
            <span class="hf-icone">&#43;</span>
            <span class="hf-nome">Adicionar pasta&hellip;</span>
        </div>`);

    grade.innerHTML = partes.join('');
}
window.desenharGradeHotFolders = desenharGradeHotFolders;

/**
 * Clicar num ladrilho: escolhe aquela pasta — e escolher E' ativar.
 * Clicar no ladrilho ja escolhido desfaz e devolve o trabalho a impressora.
 */
function escolherHotFolderDaGrade(caminho) {
    const campo = document.getElementById('ped-hotfolder-path');
    if (!campo) return;

    if (_mesmaPasta(caminho, _hotFolderPath())) {
        campo.value = '';
        _hotFolderStatus('', null);
    } else {
        campo.value = caminho;
        const p = _hotFoldersDaEstacao.find(x => _mesmaPasta(x.path, caminho));
        const cam = (typeof escapeHtml === 'function') ? escapeHtml(caminho) : caminho;
        if (p && p.existe === false) {
            _hotFolderStatus(
                `&#9888; A pasta <code>${cam}</code> nao esta acessivel agora. ` +
                `O envio vai falhar enquanto ela nao voltar.`, 'erro');
        } else {
            _hotFolderStatus(`&#10003; Sai para <code>${cam}</code>`, 'ok');
        }
    }
    _aplicarEstadoHotFolder();
    desenharGradeHotFolders();
}
window.escolherHotFolderDaGrade = escolherHotFolderDaGrade;

/** Tira a pasta da lista da estacao. Nada e' apagado do disco. */
async function esquecerHotFolder(caminho) {
    const pergunta = `Tirar "${_nomeDaPasta(caminho)}" da lista desta estacao?\n\n`
        + `A pasta continua no disco — ela so deixa de aparecer aqui e perde a `
        + `autorizacao de receber material.`;
    if (!confirm(pergunta)) return;
    try {
        await fetch(`${AGENTE_LOCAL_URL}/api/hotfolder/esquecer`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ path: caminho })
        });
    } catch (e) {
        console.warn('[hotFolder] nao consegui esquecer a pasta:', e);
    }
    // Esquecida a pasta que estava escolhida, o trabalho volta para a impressora.
    if (_mesmaPasta(caminho, _hotFolderPath())) {
        const campo = document.getElementById('ped-hotfolder-path');
        if (campo) campo.value = '';
        _hotFolderStatus('', null);
        _aplicarEstadoHotFolder();
    }
    await carregarHotFolders();
}
window.esquecerHotFolder = esquecerHotFolder;

// Hot folder nao carrega DEVMODE: bandeja, papel, frente/verso, cor e copias sao
// do preset da pasta no RIP — e numa impressora de rolo para sublimacao metade
// desses conceitos nem existe. Deixar os campos ativos faria o operador marcar
// "Duplex" aqui, receber simplex no papel e concluir que o sistema esta errado.
//
// #ped-print-modes-box fica de fora da desabilitacao de proposito: Impressao
// Reversa e Folha a Folha sao aplicadas ao PDF pelo navegador antes do envio, e
// por isso continuam valendo.
function _aplicarEstadoHotFolder() {
    const ativo = _hotFolderAtivo();

    // O ESTADO nao se esconde com os controles: fechado o grupo, o selo continua
    // dizendo para onde o material vai. Mesma regra do Gerenciamento de Cores.
    const selo = document.getElementById('ped-hotfolder-selo');
    if (selo) {
        selo.textContent = ativo ? _nomeDaPasta(_hotFolderPath()) : '';
        selo.style.display = ativo ? 'inline-block' : 'none';
    }

    const aviso = document.getElementById('ped-hotfolder-aviso');
    if (aviso) aviso.style.display = ativo ? 'block' : 'none';

    ['ped-printer-box', 'ped-driver-options'].forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        el.style.opacity = ativo ? '0.35' : '1';
        el.querySelectorAll('select, input, button').forEach(c => { c.disabled = ativo; });
    });

    const hint = document.getElementById('ped-driver-hint');
    if (hint && ativo) hint.style.display = 'none';

    // O remendo que forcava o botao de salvar a aparecer no modo hot folder saiu
    // em 29/08/2026: o SALVAR virou rodape fixo da coluna e nao se esconde mais,
    // nem sem impressora nem sem pasta. Quem cuida do estado dele e' o
    // _updateSaveButtonLabel().
}

// O navegador nao enxerga o disco da estacao: quem abre o seletor e o agente.
// A resposta demora o tempo que o operador levar para escolher — e uma janela
// modal do Windows, aberta na maquina, nao ha como ser diferente.
async function escolherHotFolder() {
    const grade = document.getElementById('ped-hotfolder-grade');
    const add = grade ? grade.querySelector('.hf-add .hf-nome') : null;
    const rotulo = add ? add.innerHTML : '';
    if (add) add.innerHTML = 'Escolha na janela que abriu&hellip;';
    try {
        const resp = await fetch(`${AGENTE_LOCAL_URL}/api/hotfolder/escolher`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ inicial: _hotFolderPath() })
        });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        if (data.cancelado) { _hotFolderStatus('Nenhuma pasta escolhida.', 'aviso'); return; }
        if (!data.ok) throw new Error(data.detail || 'o agente recusou a pasta');
        await _definirHotFolder(data);
    } catch (e) {
        console.error('[hotFolder] seletor indisponivel:', e);
        _hotFolderStatus(
            `Não foi possível abrir o seletor nesta estação (${e.message}).<br>` +
            `Cole o caminho da pasta no campo abaixo — ele é conferido quando você sair do campo.`, 'erro');
    } finally {
        if (add) add.innerHTML = rotulo;
    }
}

// Plano B do seletor: o caminho digitado ou colado. Vale a mesma validacao —
// so pasta que existe, e pasta que aceita escrita, entra na lista da estacao.
async function adicionarHotFolderColada() {
    const campo = document.getElementById('ped-hotfolder-colar');
    const caminho = (campo?.value || '').trim();
    if (!caminho) { _hotFolderStatus('', null); return; }
    try {
        const resp = await fetch(`${AGENTE_LOCAL_URL}/api/hotfolder/validar`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ path: caminho })
        });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        if (!data.ok) { _hotFolderStatus(`✗ ${data.detail}`, 'erro'); return; }
        if (campo) campo.value = '';
        await _definirHotFolder(data);
    } catch (e) {
        _hotFolderStatus(`Não foi possível conferir a pasta: ${e.message}`, 'erro');
    }
}
window.adicionarHotFolderColada = adicionarHotFolderColada;

async function _definirHotFolder(data) {
    const campo = document.getElementById('ped-hotfolder-path');
    if (campo) campo.value = data.path;

    // Registrada no agente, ela precisa aparecer como ladrilho JA escolhido: o
    // operador acabou de apontar aquela pasta, e pedir um segundo clique para
    // confirmar o que ele acabou de fazer nao ajuda ninguem.
    _aplicarEstadoHotFolder();
    await carregarHotFolders();

    if (data.aviso_unidade_mapeada) {
        // Letra mapeada pertence a sessao do usuario. Se o agente um dia rodar
        // como servico ou sob outra conta, "Z:" nao existe para ele e o envio
        // quebra em silencio — o arquivo simplesmente nunca chega ao RIP.
        _hotFolderStatus(
            `✓ Pasta pronta: <code>${data.path}</code><br>` +
            `⚠ É uma unidade de rede mapeada. Prefira o caminho UNC ` +
            `(<code>\\\\servidor\\pasta</code>).`, 'aviso');
    } else {
        _hotFolderStatus(`✓ Pasta pronta: <code>${data.path}</code>`, 'ok');
    }
}

// O Edge Print importa o arquivo e o remove da pasta. Sobrando arquivo alguns
// segundos depois, o watcher provavelmente nao esta rodando — e, uma vez largado
// o PDF, este e o unico sinal barato de que o outro lado esta vivo.
//
// E aviso, nunca erro: ha RIP que deixa o arquivo no lugar de proposito.
function _conferirConsumoHotFolder(caminhos) {
    if (!caminhos || !caminhos.length) return;
    setTimeout(async () => {
        try {
            const resp = await fetch(`${AGENTE_LOCAL_URL}/api/hotfolder/conferir`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ paths: caminhos })
            });
            if (!resp.ok) return;
            const data = await resp.json();
            const restantes = data.restantes || [];
            if (restantes.length) {
                toast(`⚠ ${restantes.length} de ${caminhos.length} arquivo(s) continuam na ` +
                      `pasta — o RIP está rodando e observando o hot folder?`, 'warning');
            }
        } catch (e) {
            // Sem agente nao ha o que conferir, e isso nao e falha do envio.
            console.warn('[hotFolder] conferencia de consumo indisponivel:', e);
        }
    }, 12000);
}

function getPedPrintOptions() {
    const printerName = document.getElementById('ped-print-printer')?.value || '';
    const trayDual = document.getElementById('ped-tray-dual');
    const isDualTray = trayDual && trayDual.style.display !== 'none';
    const options = {
        paper_size: parseInt(document.getElementById('ped-print-paper')?.value) || 9,
        tray: parseInt(document.getElementById('ped-print-tray')?.value) || 7,
        duplex: parseInt(document.getElementById('ped-print-duplex')?.value) || 1,
        color: parseInt(document.getElementById('ped-print-color')?.value) || 2,
        copies: parseInt(document.getElementById('ped-print-copies')?.value) || 1,
        orientation: parseInt(document.getElementById('ped-print-orientation')?.value) || 1,
        print_mode: document.getElementById('ped-print-engine-mode')?.value || 'gdi',
        impressao_reversa: document.getElementById('ped-print-reverse')?.checked === true,
        folha_a_folha: document.getElementById('ped-print-sheet-by-sheet')?.checked === true
    };
    if (isDualTray) {
        options.tray_capa = parseInt(document.getElementById('ped-print-tray-capa')?.value) || options.tray;
        options.tray_miolo = parseInt(document.getElementById('ped-print-tray-miolo')?.value) || options.tray;
    }
    // No relay, este campo e o que faz o agente desviar do spooler para a pasta.
    // Ele viaja dentro do ppd_options, que ja e coluna JSON no print_queue — por
    // isso o hot folder nao exigiu coluna nova no Supabase.
    if (_hotFolderAtivo()) options.hot_folder_path = _hotFolderPath();
    return { printerName, options };
}

// Processa a fila de PDFs aplicando Impressão Reversa e/ou Folha a Folha se ativados
async function processPrintQueueOptions(queue, options) {
    if (!options || (!options.impressao_reversa && !options.folha_a_folha)) {
        return queue;
    }

    const { PDFDocument } = window.PDFLib || {};
    if (!PDFDocument) {
        console.warn('[processPrintQueueOptions] window.PDFLib.PDFDocument não disponível.');
        return queue;
    }

    const newQueue = [];

    for (let i = 0; i < queue.length; i++) {
        const item = queue[i];
        try {
            const arrayBuffer = await item.blob.arrayBuffer();
            const pdfDoc = await PDFDocument.load(arrayBuffer);
            const totalPages = pdfDoc.getPageCount();

            // Determinar a ordem das páginas (reversa: N -> 1, normal: 1 -> N)
            const pageIndices = [];
            if (options.impressao_reversa) {
                for (let p = totalPages - 1; p >= 0; p--) pageIndices.push(p);
            } else {
                for (let p = 0; p < totalPages; p++) pageIndices.push(p);
            }

            if (options.folha_a_folha) {
                // Gerar 1 arquivo PDF para cada página individualmente na ordem calculada
                const baseName = (item.name || 'documento.pdf').replace(/\.pdf$/i, '');
                for (let k = 0; k < pageIndices.length; k++) {
                    const pageIdx = pageIndices[k];
                    const singleDoc = await PDFDocument.create();
                    const [copiedPage] = await singleDoc.copyPages(pdfDoc, [pageIdx]);
                    singleDoc.addPage(copiedPage);
                    const singleBytes = await singleDoc.save();
                    const singleBlob = new Blob([singleBytes], { type: 'application/pdf' });
                    const pageNumStr = String(pageIdx + 1).padStart(3, '0');
                    newQueue.push({
                        name: `${baseName}_pag_${pageNumStr}.pdf`,
                        blob: singleBlob
                    });
                }
            } else if (options.impressao_reversa) {
                // Arquivo único contendo todas as páginas em ordem invertida
                const reverseDoc = await PDFDocument.create();
                const copiedPages = await reverseDoc.copyPages(pdfDoc, pageIndices);
                copiedPages.forEach(p => reverseDoc.addPage(p));
                const reverseBytes = await reverseDoc.save();
                const reverseBlob = new Blob([reverseBytes], { type: 'application/pdf' });
                newQueue.push({ name: item.name, blob: reverseBlob });
            } else {
                newQueue.push(item);
            }
        } catch (err) {
            console.error(`[processPrintQueueOptions] Erro ao reordenar PDF "${item.name}":`, err);
            newQueue.push(item);
        }
    }
    return newQueue;
}

// ═══════════════════════════════════════════════════════════════════════
// ENTREGAR CADA LOTE ENQUANTO O MOTOR AINDA GERA (27/08/2026)
// ═══════════════════════════════════════════════════════════════════════
//
// A tela juntava TODOS os arquivos que o streaming trazia num array e só
// chamava o envio depois que o motor terminava. Com a entrega por bloco isso
// anulava o recurso inteiro: no modelo de 14.000 células do pedido 21202 o
// motor entregava o primeiro lote em 4 s, e a impressora não recebia nada até
// a última das 1.400 folhas ficar pronta.
//
// A entrega virou um objeto de vida longa porque há estado que atravessa os
// lotes e que se perderia se cada um fosse um envio independente:
//
//  - a ORDEM do spool (`nomeParaSpool`) tem de continuar subindo de lote em
//    lote. Reiniciando em 00001 a cada lote, o watcher do hot folder — que lê
//    a pasta em ordem alfabética — embaralharia a tiragem.
//  - a pasta do lote no Storage (`loteId`), que o relay usa para achar os
//    arquivos de um mesmo trabalho.
//  - as contas do relatório final e os caminhos que o hot folder confere
//    depois.
//
// `sendPrintJobDirect` continua com a mesma assinatura, agora escrito em cima
// disto — os caminhos que já têm a fila inteira na mão (o fallback sem
// streaming, o modal) não mudaram de comportamento.
function criarEntregaDeImpressao({ total = null } = {}) {
    const { printerName, options } = getPedPrintOptions();
    const hotFolder = options.hot_folder_path || '';

    if (_hotFolderAtivo() && !hotFolder) {
        toast('HOT FOLDER está marcado, mas nenhuma pasta foi escolhida.', 'error');
        return null;
    }
    if (!hotFolder && !printerName) {
        toast('Selecione uma impressora no painel de configuração de impressão.', 'error');
        return null;
    }

    const btnCancelPed = document.getElementById('ped-btn-cancel-print');
    if (btnCancelPed) btnCancelPed.style.display = 'inline-flex';
    const btnImpose = document.getElementById('ped-btn-impose');
    if (btnImpose) btnImpose.style.display = 'none';
    const btnImposePrint = document.getElementById('ped-btn-impose-print');
    if (btnImposePrint) btnImposePrint.style.display = 'none';

    window.isPrinting = true;

    const isLocalMode = !window._activeAgentData ||
        window.location.hostname === 'localhost' ||
        window.location.hostname === '127.0.0.1';

    const loteId = Date.now();   // pasta do lote no Storage (so o relay usa)
    const caminhosSoltos = [];   // hot folder: o que conferir depois
    let ordem = 0;               // prefixo do spool, continuo no trabalho inteiro
    let successCount = 0;
    let failCount = 0;
    let cancelado = false;
    let encerrada = false;
    let avisouTransformacao = false;

    async function enviarUm(item) {
        ordem++;
        toast(total
            ? `Enviando ${ordem}/${total}: ${item.name}...`
            : `Enviando ${ordem}: ${item.name}...`, 'info');

        // Determinar bandeja correta baseado no tipo de arquivo (capa/miolo)
        let itemOptions = { ...options };
        if (options.tray_capa && options.tray_miolo) {
            const nameLower = (item.name || '').toLowerCase();
            if (nameLower.includes('_capa') || nameLower.includes('_contracapa')) {
                itemOptions.tray = options.tray_capa;
            } else {
                itemOptions.tray = options.tray_miolo;
            }
        }

        try {
            if (isLocalMode && hotFolder) {
                // O prefixo de ordem (00001_, 00002_...) passa a servir a dois
                // donos: o titulo do job no spooler e a ordem alfabetica em que
                // o watcher do Edge Print importa os arquivos da pasta.
                const formData = new FormData();
                formData.append('file', item.blob, nomeParaSpool(ordem, item.name));
                formData.append('folder', hotFolder);
                const res = await fetch('/api/hotfolder/drop', { method: 'POST', body: formData });
                if (!res.ok) {
                    let motivo = `HTTP ${res.status}`;
                    try { motivo = (await res.json()).detail || motivo; } catch (_) {}
                    throw new Error(motivo);
                }
                const dropData = await res.json();
                if (dropData.path) caminhosSoltos.push(dropData.path);
            } else if (isLocalMode) {
                const formData = new FormData();
                formData.append('file', item.blob, nomeParaSpool(ordem, item.name));
                formData.append('printer_name', printerName);
                formData.append('options', JSON.stringify(itemOptions));
                const res = await fetch('/api/print/submit', { method: 'POST', body: formData });
                if (!res.ok) {
                    const errText = await res.text();
                    throw new Error(errText || 'Falha ao enviar para impressora local.');
                }
            } else {
                if (!_printerAgentActive || !window._activeAgentData) {
                    throw new Error('Agente de Impressão inativo. Inicie o NewProd.exe.');
                }
                const fileName = nomeObjetoStorage(nomeParaSpool(ordem, item.name));
                const filePath = `${window._activeAgentData.id}/${loteId}/${fileName}`;
                const { error: uploadError } = await supabaseClient.storage
                    .from('print_jobs')
                    .upload(filePath, item.blob, { contentType: 'application/pdf', upsert: false });
                if (uploadError) throw new Error(`Falha no upload: ${uploadError.message}`);
                const { data: urlData } = supabaseClient.storage.from('print_jobs').getPublicUrl(filePath);
                const { error: dbError } = await supabaseClient.from('print_queue').insert({
                    agent_id: window._activeAgentData.id,
                    file_url: urlData.publicUrl,
                    // Sem impressora escolhida no modo hot folder, mas a coluna
                    // e o que o operador le no historico da fila — deixar vazio
                    // ali nao ajuda ninguem a saber para onde o trabalho foi.
                    printer_name: printerName || (hotFolder ? `HOT FOLDER: ${hotFolder}` : ''),
                    ppd_options: options,
                    status: 'pending'
                });
                if (dbError) throw new Error(`Falha ao registrar job: ${dbError.message}`);
            }
            successCount++;
        } catch (e) {
            failCount++;
            console.error(`[PrintDirect] Erro ao enviar ${item.name}:`, e);
            toast(`Erro ao imprimir "${item.name}": ${e.message}`, 'error');
        }
    }

    return {
        get cancelado() { return cancelado; },
        get enviados() { return successCount; },
        get falhas() { return failCount; },

        // Entrega ESTES arquivos agora. Chamada uma vez por lote no caminho em
        // streaming, e uma vez so, com a fila inteira, nos outros.
        async entregar(itens) {
            let fila = itens;
            if (options.impressao_reversa || options.folha_a_folha) {
                if (!avisouTransformacao) {
                    const modoDesc = options.impressao_reversa && options.folha_a_folha
                        ? 'Reversa + Folha a Folha'
                        : (options.impressao_reversa ? 'Impressão Reversa' : 'Folha a Folha');
                    toast(`Processando páginas (${modoDesc})...`, 'info');
                    avisouTransformacao = true;
                }
                fila = await processPrintQueueOptions(fila, options);
            }

            for (const item of fila) {
                if (window._printCancelRequested) {
                    console.warn('[entregaDeImpressao] Interrompido por solicitação de cancelamento.');
                    toast('🛑 Envio para a impressora cancelado!', 'warning');
                    window._printCancelRequested = false;
                    cancelado = true;
                    return false;
                }
                await enviarUm(item);
            }
            return true;
        },

        // Fecha a entrega: relatorio, conferencia do hot folder e a tela de
        // volta ao normal. Idempotente de proposito — o caminho em streaming
        // chama daqui e tambem do tratamento de erro, e chamar duas vezes nao
        // pode deixar os botoes presos no estado de "imprimindo".
        finalizar({ interrompido = false } = {}) {
            const ok = failCount === 0 && !cancelado && !interrompido;
            if (encerrada) return ok;
            encerrada = true;

            window.isPrinting = false;
            if (btnCancelPed) btnCancelPed.style.display = 'none';
            if (btnImpose) btnImpose.style.display = 'inline-flex';
            if (btnImposePrint) btnImposePrint.style.display = 'inline-flex';

            if (ok) {
                const destino = hotFolder ? `a pasta "${hotFolder}"` : `"${printerName}"`;
                toast(`✓ ${successCount} arquivo(s) enviado(s) para ${destino}!`, 'success');
                _conferirConsumoHotFolder(caminhosSoltos);
            } else if (successCount > 0) {
                // Papel entregue nao volta: quem parou no meio ainda precisa da
                // conferencia do que ja caiu na pasta.
                _conferirConsumoHotFolder(caminhosSoltos);
            }
            return ok;
        }
    };
}
window.criarEntregaDeImpressao = criarEntregaDeImpressao;

// Envia os blobs gerados diretamente para a impressora configurada no painel lateral
// sem abrir o modal (modo "print sem modal")
async function sendPrintJobDirect(queue) {
    const entrega = criarEntregaDeImpressao({ total: (queue || []).length });
    if (!entrega) return false;
    try {
        await entrega.entregar(queue);
        return entrega.finalizar();
    } catch (e) {
        entrega.finalizar({ interrompido: true });
        throw e;
    }
}


// ═══════════════════════════════════════════════════════════════════════
// MEMÓRIA DE CONFIGURAÇÃO DE IMPRESSORA POR PRODUTO
// ═══════════════════════════════════════════════════════════════════════

// Cache local para evitar requisicoes repetidas
const _printConfigCache = {};

function _getActiveProductInfo() {
    const activeItem = state.activeOSItem;
    if (!activeItem) return null;
    const itens = state.osItens[activeItem.osId] || [];
    const item = itens.find(i => String(i.id) === String(activeItem.itemId));
    if (!item) return null;
    const prodId = item._vibe_id_produto || item.id_produto || item.produto_id || null;
    if (!prodId) return null;
    const prodObj = (state.produtosGlobais || []).find(p => String(p.id_produto) === String(prodId));
    const prodNome = prodObj ? (prodObj.nomeReal || `Produto #${prodId}`) : (item.nome_produto_real || item.produto || 'Produto');
    return { prodId: String(prodId), prodNome };
}

/**
 * O rodape do box da direita: o botao SALVAR e a nota que diz o que ele grava.
 *
 * O BOTAO NAO SE ESCONDE MAIS. Ate 29/08/2026 esta funcao apagava a secao
 * inteira quando nao havia produto ativo, e a secao morava dentro do grupo
 * "Configuracao de Impressao", que nasce fechado. Somando as duas coisas, o
 * operador praticamente nunca via o botao — e a configuracao de impressao da
 * estacao se perdia ao trocar de pedido, porque ninguem a gravava.
 *
 * Sem produto ativo ele fica na tela, DESABILITADO, com a nota dizendo o que
 * falta. Toda trava desta aplicacao precisa mostrar a saida na propria tela.
 */
function _updateSaveButtonLabel() {
    const info = _getActiveProductInfo();
    const section = document.getElementById('ped-print-save-section');
    const btn = document.getElementById('ped-print-save-btn');
    const nota = document.getElementById('ped-print-save-nota');

    if (section) section.style.display = 'flex';
    if (btn) btn.disabled = !info;
    if (!nota) return;

    nota.innerHTML = info
        ? `Guarda nesta esta&ccedil;&atilde;o, para <b style="color:#cbd5e1;">${escapeHtml(info.prodNome)}</b>, `
          + 'a pasta observada, a configura&ccedil;&atilde;o de impress&atilde;o, a entrega por bloco '
          + 'e o gerenciamento de cores.'
        : 'Este modelo n&atilde;o tem produto do ERP, ent&atilde;o n&atilde;o h&aacute; a quem '
          + 'atribuir a configura&ccedil;&atilde;o. Abra um modelo vindo do pedido para grav&aacute;-la.';
}

// URL do agente desta maquina. Sempre 127.0.0.1: a configuracao de impressao e
// fisica DESTA maquina -- impressora, bandeja, papel --, entao nao pode vir de
// caminho relativo (que na nuvem nao chega a lugar nenhum) nem do Supabase, que e
// compartilhado por todas as estacoes.
const AGENTE_LOCAL_URL = 'http://127.0.0.1:9000';

async function savePrintConfigForProduct() {
    const info = _getActiveProductInfo();
    if (!info) return toast('Nenhum produto ativo para salvar.', 'warning');

    const printerSel = document.getElementById('ped-print-printer');
    const hotFolderAtivo = _hotFolderAtivo();
    if (hotFolderAtivo && !_hotFolderPath()) {
        return toast('Escolha a pasta do hot folder primeiro.', 'warning');
    }
    if (!hotFolderAtivo && (!printerSel || !printerSel.value)) {
        return toast('Selecione uma impressora primeiro.', 'warning');
    }

    const config = {
        produto_id: String(info.prodId),
        produto_nome: info.prodNome,
        printer_name: printerSel?.value || '',
        hot_folder: hotFolderAtivo,
        hot_folder_path: hotFolderAtivo ? _hotFolderPath() : '',
        tray: parseInt(document.getElementById('ped-print-tray')?.value) || null,
        tray_capa: parseInt(document.getElementById('ped-print-tray-capa')?.value) || null,
        tray_miolo: parseInt(document.getElementById('ped-print-tray-miolo')?.value) || null,
        paper_size: parseInt(document.getElementById('ped-print-paper')?.value) || null,
        duplex: parseInt(document.getElementById('ped-print-duplex')?.value) || 1,
        color: parseInt(document.getElementById('ped-print-color')?.value) || 2,
        copies: parseInt(document.getElementById('ped-print-copies')?.value) || 1,
        orientation: parseInt(document.getElementById('ped-print-orientation')?.value) || 1,
        print_mode: document.getElementById('ped-print-engine-mode')?.value || 'gdi',
        impressao_reversa: document.getElementById('ped-print-reverse')?.checked === true,
        folha_a_folha: document.getElementById('ped-print-sheet-by-sheet')?.checked === true,

        // A ENTREGA POR BLOCO, que tambem mora nesta coluna.
        //
        // Ela ja se grava sozinha no MODELO (`pedidos_modelos.entregar_por_bloco`,
        // ver onPedEntregarPorBlocoToggle no pedido.js), e continua sendo o modelo
        // quem decide na hora de abrir. Aqui ela e' REGISTRO do que esta estacao
        // usa para o produto — nunca uma segunda fonte que possa discordar do
        // modelo, e por isso o _applyPrintConfig nao a aplica de volta na caixa.
        entregar_por_bloco: document.getElementById('ped-entregar-por-bloco')?.checked === true,

        updated_at: new Date().toISOString()
    };

    // 1. Salvar no cache local
    _printConfigCache[info.prodId] = config;

    // 2. Salvar no localStorage (fallback offline)
    try { localStorage.setItem(`printConfig_${info.prodId}`, JSON.stringify(config)); } catch(e) {}

    // 3. Gravar no agente desta máquina.
    //    Sempre no agente local, e nunca por caminho relativo: no painel da
    //    nuvem um `/api/…` não chega a máquina nenhuma, e a configuração é
    //    física DESTA aqui — impressora, bandeja e papel.
    const btn = document.getElementById('ped-print-save-btn');
    if (btn) { btn.disabled = true; btn.style.opacity = '0.5'; }
    try {
        const resp = await fetch(`${AGENTE_LOCAL_URL}/api/print-config`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(config)
        });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        if (!data.ok) throw new Error(data.detail || 'o agente recusou a gravação');

        // 4. O GERENCIAMENTO DE CORES, que e' do mesmo box da direita.
        //
        //    Ele ja se grava a cada mexida nos controles, mas quem aperta SALVAR
        //    espera que TUDO o que esta na coluna tenha sido gravado — e uma
        //    gravacao anterior pode ter falhado com o agente fora do ar.
        //
        //    Vale por IMPRESSORA, e nao por produto: perfil .icm, intento e
        //    curvas sao ajuste fisico do equipamento. Duplicar isso na config do
        //    produto criaria duas fontes que discordam, e quem descobriria a
        //    divergencia seria o operador, olhando o papel.
        let recadoCor = '';
        if (printerSel?.value) {
            try {
                await salvarCorImpressora();
                recadoCor = ` Cores gravadas para a impressora "${printerSel.value}".`;
            } catch (e) {
                console.warn('[printConfig] cores nao gravadas:', e);
                recadoCor = ' As cores desta impressora nao puderam ser gravadas.';
            }
        }

        toast(`✅ Configuração salva nesta estação para "${info.prodNome}".${recadoCor}`, 'success');
    } catch (e) {
        // Falha aqui era engolida num console.warn e o operador via "salva
        // localmente", achando que tinha dado certo — some ao trocar de pedido.
        console.error('[printConfig] falha ao salvar no agente:', e);
        toast(`Não foi possível salvar: o agente local respondeu "${e.message}". ` +
              `A configuração vale só neste navegador até o agente voltar.`, 'error');
    } finally {
        if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    }
}

async function loadPrintConfigForProduct(produtoId) {
    if (!produtoId) return;
    const prodId = String(produtoId);

    // 1. Verificar cache em memória
    if (_printConfigCache[prodId]) {
        await _applyPrintConfig(_printConfigCache[prodId]);
        return;
    }

    // 2. Perguntar ao agente desta máquina (fonte da verdade).
    //    Não consulta o Supabase: a configuração é da estação, e a tabela
    //    compartilhada fazia duas máquinas disputarem a mesma linha.
    try {
        const resp = await fetch(`${AGENTE_LOCAL_URL}/api/print-config/${encodeURIComponent(prodId)}`);
        if (resp.ok) {
            const data = await resp.json();
            if (data.ok && data.config) {
                _printConfigCache[prodId] = data.config;
                try { localStorage.setItem(`printConfig_${prodId}`, JSON.stringify(data.config)); } catch(e) {}
                await _applyPrintConfig(data.config);
                return;
            }
        }
    } catch (e) {
        console.warn('[printConfig] agente local não respondeu:', e);
    }

    // 4. Fallback localStorage
    try {
        const stored = localStorage.getItem(`printConfig_${prodId}`);
        if (stored) {
            const config = JSON.parse(stored);
            _printConfigCache[prodId] = config;
            await _applyPrintConfig(config);
            return;
        }
    } catch (e) {}

    // Sem config salva — esconder indicador
    const indicator = document.getElementById('ped-print-saved-indicator');
    if (indicator) indicator.style.display = 'none';
}

async function _applyPrintConfig(config) {
    if (!config) return;

    // Hot folder vem antes da impressora, e fora do ramo dela de proposito: um
    // produto configurado so para hot folder nao tem printer_name para casar com
    // a lista da maquina, e o ramo abaixo nunca seria alcancado.
    const campoHot = document.getElementById('ped-hotfolder-path');
    if (campoHot) {
        // A PASTA e' o estado. O `hot_folder` do registro antigo era uma caixa
        // separada que podia discordar do caminho; aqui ele so' decide se o
        // caminho gravado vale, para nao ligar hot folder num produto que foi
        // salvo com a caixa desmarcada e um caminho esquecido no campo.
        campoHot.value = (config.hot_folder === false) ? '' : (config.hot_folder_path || '');
        _aplicarEstadoHotFolder();
        if (typeof desenharGradeHotFolders === 'function') desenharGradeHotFolders();
        if (campoHot.value) {
            _hotFolderStatus(`Pasta salva para este produto: <code>${campoHot.value}</code>`, 'ok');
            const indicador = document.getElementById('ped-print-saved-indicator');
            if (indicador) {
                indicador.style.display = 'block';
                setTimeout(() => { if (indicador) indicador.style.display = 'none'; }, 5000);
            }
        }
    }

    // Selecionar impressora
    const printerSel = document.getElementById('ped-print-printer');
    if (printerSel && config.printer_name) {
        // Verificar se a impressora esta na lista
        const exists = Array.from(printerSel.options).some(o => o.value === config.printer_name);
        if (exists) {
            printerSel.value = config.printer_name;
            // Trigger change para carregar capabilities do driver
            if (typeof onPedPrinterChange === 'function') {
                await onPedPrinterChange();
            }

            // Aguardar driver options carregarem e depois aplicar os valores
            setTimeout(() => {
                if (config.tray != null) {
                    const traySel = document.getElementById('ped-print-tray');
                    if (traySel) traySel.value = String(config.tray);
                }
                if (config.tray_capa != null) {
                    const trayCapaSel = document.getElementById('ped-print-tray-capa');
                    if (trayCapaSel) trayCapaSel.value = String(config.tray_capa);
                }
                if (config.tray_miolo != null) {
                    const trayMioloSel = document.getElementById('ped-print-tray-miolo');
                    if (trayMioloSel) trayMioloSel.value = String(config.tray_miolo);
                }
                if (config.paper_size != null) {
                    const paperSel = document.getElementById('ped-print-paper');
                    if (paperSel) paperSel.value = String(config.paper_size);
                }
                if (config.duplex != null) {
                    const duplexSel = document.getElementById('ped-print-duplex');
                    if (duplexSel) duplexSel.value = String(config.duplex);
                }
                if (config.color != null) {
                    const colorSel = document.getElementById('ped-print-color');
                    if (colorSel) colorSel.value = String(config.color);
                }
                if (config.copies != null) {
                    const copiesInput = document.getElementById('ped-print-copies');
                    if (copiesInput) copiesInput.value = String(config.copies);
                }
                if (config.orientation != null) {
                    const orientSel = document.getElementById('ped-print-orientation');
                    if (orientSel) orientSel.value = String(config.orientation);
                }
                if (config.print_mode != null) {
                    const engineSel = document.getElementById('ped-print-engine-mode');
                    if (engineSel) engineSel.value = String(config.print_mode);
                }
                const chkReverse = document.getElementById('ped-print-reverse');
                if (chkReverse) chkReverse.checked = !!(config.impressao_reversa || config.reverse_print);

                const chkSheet = document.getElementById('ped-print-sheet-by-sheet');
                if (chkSheet) chkSheet.checked = !!(config.folha_a_folha || config.sheet_by_sheet);

                // O `config.entregar_por_bloco` E' LIDO DE PROPOSITO POR NINGUEM.
                //
                // O SALVAR o grava (e' um controle desta coluna, e quem aperta o
                // botao espera que ele tenha sido gravado), mas quem decide a
                // caixa ao abrir o modelo continua sendo `pedidos_modelos`, no
                // carregarPedidoNaTela do pedido.js. Aplica-lo aqui poria duas
                // fontes disputando a mesma caixa, com um setTimeout de 800 ms de
                // cada lado decidindo quem escreve por ultimo.

                // Mostrar indicador visual
                const indicator = document.getElementById('ped-print-saved-indicator');
                if (indicator) {
                    indicator.style.display = 'block';
                    // Auto-esconder após 5 segundos
                    setTimeout(() => { if (indicator) indicator.style.display = 'none'; }, 5000);
                }

                // onPedPrinterChange() acabou de reexibir o bloco do driver; se o
                // produto e de hot folder, ele precisa voltar a ficar desabilitado.
                _aplicarEstadoHotFolder();
            }, 800);
        }
    }
}

